INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pluginagentmarketplace/custom-plugin-cpp/stl', 'stl', 'pluginagentmarketplace', 'custom-plugin-cpp', 'community', 'stl pluginagentmarketplace custom-plugin-cpp community The stl skill provides a C++ programming language roadmap plugin for mastering containers, algorithms, and iterators. It benefits developers seeking efficient programming solutions. STL容器、算法和迭代器的高效编程方法，用于C++编程语言 STLコンテナ、アルゴリズム、イテレータの効率的なプログラミング方法、C++プログラミング言語 STL 컨테이너, 알고리즘, 반복자의 효율적인 프로그래밍 방법, C++ 프로그래밍 언어 El plugin de STL ofrece una guía de selección de contenedores y una visión general de los algoritmos y iteradores para programación C++ eficiente. Le plugin STL propose un guide de sélection de conteneurs et une vue d''ensemble des algorithmes et itérateurs pour une programmation C++ optimale. Das STL-Plugin bietet eine Container-Auswahlguide und eine Übersicht über Algorithmen und Iteratoren für effizientes C++-Programming. O STL é uma biblioteca de programação C++ que fornece containers, algoritmos e iteradores para programação eficiente STL - это библиотека программирования на C++, которая предоставляет контейнеры, алгоритмы и итераторы для эффективного программирования для ИИ Агентов STL هي مكتبة برمجة C++ توفر حاويات و خوارزميات و معادلات للبرمجة الفعالة لأدوات الذكاء الاصطناعي how to use stl in C++ what is stl in programming stl alternative libraries stl vs boost stl install guide std::map tutorial C++ container selection stl setup for beginners efficient C++ programming with stl STL容器 C++编程语言 AIエージェント STL算法 STL迭代器 std::map std::unordered_map Provides a container selection guide with decision flowcharts Supports std::map for key-value pairs with ordering Utilizes std::unordered_map for fast lookup Offers std::set for unique elements with ordering Enables std::unordered_set for fast lookup of unique elements Guides sequence storage with random access stl is a Standard Template Library skill for mastering C++ containers, algorithms, and iterators');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('seanb4t/specgraph/buf-regen', 'community', 'seanb4t', 'specgraph', 'seanb4t/specgraph', 'buf-regen', 0, 0, 35, '2026-03-08T01:25:01Z', '2026-03-08T02:17:39.212Z', '760abbc8f37afc5c490f24c0dfdeb04072ddd7458de17e757bedfb4e7bc81834', '{"id":"seanb4t/specgraph/buf-regen","name":"buf-regen","description":{"en":"buf-regen is a skill that regenerates Go code from protobuf definitions, benefiting developers working with Go and protobuf. It automates code generation, validation, and compilation.","zh":"buf-regen 是一种用于重新生成Go代码的AI工具，通过运行 buf lint、buf generate 和 go mod tidy 命令","ja":"buf-regenはGoコードを再生成するAIエージェントで、buf lint、buf generate、go mod tidyコマンドを実行します","ko":"buf-regen은 Go 코드를 재생성하는 AI 도구로, buf lint, buf generate, go mod tidy 명령을 실행합니다","es":"buf-regen es una herramienta para regenerar código Go desde definiciones de protocolo de buf. Ayuda a mantener el código actualizado después de cambios en los archivos de protocolo","fr":"buf-regen est un outil pour régénérer du code Go à partir de définitions de protocole de buf. Il aide à maintenir le code à jour après des modifications dans les fichiers de protocole","de":"buf-regen ist ein Tool, um Go-Code aus Protokolldefinitionen von buf zu regenerieren. Es hilft, den Code nach Änderungen in den Protokoll-Dateien auf dem neuesten Stand zu halten","pt":"O buf-regen regenera código Go a partir de definições de protocolo. Use-o após alterações nos arquivos de protocolo.","ru":"buf-regen регенерирует код Go из определений протокола. Используйте его после изменений в файлах протокола.","ar":"يعادة buf-regen إنشاء كود Go من تعريفات البروتوكول. استخدمه بعد تغييرات في ملفات البروتوكول."},"seo":{"title":{"en":"buf-regen: Regenerate Go Code from Protobuf Definitions |...","zh":"buf-regen Setup Guide:Protobuf代码生成","ja":"buf-regen設定ガイド: Protocol Buffersコード生成","ko":"buf-regen 설정 가이드: 프로토 버프 코드 생성","es":"Guía de configuración de buf-regen para regenerar código Go","fr":"Guide de mise en place de buf-regen pour régénérer du cod...","de":"Einrichtungsleitfaden für buf-regen zur Regenerierung von...","pt":"Guia de Configuração do buf-regen: Regeneração de Código Go","ru":"Настройка buf-regen: Руководство по Регенерации Кодов Go","ar":"دليل إعداد buf-regen: إعادة إنشاء كود Go"},"description":{"en":"Learn how to use buf-regen to regenerate Go code from protobuf definitions. Follow our step-by-step guide to get started today!","zh":"buf-regen 是一种用于从protobuf定义中重新生成Go代码的AIエージェント。了解如何设置和使用","ja":"buf-regenはProtocol Buffers定義からGoコードを再生成するAIエージェントです。設定方法と使い方を学ぶ","ko":"buf-regen은 프로토 버프 정의에서 Go 코드를 재생성하는 AI 도구입니다. 설정 방법과 사용법을 알아보세요","es":"Aprende a utilizar buf-regen para regenerar código Go desde definiciones de protocolo de buf. Sigue nuestros pasos para una integración exitosa","fr":"Découvrez comment utiliser buf-regen pour régénérer du code Go à partir de définitions de protocole de buf. Suivez nos étapes pour une intégration réussie","de":"Erfahren Sie, wie Sie buf-regen verwenden, um Go-Code aus Protokolldefinitionen von buf zu regenerieren. Befolgen Sie unsere Schritte für eine erfolgreiche I...","pt":"Aprenda a usar o buf-regen para regenerar código Go a partir de definições de protocolo. Siga os passos para validar, gerar e compilar o código.","ru":"Узнайте, как использовать buf-regen для регенерации кода Go из определений протокола. Следуйте шагам для проверки, генерации и компиляции кода.","ar":"تعرف على كيفية استخدام buf-regen لإعادة إنشاء كود Go من تعريفات البروتوكول. اتبع الخطوات لتحقق من الصحة وتوليد وترجمة الكود."},"definition":{"en":"buf-regen is a tool that regenerates Go code from protobuf definitions, using commands like buf lint and buf generate to validate and generate code.","zh":"buf-regen是一种AIエージェント，用于重新生成Go代码从protobuf定义","ja":"buf-regenはProtocol Buffers定義からGoコードを再生成するAIエージェント","ko":"buf-regen은 프로토 버프 정의에서 Go 코드를 재생성하는 AI 도구","es":"buf-regen es una herramienta de línea de comandos que regenera código Go desde definiciones de protocolo de buf","fr":"buf-regen est un outil de ligne de commande qui régénère du code Go à partir de définitions de protocole de buf","de":"buf-regen ist ein Kommandozeilentool, das Go-Code aus Protokolldefinitionen von buf regeneriert","pt":"buf-regen é uma ferramenta que regenera código Go a partir de definições de protocolo.","ru":"buf-regen - это инструмент, который регенерирует код Go из определений протокола.","ar":"buf-regen هو أداة لإعادة إنشاء كود Go من تعريفات البروتوكول."},"features":{"en":["Runs buf lint to validate proto files","Executes buf generate to regenerate Go code in gen/","Updates dependencies using go mod tidy","Verifies generated code compiles with go build ./gen/...","Reports any errors encountered during the process"],"zh":["重新生成Go代码从protobuf定义","运行buf lint命令验证proto文件","运行buf generate命令生成Go代码","运行go mod tidy命令更新依赖","支持ConnectRPC代码生成"],"ja":["Protocol Buffers定義からGoコードを再生成","buf lintコマンドでprotoファイルを検証","buf generateコマンドでGoコードを生成","go mod tidyコマンドで依存関係を更新","ConnectRPCコード生成をサポート"],"ko":["프로토 버프 정의에서 Go 코드를 재생성","buf lint 명령으로 proto 파일을 검증","buf generate 명령으로 Go 코드를 생성","go mod tidy 명령으로 의존 관계를 업데이트","ConnectRPC 코드 생성을 지원"],"es":["Regeneración de código Go desde definiciones de protocolo de buf","Validación de archivos de protocolo con buf lint","Actualización de dependencias con go mod tidy","Verificación de la compilación del código generado con go build","Compatibilidad con ConnectRPC y protobuf"],"fr":["Régénération de code Go à partir de définitions de protocole de buf","Validation de fichiers de protocole avec buf lint","Mise à jour des dépendances avec go mod tidy","Vérification de la compilation du code généré avec go build","Compatibilité avec ConnectRPC et protobuf"],"de":["Regenerierung von Go-Code aus Protokolldefinitionen von buf","Validierung von Protokoll-Dateien mit buf lint","Aktualisierung von Abhängigkeiten mit go mod tidy","Überprüfung der Kompilierung des generierten Codes mit go build","Kompatibilität mit ConnectRPC und protobuf"],"pt":["Regeneração de código Go a partir de definições de protocolo","Validação de arquivos de protocolo com buf lint","Geração de código em gen/","Atualização de dependências com go mod tidy","Compilação de código gerado com go build"],"ru":["Регенерация кода Go из определений протокола","Проверка файлов протокола с помощью buf lint","Генерация кода в gen/","Обновление зависимостей с помощью go mod tidy","Компиляция сгенерированного кода с помощью go build"],"ar":["إعادة إنشاء كود Go من تعريفات البروتوكول","التحقق من صحة ملفات البروتوكول باستخدام buf lint","توليد الكود في gen/","تحديث التبعيات باستخدام go mod tidy","ترجمة الكود المنشأ باستخدام go build"]},"keywords":{"en":["how to use buf-regen","buf-regen setup guide","regenerate Go code from protobuf","buf-regen alternative","buf-regen vs protoc","buf-regen install","protobuf to Go code generation","buf-regen tutorial","Go code regeneration from protobuf definitions"],"zh":["buf-regen","protobuf","Go代码生成","AIエージェント","buf lint","buf generate","go mod tidy","ConnectRPC"],"ja":["buf-regen","Protocol Buffers","Goコード生成","AIエージェント","buf lint","buf generate","go mod tidy","ConnectRPC"],"ko":["buf-regen","프로토 버프","Go 코드 생성","AI 도구","buf lint","buf generate","go mod tidy","ConnectRPC"],"es":["buf-regen","regenerar código Go","definiciones de protocolo de buf","buf lint","go mod tidy","go build","ConnectRPC","protobuf","herramientas de desarrollo de Go"],"fr":["buf-regen","régénérer du code Go","définitions de protocole de buf","buf lint","go mod tidy","go build","ConnectRPC","protobuf","outils de développement de Go"],"de":["buf-regen","Go-Code regenerieren","Protokolldefinitionen von buf","buf lint","go mod tidy","go build","ConnectRPC","protobuf","Entwickler-Tools für Go"],"pt":["buf-regen","regeneração de código","definições de protocolo","código Go","buf lint","go mod tidy","go build"],"ru":["buf-regen","регенерация кода","определения протокола","код Go","buf lint","go mod tidy","go build","ИИ Агенты"],"ar":["buf-regen","إعادة إنشاء كود","تعريفات البروتوكول","كود Go","buf lint","go mod tidy","go build","أدوات الذكاء الاصطناعي"]}},"owner":"seanb4t","repo":"specgraph","repoPath":"seanb4t/specgraph","stars":0,"forks":0,"updatedAt":"2026-03-08T01:25:01Z","topics":[],"category":"community","skillMd":{"name":"buf-regen","description":"Regenerate protobuf Go code after .proto file changes. Runs buf generate, tidies modules, and verifies build.","bodyPreview":"# buf-regen\n\nRegenerate Go code from protobuf definitions.\n\n## When to use\n\nAfter any change to files in `proto/specgraph/v1/*.proto`.\n\n## Steps\n\n1. Run `buf lint` to validate proto files\n2. Run `buf generate` to regenerate Go code in `gen/`\n3. Run `go mod tidy` to update dependencies\n4. Run `go build ./gen/...` to verify generated code compiles\n5. Report any errors\n\n## Notes\n\n- Generated files go to `gen/specgraph/v1/` (protobuf) and `gen/specgraph/v1/specgraphv1connect/` (ConnectRPC)\n- Never h","body":"# buf-regen\n\nRegenerate Go code from protobuf definitions.\n\n## When to use\n\nAfter any change to files in `proto/specgraph/v1/*.proto`.\n\n## Steps\n\n1. Run `buf lint` to validate proto files\n2. Run `buf generate` to regenerate Go code in `gen/`\n3. Run `go mod tidy` to update dependencies\n4. Run `go build ./gen/...` to verify generated code compiles\n5. Report any errors\n\n## Notes\n\n- Generated files go to `gen/specgraph/v1/` (protobuf) and `gen/specgraph/v1/specgraphv1connect/` (ConnectRPC)\n- Never hand-edit files in `gen/` — they are overwritten by `buf generate`\n- buf STANDARD lint requires unique response type names per RPC (wrap with `GetXxxResponse`, `UpdateXxxResponse`)\n"},"lastSynced":"2026-03-08T02:17:39.212Z","agentAnalysis":{"suitability":{"en":"Perfect for Go Development Agents needing automated protobuf code regeneration and validation.","zh":"非常适合需要自动重新生成protobuf代码和验证的Go开发代理。","ja":"Go開発エージェントが自動でprotobufコードを再生成および検証する必要がある場合に最適です。","ko":"자동으로 protobuf 코드를 재생성하고 검증해야 하는 Go 개발 에이전트에 적합합니다.","es":"Perfecto para agentes de desarrollo de Go que necesitan regeneración y validación de código protobuf automatizadas.","fr":"Parfait pour les agents de développement Go nécessitant une régénération et une validation de code protobuf automatisées.","de":"Perfekt für Go-Entwicklungsagenten, die eine automatisierte Regenerierung und Validierung von Protobuf-Code benötigen.","pt":"Perfeito para Agentes de Desenvolvimento Go que necessitam de regeneração automatizada de código protobuf e validação.","ru":"Идеально подходит для агентов разработки Go, которым требуется автоматическая регенерация кода protobuf и проверка.","ar":"مثالي لعمليات开发 Go التي تحتاج إلى إعادة إنشاء وتحقق آلي للكود protobuf."},"recommendation":{"en":"Empowers agents to regenerate Go code from protobuf definitions using buf, enabling automated validation and compilation with buf lint and go build, while updating dependencies with go mod tidy.","zh":"赋予代理从protobuf定义中使用buf重新生成Go代码的能力，实现buf lint和go build的自动验证和编译，同时使用go mod tidy更新依赖项。","ja":"エージェントがbufを使用してprotobuf定義からGoコードを再生成し、buf lintおよびgo buildを使用した自動検証とコンパイルを可能にし、同時にgo mod tidyを使用して依存関係を更新することを可能にします。","ko":"buf를 사용하여 protobuf 정의에서 Go 코드를 재생성하고, buf lint 및 go build를 사용한 자동 검증 및 컴파일을 가능하게 하며, 동시에 go mod tidy를 사용하여 의존성을 업데이트할 수 있습니다.","es":"Habilita a los agentes a regenerar código Go a partir de definiciones de protobuf utilizando buf, lo que permite la validación y compilación automatizadas con buf lint y go build, mientras que se actualizan las dependencias con go mod tidy.","fr":"Permet aux agents de régénérer du code Go à partir de définitions de protobuf en utilisant buf, ce qui permet une validation et une compilation automatisées avec buf lint et go build, tout en mettant à jour les dépendances avec go mod tidy.","de":"Ermächtigt die Agenten, Go-Code aus Protobuf-Definitionen mit buf zu regenerieren, wodurch eine automatisierte Validierung und Kompilierung mit buf lint und go build ermöglicht wird, während die Abhängigkeiten mit go mod tidy aktualisiert werden.","pt":"Permite que os agentes regenerem o código Go a partir de definições protobuf usando buf, habilitando a validação e compilação automatizadas com buf lint e go build, além de atualizar dependências com go mod tidy.","ru":"Позволяет агентам регенерировать код Go из определений protobuf с помощью buf, обеспечивая автоматическую проверку и сборку с buf lint и go build, а также обновление зависимостей с помощью go mod tidy.","ar":"يمكن للعميل إعادة إنشاء كود Go من التعريفات protobuf باستخدام buf، مما يمكّن من التحقق والتركيب الآليين باستخدام buf lint و go build، بالإضافة إلى تحديث الاعتماديات باستخدام go mod tidy."},"useCases":{"en":["Regenerating Go code after proto file changes","Validating protobuf definitions with buf lint","Compiling generated Go code with go build"],"zh":["proto文件更改后重新生成Go代码","使用buf lint验证protobuf定义","使用go build编译生成的Go代码"],"ja":["protoファイルの変更後、Goコードを再生成する","buf lintを使用してprotobuf定義を検証する","go buildを使用して生成されたGoコードをコンパイルする"],"ko":["proto 파일 변경 후 Go 코드 재생성","buf lint를 사용하여 protobuf 정의 검증","go build를 사용하여 생성된 Go 코드 컴파일"],"es":["Regenerar código Go después de cambios en archivos proto","Validar definiciones de protobuf con buf lint","Compilar código Go generado con go build"],"fr":["Régénérer du code Go après des modifications de fichiers proto","Valider les définitions de protobuf avec buf lint","Compiler le code Go généré avec go build"],"de":["Go-Code nach Änderungen an Proto-Dateien regenerieren","Protobuf-Definitionen mit buf lint validieren","Mit go build generierten Go-Code kompilieren"],"pt":["Regenerar código Go após alterações no arquivo proto","Validar definições protobuf com buf lint","Compilar código Go gerado com go build"],"ru":["Регенерировать код Go после изменений файла proto","Проверять определения protobuf с помощью buf lint","Собирать сгенерированный код Go с помощью go build"],"ar":["إعادة إنشاء كود Go بعد تغييرات في الملف proto","التحقق من تعريفات protobuf باستخدام buf lint","تركيب كود Go المُنشأ باستخدام go build"]},"limitations":{"en":["Requires buf and Go installed","Limited to Go and protobuf","Needs access to proto files in proto/specgraph/v1/"],"zh":["需要安装buf和Go","仅限于Go和protobuf","需要访问proto文件夹proto/specgraph/v1/"],"ja":["bufおよびGoのインストールが必要","Goおよびprotobufに限定される","proto/specgraph/v1/内のprotoファイルにアクセスする必要がある"],"ko":["buf 및 Go 설치 필요","Go 및 protobuf에만 한정됨","proto/specgraph/v1/ 내의 proto 파일에 접근할 수 있어야 함"],"es":["Requiere buf y Go instalados","Limitado a Go y protobuf","Necesita acceso a archivos proto en proto/specgraph/v1/"],"fr":["Nécessite buf et Go installés","Limité à Go et protobuf","Nécessite l''accès aux fichiers proto dans proto/specgraph/v1/"],"de":["Buf und Go müssen installiert sein","Begrenzt auf Go und Protobuf","Benötigt Zugriff auf Proto-Dateien in proto/specgraph/v1/"],"pt":["Exige buf e Go instalados","Limitado a Go e protobuf","Necessita acesso aos arquivos proto em proto/specgraph/v1/"],"ru":["Требует buf и Go для установки","Ограничен для Go и protobuf","Требует доступа к файлам proto в proto/specgraph/v1/"],"ar":["يتطلب تثبيت buf و Go","محدود لاستخدام Go و protobuf","يتطلب الوصول إلى الملفات proto في proto/specgraph/v1/"]},"version":4},"contentHash":"760abbc8f37afc5c490f24c0dfdeb04072ddd7458de17e757bedfb4e7bc81834","qualityScore":35}');
