INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('KatTate/Katalyst_Franchise_Planner/bmad-validate-prd', 'community', 'KatTate', 'Katalyst_Franchise_Planner', 'KatTate/Katalyst_Franchise_Planner', 'bmad-validate-prd', 0, 0, 35, '2026-03-07T01:49:01.777Z', '2026-03-07T03:15:11.799Z', '1cea6cd7265bac89d5b4015f1d39eda0943013094361bdb77234eaa3104385b1', '{"id":"KatTate/Katalyst_Franchise_Planner/bmad-validate-prd","name":"bmad-validate-prd","description":{"en":"The bmad-validate-prd skill activates the BMAD PRD Validation workflow, reviewing existing PRDs against BMAD standards. It benefits developers by providing a comprehensive quality assessment.","zh":"BMAD Validate PRD 工作流激活后，会加载并执行综合质量评估工作流，确保 PRD 符合 BMAD 标准","ja":"BMAD Validate PRD ワークフローをトリガーすると、全面的品質評価ワークフローが実行され、PRD が BMAD 標準に準拠する","ko":"BMAD Validate PRD 워크플로우가 활성화되면, 포괄적인 품질 평가 워크플로우가 실행되어 PRD가 BMAD 표준에 맞게 구성","es":"bmad-validate-prd es un skill que activa el flujo de trabajo de validación PRD para revisar y evaluar la calidad de los PRD existentes según los estándares de BMAD","fr":"bmad-validate-prd est une compétence qui active le flux de travail de validation PRD pour examiner et évaluer la qualité des PRD existants selon les normes de BMAD","de":"bmad-validate-prd ist ein Skill, der den PRD-Validierungs-Workflow aktiviert, um bestehende PRD anhand der BMAD-Standards zu überprüfen und zu bewerten","pt":"O bmad-validate-prd é uma habilidade que ativa o fluxo de trabalho de validação de PRD do BMAD, verificando a qualidade de um PRD existente","ru":"bmad-validate-prd - это навык, который активирует рабочий процесс проверки PRD BMAD, осуществляя комплексную оценку качества существующего PRD","ar":"bmad-validate-prd هو مهارة يؤدي إلى تفعيل سير عمل التحقق من PRD في BMAD، ويتضمن تقييمًا شاملاً لجودة وثيقة PRD موجودة"},"seo":{"title":{"en":"bmad-validate-prd: PRD Validation Workflow Setup Guide | ...","zh":"BMAD Validate PRD 工作流配置指南","ja":"BMAD Validate PRD ワークフロー設定ガイド - AIエージェント","ko":"BMAD Validate PRD 워크플ロー 설정 가이드 - AI 툴","es":"Guía de configuración de bmad-validate-prd para flujos de...","fr":"Guide de configuration de bmad-validate-prd pour les flux...","de":"Konfigurationsleitfaden für bmad-validate-prd-Workflows","pt":"Guia de Configuração do bmad-validate-prd: Validação de PRD","ru":"Настройка bmad-validate-prd: Руководство по валидации PRD...","ar":"إعداد bmad-validate-prd: دليل التحقق من PRD باستخدام أدوا..."},"description":{"en":"Trigger the BMAD PRD Validation workflow with bmad-validate-prd. Learn how to load and follow the workflow for comprehensive quality assessment and discover ...","zh":"了解 BMAD Validate PRD 工作流的激活和配置，优化您的 PRD 质量评估","ja":"BMAD Validate PRD ワークフローの設定と活用方法を紹介。PRD の品質評価を最適化する","ko":"BMAD Validate PRD 워크플로우 설정과 구성 방법을 알아보세요. PRD 품질 평가를 최적화하는 방법","es":"Aprende a configurar y utilizar bmad-validate-prd para validar flujos de trabajo de PRD de manera efectiva con esta guía detallada","fr":"Découvrez comment configurer et utiliser bmad-validate-prd pour valider les flux de travail PRD de manière efficace avec ce guide détaillé","de":"Erfahren Sie, wie Sie bmad-validate-prd konfigurieren und verwenden, um PRD-Workflows effektiv zu validieren","pt":"Aprenda a configurar o bmad-validate-prd para validar PRDs contra padrões BMAD com essa guia passo a passo","ru":"Узнайте, как настроить bmad-validate-prd для проверки PRD на соответствие стандартам BMAD с помощью этого пошагового руководства и ИИ Агентов","ar":"تعرف على كيفية إعداد bmad-validate-prd للتحقق من صحة وثائق PRD مقابل معايير BMAD باستخدام أدوات الذكاء الاصطناعي و دليل خطوة بخطوة"},"definition":{"en":"bmad-validate-prd is a skill that activates the BMAD PRD Validation workflow, using a step-file architecture and configuration loading from _bmad/bmm/config.yaml","zh":"BMAD Validate PRD 是一种工作流技能，用于验证 PRD 是否符合 BMAD 标准","ja":"BMAD Validate PRD は、PRD が BMAD 標準に準拠しているかを検証するワークフロー スキル","ko":"BMAD Validate PRD는 PRD가 BMAD 표준에 맞는지 검증하는 워크플로우 스킬","es":"bmad-validate-prd es un agente de AI que valida flujos de trabajo de PRD según los estándares de BMAD","fr":"bmad-validate-prd est un agent d''IA qui valide les flux de travail PRD selon les normes de BMAD","de":"bmad-validate-prd ist ein KI-Agent, der PRD-Workflows nach BMAD-Standards validiert","pt":"O bmad-validate-prd é uma habilidade de validação de PRD que utiliza o fluxo de trabalho do BMAD para garantir a qualidade","ru":"bmad-validate-prd - это навык проверки PRD, использующий рабочий процесс BMAD для обеспечения качества","ar":"bmad-validate-prd هو مهارة للتحقق من صحة PRD التي تستخدم سير عمل BMAD لضمان الجودة"},"features":{"en":["Loads and follows the workflow directly from _bmad/bmm/workflows/2-plan-workflows/create-prd/workflow-validate-prd.md","Uses step-file architecture with steps in steps-v/ directory","Configuration loading from _bmad/bmm/config.yaml","Reviews existing PRDs against BMAD standards through comprehensive quality assessment","Triggers the BMAD PRD Validation workflow for automated validation"],"zh":["加载和执行综合质量评估工作流","配置加载从 `_bmad/bmm/config.yaml`","使用步骤文件架构，步骤位于 `steps-v/` 目录","遵循 `_bmad/bmm/workflows/2-plan-workflows/create-prd/workflow-validate-prd.md` 工作流"],"ja":["全面的品質評価ワークフローをロードして実行","設定のロードは `_bmad/bmm/config.yaml` から","ステップファイルアーキテクチャを使用、ステップは `steps-v/` ディレクトリに配置"," `_bmad/bmm/workflows/2-plan-workflows/create-prd/workflow-validate-prd.md` ワークフローに従う"],"ko":["포괄적인 품질 평가 워크플로우를 로드하고 실행","설정 로드는 `_bmad/bmm/config.yaml` 에서","스텝 파일 아키텍처를 사용, 스텝은 `steps-v/` 디렉토리에 위치"," `_bmad/bmm/workflows/2-plan-workflows/create-prd/workflow-validate-prd.md` 워크플로우에 따름"],"es":["Validación de flujos de trabajo de PRD según los estándares de BMAD","Arquitectura de paso a paso con pasos en el directorio steps-v/","Carga de configuración desde _bmad/bmm/config.yaml","Revisión y evaluación de la calidad de los PRD existentes"],"fr":["Validation des flux de travail PRD selon les normes de BMAD","Architecture de flux de travail avec des étapes dans le répertoire steps-v/","Chargement de la configuration à partir de _bmad/bmm/config.yaml","Examen et évaluation de la qualité des PRD existants"],"de":["Validierung von PRD-Workflows nach BMAD-Standards","Schritt-für-Schritt-Architektur mit Schritten im Verzeichnis steps-v/","Laden der Konfiguration aus _bmad/bmm/config.yaml","Überprüfung und Bewertung der Qualität bestehender PRD"],"pt":["Ativa o fluxo de trabalho de validação de PRD do BMAD","Verifica a qualidade de um PRD existente contra padrões BMAD","Utiliza arquitetura de arquivo de etapas com etapas em `steps-v/`","Carrega configuração do arquivo `_bmad/bmm/config.yaml`"],"ru":["Активирует рабочий процесс проверки PRD BMAD","Проверяет качество существующего PRD на соответствие стандартам BMAD","Использует архитектуру файла шагов со шагами в `steps-v/`","Загружает конфигурацию из файла `_bmad/bmm/config.yaml`"],"ar":["يفعّل سير عمل التحقق من PRD في BMAD","يتحقق من جودة وثيقة PRD موجودة مقابل معايير BMAD","يستخدم هندسة ملف الخطوات مع خطوات في `steps-v/`","يحمّل التكوين من ملف `_bmad/bmm/config.yaml`"]},"keywords":{"en":["how to use bmad-validate-prd","bmad-validate-prd setup guide","bmad-validate-prd alternative","bmad-validate-prd vs manual validation","what is bmad-validate-prd","bmad-validate-prd install","PRD validation workflow","BMAD standards compliance","automated PRD validation"],"zh":["BMAD Validate PRD","工作流技能","PRD 质量评估","BMAD 标准","配置加载","步骤文件架构","AI 工具","工作流配置"],"ja":["BMAD Validate PRD","ワークフロー スキル","PRD 品質評価","BMAD 標準","設定のロード","ステップファイルアーキテクチャ","AI エージェント","ワークフロー設定"],"ko":["BMAD Validate PRD","워크플로우 스킬","PRD 품질 평가","BMAD 표준","설정 로드","스텝 파일 아키텍처","AI 툴","워크플로우 설정"],"es":["bmad-validate-prd","validación de PRD","flujos de trabajo de PRD","BMAD","agentes de AI","herramientas de validación","configuración de workflows","evaluación de calidad"],"fr":["bmad-validate-prd","validation de PRD","flux de travail PRD","BMAD","agents d''IA","outils de validation","configuration de workflows","évaluation de qualité"],"de":["bmad-validate-prd","Validierung von PRD","PRD-Workflows","BMAD","KI-Agents","Validierungstools","Workflow-Konfiguration","Qualitätsbewertung"],"pt":["bmad-validate-prd","validação de PRD","fluxo de trabalho do BMAD","qualidade de PRD","configuração do BMAD","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["bmad-validate-prd","проверка PRD","рабочий процесс BMAD","качество PRD","конфигурация BMAD","разработка программного обеспечения","инструменты разработки","ИИ Агенты"],"ar":["bmad-validate-prd","التحقق من PRD","سير عمل BMAD","جودة PRD","تكوين BMAD","تطوير البرمجيات","أدوات التطوير","أدوات الذكاء الاصطناعي"]}},"owner":"KatTate","repo":"Katalyst_Franchise_Planner","repoPath":"KatTate/Katalyst_Franchise_Planner","stars":0,"forks":0,"updatedAt":"2026-03-07T01:49:01.777Z","topics":[],"category":"community","skillMd":{"name":"bmad-validate-prd","description":">","bodyPreview":"# BMAD Validate PRD Workflow\n\nThis skill activates the BMAD PRD Validation workflow. It reviews an existing\nPRD against BMAD standards through comprehensive quality assessment.\n\n## Activation\n\nWhen this skill is triggered, load and follow the workflow directly:\n\nRead fully and follow: `_bmad/bmm/workflows/2-plan-workflows/create-prd/workflow-validate-prd.md`\n\nThe workflow uses step-file architecture with steps in `steps-v/` directory.\n- Configuration loading from `_bmad/bmm/config.yaml`\n- PRD fi","body":"# BMAD Validate PRD Workflow\n\nThis skill activates the BMAD PRD Validation workflow. It reviews an existing\nPRD against BMAD standards through comprehensive quality assessment.\n\n## Activation\n\nWhen this skill is triggered, load and follow the workflow directly:\n\nRead fully and follow: `_bmad/bmm/workflows/2-plan-workflows/create-prd/workflow-validate-prd.md`\n\nThe workflow uses step-file architecture with steps in `steps-v/` directory.\n- Configuration loading from `_bmad/bmm/config.yaml`\n- PRD file discovery and loading\n- Output: validation report\n\n## Workflow Steps (13 Steps + 1 Conditional Branch)\n\n1. **step-v-01-discovery** — Discover and load the PRD to validate, detect format\n2. **step-v-02-format-detection** — Format classification and structure analysis\n   - ↳ **step-v-02b-parity-check** — Parity check handler (conditional: auto-loaded for variant/legacy formats)\n3. **step-v-03-density-validation** — Information density validation (wordiness, filler, conciseness)\n4. **step-v-04-brief-coverage-validation** — Product brief coverage validation\n5. **step-v-05-measurability-validation** — Measurability validation (quantified success criteria)\n6. **step-v-06-traceability-validation** — Traceability validation (requirements linkage)\n7. **step-v-07-implementation-leakage-validation** — Implementation leakage detection (technology in requirements)\n8. **step-v-08-domain-compliance-validation** — Domain compliance validation\n9. **step-v-09-project-type-validation** — Project-type compliance validation\n10. **step-v-10-smart-validation** — SMART requirements validation\n11. **step-v-11-holistic-quality-validation** — Holistic quality assessment and rating\n12. **step-v-12-completeness-validation** — Completeness validation\n13. **step-v-13-report-complete** — Final report compilation, summary, and next steps\n\n## Commonly Missed Steps\n\n- ⚠️ **step-v-07-implementation-leakage** — Agents may skip leakage detection since it requires checking FRs/NFRs for technology-specific language. This is a critical quality gate.\n- ⚠️ **step-v-11-holistic-quality** — The holistic assessment provides the overall quality rating. Skipping it means no overall score.\n- ⚠️ **step-v-13-report-complete** — Final report step that compiles all findings and presents actionable options (edit, review, fix). Must not be skipped.\n- ⚠️ **Each validation step must be executed sequentially** — agents may try to batch multiple validations together. Each step must complete fully before the next begins.\n\n## Replit Task List Integration\n\n**MANDATORY on activation:** Before beginning Step 1, create a Replit task list using the `write_task_list` tool with one task per workflow step listed above (13 sequential steps; if step-v-02b parity check is triggered, add it as a task dynamically). Each task should include the step number and name (e.g., \"Step 1: Discovery — Discover and load the PRD to validate\"). Mark the first task as `in_progress`. As you complete each step, immediately mark its task as `completed` (architect_reviewed: \"not_applicable\", reason: \"BMAD workflow step — planning/facilitation, not code\") and mark the next task as `in_progress`. This gives the user visible progress tracking throughout the workflow.\n\n## Critical Rules\n\n- NEVER skip steps or optimize the sequence\n- NEVER auto-proceed past WAIT points — stop and wait for user input\n- ALWAYS read each step file completely before taking action\n- ALWAYS follow step-file architecture: load one step at a time, never look ahead\n- ALWAYS halt at menus and wait for user selection\n- Recommend using a different high-quality LLM for validation if available\n- Each validation step must produce findings independently — do not batch\n\n## What''s Next\n\nAfter validating a PRD, the typical next steps are:\n- If issues found: **Edit PRD (EP)** — fix the identified problems\n- If passed: **Create Architecture (CA)** or **Create UX (CU)**\n"},"lastSynced":"2026-03-07T03:15:11.799Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing comprehensive PRD validation against BMAD standards","zh":"非常适合需要对PRD进行全面验证的开发代理，验证标准基于BMAD","ja":"BMAD規格への対応を必要とする開発エージェントにとって最適です。","ko":"BMAD 표준에 대한 철저한 PRD 검증이 필요한 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan una validación de PRD integral contra los estándares de BMAD","fr":"Parfait pour les agents de développement nécessitant une validation de PRD complète contre les normes BMAD","de":"Perfekt für Entwicklungsmittel, die eine umfassende PRD-Validierung gegen die BMAD-Standards benötigen","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de validação abrangente do PRD contra os padrões BMAD","ru":"Идеально подходит для агентов разработки, которым необходима комплексная проверка PRD на соответствие стандартам BMAD","ar":"مثالي للوكلاء الناشئين الذين يحتاجون إلى التحقق الشامل من وثائق مواصفات المنتج مقابل معايير BMAD"},"recommendation":{"en":"Empowers agents to review existing PRDs through a comprehensive quality assessment, utilizing step-file architecture and configuration loading from config.yaml, to ensure adherence to BMAD standards and best practices","zh":"赋予代理查看现有PRD的能力，通过全面质量评估，利用步骤文件架构和从config.yaml加载配置，确保遵循BMAD标准和最佳实践","ja":"エージェントが既存のPRDを確認する機能を提供し、ステップファイルアーキテクチャとconfig.yamlからの設定読み込みを使用して、包括的な品質評価を行い、BMAD規格とベストプラクティスに準拠することを保証します。","ko":"에이전트가 기존 PRD를 검토할 수 있는 기능을 제공하며, 단계 파일 아키텍처와 config.yaml에서 설정을 로드하여 포괄적인 품질 평가를 수행하여 BMAD 표준 및 최선의实践을 준수하도록 합니다.","es":"Habilita a los agentes a revisar los PRD existentes a través de una evaluación de calidad integral, utilizando la arquitectura de archivos de paso y la carga de configuración desde config.yaml, para garantizar el cumplimiento de los estándares y las mejores prácticas de BMAD","fr":"Équipe les agents pour examiner les PRD existants via une évaluation de qualité complète, en utilisant l''architecture de fichiers de pas et le chargement de la configuration à partir de config.yaml, pour assurer le respect des normes et des meilleures pratiques de BMAD","de":"Ermächtigt die Mittel, bestehende PRDs durch eine umfassende Qualitätsbewertung zu überprüfen, die Schritt-Datei-Architektur und die Konfigurationsladung aus config.yaml nutzt, um die Einhaltung der BMAD-Standards und -Best-Practices sicherzustellen","pt":"Habilita os agentes a revisar os PRDs existentes por meio de uma avaliação de qualidade abrangente, utilizando arquitetura de arquivo de etapas e carregamento de configuração do config.yaml, para garantir a adesão aos padrões BMAD e às melhores práticas","ru":"Предоставляет агентам возможность просматривать существующие PRD через комплексную оценку качества, используя архитектуру файла шагов и загрузку конфигурации из config.yaml, для обеспечения соответствия стандартам BMAD и передовым практикам","ar":"تمكّن الوكلاء من استعراض وثائق مواصفات المنتج الحالية من خلال تقييم جودة شامل، باستخدام هندسة ملف خطوة وتحميل التكوين من config.yaml، لضمان الامتثال لمعايير BMAD وأفضل الممارسات"},"useCases":{"en":["Validating PRDs against BMAD standards","Automating quality assessments for development teams","Ensuring compliance with BMAD workflow guidelines"],"zh":["验证PRD是否符合BMAD标准","为开发团队自动化质量评估","确保遵循BMAD工作流指南"],"ja":["PRDをBMAD規格に従って検証する","開発チームの品質評価を自動化する","BMADワークフローガイドラインに従うことを保証する"],"ko":["PRD를 BMAD 표준에 따라 검증한다","개발 팀의 품질 평가를 자동화한다","BMAD 워크플로 가이드라인을 준수한다"],"es":["Validar PRDs contra los estándares de BMAD","Automatizar las evaluaciones de calidad para los equipos de desarrollo","Garantizar el cumplimiento de las directrices de flujo de trabajo de BMAD"],"fr":["Valider les PRD contre les normes BMAD","Automatiser les évaluations de qualité pour les équipes de développement","Assurer le respect des lignes directrices de workflow BMAD"],"de":["PRDs gegen die BMAD-Standards validieren","Qualitätsbewertungen für Entwicklungsteams automatisieren","Die Einhaltung der BMAD-Workflow-Richtlinien sicherstellen"],"pt":["Validar PRDs contra os padrões BMAD","Automatizar avaliações de qualidade para equipes de desenvolvimento","Garantir conformidade com diretrizes de fluxo de trabalho BMAD"],"ru":["Проверка PRD на соответствие стандартам BMAD","Автоматизация оценок качества для команд разработки","Обеспечение соблюдения рекомендаций по рабочему процессу BMAD"],"ar":["التحقق من وثائق مواصفات المنتج مقابل معايير BMAD","توفير تقييمات جودة آليّة للفرق الناشئة","ضمان الامتثال لإرشادات سير عمل BMAD"]},"limitations":{"en":["Requires access to _bmad/bmm/config.yaml and _bmad/bmm/workflows/2-plan-workflows/create-prd/workflow-validate-prd.md","Limited to BMAD PRD Validation workflow"],"zh":["需要访问_bmad/bmm/config.yaml和_bmad/bmm/workflows/2-plan-workflows/create-prd/workflow-validate-prd.md","仅限BMAD PRD验证工作流"],"ja":["_bmad/bmm/config.yamlおよび_bmad/bmm/workflows/2-plan-workflows/create-prd/workflow-validate-prd.mdへのアクセスが必要","BMAD PRD検証ワークフローに限定される"],"ko":["_bmad/bmm/config.yaml 및 _bmad/bmm/workflows/2-plan-workflows/create-prd/workflow-validate-prd.md에 접근해야 함","BMAD PRD検証 워크플로우로 제한됨"],"es":["Requiere acceso a _bmad/bmm/config.yaml y _bmad/bmm/workflows/2-plan-workflows/create-prd/workflow-validate-prd.md","Limitado al flujo de trabajo de validación de PRD de BMAD"],"fr":["Nécessite l''accès à _bmad/bmm/config.yaml et _bmad/bmm/workflows/2-plan-workflows/create-prd/workflow-validate-prd.md","Limité au workflow de validation de PRD BMAD"],"de":["Erfordert Zugriff auf _bmad/bmm/config.yaml und _bmad/bmm/workflows/2-plan-workflows/create-prd/workflow-validate-prd.md","Begrenzt auf den BMAD-PRD-Validierungs-Workflow"],"pt":["Requer acesso a _bmad/bmm/config.yaml e _bmad/bmm/workflows/2-plan-workflows/create-prd/workflow-validate-prd.md","Limitado ao fluxo de trabalho de validação do PRD do BMAD"],"ru":["Требует доступа к _bmad/bmm/config.yaml и _bmad/bmm/workflows/2-plan-workflows/create-prd/workflow-validate-prd.md","Ограничен рабочим процессом проверки PRD BMAD"],"ar":["يتطلب الوصول إلى _bmad/bmm/config.yaml و _bmad/bmm/workflows/2-plan-workflows/create-prd/workflow-validate-prd.md","محدود بتدفق عمل التحقق من وثائق مواصفات المنتج BMAD"]},"version":4},"contentHash":"1cea6cd7265bac89d5b4015f1d39eda0943013094361bdb77234eaa3104385b1","qualityScore":35}');
