INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('lushly-dev/afd/run-dev-checks', 'run-dev-checks', 'lushly-dev', 'afd', 'community', 'run-dev-checks lushly-dev afd community The run-dev-checks skill provides expert guidance for botcore''s development command suite, supporting language-aware linting, testing, and building for Python, TypeScript, and Rust. It benefits developers by validating code quality and analyzing code structure. run-dev-checks AI工具提供语言感知命令、代码质量检查和代码结构分析等功能 開発チェックを実行し、コードの品質と構造を改善するためのAIエージェント 개발 체크를 실행하고 코드 품질 및 구조를 분석하는 AI 도구 run-dev-checks es una herramienta de desarrollo que ejecuta comandos de linter, pruebas y compilación para Python, TypeScript y Rust run-dev-checks est un outil de développement qui exécute des commandes de linter, de tests et de compilation pour Python, TypeScript et Rust run-dev-checks ist ein Entwicklungstool, das Befehle für Linter, Tests und Kompilierung für Python, TypeScript und Rust ausführt O run-dev-checks é uma ferramenta de desenvolvimento de código que executa linting, testes e análise estática para garantir a qualidade do código Run-dev-checks - это инструмент для разработки кода, который выполняет линтинг, тестирование и статический анализ для обеспечения качества кода с ИИ Агентами run-dev-checks هو أداة تطوير كود تقوم بتنفيذ لينتينج واختبار وتحليل ثابت لضمان جودة الكود مع وكلاء الذكاء الاصطناعي how to use run-dev-checks run-dev-checks setup guide run-dev-checks alternative run-dev-checks vs linting tools what is run-dev-checks run-dev-checks install automated code quality tools language-aware development tools botcore development command suite AI工具 开发检查 语言感知命令 代码质量检查 代码结构分析 Python开发 TypeScript开发 Rust开发 Executes lint, test, and build commands using the correct tool for detected languages (Python, TypeScript, Rust) Validates file sizes, test coverage, and dependency freshness against configurable thresholds Analyzes code structure to find dead code and circular imports Supports language-aware testing and building Provides quality gates for ensuring code quality Performs static analysis for improved code maintenance run-dev-checks is a development tool that executes language-aware commands, checks code quality, and analyzes code structure to ensure high-quality codebases.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ModelsLab/docs-v2/Mod', 'community', 'ModelsLab', 'docs-v2', 'ModelsLab/docs-v2', 'Mod', 0, 0, 34, '2026-03-05T13:43:31Z', '2026-03-07T13:12:24.197Z', '94886853ba503864ae73896b2386c92e50fc60565c09bf5c751aeaf824332155', '{"id":"ModelsLab/docs-v2/Mod","name":"Mod","description":{"en":"Mod enables agents to leverage AI generation APIs for creating visual, audio, and textual content. It supports ModelsLab documentation and benefits AI agents.","zh":"Mod 是 ModelsLab 官方仓库的文档，提供了 AI 生成 API 的技术细节和集成方法","ja":"Mod は ModelsLab 公式リポジトリのドキュメントであり、AI 生成 API の技術的な詳細と統合方法を提供する","ko":"Mod 는 ModelsLab 공식 리포지토리의 문서로 AI 생성 API 의 기술 세부 사항과 통합 방법을 제공","es":"Mod es una plataforma que permite a los agentes de IA aprovechar una suite completa de API de generación de AI para crear y transformar contenido","fr":"Mod est une plateforme qui permet aux outils d''IA d''exploiter une gamme complète d''API de génération d''IA pour créer et transformer du contenu","de":"Mod ist eine Plattform, die es KI-Agents ermöglicht, eine umfassende Suite von AI-Generierungs-APIs zu nutzen, um Inhalte zu erstellen und zu transformieren","pt":"O Mod é uma ferramenta oficial para documentação de ModelsLab, permitindo que os desenvolvedores usem APIs de geração de conteúdo avançadas.","ru":"Mod — официальный репозиторий документации ModelsLab, позволяющий разработчикам использовать продвинутые API для создания контента.","ar":"Mod هو مستودع وثائق ModelsLab الرسمي، يتيح للمطورين استخدام واجهات برمجة تطبيقات متقدمة لإنشاء المحتوى"},"seo":{"title":{"en":"Mod: Comprehensive AI Generation API Setup Guide | AI Age...","zh":"Mod_SETUP GUIDE: ModelsLab AI 生成 API 集成","ja":"Mod セットアップガイド: ModelsLab AI エージェントの生成 API","ko":"Mod Setup Guide: ModelsLab AI 에이전트 생성 API 통합","es":"Guía de configuración de Mod para Agentes de IA","fr":"Guide de mise en place de Mod pour les Outils d''IA","de":"Einrichtungsleitfaden für Mod in KI-Agents","pt":"Guia de Configuração do Mod para Desenvolvedores","ru":"Настройка Mod: Руководство для Разработчиков ИИ Агентов","ar":"دليل تنصيب Mod للعاملين بالإصدارات الجديدة من أدوات الذكا..."},"description":{"en":"Unlock advanced AI capabilities with Mod! Explore the official ModelsLab documentation and discover how to integrate REST APIs and MCP for seamless content c...","zh":"了解 Mod 的技术细节和 ModelsLab AI 生成 API 的集成方法，实现视觉、音频和文本内容的创建和转换","ja":"Mod の技術的な詳細と ModelsLab AI エージェントの生成 API の統合方法を学び、視覚、音声、テキストコンテンツの作成と変換を実現する","ko":"Mod 의 기술 세부 사항과 ModelsLab AI 에이전트의 생성 API 통합 방법을 학습하여 시각, 음성 및 텍스트 콘텐츠의 생성 및 변환을 구현","es":"Descubre cómo configurar Mod para aprovechar al máximo las API de generación de AI para contenido visual, de audio y textual","fr":"Découvrez comment configurer Mod pour exploiter pleinement les API de génération d''IA pour le contenu visuel, audio et textuel","de":"Erfahren Sie, wie Sie Mod einrichten, um die AI-Generierungs-APIs für visuellen, Audio- und Textinhalt optimal zu nutzen","pt":"Aprenda a configurar o Mod para aproveitar ao máximo as APIs de geração de conteúdo de ModelsLab","ru":"Узнайте, как настроить Mod для работы с API ModelsLab и создания контента с помощью ИИ Агентов","ar":"اكتشف كيفية تثبيت Mod لاستخدام واجهات برمجة تطبيقات ModelsLab في مشاريع الذكاء الاصطناعي"},"definition":{"en":"Mod is an official repository for ModelsLab documentation, providing a suite of AI generation APIs for content creation and transformation","zh":"Mod 是 ModelsLab 的官方文档，提供 AI 生成 API 的技术细节和集成方法","ja":"Mod は ModelsLab の公式ドキュメントであり、AI 生成 API の技術的な詳細と統合方法を提供する","ko":"Mod 는 ModelsLab 의 공식 문서로 AI 생성 API 의 기술 세부 사항과 통합 방법을 제공","es":"Mod es un conjunto de API de generación de AI para crear y transformar contenido visual, de audio y textual","fr":"Mod est un ensemble d''API de génération d''IA pour créer et transformer du contenu visuel, audio et textuel","de":"Mod ist ein Satz von AI-Generierungs-APIs für die Erstellung und Transformation von visuellem, Audio- und Textinhalt","pt":"O Mod é uma ferramenta de documentação para ModelsLab, oferecendo acesso a APIs de geração de conteúdo de áudio, visual e textual.","ru":"Mod — это инструмент документации для ModelsLab, предоставляющий доступ к API для создания контента аудио, визуального и текстового формата.","ar":"Mod هو أداة وثائق ModelsLab، يوفر إمكانية الوصول إلى واجهات برمجة تطبيقات لإنشاء المحتوى الصوتي والمرئي والنصي"},"features":{"en":["Generates photorealistic images from text using AI generation APIs","Creates videos from descriptions or images via REST APIs","Supports voice cloning and transformation using MCP integration","Performs advanced image editing and generates 3D models","Enables interaction with uncensored language models for seamless content creation"],"zh":["生成 photorealistic 图像","创建视频从描述或图像","克隆和转换语音","生成 3D 模型","高级图像编辑","创建深度伪造视频"],"ja":["写実的な画像の生成","説明または画像からビデオの作成","声のクローンと変換","3D モデルの生成","高度な画像編集","ディープフェイクビデオの作成"],"ko":["写実적인 이미지 생성","설명 또는 이미지에서 비디오 생성","음성 클론 및 변환","3D 모델 생성","고급 이미지 편집","ディープフェイク 비디오 생성"],"es":["Generación de imágenes fotorealistas a partir de texto","Creación de videos a partir de descripciones o imágenes","Clonación y transformación de voces","Generación de modelos 3D","Edición avanzada de imágenes","Integración con protocolo de contexto de modelo (MCP)"],"fr":["Génération d''images photoréalistes à partir de texte","Création de vidéos à partir de descriptions ou d''images","Clonage et transformation de voix","Génération de modèles 3D","Édition avancée d''images","Intégration avec le protocole de contexte de modèle (MCP)"],"de":["Generierung von photorealistischen Bildern aus Text","Erstellung von Videos aus Beschreibungen oder Bildern","Klonen und Transformieren von Stimmen","Generierung von 3D-Modellen","Erweiterte Bildbearbeitung","Integration mit dem Modell-Kontext-Protokoll (MCP)"],"pt":["Geração de imagens fotorealistas a partir de texto","Criação de vídeos a partir de descrições ou imagens","Clonagem e transformação de vozes","Geração de modelos 3D","Edição avançada de imagens","Criação de vídeos deepfake"],"ru":["Генерация фотореалистичных изображений из текста","Создание видео из описаний или изображений","Клонирование и трансформация голосов","Генерация 3D-моделей","Продвинутая редакция изображений","Создание видео deepfake"],"ar":["إنشاء صور فوتوغرافية متقدمة من النص","إنشاء مقاطع فيديو من التعريفات أو الصور","استنساخ و تحويل الأصوات","إنشاء نماذج ثلاثية الأبعاد","التحرير المتقدم للصور","إنشاء مقاطع فيديو من نوع deepfake"]},"keywords":{"en":["how to use Mod for AI generation","Mod alternative for content creation","Mod vs ModelsLab for AI agents","Mod install guide for developers","Mod setup for AI-powered content transformation","what is Mod in AI generation"],"zh":["Mod ModelsLab","AI 生成 API","视觉内容创建","音频内容转换","文本内容生成","REST APIs","MCP 统合","AI エージェント"],"ja":["Mod ModelsLab","AI 生成 API","視覚コンテンツ作成","音声コンテンツ変換","テキストコンテンツ生成","REST APIs","MCP 統合","AI エージェント"],"ko":["Mod ModelsLab","AI 생성 API","시각 콘텐츠 생성","음성 콘텐츠 변환","텍스트 콘텐츠 생성","REST APIs","MCP 통합","AI 에이전트"],"es":["agentes de IA","herramientas de IA","API de generación de AI","contenido visual","contenido de audio","contenido textual","modelos 3D","edición de imágenes","protocolo de contexto de modelo"],"fr":["outils d''IA","agents d''IA","API de génération d''IA","contenu visuel","contenu audio","contenu textuel","modèles 3D","édition d''images","protocole de contexte de modèle"],"de":["KI-Agents","KI-Tools","AI-Generierungs-APIs","visueller Inhalt","Audio-Inhalt","Textinhalt","3D-Modelle","Bildbearbeitung","Modell-Kontext-Protokoll"],"pt":["Mod ModelsLab","APIs de geração de conteúdo","Desenvolvimento de IA","Ferramentas de desenvolvimento de ModelsLab","Geração de imagens","Criação de vídeos","Edição de áudio","Modelos 3D","Desenvolvedores de IA"],"ru":["Mod ModelsLab","API для создания контента","Разработка ИИ","Инструменты разработки ModelsLab","Генерация изображений","Создание видео","Редактирование аудио","3D-модели","Разработчики ИИ Агентов"],"ar":["Mod ModelsLab","واجهات برمجة تطبيقات إنشاء المحتوى","تطوير الذكاء الاصطناعي","أدوات تطوير ModelsLab","إنشاء الصور","إنشاء الفيديو","تحرير الصوت","نماذج ثلاثية الأبعاد","مطورو أدوات الذكاء الاصطناعي"]}},"owner":"ModelsLab","repo":"docs-v2","repoPath":"ModelsLab/docs-v2","stars":0,"forks":0,"updatedAt":"2026-03-05T13:43:31Z","topics":["documentation","modelslab"],"category":"community","skillMd":{"name":"Mod","description":"Documentation and capabilities reference for Mod","version":"1.0","bodyPreview":"## Capabilities\n\nModelsLab enables agents to leverage a comprehensive suite of AI generation APIs for creating and transforming visual, audio, and textual content. Agents can generate photorealistic images from text, create videos from descriptions or images, clone and transform voices, generate 3D models, perform advanced image editing, create deepfake videos, and interact with uncensored language models. The platform supports both REST APIs and MCP (Model Context Protocol) integration for seam","body":"## Capabilities\n\nModelsLab enables agents to leverage a comprehensive suite of AI generation APIs for creating and transforming visual, audio, and textual content. Agents can generate photorealistic images from text, create videos from descriptions or images, clone and transform voices, generate 3D models, perform advanced image editing, create deepfake videos, and interact with uncensored language models. The platform supports both REST APIs and MCP (Model Context Protocol) integration for seamless agent connectivity.\n\n## Skills\n\n### Image Generation\n- **Text-to-Image**: Generate images from text prompts using models like Flux and Stable Diffusion\n  - Endpoint: `POST https://modelslab.com/api/v6/images/text2img`\n  - Parameters: `prompt`, `model_id`, `width`, `height`, `samples`, `num_inference_steps`, `guidance_scale`\n- **Image-to-Image**: Transform existing images based on text descriptions\n- **Inpainting**: Edit specific areas of images using masks\n- **ControlNet**: Generate images with precise control using ControlNet models\n- **Community Models**: Access 10,000+ Stable Diffusion models including DreamBooth and LoRA models\n- **Model Training**: Fine-tune models with LoRA training capabilities\n\n### Image Editing\n- **Qwen Edit**: Edit images using Qwen model with text prompts\n- **Object Removal**: Remove unwanted objects from images\n- **Super Resolution**: Upscale and enhance image quality\n- **Background Removal**: Remove or create masks for image backgrounds\n- **Inpainting/Outpainting**: Fill or extend image areas\n- **Face Generation**: Generate faces with specific characteristics\n- **Image Mixing**: Merge two images together\n- **Mask Creator**: Create masks for specific objects in images\n- **Fashion Overlay**: Apply clothing to model bodies\n- **Head Shot Generation**: Generate professional headshots\n\n### Video Generation\n- **Text-to-Video**: Generate videos from text descriptions using CogVideoX\n- **Image-to-Video**: Animate static images into videos\n- **Text-to-Video Ultra**: High-definition video generation from text\n- **Image-to-Video Ultra**: High-definition video generation from images\n- **Video-to-Video**: Transform existing videos with AI\n- **Watermark Removal**: Remove watermarks from videos\n- **Lip Sync**: Synchronize video with audio for realistic lip movements\n- **Motion Control**: Control video motion using reference videos\n\n### Voice & Audio\n- **Text-to-Speech**: Convert text to natural speech with voice selection\n- **Voice Cloning**: Clone and replicate voices from audio samples\n- **Speech-to-Text**: Transcribe audio to text\n- **Voice-to-Voice**: Transform voices with voice conversion\n- **Music Generation**: Create original music from text descriptions\n- **Sound Effects**: Generate custom sound effects from descriptions\n- **Song Generator**: Create complete songs with AI-generated music\n- **Vocal Isolator**: Extract vocal tracks from music\n- **Lyrics Generator**: Generate song lyrics with AI\n- **Dubbing**: Create professional dubbed audio for videos\n- **Voice Cover**: Generate cover versions of songs\n\n### 3D Generation\n- **Text-to-3D**: Generate 3D models from text prompts\n- **Image-to-3D**: Convert 2D images into 3D models\n- **3D Fetch**: Retrieve processing status and results\n\n### Deepfake & Face Manipulation\n- **Specific Face Swap**: Swap faces in single images\n- **Multiple Face Swap**: Swap all detected faces in images\n- **Single Video Swap**: Swap faces in videos\n- **Specific Video Swap**: Swap specific faces in videos based on reference\n\n### Interior Design\n- **Interior Generation**: Generate home interior designs\n- **Floor Planning**: Generate floor plans from room images\n- **Room Decorator**: Create room designs using text prompts\n- **Exterior Restoration**: Improve exterior building images\n- **Scenario Changer**: Change environment scenarios\n- **Sketch Rendering**: Convert architectural sketches to photorealistic images\n- **Object Removal**: Remove objects from interior images\n- **Interior Mixer**: Add objects from one room to another\n\n### Chat & Language Models\n- **Uncensored Chat**: Engage in unrestricted conversations without censorship\n- **Chat Completions**: Generate responses from prompts with OpenAI SDK compatibility\n- **LLM Chat**: Interact with language models like Llama-3 and DeepSeek\n\n### Utility Functions\n- **Base64 Conversion**: Convert base64 strings to URLs for images, videos, audio, and 3D objects\n- **Image Cropping**: Crop images in base64 format\n- **NSFW Detection**: Check if images or prompts contain NSFW content\n- **Cache Management**: Clear user cache for performance\n- **Subscription Management**: Purchase and manage API subscriptions\n- **Asset Tracking**: Monitor generated assets and request history\n\n## Workflows\n\n### Image Generation Workflow\n1. Prepare text prompt with detailed description\n2. Call `text-to-image` endpoint with model selection (flux, sdxl, etc.)\n3. Receive request ID if processing asynchronously\n4. Poll `fetch-image` endpoint to check status\n5. Retrieve generated image URL from response\n\n### Video Creation from Image Workflow\n1. Prepare source image (URL or base64)\n2. Define motion/transformation description\n3. Call `image-to-video` endpoint with duration and resolution\n4. Monitor processing with `fetch-video` endpoint\n5. Download completed video from returned URL\n\n### Voice Cloning Workflow\n1. Upload reference voice sample via `upload-voice` endpoint\n2. Prepare text content for speech synthesis\n3. Call `text-to-speech` with cloned voice ID\n4. Retrieve audio file from response\n5. Optionally apply voice transformations with `voice-to-voice`\n\n### Interior Design Workflow\n1. Upload room image or sketch\n2. Call appropriate endpoint (interior, floor-planning, room-decorator)\n3. Provide text prompt describing desired changes\n4. Retrieve generated design image\n5. Iterate with additional prompts for refinement\n\n### Multi-Modal Content Creation\n1. Generate base image with `text-to-image`\n2. Create video from image with `image-to-video`\n3. Generate audio with `text-to-speech` or `music-generation`\n4. Optionally add lip-sync with `lip-sync` endpoint\n5. Combine assets into final multimedia content\n\n## Integration\n\n### MCP Web API Integration\nModelsLab provides hosted MCP (Model Context Protocol) integration at `https://modelslab.com/mcp/v7` for seamless agent connectivity:\n- Compatible with Claude Code, OpenCode, Cursor, Continue, and custom MCP clients\n- Authentication via `Authorization: Bearer YOUR_API_KEY` header\n- JSON-RPC 2.0 protocol over HTTP\n- Tools available: `list-models`, `text-to-image`, `image-to-image`, `text-to-video`, `image-to-video`, `text-to-speech`, `speech-to-text`, `chat-completion`, and more\n\n### REST API Integration\n- Base URL: `https://modelslab.com/api/v6/` (standard) or `https://modelslab.com/api/v1/` (workflows)\n- Authentication: Include `key` parameter in request body or use API key header\n- Response format: JSON with status, output URLs, and metadata\n- Async processing: Use fetch endpoints to poll for results\n\n### Webhook Support\n- Configure webhook URLs for automatic result delivery\n- Receive notifications when generation completes\n- Payload includes execution ID, status, output, and completion timestamp\n\n### Client SDKs\nOfficial SDKs available for Python, TypeScript, PHP, Dart, and Go for faster integration\n\n### Workflows API\nCreate custom workflows combining multiple API calls with configurable parameters and responses\n\n## Context\n\n### Authentication\nAll API requests require a ModelsLab API key obtainable from the dashboard at `https://modelslab.com/dashboard/api-keys`. Keys can be passed via request body parameter `key` or HTTP headers.\n\n### Rate Limiting\nDefault rate limits apply per plan tier. Workflows have configurable rate limits (default 10 requests/minute). Exceeding limits returns 429 status with `retry_after` field.\n\n### Model Selection\nModelsLab supports 10,000+ models across categories:\n- **Image**: Flux, Stable Diffusion XL, Stable Diffusion 3, community models\n- **Video**: CogVideoX, AnimateDiff, Runway\n- **Audio**: TTS models, music generation, voice cloning\n- **3D**: Text-to-3D, image-to-3D models\n- **LLM**: Llama-3, DeepSeek, and other language models\n\n### Async Processing\nComplex generations may return processing status. Use fetch endpoints with request ID to poll for completion. Webhook URLs enable push-based notifications instead of polling.\n\n### Image Dimensions\nStandard dimensions: 512x512, 768x768, 1024x1024 pixels. Aspect ratios supported: 1:1, 16:9, 9:16, and custom dimensions within platform limits.\n\n### Enterprise Solutions\nPrivate GPU infrastructure available for enterprise customers with custom pricing, dedicated support, and flexible deployment options. Contact support@modelslab.com for enterprise inquiries.\n\n### Error Handling\nStandard HTTP status codes with JSON error responses. Common codes: 400 (invalid request), 401 (authentication), 429 (rate limit), 500 (server error). Detailed error messages guide troubleshooting.\n\n---\n\n> For additional documentation and navigation, see: https://docs.modelslab.com/llms.txt"},"lastSynced":"2026-03-07T13:12:24.197Z","agentAnalysis":{"suitability":{"en":"Ideal for Media Generation Agents requiring advanced AI-powered content creation capabilities for visual, audio, and textual content.","zh":"适合需要高级AI驱动内容创作能力的媒体生成代理，用于创建视觉、音频和文本内容。","ja":"高度なAIを活用したコンテンツ作成機能を必要とするメディア生成エージェントに適しています。視覚、オーディオ、テキストコンテンツを作成するために使用されます。","ko":"고급 AI 드라이브 콘텐츠 생성 기능이 필요한 미디어 생성 에이전트에게 적합합니다. 시각, 오디오 및 텍스트 콘텐츠를 생성하는 데 사용됩니다.","es":"Ideal para agentes de generación de medios que requieren capacidades de creación de contenido avanzadas con inteligencia artificial para contenido visual, de audio y textual.","fr":"Idéal pour les agents de génération de médias nécessitant des capacités de création de contenu avancées alimentées par l''IA pour le contenu visuel, audio et textuel.","de":"Ideal für Media-Generation-Agents, die erweiterte künstliche Intelligenz-basierte Inhaltserschaffungsfähigkeiten für visuelle, Audio- und textbasierte Inhalte benötigen.","pt":"Ideal para Agentes de Geração de Mídia que requerem capacidades avançadas de criação de conteúdo impulsionadas por IA para conteúdo visual, áudio e textual.","ru":"Идеально подходит для агентов генерации медиа, требующих продвинутых возможностей создания контента на основе ИИ для визуального, аудио и текстового контента.","ar":"مثالية للوكلاء الذين يولدون وسائط متعددة ويتطلبون إمكانيات متقدمة لإنشاء محتوى مدعوم من الذكاء الاصطناعي لوسائط بصرية وسمعية ونصية."},"recommendation":{"en":"Empowers agents to leverage AI generation APIs for creating photorealistic images, videos, and 3D models, while supporting REST APIs and Model Context Protocol (MCP) integration for seamless interaction with uncensored language models and advanced image editing.","zh":"赋予代理使用AI生成API创建照片真实的图像、视频和3D模型的能力，同时支持REST APIs和模型上下文协议（MCP）集成，以实现与无审查语言模型和高级图像编辑的无缝交互。","ja":"エージェントにAI生成APIを使用して写真のような画像、動画、3Dモデルを作成する能力を付与し、REST APIやモデルコンテキストプロトコル（MCP）などのプロトコルをサポートして、検閲のない言語モデルや高度な画像編集とのシームレスなやり取りを可能にします。","ko":"에이전트가 AI 생성 API를 사용하여 사진과 같은 이미지, 동영상 및 3D 모델을 생성할 수 있는 기능을 부여하며, REST API 및 모델 컨텍스트 프로토콜(MCP)과 같은 프로토콜을 지원하여 검열되지 않은 언어 모델 및 고급 이미지 편집과 원활한 상호 작용을 가능하게 합니다.","es":"Habilita a los agentes a aprovechar las APIs de generación de IA para crear imágenes fotorealistas, videos y modelos 3D, al tiempo que admite la integración de APIs REST y Protocolo de Contexto de Modelo (MCP) para una interacción sin problemas con modelos de lenguaje sin censura y edición de imágenes avanzada.","fr":"Permet aux agents d''exploiter les API de génération d''IA pour créer des images photoréalistes, des vidéos et des modèles 3D, tout en prenant en charge l''intégration des API REST et du Protocole de Contexte de Modèle (MCP) pour une interaction sans accroc avec des modèles de langage non censurés et une édition d''images avancée.","de":"Ermöglicht es Agenten, AI-Generation-APIs für die Erstellung photorealistischer Bilder, Videos und 3D-Modelle zu nutzen, während sie gleichzeitig die Integration von REST-APIs und Modellkontextprotokoll (MCP) für eine nahtlose Interaktion mit unzensierten Sprachmodellen und erweiterter Bildbearbeitung unterstützt.","pt":"Habilita os agentes a aproveitar APIs de geração de IA para criar imagens fotorealistas, vídeos e modelos 3D, além de suportar integração de APIs REST e Protocolo de Contexto de Modelo (MCP) para interação sem problemas com modelos de linguagem não censurados e edição de imagem avançada.","ru":"Позволяет агентам использовать API генерации ИИ для создания фотorealалистических изображений, видео и 3D-моделей, а также поддерживает интеграцию с REST API и протоколом контекста модели (MCP) для беспрепятственного взаимодействия с нецензурированными языковыми моделями и продвинутым редактором изображений.","ar":"تمكّن الوكلاء من الاستفادة من واجهات برمجة تطبيقات توليد الذكاء الاصطناعي لإنشاء صور واضحة للغاية وأفلام وصور ثلاثية الأبعاد، مع دعم تكامل واجهة برمجة تطبيقات REST وبروتوكول سياق النموذج (MCP) من أجل التفاعل السلس مع نماذج اللغة غير الخاضعة للرقابة وتحرير الصور المتقدم."},"useCases":{"en":["Generating photorealistic images from text descriptions","Creating videos from image or text inputs using AI generation APIs","Transforming voices and generating deepfake videos for multimedia applications"],"zh":["从文本描述生成照片真实的图像","使用AI生成API从图像或文本输入创建视频","将声音转换并为多媒体应用程序生成深度伪造视频"],"ja":["テキストの説明から写真のような画像を生成する","AI生成APIを使用して画像またはテキストの入力から動画を作成する","音声を変換し、多媒体アプリケーションのためにディープフェイク動画を生成する"],"ko":["텍스트 설명에서 사진과 같은 이미지를 생성하는 것","AI 생성 API를 사용하여 이미지 또는 텍스트 입력에서 동영상 생성","소리를 변환하고 멀티미디어 애플리케이션을 위한 디ープ페이크 동영상 생성"],"es":["Generar imágenes fotorealistas a partir de descripciones de texto","Crear videos a partir de imágenes o entradas de texto utilizando APIs de generación de IA","Transformar voces y generar videos deepfake para aplicaciones multimedia"],"fr":["Générer des images photoréalistes à partir de descriptions de texte","Créer des vidéos à partir d''images ou d''entrées de texte en utilisant des API de génération d''IA","Transformer des voix et générer des vidéos deepfake pour des applications multimédia"],"de":["Erstellung photorealistischer Bilder aus Textbeschreibungen","Erstellen von Videos aus Bild- oder Texteingaben mit Hilfe von AI-Generation-APIs","Transformieren von Stimmen und Erstellen von Deepfake-Videos für Multimedia-Anwendungen"],"pt":["Gerar imagens fotorealistas a partir de descrições de texto","Criar vídeos a partir de entradas de imagem ou texto usando APIs de geração de IA","Transformar vozes e gerar vídeos deepfake para aplicações multimídia"],"ru":["Генерировать фотorealалистические изображения из текстовых описаний","Создавать видео из входных данных изображений или текста с помощью API генерации ИИ","Преобразовывать голоса и генерировать видео deepfake для мультимедийных приложений"],"ar":["توليد صور واضحة للغاية من وصف النص","إنشاء مقاطع فيديو من مدخلات الصورة أو النص باستخدام واجهات برمجة تطبيقات توليد الذكاء الاصطناعي","تحويل الأصوات وتوليد مقاطع فيديو وهمية لغرض التطبيقات المتعددة الوسائط"]},"limitations":{"en":["Requires access to AI generation APIs","Supports ModelsLab documentation and specific integration protocols like MCP"],"zh":["需要访问AI生成API","支持ModelsLab文档和特定的集成协议，如MCP"],"ja":["AI生成APIへのアクセスが必要","ModelsLabのドキュメントやMCPなどの特定の統合プロトコルをサポート"],"ko":["AI 생성 API에 대한 액세스가 필요","ModelsLab 문서 및 MCP와 같은 특정 통합 프로토콜 지원"],"es":["Requiere acceso a APIs de generación de IA","Admite la documentación de ModelsLab y protocolos de integración específicos como MCP"],"fr":["Nécessite un accès aux API de génération d''IA","Prend en charge la documentation de ModelsLab et des protocoles d''intégration spécifiques comme MCP"],"de":["Benötigt Zugriff auf AI-Generation-APIs","Unterstützt ModelsLab-Dokumentation und spezifische Integrationsprotokolle wie MCP"],"pt":["Requer acesso a APIs de geração de IA","Suporta documentação do ModelsLab e protocolos de integração específicos como o MCP"],"ru":["Требует доступа к API генерации ИИ","Поддерживает документацию ModelsLab и конкретные протоколы интеграции, такие как MCP"],"ar":["يتطلب الوصول إلى واجهات برمجة تطبيقات توليد الذكاء الاصطناعي","يدعم وثائق ModelsLab وبروتوكولات التكامل المحددة مثل MCP"]},"version":4},"contentHash":"94886853ba503864ae73896b2386c92e50fc60565c09bf5c751aeaf824332155","qualityScore":34}');
