INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jbabin91/autocomplete-rs/beads-workflow', 'beads-workflow', 'jbabin91', 'autocomplete-rs', 'community', 'beads-workflow jbabin91 autocomplete-rs community The beads-workflow skill is a fast, intelligent shell completion engine written in Rust, designed to optimize task management for AI coding agents. It benefits developers by converting markdown plans into implementation-ready tasks. Beads Workflow 是一个快速、智能的 Shell 完成引擎，用于将 markdown 计划转换为可执行任务。它支持 AI 编码代理的高效协作 Beads Workflow は、Markdown 計画を実行可能なタスクに変換する高速な AI エージェント シェル完了エンジンです。AI エージェントの効率的な協力をサポートします Beads Workflow는 markdown 계획을 실행 가능한 태스크로 변환하는 고성능 AI 에이전트 셸 완성 엔진입니다. AI 에이전트의 효율적인 협력을 지원합니다 Beads Workflow es un motor de autocompletado de shell inteligente escrito en Rust para agentes de codificación de IA. Optimiza epics, tareas y subtareas con estructura de dependencia Beads Workflow est un moteur de complétion de shell intelligent écrit en Rust pour les agents de codage IA. Il optimise les épopées, les tâches et les sous-tâches avec une structure de dépendance Beads Workflow ist ein schneller, intelligenter Shell-Vervollständigungs-Engine in Rust für IA-Coding-Agenten. Es optimiert Epics, Tasks und Subtasks mit Abhängigkeitsstruktur O Beads-Workflow é um motor de conclusão de shell inteligente em Rust, projetado para otimizar a produtividade de codificação em equipes de agentes de código Claude Beads-Workflow - это быстрый ИИ Агенты движок завершения shell на Rust, предназначенный для оптимизации производительности кодирования в командах агентов кода Claude Beads-Workflow هو محرك استكمال Shell الذكي المكتوب بلغة Rust، مصمم لتحسين إنتاجية كتابة الشفرة في فرق وكلاء كلود كود how to use beads-workflow beads-workflow alternative beads-workflow setup guide what is beads-workflow beads-workflow vs Linear beads-workflow install beads-workflow for AI agents Rust-based task management markdown plan conversion Claude Code agent teams Beads Workflow Rust AI 编码代理 Shell 完成引擎 markdown 计划 可执行任务 AI 工具 代码生成 Converts markdown plans into beads with dependency structure Iteratively polishes tasks across multiple rounds and models Coordinates parallel execution via Claude Code agent teams Optimizes task management for AI coding agents Written in Rust for high performance Supports full lifecycle task management beads-workflow is a task management system that utilizes a dependency structure, allowing for the conversion of markdown plans into self-contained tasks for AI agents.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('timurb/cli2docker/openspec-main-spec-format', 'community', 'timurb', 'cli2docker', 'timurb/cli2docker', 'openspec-main-spec-format', 0, 0, 34, '2026-03-08T01:57:15.379Z', '2026-03-08T02:05:34.407Z', 'e24e7ff82a3bab4e9c38596ca38db0bb8414077b9fbe6c388daeba05628694ae', '{"id":"timurb/cli2docker/openspec-main-spec-format","name":"openspec-main-spec-format","description":{"en":"The openspec-main-spec-format skill enables developers to create and update capability docs using a split-file format, enhancing security with Docker containerization. It benefits developers working with npm utils and Docker.","zh":"openspec-main-spec-format是一种使用Docker容器安装CLI npm utils的方法，提高了安全性。它包括规范测试、功能概述和使用场景等内容","ja":"openspec-main-spec-formatは、Dockerコンテナを使用してCLI npm utilsをインストールする方法で、セキュリティを強化します。規範テスト、機能概要、使用シナリオなどを含みます","ko":"openspec-main-spec-format는 Docker 컨테이너를 사용하여 CLI npm utils를 설치하는 방법으로, 보안을 강화합니다. 규범 테스트, 기능 개요, 사용 시나리오 등을 포함합니다","es":"openspec-main-spec-format es un formato de especificación que utiliza un archivo dividido para documentar capacidades, con archivos spec.md y feature.md para pruebas normativas y descripciones de características","fr":"openspec-main-spec-format est un format de spécification qui utilise un fichier divisé pour documenter les capacités, avec des fichiers spec.md et feature.md pour les tests normatifs et les descriptions de fonctionnalités","de":"openspec-main-spec-format ist ein Spezifikationsformat, das eine Datei mit getrennten Abschnitten zur Dokumentation von Fähigkeiten verwendet, mit Dateien spec.md und feature.md für normative Tests und Funktionsbeschreibungen","pt":"O openspec-main-spec-format é um formato de especificação que utiliza contêineres Docker para melhorar a segurança. Ele inclui normas de teste e requisitos para desenvolvedores","ru":"openspec-main-spec-format - это формат спецификации, использующий контейнеры Docker для повышения безопасности. Он включает нормы тестирования и требования для разработчиков с ИИ Агентами","ar":"openspec-main-spec-format هو تنسيق مواصفات يستخدم حاويات Docker لتحسين الأمان. يتضمن معايير الاختبار والمتطلبات لل مطورين مع أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"openspec-main-spec-format: Docker Container Setup Guide |...","zh":"openspec-main-spec-format 安装指南：使用Docker容器增强安全性","ja":"openspec-main-spec-format セットアップガイド：Dockerコンテナによるセキュリティの強化","ko":"openspec-main-spec-format 설치 가이드: Docker 컨테이너를 사용한 보안 강화","es":"Guía de configuración de openspec-main-spec-format para/d...","fr":"Guide d''installation d''openspec-main-spec-format avec Docker","de":"Einrichtungsleitfaden für openspec-main-spec-format mit D...","pt":"Guia de Configuração do openspec-main-spec-format para Se...","ru":"Установка openspec-main-spec-format: Руководство по Безоп...","ar":"دليل إعداد openspec-main-spec-format لتحسين الأمان مع أدو..."},"description":{"en":"Learn how to install CLI npm utils as a Docker container for enhanced security with openspec-main-spec-format. Get started with our expert guide today!","zh":"了解openspec-main-spec-format的安装和配置，使用Docker容器提高CLI npm utils的安全性，AIエージェント","ja":"openspec-main-spec-formatのインストールと設定方法を学び、Dockerコンテナを使用してCLI npm utilsのセキュリティを強化する、AIエージェント","ko":"openspec-main-spec-format의 설치와 설정 방법을 알아보고, Docker 컨테이너를 사용하여 CLI npm utils의 보안을 강화하는 방법, AI 도구","es":"Aprende a instalar openspec-main-spec-format como contenedor Docker para mejorar la seguridad y seguir las mejores prácticas de desarrollo","fr":"Découvrez comment installer openspec-main-spec-format en tant que conteneur Docker pour améliorer la sécurité et suivre les meilleures pratiques de développe...","de":"Erfahren Sie, wie Sie openspec-main-spec-format als Docker-Container installieren, um die Sicherheit zu erhöhen und die besten Entwicklungspraktiken zu befolgen","pt":"Aprenda a instalar o openspec-main-spec-format como contêiner Docker para melhorar a segurança e seguir as melhores práticas de desenvolvimento","ru":"Узнайте, как установить openspec-main-spec-format в качестве контейнера Docker для повышения безопасности и следования рекомендациям по разработке с ИИ Агентами","ar":"تعرف على كيفية تثبيت openspec-main-spec-format كحاوية Docker لتحسين الأمان ومتابعة أفضل الممارسات التطويرية مع أدوات الذكاء الاصطناعي"},"definition":{"en":"openspec-main-spec-format is a specification format for creating and updating capability docs using a split-file format, with increased security through Docker containerization.","zh":"openspec-main-spec-format是一种使用Docker容器安装CLI npm utils的格式，用于提高安全性和规范测试","ja":"openspec-main-spec-formatは、Dockerコンテナを使用してCLI npm utilsをインストールするためのフォーマットで、セキュリティと規範テストを強化するために使用されます","ko":"openspec-main-spec-format는 Docker 컨테이너를 사용하여 CLI npm utils를 설치하는 형식으로, 보안과 규범 테스트를 강화하는 데 사용됩니다","es":"openspec-main-spec-format es un formato de archivo que combina spec.md y feature.md para documentar capacidades de manera estructurada","fr":"openspec-main-spec-format est un format de fichier qui combine spec.md et feature.md pour documenter les capacités de manière structurée","de":"openspec-main-spec-format ist ein Dateiformat, das spec.md und feature.md kombiniert, um Fähigkeiten strukturiert zu dokumentieren","pt":"O que é openspec-main-spec-format? É um formato de especificação de software que utiliza contêineres Docker para melhorar a segurança","ru":"Что такое openspec-main-spec-format? Это формат спецификации программного обеспечения, использующий контейнеры Docker для повышения безопасности с ИИ Агентами","ar":"ما هو openspec-main-spec-format؟ هو تنسيق مواصفات البرمجيات الذي يستخدم حاويات Docker لتحسين الأمان مع أدوات الذكاء الاصطناعي"},"features":{"en":["Utilizes a split-file format with spec.md and feature.md files","Supports normative tests and black + white box testing in a single file","Enables linking to sibling docs using markdown links","Includes requirements and scenarios in spec.md files","Allows for overview and context documentation in feature.md files","Supports Docker containerization for increased security"],"zh":["使用Docker容器安装CLI npm utils","规范测试和功能概述","使用场景和成功标准","支持分文件格式（spec.md和feature.md）","提高安全性和可靠性"],"ja":["Dockerコンテナを使用してCLI npm utilsをインストール","規範テストと機能概要","使用シナリオと成功標準","分ファイルフォーマット（spec.mdとfeature.md）をサポート","セキュリティと信頼性を強化"],"ko":["Docker 컨테이너를 사용하여 CLI npm utils를 설치","규범 테스트와 기능 개요","사용 시나리오와 성공 기준","분 파일 형식（spec.md와 feature.md）을 지원","보안과 신뢰성을 강화"],"es":["Utiliza un formato de archivo dividido para documentar capacidades","Incluye archivos spec.md para pruebas normativas","Incluye archivos feature.md para descripciones de características","Permite la documentación de flujos de trabajo y escenarios de uso","Soporta la creación de enlaces a documentos hermanos en markdown","Se puede instalar como contenedor Docker para mejorar la seguridad"],"fr":["Utilise un format de fichier divisé pour documenter les capacités","Inclut des fichiers spec.md pour les tests normatifs","Inclut des fichiers feature.md pour les descriptions de fonctionnalités","Permet la documentation de flux de travail et de scénarios d''utilisation","Prend en charge la création de liens à des documents frères en markdown","Peut être installé en tant que conteneur Docker pour améliorer la sécurité"],"de":["Verwendet ein Dateiformat mit getrennten Abschnitten zur Dokumentation von Fähigkeiten","Enthält Dateien spec.md für normative Tests","Enthält Dateien feature.md für Funktionsbeschreibungen","Ermöglicht die Dokumentation von Arbeitsabläufen und Einsatzszenarien","Unterstützt die Erstellung von Verknüpfungen zu Schwesterdokumenten in Markdown","Kann als Docker-Container installiert werden, um die Sicherheit zu erhöhen"],"pt":["Utiliza contêineres Docker para melhorar a segurança","Inclui normas de teste e requisitos para desenvolvedores","Suporta formatos de arquivo split-file para especificações","Permite a criação de documentos de especificação com links para documentos irmãos","Oferece uma estrutura para descrever propósitos, requisitos e cenários de teste"],"ru":["Использует контейнеры Docker для повышения безопасности с ИИ Агентами","Включает нормы тестирования и требования для разработчиков","Поддерживает форматы файлов split-file для спецификаций","Позволяет создавать документы спецификации с ссылками на документы-братья","Предоставляет структуру для описания целей, требований и сценариев тестирования"],"ar":["يستخدم حاويات Docker لتحسين الأمان مع أدوات الذكاء الاصطناعي","يتضمن معايير الاختبار والمتطلبات لل مطورين","يدعم تنسيقات الملفات split-file للمواصفات","يسمح بإنشاء مستندات المواصفات مع روابط لمستندات الشقيقة","يقدم هيكلا لوصف الأهداف والمتطلبات وسيناريوهات الاختبار"]},"keywords":{"en":["how to use openspec-main-spec-format","what is openspec-main-spec-format","openspec-main-spec-format alternative","openspec-main-spec-format vs npm utils","openspec-main-spec-format install","openspec-main-spec-format setup guide","docker containerization for security","npm utils with Docker","split-file format for documentation"],"zh":["openspec-main-spec-format","Docker容器","CLI npm utils","AIエージェント","安全性","规范测试","功能概述","使用场景"],"ja":["openspec-main-spec-format","Dockerコンテナ","CLI npm utils","AIエージェント","セキュリティ","規範テスト","機能概要","使用シナリオ"],"ko":["openspec-main-spec-format","Docker 컨테이너","CLI npm utils","AI 도구","보안","규범 테스트","기능 개요","사용 시나리오"],"es":["openspec-main-spec-format","formato de especificación","documentación de capacidades","pruebas normativas","descripciones de características","Docker","seguridad","mejores prácticas de desarrollo","Herramientas de desarrollo","Agentes de IA"],"fr":["openspec-main-spec-format","format de spécification","documentation de capacités","tests normatifs","descriptions de fonctionnalités","Docker","sécurité","meilleures pratiques de développement","Outils de développement","Agents d''IA"],"de":["openspec-main-spec-format","Spezifikationsformat","Dokumentation von Fähigkeiten","normative Tests","Funktionsbeschreibungen","Docker","Sicherheit","beste Entwicklungspraktiken","Entwicklungstools","KI-Agents"],"pt":["openspec-main-spec-format","contêineres Docker","segurança","desenvolvimento de software","normas de teste","requisitos de desenvolvedores","formatos de arquivo split-file","documentos de especificação"],"ru":["openspec-main-spec-format","контейнеры Docker","безопасность","разработка программного обеспечения","нормы тестирования","требования разработчиков","форматы файлов split-file","документы спецификации","ИИ Агенты"],"ar":["openspec-main-spec-format","حاويات Docker","أمان","تطوير البرمجيات","معايير الاختبار","متطلبات المطورين","تنسيقات الملفات split-file","مستندات المواصفات","أدوات الذكاء الاصطناعي"]}},"owner":"timurb","repo":"cli2docker","repoPath":"timurb/cli2docker","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.379Z","topics":[],"category":"community","skillMd":{"name":"openspec-main-spec-format","description":"Enforce the main OpenSpec spec format with overview, scope, interfaces, and requirements.","version":"1.0","bodyPreview":"When creating or updating capability docs under `openspec/specs/<capability>/`, use a split-file format:\n\n1) `spec.md` (normative tests only)\n   - Purpose (1–3 sentences)\n   - Requirements/Scenarios (normative)\n   - Links to sibling docs (markdown links)\n\n2) `feature.md` (black + white box in one file)\n   - Overview / Context / Problems addressed\n   - Goals / Non-Goals (or In scope / Out of scope)\n   - Usage workflows / scenarios beyond tests\n   - Success criteria (if applicable)\n   - Architectu","body":"When creating or updating capability docs under `openspec/specs/<capability>/`, use a split-file format:\n\n1) `spec.md` (normative tests only)\n   - Purpose (1–3 sentences)\n   - Requirements/Scenarios (normative)\n   - Links to sibling docs (markdown links)\n\n2) `feature.md` (black + white box in one file)\n   - Overview / Context / Problems addressed\n   - Goals / Non-Goals (or In scope / Out of scope)\n   - Usage workflows / scenarios beyond tests\n   - Success criteria (if applicable)\n   - Architecture description\n   - Constraints\n   - Entities\n   - Interfaces (Inputs/Outputs)\n   - Invariants (if applicable)\n   - Events / Triggers\n   - Links to sibling docs (markdown links)\n\nCross-links are recommended in all files:\n- Link to sibling docs within the same capability\n- Link across capabilities when concepts are shared\nUse markdown links (e.g., `[feature](feature.md)`), not backticked filenames.\n\nKeep `spec.md` lean; requirements and scenarios are the normative tests.\n"},"lastSynced":"2026-03-08T02:05:34.407Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing structured documentation capabilities with Docker containerization and npm utils","zh":"非常适合需要结构化文档功能的开发者代理，并支持Docker容器化和npm工具","ja":"構造化ドキュメント機能とDockerコンテナ化、npmユーティリティが必要な開発者エージェントに最適","ko":"구조화된 문서 기능과 Docker 컨테이너화, npm 유틸리티가 필요한 개발자 에이전트에 적합","es":"Perfecto para Agentes de Desarrollador que necesitan capacidades de documentación estructurada con contenedorización de Docker y utilidades de npm","fr":"Parfait pour les agents de développement nécessitant des capacités de documentation structurée avec une conteneurisation Docker et des utilitaires npm","de":"Perfekt für Developer-Agents, die strukturierte Dokumentationsfunktionen mit Docker-Containerisierung und npm-Utils benötigen","pt":"Perfeito para Agentes de Desenvolvedor que necessitam de capacidades de documentação estruturada com containerização do Docker e utils do npm","ru":"Идеально подходит для агентов-разработчиков, которым необходимы возможности структурированной документации с контейнеризацией Docker и утилитами npm","ar":"مثالي لعميل التطوير الذي يحتاج إلى إمكانيات توثيقية منظمة مع حاويات Docker وملحقات npm"},"recommendation":{"en":"Empowers agents to create and update capability docs using a split-file format, enhancing security with Docker and streamlining documentation with normative tests in spec.md and feature descriptions in feature.md","zh":"赋予代理创建和更新能力文档的功能，使用分文件格式，通过Docker增强安全性，并通过spec.md中的规范测试和feature.md中的功能描述简化文档","ja":"エージェントがスプリットファイル形式を使用して機能ドキュメントを作成および更新する機能を提供し、Dockerでセキュリティを強化し、spec.md内の規範テストとfeature.md内の機能説明でドキュメントを簡素化","ko":"에이전트가 분할 파일 형식을 사용하여 기능 문서를 생성하고 업데이트 할 수 있는 기능을 제공하며, Docker로 보안을 강화하고 spec.md의 규范 테스트와 feature.md의 기능 설명으로 문서를 간소화","es":"Habilita a los agentes a crear y actualizar documentación de capacidades utilizando un formato de archivo dividido, mejorando la seguridad con Docker y simplificando la documentación con pruebas normativas en spec.md y descripciones de características en feature.md","fr":"Permet aux agents de créer et de mettre à jour la documentation des capacités en utilisant un format de fichier divisé, améliorant la sécurité avec Docker et simplifiant la documentation avec des tests normatifs dans spec.md et des descriptions de fonctionnalités dans feature.md","de":"Ermöglicht es Agents, Kapazitätsdokumentationen zu erstellen und zu aktualisieren, indem sie ein Split-Dateiformat verwenden, die Sicherheit mit Docker verbessern und die Dokumentation mit normativen Tests in spec.md und Funktionsbeschreibungen in feature.md straffen","pt":"Habilita os agentes a criar e atualizar documentos de capacidade usando um formato de arquivo dividido, melhorando a segurança com o Docker e otimizando a documentação com testes normativos em spec.md e descrições de recursos em feature.md","ru":"Наделяет агентов возможностью создавать и обновлять документы возможностей, используя формат файлаsplit, повышая безопасность с помощью Docker и оптимизируя документацию с нормативными тестами в spec.md и описаниями функций в feature.md","ar":"يمنح الوكلاء القدرة على إنشاء وتحديث وثائق القدرات باستخدام تنسيق ملف منقسم، ومحسين الأمان مع Docker وتبسيط الوثائق مع الاختبارات القائمة على المواصفات في spec.md ووصف الميزات في feature.md"},"useCases":{"en":["Generating capability docs with normative tests","Creating feature descriptions with black and white box testing","Updating specs with Docker containerization for enhanced security"],"zh":["使用规范测试生成能力文档","使用黑盒测试和白盒测试创建功能描述","使用Docker容器化更新规格以增强安全性"],"ja":["規範テストを使用して機能ドキュメントを生成","ブラックボックステストとホワイトボックステストを使用して機能説明を作成","Dockerコンテナ化を使用して規格を更新しセキュリティを強化"],"ko":["규范 테스트를 사용하여 기능 문서를 생성","블랙박스 테스트와 화이트박스 테스트를 사용하여 기능 설명을 생성","Docker 컨테이너화로 규격을 업데이트하여 보안을 강화"],"es":["Generar documentación de capacidades con pruebas normativas","Crear descripciones de características con pruebas de caja blanca y negra","Actualizar especificaciones con contenedorización de Docker para una mayor seguridad"],"fr":["Générer la documentation des capacités avec des tests normatifs","Créer des descriptions de fonctionnalités avec des tests de boîte noire et blanche","Mettre à jour les spécifications avec une conteneurisation Docker pour une sécurité renforcée"],"de":["Erzeugen von Kapazitätsdokumentationen mit normativen Tests","Erstellen von Funktionsbeschreibungen mit schwarzer und weißer Box-Testing","Aktualisieren von Spezifikationen mit Docker-Containerisierung für erhöhte Sicherheit"],"pt":["Geração de documentos de capacidade com testes normativos","Criação de descrições de recursos com testes de caixa preta e branca","Atualização de especificações com containerização do Docker para segurança aprimorada"],"ru":["Генерация документов возможностей с нормативными тестами","Создание описаний функций с белыми и черными ящиками тестирования","Обновление спецификаций с контейнеризацией Docker для повышения безопасности"],"ar":["إنشاء وثائق القدرات مع الاختبارات القائمة على المواصفات","إنشاء وصفات الميزات مع الاختبارات السوداء والبيضاء","تحديث المواصفات مع حاويات Docker لتحسين الأمان"]},"limitations":{"en":["Requires Docker containerization","Specific to npm utils and openspec/specs/ directory structure"],"zh":["需要Docker容器化","特定于npm工具和openspec/specs/目录结构"],"ja":["Dockerコンテナ化が必要","npmユーティリティとopenspec/specs/ディレクトリ構造に特定"],"ko":["Docker 컨테이너화가 필요","npm 유틸리티와 openspec/specs/ 디렉토리 구조에 특정"],"es":["Requiere contenedorización de Docker","Específico para utilidades de npm y estructura de directorio openspec/specs/"],"fr":["Nécessite une conteneurisation Docker","Spécifique aux utilitaires npm et à la structure de répertoire openspec/specs/"],"de":["Benötigt Docker-Containerisierung","Spezifisch für npm-Utils und openspec/specs/-Verzeichnisstruktur"],"pt":["Exige containerização do Docker","Específico para utils do npm e estrutura de diretório openspec/specs/"],"ru":["Требует контейнеризации Docker","Специфичен для утилит npm и структуры каталога openspec/specs/"],"ar":["يتطلب حاويات Docker","محدد لملحقات npm وهيكل الدليل openspec/specs/"]},"version":4},"contentHash":"e24e7ff82a3bab4e9c38596ca38db0bb8414077b9fbe6c388daeba05628694ae","qualityScore":34}');
