INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('timurb/cli2docker/openspec-main-spec-format', 'openspec-main-spec-format', 'timurb', 'cli2docker', 'community', 'openspec-main-spec-format timurb cli2docker community The openspec-main-spec-format skill enables developers to create and update capability docs using a split-file format, enhancing security with Docker containerization. It benefits developers working with npm utils and Docker. openspec-main-spec-format是一种使用Docker容器安装CLI npm utils的方法，提高了安全性。它包括规范测试、功能概述和使用场景等内容 openspec-main-spec-formatは、Dockerコンテナを使用してCLI npm utilsをインストールする方法で、セキュリティを強化します。規範テスト、機能概要、使用シナリオなどを含みます openspec-main-spec-format는 Docker 컨테이너를 사용하여 CLI npm utils를 설치하는 방법으로, 보안을 강화합니다. 규범 테스트, 기능 개요, 사용 시나리오 등을 포함합니다 openspec-main-spec-format es un formato de especificación que utiliza un archivo dividido para documentar capacidades, con archivos spec.md y feature.md para pruebas normativas y descripciones de características openspec-main-spec-format est un format de spécification qui utilise un fichier divisé pour documenter les capacités, avec des fichiers spec.md et feature.md pour les tests normatifs et les descriptions de fonctionnalités openspec-main-spec-format ist ein Spezifikationsformat, das eine Datei mit getrennten Abschnitten zur Dokumentation von Fähigkeiten verwendet, mit Dateien spec.md und feature.md für normative Tests und Funktionsbeschreibungen O openspec-main-spec-format é um formato de especificação que utiliza contêineres Docker para melhorar a segurança. Ele inclui normas de teste e requisitos para desenvolvedores openspec-main-spec-format - это формат спецификации, использующий контейнеры Docker для повышения безопасности. Он включает нормы тестирования и требования для разработчиков с ИИ Агентами openspec-main-spec-format هو تنسيق مواصفات يستخدم حاويات Docker لتحسين الأمان. يتضمن معايير الاختبار والمتطلبات لل مطورين مع أدوات الذكاء الاصطناعي how to use openspec-main-spec-format what is openspec-main-spec-format openspec-main-spec-format alternative openspec-main-spec-format vs npm utils openspec-main-spec-format install openspec-main-spec-format setup guide docker containerization for security npm utils with Docker split-file format for documentation openspec-main-spec-format Docker容器 CLI npm utils AIエージェント 安全性 规范测试 功能概述 使用场景 Utilizes a split-file format with spec.md and feature.md files Supports normative tests and black + white box testing in a single file Enables linking to sibling docs using markdown links Includes requirements and scenarios in spec.md files Allows for overview and context documentation in feature.md files Supports Docker containerization for increased security openspec-main-spec-format is a specification format for creating and updating capability docs using a split-file format, with increased security through Docker containerization.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sylin-org/koi/explore', 'community', 'sylin-org', 'koi', 'sylin-org/koi', 'explore', 0, 0, 34, '2026-03-05T06:20:06.292Z', '2026-03-05T08:33:19.159Z', '27206e323e2ea1811659ed31a031b634e61f279727f4d7f03bf156542d7dd840', '{"id":"sylin-org/koi/explore","name":"explore","description":{"zh":"本地mDNS服务发现工具，帮助开发者轻松探索和发现本地服务","ja":"ローカルmDNSサービスの検出ツール、開発者が簡単にローカルサービスを検出できるようにする","ko":"로컬 mDNS 서비스 검색 도구, 개발자가 로컬 서비스를 쉽게 검색할 수 있도록 도와줍니다","es":"Explorar es un servicio de descubrimiento de mDNS para todos. Permite a los desarrolladores descubrir servicios locales de manera sencilla.","fr":"Explorer est un service de découverte mDNS pour tous. Il permet aux développeurs de découvrir des services locaux de manière simple.","de":"Explorer ist ein mDNS-Entdeckungsdienst für alle. Er ermöglicht es Entwicklern, lokale Dienste einfach zu entdecken.","pt":"O Explore é uma ferramenta de IA para descoberta de serviços mDNS locais, facilitando a vida dos desenvolvedores com soluções de código aberto.","ru":"Explore - это инструмент ИИ для обнаружения местных сервисов mDNS, упрощающий жизнь разработчиков с открытым исходным кодом.","ar":"استكشاف هو أداة ذكاء اصطناعي لاكتشاف خدمات mDNS المحلية، ويسهل الحياة للمطورين مع حلول مفتوحة المصدر.","en":"Local mDNS service discovery for everyone."},"seo":{"title":{"zh":"AI智能探索工具 - 本地mDNS服务发现","ja":"AIエージェント - ローカルmDNSサービスの検出","ko":"AI 에이전트 - 로컬 mDNS 서비스 검색","es":"Herramientas de AI: Explorar con mDNS","fr":"Outils IA : Découvrez avec mDNS","de":"KI-Tools: Entdecken mit mDNS","pt":"Ferramentas de IA: Explore - Serviço de Descoberta mDNS L...","ru":"ИИ Агенты: Explore - Местная служба обнаружения mDNS","ar":"أدوات الذكاء الاصطناعي: استكشاف - خدمة اكتشاف mDNS المحلية","en":"explore"},"description":{"zh":"本地mDNS服务发现工具，帮助开发者轻松探索和发现本地服务","ja":"ローカルmDNSサービスの検出ツール、開発者が簡単にローカルサービスを検出できるようにする","ko":"로컬 mDNS 서비스 검색 도구, 개발자가 로컬 서비스를 쉽게 검색할 수 있도록 도와줍니다","es":"Explorar es un servicio de descubrimiento de mDNS para todos. Permite a los desarrolladores descubrir servicios locales de manera sencilla.","fr":"Explorer est un service de découverte mDNS pour tous. Il permet aux développeurs de découvrir des services locaux de manière simple.","de":"Explorer ist ein mDNS-Entdeckungsdienst für alle. Er ermöglicht es Entwicklern, lokale Dienste einfach zu entdecken.","pt":"O Explore é uma ferramenta de IA para descoberta de serviços mDNS locais, facilitando a vida dos desenvolvedores com soluções de código aberto.","ru":"Explore - это инструмент ИИ для обнаружения местных сервисов mDNS, упрощающий жизнь разработчиков с открытым исходным кодом.","ar":"استكشاف هو أداة ذكاء اصطناعي لاكتشاف خدمات mDNS المحلية، ويسهل الحياة للمطورين مع حلول مفتوحة المصدر.","en":"Local mDNS service discovery for everyone."},"definition":{"en":"Local mDNS service discovery for everyone."},"features":{"zh":["本地mDNS服务发现","支持多种开发语言","轻松集成到现有项目中","提高开发效率","简化服务搜索过程"],"ja":["ローカルmDNSサービスの検出","多くの開発言語をサポート","既存のプロジェクトに簡単に統合","開発効率の向上","サービス検索プロセスの簡素化"],"ko":["로컬 mDNS 서비스 검색","다수의 개발 언어 지원","既存 프로젝트에 쉽게 통합","개발 효율성 향상","서비스 검색 프로세스 간소화"],"es":["Descubrimiento de servicios mDNS","Búsqueda de servicios locales","Integración con herramientas de desarrollo","Compatibilidad con múltiples plataformas","Interfaz de línea de comandos (CLI) para desarrolladores"],"fr":["Découverte de services mDNS","Recherche de services locaux","Intégration avec des outils de développement","Compatibilité avec plusieurs plateformes","Interface de ligne de commande (CLI) pour les développeurs"],"de":["Entdeckung von mDNS-Diensten","Suche nach lokalen Diensten","Integration mit Entwicklungstools","Kompatibilität mit mehreren Plattformen","Kommandozeileninterface (CLI) für Entwickler"],"pt":["Descoberta de serviços mDNS locais","Suporte a múltiplas plataformas","Código aberto e personalizável","Integração com ferramentas de desenvolvimento","Suporte a protocolos de rede variados"],"ru":["Обнаружение местных сервисов mDNS","Поддержка нескольких платформ","Открытый исходный код и настраиваемый","Интеграция с инструментами разработки","Поддержка различных сетевых протоколов"],"ar":["اكتشاف خدمات mDNS المحلية","دعم منصات متعددة","مفتوح المصدر وقابل للتخصيص","التكامل مع أدوات التطوير","دعم بروتوكولات شبكة متعددة"]},"keywords":{"zh":["AI智能探索工具","本地mDNS服务发现","如何使用mDNS","mDNS服务搜索","AI智能工具安装","AI智能工具设置指南","mDNS服务发现工具比较"],"ja":["AIエージェント","ローカルmDNSサービスの検出","mDNSの使い方","mDNSサービス検索","AIエージェントのインストール","AIエージェントの設定ガイド","mDNSサービス検出ツールの比較"],"ko":["AI 에이전트","로컬 mDNS 서비스 검색","mDNS 사용 방법","mDNS 서비스 검색","AI 에이전트 설치","AI 에이전트 설정 가이드","mDNS 서비스 검색 도구 비교"],"es":["herramientas de AI","mDNS","descubrimiento de servicios","desarrollo de software","GUI vs CLI","cómo utilizar mDNS","alternativas a mDNS","instalación de mDNS","guía de configuración de mDNS"],"fr":["outils IA","mDNS","découverte de services","développement de logiciels","GUI vs CLI","comment utiliser mDNS","alternatives à mDNS","installation de mDNS","guide de configuration de mDNS"],"de":["KI-Tools","mDNS","Entdeckung von Diensten","Softwareentwicklung","GUI vs CLI","wie man mDNS verwendet","Alternativen zu mDNS","Installation von mDNS","Konfigurationsanleitung für mDNS"],"pt":["como usar o Explore","o que é mDNS","ferramentas de IA para desenvolvedores","Explore vs outras ferramentas","guia de instalação do Explore","configuração do Explore","desenvolvimento de aplicativos com Explore"],"ru":["как использовать Explore","что такое mDNS","инструменты ИИ для разработчиков","Explore vs другие инструменты","руководство по установке Explore","настройка Explore","разработка приложений с Explore"],"ar":["كيفية استخدام استكشاف","ما هي mDNS","أدوات الذكاء الاصطناعي للمطورين","استكشاف مقابل أدوات أخرى","دليل تثبيت استكشاف","تكوين استكشاف","تطوير التطبيقات باستخدام استكشاف"]}},"owner":"sylin-org","repo":"koi","repoPath":"sylin-org/koi","stars":0,"forks":0,"updatedAt":"2026-03-05T06:20:06.292Z","topics":[],"category":"community","skillMd":{"name":"explore","description":"Run a mandatory pre-implementation exploration workflow before writing production code. Use when a task requires code changes and Codex must first map concerns/layers, read relevant files, check existing constants and types, identify the closest existing pattern, plan exact code placement, and confirm architectural guardrails.","bodyPreview":"# Explore\n\nBefore implementing anything for a task, complete the following steps in order.\nDo not write production code until all steps are done.\n\n## Step 1: Understand the task\n\nRestate the task in your own words. Identify:\n- What crate this touches: `koi-common`, `koi-client`, `koi-mdns`, `koi-config`, `koi-dns`, `koi-health`, `koi-proxy`, `koi-certmesh`, `koi-crypto`, `koi-truststore`, `koi-embedded`, `koi` binary\n- Which layer is involved: transport, business logic, wire format, CLI\n- Expect","body":"# Explore\n\nBefore implementing anything for a task, complete the following steps in order.\nDo not write production code until all steps are done.\n\n## Step 1: Understand the task\n\nRestate the task in your own words. Identify:\n- What crate this touches: `koi-common`, `koi-client`, `koi-mdns`, `koi-config`, `koi-dns`, `koi-health`, `koi-proxy`, `koi-certmesh`, `koi-crypto`, `koi-truststore`, `koi-embedded`, `koi` binary\n- Which layer is involved: transport, business logic, wire format, CLI\n- Expected output: new feature, refactor, bug fix, extension\n\n## Step 2: Read existing code\n\nOpen and read the 3-5 most relevant existing files.\nUse searches like:\n\n```bash\n# Find types related to the task\nrg \"struct|enum|trait\" crates/ -l | head -20\n\n# Find functions related to the task\nrg \"fn keyword_from_task\" crates/\n\n# Find the closest existing implementation to what we''re building\nrg \"similar_feature_keyword\" crates/ -l\n```\n\nFor each file read, state in one sentence what it does and whether it is relevant.\n\n## Step 3: Check for existing constants and types\n\nRun these searches explicitly and report results:\n\n```bash\n# Constants in the binary crate\nrg \"const \" crates/koi/src/\n\n# Shared types and utilities\nrg \"struct|enum\" crates/koi-common/src/\nrg \"struct|enum\" crates/koi-mdns/src/protocol/\n\n# Client types\nrg \"struct|enum\" crates/koi-client/src/\n\n# Domain crate types\nrg \"struct|enum\" crates/koi-dns/src/\nrg \"struct|enum\" crates/koi-health/src/\nrg \"struct|enum\" crates/koi-proxy/src/\nrg \"struct|enum\" crates/koi-certmesh/src/\n```\n\nFor each required piece of functionality, state clearly:\n- `Already exists`\n- `Needs to be created`\n\n## Step 4: Identify the closest pattern to follow\n\nFind the most similar existing feature in the codebase.\nExamples:\n- New HTTP endpoint: read `crates/koi/src/adapters/http.rs` or `crates/koi/src/adapters/dispatch.rs`\n- New CLI command: read a module in `crates/koi/src/commands/`\n- New shared types: read `crates/koi-common/src/types.rs` or `crates/koi-common/src/api.rs`\n- New domain logic: read the relevant domain crate (e.g., `crates/koi-mdns/`, `crates/koi-dns/`)\n- Platform integration: read `crates/koi/src/platform/`\n- Formatting: read `crates/koi/src/format.rs`\n- Client operations: read `crates/koi-client/src/lib.rs`\n\nState:\n- `Following the pattern from [specific file]`\n\n## Step 5: Plan where new code will live\n\nFor every new file, type, function, or constant, state location and justification:\n\n| New code | Location | Justification |\n|----------|----------|---------------|\n| (type/fn/const) | (exact path) | (why here and not elsewhere) |\n\nApply crate placement rules:\n- Shared types, traits, utilities: `crates/koi-common/`\n- mDNS protocol types: `crates/koi-mdns/`\n- HTTP client methods: `crates/koi-client/`\n- CLI commands / subcommands: `crates/koi/src/commands/`\n- HTTP server / adapters: `crates/koi/src/adapters/`\n- OS integration: `crates/koi/src/platform/`\n- Output formatting: `crates/koi/src/format.rs`\n- DNS domain logic: `crates/koi-dns/`\n- Health checks: `crates/koi-health/`\n- Reverse proxy: `crates/koi-proxy/`\n- Certificate mesh: `crates/koi-certmesh/`\n- Crypto primitives: `crates/koi-crypto/`\n- Configuration / breadcrumb: `crates/koi-config/`\n\n## Step 6: Check for potential violations\n\nBefore proceeding, confirm:\n\n- [ ] No `mdns-sd` imports outside `crates/koi-mdns/`\n- [ ] No new type duplicates one in `koi-common` or domain crates\n- [ ] Constants are co-located with usage (not in a centralized module)\n- [ ] New protocol types have serde round-trip tests planned\n- [ ] Cross-crate dependencies flow downward (binary -> domain crates -> koi-common)\n\n## Step 7: Present the plan\n\nSummarize findings in this exact format:\n\n**Task:** (one sentence)\n**Files read:** (list with one-sentence relevance notes)\n**Reusing:** (list what already exists)\n**Creating new:** (table from Step 5)\n**Pattern:** (which existing file you''re following)\n**Risks:** (anything you''re unsure about)\n\nThen stop and wait for approval before implementing.\n"},"lastSynced":"2026-03-05T08:33:19.159Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring thorough task analysis and mDNS service discovery capabilities.","zh":"适用于需要彻底任务分析和mDNS服务发现功能的开发代理。","ja":"開発エージェントが徹底的なタスク分析とmDNSサービス検出機能を必要とする場合に最適です。","ko":"개발 에이전트가 철저한 작업 분석 및 mDNS 서비스 검색 기능을 필요로 할 때 적합합니다.","es":"Ideal para agentes de desarrollo que requieren un análisis de tareas exhaustivo y capacidades de descubrimiento de servicios mDNS.","fr":"Idéal pour les agents de développement nécessitant une analyse de tâches approfondie et des capacités de découverte de services mDNS.","de":"Ideal für Entwicklungssagenten, die eine gründliche Aufgabenanalyse und mDNS-Service-Entdeckungsfunktionen erfordern.","pt":"Ideal para Agentes de Desenvolvimento que requerem uma análise de tarefas aprofundada e capacidades de descoberta de serviço mDNS.","ru":"Идеально для агентов разработки, требующих тщательного анализа задач и возможностей обнаружения службы mDNS.","ar":"مثالي للوكلاء النموذجيين الذين يتطلبون تحليلًا شاملاً للمهام وقدرات اكتشاف الخدمة mDNS."},"recommendation":{"en":"Empowers agents to conduct comprehensive task analysis, utilizing local mDNS service discovery and touching various crates such as `koi-common`, `koi-client`, and `koi-mdns`, to ensure thorough understanding before production code implementation.","zh":"赋予代理进行全面任务分析的能力，利用本地mDNS服务发现，并接触诸如`koi-common`、`koi-client`和`koi-mdns`等多个crate，以确保在生产代码实现之前的彻底理解。","ja":"エージェントが包括的なタスク分析を実行できるようにし、ローカルのmDNSサービス検出を利用し、`koi-common`、`koi-client`、`koi-mdns`などの複数のcrateにアクセスして、プロダクションコードの実装前に包括的な理解を保証する。","ko":"에이전트가 포괄적인 작업 분석을 수행할 수 있도록 하며, 로컬 mDNS 서비스 검색을 사용하며, `koi-common`, `koi-client`, `koi-mdns`などの 여러 개의 crate에 접근하여 프로덕션 코드 구현 전에 포괄적인 이해를 보장합니다.","es":"Habilita a los agentes a realizar un análisis de tareas comprehensivo, utilizando la descubierta de servicios mDNS local y tocando varios crates como `koi-common`, `koi-client` y `koi-mdns`, para asegurar una comprensión exhaustiva antes de la implementación del código de producción.","fr":"Permet aux agents de réaliser une analyse de tâches complète, en utilisant la découverte de services mDNS locale et en touchant divers crates tels que `koi-common`, `koi-client` et `koi-mdns`, pour assurer une compréhension approfondie avant la mise en œuvre du code de production.","de":"Ermächtigt Agenten, eine umfassende Aufgabenanalyse durchzuführen, indem sie die lokale mDNS-Service-Entdeckung nutzen und verschiedene Crates wie `koi-common`, `koi-client` und `koi-mdns` berühren, um eine gründliche Verständnis vor der Implementierung des Produktionscodes sicherzustellen.","pt":"Habilita os agentes a realizar uma análise de tarefas abrangente, utilizando a descoberta de serviço mDNS local e tocando várias crates como `koi-common`, `koi-client` e `koi-mdns`, para garantir uma compreensão aprofundada antes da implementação do código de produção.","ru":"Наделяет агентов способностью проводить всесторонний анализ задач, используя локальное обнаружение службы mDNS и затрагивая различные crates, такие как `koi-common`, `koi-client` и `koi-mdns`, для обеспечения полного понимания перед реализацией кода производства.","ar":"يمنح الوكلاء القدرة على إجراء تحليل مهام شامل، باستخدام اكتشاف الخدمة mDNS المحلي واللمس العديد من الحاويات مثل `koi-common` و `koi-client` و `koi-mdns`، لضمان فهم شامل قبل تنفيذ رمز الإنتاج."},"useCases":{"en":["Analyzing tasks through local mDNS service discovery","Identifying involved layers such as transport, business logic, or wire format","Determining affected crates like `koi-config` or `koi-dns`"],"zh":["通过本地mDNS服务发现进行任务分析","识别涉及的层次，例如传输、业务逻辑或线层格式","确定受影响的crate，例如`koi-config`或`koi-dns`"],"ja":["ローカルのmDNSサービス検出を使用したタスク分析","関与する層を特定する、たとえばトランスポート、ビジネスロジック、またはワイヤーフォーマット","影響を受けるcrateを決定する、たとえば`koi-config`または`koi-dns`"],"ko":["로컬 mDNS 서비스 검색을 사용한 작업 분석","관련된 계층을 식별하는 것, 예를 들어 전송, 비즈니스 논리 또는 와이어 형식","영향을 받는 crate를 결정하는 것, 예를 들어 `koi-config` 또는 `koi-dns`"],"es":["Análisis de tareas a través de la descubierta de servicios mDNS local","Identificación de capas involucradas como transporte, lógica de negocio o formato de cable","Determinación de crates afectados como `koi-config` o `koi-dns`"],"fr":["Analyse de tâches via la découverte de services mDNS locale","Identification des couches impliquées telles que le transport, la logique métier ou le format de fil","Détermination des crates affectés comme `koi-config` ou `koi-dns`"],"de":["Analyse von Aufgaben durch die lokale mDNS-Service-Entdeckung","Identifizierung der beteiligten Schichten wie Transport, Geschäftslogik oder Drahtformat","Bestimmung der betroffenen Crates wie `koi-config` oder `koi-dns`"],"pt":["Analisar tarefas por meio da descoberta de serviço mDNS local","Identificar camadas envolvidas, como transporte, lógica de negócios ou formato de fio","Determinar crates afetados, como `koi-config` ou `koi-dns`"],"ru":["Анализ задач через локальное обнаружение службы mDNS","Определение задействованных слоев, таких как транспорт, бизнес-логика или формат провода","Определение затронутых crates, таких как `koi-config` или `koi-dns`"],"ar":["تحليل المهام من خلال اكتشاف الخدمة mDNS المحلي","تحديد الطبقات المشاركة، مثل النقل أو منطق الأعمال أو تنسيق السلك","تحديد الحاويات المتأثرة، مثل `koi-config` أو `koi-dns`"]},"limitations":{"en":["Requires completion of all analysis steps before production code implementation","Touches multiple crates which may add complexity"],"zh":["需要在生产代码实现之前完成所有分析步骤","接触多个crate，这可能会增加复杂性"],"ja":["プロダクションコードの実装前にすべての分析ステップを完了する必要がある","複数のcrateにアクセスするため、複雑性が増す可能性がある"],"ko":["프로덕션 코드 구현 전에 모든 분석 단계를 완료해야 함","여러 개의 crate에 접근하기 때문에 복잡성이 증가할 수 있음"],"es":["Requiere la finalización de todos los pasos de análisis antes de la implementación del código de producción","Toca varios crates que pueden agregar complejidad"],"fr":["Nécessite la finalisation de toutes les étapes d''analyse avant la mise en œuvre du code de production","Touche plusieurs crates qui peuvent ajouter de la complexité"],"de":["Erfordert die Fertigstellung aller Analyse-Schritte vor der Implementierung des Produktionscodes","Berührt mehrere Crates, die möglicherweise Komplexität hinzufügen"],"pt":["Requer a conclusão de todas as etapas de análise antes da implementação do código de produção","Toca várias crates, o que pode adicionar complexidade"],"ru":["Требует завершения всех шагов анализа перед реализацией кода производства","Затрагивает несколько crates, что может добавить сложность"],"ar":["يتطلب إكمال جميع خطوات التحليل قبل تنفيذ رمز الإنتاج","يلمس العديد من الحاويات، مما قد يزيد من التعقيد"]},"version":3},"contentHash":"27206e323e2ea1811659ed31a031b634e61f279727f4d7f03bf156542d7dd840","qualityScore":34}');
