INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('skillrecordings/support/tdd-red-green-refactor', 'tdd-red-green-refactor', 'skillrecordings', 'support', 'community', 'tdd-red-green-refactor skillrecordings support community TDD 红绿重构 AI 工具是 Badass Courses 支持团队的 AI 辅助工具，用于提升代码质量 TDD レッドグリーンリファクタリング AI エージェントは、Badass Courses サポートデスク用の AI ツールです。コードの品質を向上させます TDD 빨강초록 리팩토링 AI 에이전트는 Badass Courses 지원 데스크를 위한 AI 도구로, 코드 품질을 향상시킵니다 El agente de AI tdd-red-green-refactor es una herramienta de desarrollo para soporte técnico en Badass Courses, que aplica TDD para mejorar la calidad del código L''agent d''IA tdd-red-green-refactor est un outil de développement pour le support technique chez Badass Courses, qui applique le TDD pour améliorer la qualité du code Der KI-Agent tdd-red-green-refactor ist ein Entwicklungstool für den Support bei Badass Courses, das TDD anwendet, um die Codequalität zu verbessern O agente de IA tdd-red-green-refactor é uma ferramenta de suporte técnico para Badass Courses ИИ Агент tdd-red-green-refactor - это инструмент поддержки технического desks для Badass Courses أداة الذكاء الاصطناعي tdd-red-green-refactor هي أداة دعم فني للصفحات الدراسية Badass 🤖 an AI agent for the support desk at Badass Courses TDD 工具 红绿重构 AI 测试工具 自动化测试 代码重构 测试驱动开发 如何使用 TDD TDD 教程 🤖 an AI agent for the support desk at Badass Courses');
