INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jeffwweee/dev-workspace/project-planner', 'project-planner', 'jeffwweee', 'dev-workspace', 'community', 'project-planner jeffwweee dev-workspace community 项目规划助手是一个开发工作空间，用于组织多个项目，简化工作流程，提高开发效率 プロジェクト計画アシスタントは、複数のプロジェクトを整理し、ワークフローを簡素化する開発ワークスペースです 프로젝트 계획 어시스턴트는 여러 프로젝트를 조직하고 워크플ロー를 단순화하여 개발 효율성을 높이는 개발 작업 공간입니다 Nuestro espacio de trabajo de planificación de proyectos AI es ideal para desarrolladores que necesitan organizar múltiples proyectos de manera eficiente Notre espace de travail de planification de projet IA est idéal pour les développeurs qui doivent organiser plusieurs projets de manière efficace Unser AI-Projektplanungswerkzeug ist ideal für Entwickler, die mehrere Projekte effizient verwalten müssen O project-planner é uma ferramenta de desenvolvimento para organizar múltiplos projetos, aumentando a produtividade com soluções de inteligência artificial Планировщик проектов - это рабочее пространство для организации множества проектов, повышающее производительность с помощью ИИ Агентов مخطط المشروع هو مساحة عمل لتنظيم عدة مشاريع، مما يزيد من الإنتاجية باستخدام أدوات الذكاء الاصطناعي Development workspace for organizing multiple projects 如何使用项目规划工具 什么是AI智能项目规划 项目规划助手替代品 项目规划工具与其他工具的比较 项目规划助手安装 项目规划工具设置指南 开发工作空间 多项目管理 工作流程简化 Development workspace for organizing multiple projects');
