INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jjm-batwo/batwo-AI-maketing/prometheus', 'prometheus', 'jjm-batwo', 'batwo-AI-maketing', 'community', 'prometheus jjm-batwo batwo-AI-maketing community Prometheus是一个开源的监控和告警工具，帮助开发者监控系统性能和状态 Prometheusはオープンソースのモニタリングとアラートツールです。開発者がシステムのパフォーマンスとステータスを監視するのに役立ちます Prometheus는 개발자가 시스템 성능과 상태를 모니터링하는 데 도움이 되는 오픈 소스 모니터링 및 경고 도구입니다 Prometheus es una herramienta de monitoreo de código abierto que ayuda a los desarrolladores a supervisar y optimizar sus aplicaciones. Prometheus est un outil de surveillance de code ouvert qui aide les développeurs à surveiller et à optimiser leurs applications. Prometheus ist ein Open-Source-Überwachungstool, das Entwicklern hilft, ihre Anwendungen zu überwachen und zu optimieren. Prometheus é uma ferramenta de monitoramento de desempenho para desenvolvedores. Ele ajuda a melhorar a eficiência do seu projeto Prometheus - это инструмент для мониторинга производительности для разработчиков. Он помогает улучшить эффективность вашего проекта بروميثيوس هو أداة مراقبة الأداء للمطورين. يساعدهم على تحسين كفاءة مشاريعهم My Project Prometheus安装 Prometheus配置 Prometheus监控 Prometheus告警 如何使用Prometheus Prometheus替代品 Prometheus与Grafana比较 My Project');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('openai/plugins/plugin-creator', 'community', 'openai', 'plugins', 'openai/plugins', 'plugin-creator', 17, 3, 33, '2026-03-06T01:25:13Z', '2026-03-06T06:43:01.458Z', 'b8e05e29fdab15b43dd33d84df23fcea3a7a96f33bf78825f07daa0bbc77ec04', '{"id":"openai/plugins/plugin-creator","name":"plugin-creator","description":{"en":"The plugin-creator skill enables developers to generate custom plugins for AI agents. It benefits developers by providing a quick start guide and scaffold script to create plugins.","zh":"插件创建器技能允许开发人员快速创建和运行AI插件，使用Python脚本和CLI工具","ja":"プラグイン作成スキルは、開発者がPythonスクリプトとCLIツールを使用してAIプラグインを作成して実行できるようにします","ko":"플러그인 생성기 스킬을 사용하여 개발자는 Python 스크립트와 CLI 도구를 사용하여 AI 플러그인을 생성하고 실행할 수 있습니다","es":"Plugin Creator es una habilidad que permite a los desarrolladores crear plugins personalizados para herramientas de AI. Se ejecuta mediante scripts de Python.","fr":"Plugin Creator est une compétence qui permet aux développeurs de créer des plugins personnalisés pour des outils d''IA. Il s''exécute via des scripts Python.","de":"Plugin Creator ist eine Fähigkeit, die es Entwicklern ermöglicht, benutzerdefinierte Plugins für KI-Tools zu erstellen. Sie wird über Python-Skripte ausgeführt.","pt":"O Plugin Creator é uma ferramenta para criar plugins personalizados. Inicie com o script de criação e configure seu plugin em minutos","ru":"Плагин Создатель - это инструмент для создания пользовательских плагинов. Начните с скрипта создания и настройте плагин за несколько минут","ar":"Plugin Creator هو أداة لإنشاء ملحقات مخصصة. ابدأ مع سكريبت الإنشاء وتكوين الملحقات في دقائق"},"seo":{"title":{"en":"plugin-creator: Setup Guide for AI Agents | AI Agent Skill","zh":"AIエージェント插件创建器快速入门","ja":"AIエージェントプラグイン作成ガイド","ko":"AI 에이전트 플러그인 생성기 설정 가이드","es":"Guía de configuración de Plugin Creator para desarrollado...","fr":"Guide de démarrage rapide pour Plugin Creator d''outils d''IA","de":"Plugin Creator Einrichtungsleitfaden für Entwickler von K...","pt":"Guia de Configuração do Plugin Creator para Ferramentas d...","ru":"Настройка Плагина Создателя для ИИ Агентов","ar":"دليل إعداد Plugin Creator لأدوات الإتصال بالذكاء الاصطناعي"},"description":{"en":"Discover how to create custom plugins with plugin-creator. Learn to run scaffold scripts and configure plugin.json files for seamless integration with your A...","zh":"使用OpenAI插件创建器技能，快速创建并运行AI插件，了解插件创建的最佳实践","ja":"OpenAIプラグイン作成スキルを使用して、AIプラグインを作成して実行する方法を学びます","ko":"OpenAI 플러그인 생성기 스킬을 사용하여 AI 플러그인을 생성하고 실행하는 방법을 알아보세요","es":"Crea plugins personalizados con Plugin Creator. Aprende a ejecutar scripts de creación y configurar tu plugin en minutos.","fr":"Créez des plugins personnalisés avec Plugin Creator. Découvrez comment exécuter des scripts de création et configurer votre plugin en quelques minutes.","de":"Erstellen Sie benutzerdefinierte Plugins mit Plugin Creator. Erfahren Sie, wie Sie Erstellungs-Skripte ausführen und Ihr Plugin in wenigen Minuten konfigurie...","pt":"Aprenda a criar plugins personalizados com o Plugin Creator. Descubra como iniciar rapidamente com o script de criação e configure seu plugin","ru":"Узнайте, как создавать пользовательские плагины с помощью Плагина Создателя. Ознакомьтесь с быстрым стартом и настройкой плагина","ar":"تعلم كيفية إنشاء ملحقات مخصصة باستخدام Plugin Creator. اكتشف كيفية البدء بسرعة مع سكريبت الإنشاء وتكوين الملحقات"},"definition":{"en":"plugin-creator is a skill that allows developers to create and configure custom plugins for AI agents using Python scripts and JSON files.","zh":"插件创建器是一种AI工具，允许开发人员创建和运行自定义的AI插件","ja":"プラグイン作成は、開発者がカスタムのAIプラグインを作成して実行できるAIツールです","ko":"플러그인 생성기는 개발자가 사용자 정의 AI 플러그인을 생성하고 실행할 수 있는 AI 도구입니다","es":"Plugin Creator es una herramienta de desarrollo que permite la creación de plugins para herramientas de inteligencia artificial.","fr":"Plugin Creator est un outil de développement qui permet la création de plugins pour des outils d''intelligence artificielle.","de":"Plugin Creator ist ein Entwicklungstool, das die Erstellung von Plugins für KI-Tools ermöglicht.","pt":"O Plugin Creator é uma ferramenta de desenvolvimento que permite criar plugins personalizados para Ferramentas de IA","ru":"Плагин Создатель - это инструмент разработки, который позволяет создавать пользовательские плагины для ИИ Агентов","ar":"Plugin Creator هو أداة تطوير تتيح إنشاء ملحقات مخصصة لأدوات الذكاء الاصطناعي"},"features":{"en":["Runs scaffold script using python3 to generate basic plugin structure","Creates plugin.json file for configuration and customization","Supports plugin names in lower-case hyphen-case with a maximum of 64 characters","Generates folder and plugin.json name based on the provided plugin name","Allows for customization of plugin settings through the plugin.json file"],"zh":["使用Python脚本创建AI插件","支持CLI工具运行插件","插件名称规范化为小写和中线","生成的插件文件夹和plugin.json名称始终相同","支持在特定路径下创建插件"],"ja":["Pythonスクリプトを使用してAIプラグインを作成","CLIツールを使用してプラグインを実行","プラグイン名は小文字とハイフンに規格化","生成されたプラグインフォルダとplugin.json名は常に同じ","特定のパスでプラグインを作成することをサポート"],"ko":["Python 스크립트를 사용하여 AI 플러그인을 생성","CLI 도구를 사용하여 플러그인을 실행","플러그인 이름은 소문자와 하이픈으로 규격화","생성된 플러그인 폴더와 plugin.json 이름은 항상 동일","특정 경로에서 플러그인을 생성하는 것을 지원"],"es":["Ejecución de scripts de creación de plugins con Python","Configuración de plugins mediante archivos JSON","Compatibilidad con nombres de plugins normalizados a minúsculas y con guiones","Límite de 64 caracteres para los nombres de los plugins","Generación de carpetas y archivos de configuración para plugins"],"fr":["Exécution de scripts de création de plugins avec Python","Configuration de plugins via des fichiers JSON","Compatibilité avec des noms de plugins normalisés en minuscules et avec des tirets","Limite de 64 caractères pour les noms de plugins","Génération de dossiers et de fichiers de configuration pour les plugins"],"de":["Ausführung von Erstellungs-Skripten für Plugins mit Python","Konfiguration von Plugins über JSON-Dateien","Kompatibilität mit normalisierten Plugin-Namen in Kleinbuchstaben und mit Bindestrichen","Begrenzung auf 64 Zeichen für Plugin-Namen","Erzeugung von Ordnern und Konfigurationsdateien für Plugins"],"pt":["Criação de plugins personalizados com script de criação","Configuração de plugins em minutos","Suporte a nomes de plugins em lower-case hyphen-case","Geração de pastas e arquivos de plugin personalizados"],"ru":["Создание пользовательских плагинов с помощью скрипта создания","Настройка плагинов за несколько минут","Поддержка имен плагинов в нижнем регистре с дефисами","Генерация папок и файлов плагина настраиваемых"],"ar":["إنشاء ملحقات مخصصة مع سكريبت الإنشاء","تكوين الملحقات في دقائق","دعم أسماء الملحقات بحالة الحرف الصغير مع شرطات","جénération من مجلدات وملفات الملحقات المخصصة"]},"keywords":{"en":["how to use plugin-creator","plugin-creator setup guide","plugin-creator alternative","plugin-creator vs other AI plugins","plugin-creator install","custom plugin creation for AI agents","plugin-creator tutorial","AI agent plugin development"],"zh":["AI插件创建","OpenAI插件","Python脚本","CLI工具","AI工具","插件创建器","AI开发","插件开发"],"ja":["AIプラグイン作成","OpenAIプラグイン","Pythonスクリプト","CLIツール","AIツール","プラグイン作成","AI開発","プラグイン開発"],"ko":["AI 플러그인 생성","OpenAI 플러그인","Python 스크립트","CLI 도구","AI 도구","플러그인 생성기","AI 개발","플러그인 개발"],"es":["Plugin Creator","desarrollo de plugins","herramientas de AI","Python para desarrolladores","configuración de plugins","creación de plugins personalizados","plugins para inteligencia artificial","desarrollo de software de AI","herramientas de desarrollo de plugins"],"fr":["Plugin Creator","développement de plugins","outils d''IA","Python pour développeurs","configuration de plugins","création de plugins personnalisés","plugins pour intelligence artificielle","développement de logiciels d''IA","outils de développement de plugins"],"de":["Plugin Creator","Entwicklung von Plugins","KI-Tools","Python für Entwickler","Konfiguration von Plugins","Erstellung von benutzerdefinierten Plugins","Plugins für künstliche Intelligenz","Entwicklung von KI-Software","Entwicklungstools für Plugins"],"pt":["Plugin Creator","Ferramentas de IA","Desenvolvimento de plugins","Script de criação de plugins","Configuração de plugins","Plugins personalizados"],"ru":["Плагин Создатель","ИИ Агенты","Разработка плагинов","Скрипт создания плагинов","Настройка плагинов","Пользовательские плагины"],"ar":["Plugin Creator","أدوات الذكاء الاصطناعي","تطوير الملحقات","سكريبت إنشاء الملحقات","تكوين الملحقات","ملحقات مخصصة"]}},"owner":"openai","repo":"plugins","repoPath":"openai/plugins","stars":17,"forks":3,"updatedAt":"2026-03-06T01:25:13Z","topics":[],"category":"community","skillMd":{"name":"plugin-creator","description":"Create and scaffold plugin directories for Codex with a required `.codex-plugin/plugin.json`, optional plugin folders/files, and baseline placeholders you can edit before publishing or testing.","bodyPreview":"# Plugin Creator\n\n## Quick Start\n\n1. Run the scaffold script:\n\n```bash\n  # Plugin names are normalized to lower-case hyphen-case and must be <= 64 chars.\n  # The generated folder and plugin.json name are always the same.\n# Run from repo root (or replace .agents/... with the absolute path to this SKILL).\n# By default creates in <repo_root>/plugins/<plugin-name>.\npython3 .agents/skills/plugin-creator/scripts/create_basic_plugin.py <plugin-name>\n```\n\n2. Open `<plugin-path>/.codex-plugin/plugin.json","body":"# Plugin Creator\n\n## Quick Start\n\n1. Run the scaffold script:\n\n```bash\n  # Plugin names are normalized to lower-case hyphen-case and must be <= 64 chars.\n  # The generated folder and plugin.json name are always the same.\n# Run from repo root (or replace .agents/... with the absolute path to this SKILL).\n# By default creates in <repo_root>/plugins/<plugin-name>.\npython3 .agents/skills/plugin-creator/scripts/create_basic_plugin.py <plugin-name>\n```\n\n2. Open `<plugin-path>/.codex-plugin/plugin.json` and replace `[TODO: ...]` placeholders.\n\n3. Generate/adjust optional companion folders as needed:\n\n```bash\npython3 .agents/skills/plugin-creator/scripts/create_basic_plugin.py my-plugin --path <parent-plugin-directory> \\\n  --with-skills --with-hooks --with-scripts --with-assets --with-mcp --with-apps\n```\n\n`<parent-plugin-directory>` is the directory where the plugin folder `<plugin-name>` will be created (for example `~/code/plugins`).\n\n## What this skill creates\n\n- Creates plugin root at `/<parent-plugin-directory>/<plugin-name>/`.\n- Always creates `/<parent-plugin-directory>/<plugin-name>/.codex-plugin/plugin.json`.\n- Fills the manifest with the full schema shape, placeholder values, and the complete `interface` section.\n- `<plugin-name>` is normalized using skill-creator naming rules:\n  - `My Plugin` → `my-plugin`\n  - `My--Plugin` → `my-plugin`\n  - underscores, spaces, and punctuation are converted to `-`\n  - result is lower-case hyphen-delimited with consecutive hyphens collapsed\n- Supports optional creation of:\n  - `skills/`\n  - `hooks/`\n  - `scripts/`\n  - `assets/`\n  - `.mcp.json`\n  - `.app.json`\n\n## Required behavior\n\n- Outer folder name and `plugin.json` `\"name\"` are always the same normalized plugin name.\n- Do not remove required structure; keep `.codex-plugin/plugin.json` present.\n- Keep manifest values as placeholders until a human or follow-up step explicitly fills them.\n- If creating files inside an existing plugin path, use `--force` only when overwrite is intentional.\n\n## Reference to exact spec sample\n\nFor the exact canonical sample JSON, including the full `interface` block, use:\n\n- `references/plugin-json-spec.md`\n\n## Validation\n\nAfter editing `SKILL.md`, run:\n\n```bash\npython3 <path-to-skill-creator>/scripts/quick_validate.py .agents/skills/plugin-creator\n```\n"},"lastSynced":"2026-03-06T06:43:01.458Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing custom plugin development and integration capabilities.","zh":"非常适合需要自定义插件开发和集成能力的AI Agents。","ja":"カスタムプラグイン開発と統合機能を必要とするAI Agentsに最適です。","ko":"커스텀 플러그인 개발 및 통합 기능이 필요한 AI Agents에 완벽합니다.","es":"Perfecto para agentes de IA que necesitan desarrollo e integración de plugins personalizados.","fr":"Idéal pour les agents IA nécessitant un développement et une intégration de plugins personnalisés.","de":"Perfekt für KI-Agents, die eine benutzerdefinierte Plugin-Entwicklung und -Integration benötigen.","pt":"Perfeito para Agentes de IA que precisam de desenvolvimento e capacidades de integração de plugins personalizados.","ru":"Идеально для агентов ИИ, которым требуются возможности разработки и интеграции пользовательских плагинов.","ar":"مثالي للوكلاء الذكاء الاصطناعي الذين يحتاجون إلى تطوير وتكامل إضافات مخصصة."},"recommendation":{"en":"Empowers agents to generate custom plugins using Python 3, scaffold scripts, and JSON configuration files, enabling rapid development and deployment of new agent functionalities via the `.codex-plugin/plugin.json` file format.","zh":"使Agents能够使用Python 3、脚手架脚本和JSON配置文件生成自定义插件，通过`.codex-plugin/plugin.json`文件格式快速开发和部署新的Agent功能。","ja":"Python 3、スキャフォールドスクリプト、JSON設定ファイルを使用してカスタムプラグインを生成する機能をAgentsに提供し、`.codex-plugin/plugin.json`ファイル形式を通じて新しいAgent機能を迅速に開発およびデプロイできます。","ko":"Python 3, 스캐폴드 스크립트 및 JSON 구성 파일을 사용하여 커스텀 플러그인을 생성할 수 있도록 Agents에 권한을 부여하며, `.codex-plugin/plugin.json` 파일 형식을 통해 새로운 Agent 기능을 신속하게 개발 및 배포할 수 있습니다.","es":"Habilita a los agentes a generar plugins personalizados utilizando Python 3, scripts de scaffold y archivos de configuración JSON, lo que permite un desarrollo y despliegue rápidos de nuevas funcionalidades de agente a través del formato de archivo `.codex-plugin/plugin.json`.","fr":"Permet aux agents de générer des plugins personnalisés en utilisant Python 3, des scripts de scaffold et des fichiers de configuration JSON, ce qui permet un développement et un déploiement rapides de nouvelles fonctionnalités d''agent via le format de fichier `.codex-plugin/plugin.json`.","de":"Ermöglicht es Agents, benutzerdefinierte Plugins mithilfe von Python 3, Scaffold-Skripten und JSON-Konfigurationsdateien zu generieren, was ein schnelles Entwickeln und Bereitstellen neuer Agentenfunktionen über das Dateiformat `.codex-plugin/plugin.json` ermöglicht.","pt":"Habilita os agentes a gerar plugins personalizados usando Python 3, scripts de scaffold e arquivos de configuração JSON, permitindo o desenvolvimento e implantação rápidos de novas funcionalidades de agente via o formato de arquivo `.codex-plugin/plugin.json`.","ru":"Позволяет агентам создавать пользовательские плагины с помощью Python 3, скриптов scaffold и файлов конфигурации JSON, обеспечивая быструю разработку и развертывание новых функций агента через формат файла `.codex-plugin/plugin.json`.","ar":"تمكن الوكلاء من توليد إضافات مخصصة باستخدام Python 3 و스크ريبتات scaffold وملفات تكوين JSON، مما يتيح تطوير وتحديث سريع لمزايا الوكيل الجديدة عبر تنسيق ملف `.codex-plugin/plugin.json`."},"useCases":{"en":["Creating custom plugins for AI agents","Generating scaffold scripts for plugin development","Configuring plugins using JSON files"],"zh":["为AI Agents创建自定义插件","为插件开发生成脚手架脚本","使用JSON文件配置插件"],"ja":["AI Agents用のカスタムプラグインの作成","プラグイン開発のためのスキャフォールドスクリプトの生成","JSONファイルを使用したプラグインの設定"],"ko":["AI Agents용 커스텀 플러그인 생성","플러그인 개발을 위한 스캐폴드 스크립트 생성","JSON 파일을 사용한 플러그인 구성"],"es":["Creación de plugins personalizados para agentes de IA","Generación de scripts de scaffold para el desarrollo de plugins","Configuración de plugins mediante archivos JSON"],"fr":["Création de plugins personnalisés pour les agents IA","Génération de scripts de scaffold pour le développement de plugins","Configuration de plugins à l''aide de fichiers JSON"],"de":["Erstellung benutzerdefinierter Plugins für KI-Agents","Generierung von Scaffold-Skripten für die Plugin-Entwicklung","Konfiguration von Plugins mithilfe von JSON-Dateien"],"pt":["Criar plugins personalizados para agentes de IA","Gerar scripts de scaffold para desenvolvimento de plugins","Configurar plugins usando arquivos JSON"],"ru":["Создание пользовательских плагинов для агентов ИИ","Генерация скриптов scaffold для разработки плагинов","Настройка плагинов с помощью файлов JSON"],"ar":["إنشاء إضافات مخصصة للوكلاء الذكاء الاصطناعي","توليد سكريبتات scaffold لتنمية الإضافات","تكوين الإضافات باستخدام ملفات JSON"]},"limitations":{"en":["Requires Python 3 environment","Plugin names must be <= 64 characters and in lower-case hyphen-case","Generated folder and plugin.json name must match"],"zh":["需要Python 3环境","插件名称必须<=64个字符且为小写连字符格式","生成的文件夹和plugin.json名称必须匹配"],"ja":["Python 3環境が必要","プラグイン名は64文字以下で小文字のハイフンケースである必要があります","生成されたフォルダとplugin.jsonの名前が一致する必要があります"],"ko":["Python 3 환경 필요","플러그인 이름은 64자 이하이며 소문자 하이픈 케이스여야 함","생성된 폴더와 plugin.json 이름이 일치해야 함"],"es":["Requiere un entorno Python 3","Los nombres de los plugins deben ser <= 64 caracteres y en minúsculas con guiones","El nombre de la carpeta generada y plugin.json deben coincidir"],"fr":["Nécessite un environnement Python 3","Les noms de plugins doivent être <= 64 caractères et en minuscules avec traits d''union","Le nom du dossier généré et plugin.json doivent correspondre"],"de":["Benötigt eine Python 3-Umgebung","Plugin-Namen müssen <= 64 Zeichen lang sein und in kleiner Schrift mit Bindestrichen","Der Name des generierten Ordners und plugin.json müssen übereinstimmen"],"pt":["Requer ambiente Python 3","Os nomes dos plugins devem ter <= 64 caracteres e estar em minúsculas com hífen","O nome da pasta gerada e do plugin.json devem coincidir"],"ru":["Требуется среда Python 3","Имена плагинов должны быть <= 64 символов и быть в нижнем регистре с дефисом","Сгенерированное имя папки и plugin.json должны совпадать"],"ar":["يتطلب بيئة Python 3","يجب أن يكون أسماء الإضافات <= 64 حرفًا ويكون في الحالة الصغيرة مع شرطة","يجب أن يتطابق اسم المجلد المتولد وملف plugin.json"]},"version":4},"contentHash":"b8e05e29fdab15b43dd33d84df23fcea3a7a96f33bf78825f07daa0bbc77ec04","qualityScore":33}');
