INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('openai/plugins/plugin-creator', 'plugin-creator', 'openai', 'plugins', 'community', 'plugin-creator openai plugins community The plugin-creator skill enables developers to generate custom plugins for AI agents. It benefits developers by providing a quick start guide and scaffold script to create plugins. 插件创建器技能允许开发人员快速创建和运行AI插件，使用Python脚本和CLI工具 プラグイン作成スキルは、開発者がPythonスクリプトとCLIツールを使用してAIプラグインを作成して実行できるようにします 플러그인 생성기 스킬을 사용하여 개발자는 Python 스크립트와 CLI 도구를 사용하여 AI 플러그인을 생성하고 실행할 수 있습니다 Plugin Creator es una habilidad que permite a los desarrolladores crear plugins personalizados para herramientas de AI. Se ejecuta mediante scripts de Python. Plugin Creator est une compétence qui permet aux développeurs de créer des plugins personnalisés pour des outils d''IA. Il s''exécute via des scripts Python. Plugin Creator ist eine Fähigkeit, die es Entwicklern ermöglicht, benutzerdefinierte Plugins für KI-Tools zu erstellen. Sie wird über Python-Skripte ausgeführt. O Plugin Creator é uma ferramenta para criar plugins personalizados. Inicie com o script de criação e configure seu plugin em minutos Плагин Создатель - это инструмент для создания пользовательских плагинов. Начните с скрипта создания и настройте плагин за несколько минут Plugin Creator هو أداة لإنشاء ملحقات مخصصة. ابدأ مع سكريبت الإنشاء وتكوين الملحقات في دقائق how to use plugin-creator plugin-creator setup guide plugin-creator alternative plugin-creator vs other AI plugins plugin-creator install custom plugin creation for AI agents plugin-creator tutorial AI agent plugin development AI插件创建 OpenAI插件 Python脚本 CLI工具 AI工具 插件创建器 AI开发 插件开发 Runs scaffold script using python3 to generate basic plugin structure Creates plugin.json file for configuration and customization Supports plugin names in lower-case hyphen-case with a maximum of 64 characters Generates folder and plugin.json name based on the provided plugin name Allows for customization of plugin settings through the plugin.json file plugin-creator is a skill that allows developers to create and configure custom plugins for AI agents using Python scripts and JSON files.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('hzqst/metamod-fallguys/add-new-asext-api', 'community', 'hzqst', 'metamod-fallguys', 'hzqst/metamod-fallguys', 'add-new-asext-api', 16, 5, 33, '2026-02-22T05:31:36Z', '2026-03-06T06:43:17.325Z', '3cd40dcdbc897502e8b45ce6327d64555b3f41667e5807ad395223408ee0b585', '{"id":"hzqst/metamod-fallguys/add-new-asext-api","name":"add-new-asext-api","description":{"en":"The add-new-asext-api skill enables developers to expose private game server functions to external metamod plugins, such as fallguys and ascurl, for enhanced functionality.","zh":"本文介绍了如何为Sven Co-op的Fall Guys地图添加新的ASEXT API函数，包括如何使用IDA Pro查找私有函数，并将其封装到asext模块中","ja":"この記事では、Sven Co-opのFall Guysマップ用に新しいASEXT API関数を追加する方法を紹介します。IDA Proを使用してプライベート関数を見つけてasextモジュールにラップする方法を学びましょう","ko":"본 문서에서는 스벤 코옵의 폴 가이즈 맵에 새로운 ASEXT API 함수를 추가하는 방법을介绍합니다. IDA Pro를 사용하여 비공개 함수를 찾고 asext 모듈에 래핑하는 방법을 알아보세요","es":"El skill add-new-asext-api permite agregar funciones de API privadas de server.dll o server.so a la capa ASEXT para uso en plugins de Fall Guys","fr":"Le skill add-new-asext-api permet d''ajouter des fonctions d''API privées de server.dll ou server.so à la couche ASEXT pour une utilisation dans les plugins Fall Guys","de":"Das Skill add-new-asext-api ermöglicht das Hinzufügen privater API-Funktionen von server.dll oder server.so zur ASEXT-Schicht für die Verwendung in Fall-Guys-Plugins","pt":"O add-new-asext-api é um plugin de metamod que expõe funções privadas do servidor de jogo para plugins externos.","ru":"Add-new-asext-api - это плагин metamod, который暴ляет приватные функции игрового сервера для внешних плагинов.","ar":"إضافة جديدة لواجهة برمجة التطبيقات asext هي مكون إضافي لميتامود يتيح الوصول إلى وظائف خاصة بالخادم للأدوات الخارجية."},"seo":{"title":{"en":"add-new-asext-api: Metamod Plugin Setup Guide | AI Agent ...","zh":"添加新ASEXT API设置指南","ja":"新しいASEXT APIを追加するためのベストプラクティス - AIエージェント","ko":"새로운 ASEXT API 추가 방법 - AI 도구","es":"Guía de configuración de add-new-asext-api para Fall Guys","fr":"Guide d''intégration de l''API add-new-asext pour Fall Guys","de":"Einrichtungsleitfaden für add-new-asext-api in Fall Guys","pt":"Guia de Configuração do add-new-asext-api: Expansão de AP...","ru":"Руководство по настройке add-new-asext-api: Расширение AP...","ar":"دليل إعداد add-new-asext-api: توسيع واجهة برمجة التطبيقات..."},"description":{"en":"Discover how to add new ASEXT API functions to Fall Guys maps in Sven Co-op. Learn to wrap private server.dll/server.so functions for external plugin use.","zh":"了解如何为Sven Co-op的Fall Guys地图添加新的ASEXT API函数，提高游戏服务器的扩展性","ja":"Sven Co-opのFall Guysマップ用に新しいASEXT API関数を追加する方法を学び、ゲームサーバーの拡張性を高めましょう - AIエージェント","ko":"스벤 코옵의 폴 가이즈 맵에 새로운 ASEXT API 함수를 추가하여 게임 서버의 확장성을 높이는 방법을 알아보세요 - AI 도구","es":"Aprende a agregar una nueva función de API a la capa ASEXT para plugins de Fall Guys con add-new-asext-api","fr":"Découvrez comment ajouter une nouvelle fonction d''API à la couche ASEXT pour les plugins Fall Guys avec add-new-asext-api","de":"Erfahren Sie, wie Sie eine neue API-Funktion zur ASEXT-Schicht für Fall-Guys-Plugins mit add-new-asext-api hinzufügen","pt":"Aprenda a adicionar novas funções de API ao módulo asext para plugins de metamod, como fallguys e ascurl","ru":"Узнайте, как добавить новые функции API в модуль asext для плагинов metamod, таких как fallguys и ascurl","ar":"تعلم كيفية إضافة وظائف جديدة للواجهة البرمجية لمODULE asext لملحقات ميتامود مثل فॉल جايز وأسكيرل"},"definition":{"en":"add-new-asext-api is a metamod plugin skill for adding new exported API functions to the asext module in Sven Co-op","zh":"ASEXT API是Sven Co-op游戏服务器的扩展模块，允许开发者添加新的API函数以增强游戏功能","ja":"ASEXT APIは、Sven Co-opゲームサーバーの拡張モジュールであり、開発者が新しいAPI関数を追加してゲーム機能を強化できるようにします","ko":"ASEXT API는 스벤 코옵 게임 서버의 확장 모듈로, 개발자가 새로운 API 함수를 추가하여 게임 기능을 강화할 수 있도록 합니다","es":"Add-new-asext-api es un plugin de metamod que expone funciones de API privadas a la capa ASEXT para plugins de Fall Guys","fr":"Add-new-asext-api est un plugin de metamod qui expose des fonctions d''API privées à la couche ASEXT pour les plugins Fall Guys","de":"Add-new-asext-api ist ein Metamod-Plugin, das private API-Funktionen zur ASEXT-Schicht für Fall-Guys-Plugins bereitstellt","pt":"O add-new-asext-api é um plugin que adiciona novas funções de API ao módulo asext","ru":"Add-new-asext-api - это плагин, который добавляет новые функции API в модуль asext","ar":"إضافة جديدة لواجهة برمجة التطبيقات asext هو مكون إضافي يضيف وظائف جديدة إلى وحدة asext"},"features":{"en":["Wraps private functions from server.dll (Windows) / server.so (Linux) for external access","Exposes functions through the ASEXT_* API layer for plugin import","Supports runtime calls from external plugins like fallguys and ascurl","Utilizes IDA Pro for identifying private functions in game server binaries","Enables creation of custom metamod plugins for Fall Guys maps"],"zh":["使用IDA Pro查找私有函数","将私有函数封装到asext模块中","通过ASEXT_API层暴露私有函数","支持Windows和Linux游戏服务器","可用于Fall Guys和其他metamod插件"],"ja":["IDA Proを使用してプライベート関数を見つける","プライベート関数をasextモジュールにラップする","ASEXT_API層を介してプライベート関数を公開する","WindowsおよびLinuxゲームサーバーをサポートする","Fall Guysおよびその他のmetamodプラグインで使用可能"],"ko":["IDA Pro를 사용하여 비공개 함수를 찾기","비공개 함수를 asext 모듈에 래핑하기","ASEXT_API 계층을 통해 비공개 함수를公开하기","Windows 및 Linux 게임 서버를 지원하기","폴 가이즈 및 기타 metamod 플러그인에서 사용 가능"],"es":["Integración con la capa ASEXT","Acceso a funciones de API privadas de server.dll o server.so","Compatibilidad con plugins de Fall Guys","Uso de IDA Pro para identificar funciones privadas","Soporte para Windows y Linux"],"fr":["Intégration à la couche ASEXT","Accès aux fonctions d''API privées de server.dll ou server.so","Compatibilité avec les plugins Fall Guys","Utilisation d''IDA Pro pour identifier les fonctions privées","Prise en charge de Windows et Linux"],"de":["Integration in die ASEXT-Schicht","Zugriff auf private API-Funktionen von server.dll oder server.so","Kompatibilität mit Fall-Guys-Plugins","Verwendung von IDA Pro zur Identifizierung privater Funktionen","Unterstützung für Windows und Linux"],"pt":["Expõe funções privadas do servidor de jogo para plugins externos","Permite a criação de plugins personalizados para o jogo Fall Guys","Utiliza o módulo asext para fornecer uma camada de API para plugins","Compatível com plataformas Windows e Linux","Utiliza a ferramenta IDA Pro para identificar funções privadas do servidor de jogo"],"ru":["Обеспечивает доступ к приватным функциям игрового сервера для внешних плагинов","Позволяет создавать пользовательские плагины для игры Fall Guys","Использует модуль asext для предоставления слоя API для плагинов","Компатибелен с платформами Windows и Linux","Использует инструмент IDA Pro для идентификации приватных функций игрового сервера"],"ar":["يتيح الوصول إلى وظائف خاصة بالخادم للأدوات الخارجية","یمكّن من إنشاء ملحقات مخصصة للعبة فॉल جايز","يستخدم وحدة asext لتوفير طبقة واجهة برمجة التطبيقات للأدوات","متوافق مع منصات Windows و Linux","يستخدم أداة IDA Pro لتحديد وظائف خاصة بالخادم"]},"keywords":{"en":["how to use add-new-asext-api","add-new-asext-api setup guide","metamod plugin development","ASEXT API documentation","Fall Guys map customization","Sven Co-op plugin creation","add-new-asext-api alternative","add-new-asext-api vs metamod plugin"],"zh":["ASEXT API","Sven Co-op","Fall Guys","IDA Pro","游戏服务器扩展","AI工具","metamod插件","私有函数封装","ASEXT_API层"],"ja":["ASEXT API","Sven Co-op","Fall Guys","IDA Pro","ゲームサーバー拡張","AIエージェント","metamodプラグイン","プライベート関数ラップ","ASEXT_API層"],"ko":["ASEXT API","스벤 코옵","폴 가이즈","IDA Pro","게임 서버 확장","AI 도구","metamod 플러그인","비공개 함수 래핑","ASEXT_API 계층"],"es":["add-new-asext-api","plugin de metamod","Fall Guys","API ASEXT","server.dll","server.so","IDA Pro","desarrollo de plugins","Herramientas de AI para desarrolladores"],"fr":["add-new-asext-api","plugin de metamod","Fall Guys","API ASEXT","server.dll","server.so","IDA Pro","développement de plugins","Outils d''IA pour développeurs"],"de":["add-new-asext-api","Metamod-Plugin","Fall Guys","ASEXT-API","server.dll","server.so","IDA Pro","Plugin-Entwicklung","KI-Tools für Entwickler"],"pt":["add-new-asext-api","metamod plugin","fall guys","asext API","IDA Pro","servidor de jogo","plugins personalizados","desenvolvimento de jogos"],"ru":["add-new-asext-api","плагин metamod","fall guys","API asext","IDA Pro","игровой сервер","пользовательские плагины","разработка игр"],"ar":["إضافة جديدة لواجهة برمجة التطبيقات asext","مكون إضافي لميتامود","فول جايز","واجهة برمجة التطبيقات asext","IDA Pro","خادم الألعاب","ملحقات مخصصة","تطوير الألعاب"]}},"owner":"hzqst","repo":"metamod-fallguys","repoPath":"hzqst/metamod-fallguys","stars":16,"forks":5,"updatedAt":"2026-02-22T05:31:36Z","topics":[],"category":"community","skillMd":{"name":"add-new-asext-api","description":"Add a new exported API function to the asext module, wrapping a private server.dll/server.so function for use by external plugins. Use when you need to expose CASDocumentation, CASDirectoryList, or other AngelScript-related private functions through the ASEXT_* API layer.","bodyPreview":"# Add New ASEXT API\n\n## Overview\n\nThis skill covers the end-to-end process of adding a new exported API function to the **asext** module. It wraps a private function from `server.dll` (Windows) / `server.so` (Linux) and exposes it through the `ASEXT_*` API layer so that external plugins (e.g., fallguys, ascurl) can import and call it at runtime.\n\n**When to use**: You have identified a private function in the game server binary (via IDA Pro) that you want to make available to other metamod plugin","body":"# Add New ASEXT API\n\n## Overview\n\nThis skill covers the end-to-end process of adding a new exported API function to the **asext** module. It wraps a private function from `server.dll` (Windows) / `server.so` (Linux) and exposes it through the `ASEXT_*` API layer so that external plugins (e.g., fallguys, ascurl) can import and call it at runtime.\n\n**When to use**: You have identified a private function in the game server binary (via IDA Pro) that you want to make available to other metamod plugins through asext''s dynamic import system.\n\n**Prerequisite knowledge**: Familiarity with the [add-private-function-with-signatures](../add-private-function-with-signatures/SKILL.md) skill for IDA analysis and signature creation basics.\n\n## Files to Modify (6 files)\n\n| # | File | Purpose |\n|---|------|---------|\n| 1 | `asext/serverdef.h` | Function typedef + `PRIVATE_FUNCTION_EXTERN` |\n| 2 | `asext/signatures.h` | Windows signature, Linux signature + symbol |\n| 3 | `asext/server_hook.cpp` | `PRIVATE_FUNCTION_DEFINE` + `ASEXT_*` wrapper |\n| 4 | `asext/meta_api.cpp` | `FILL_FROM_*` calls (3 code paths) + `LOG_MESSAGE` |\n| 5 | `asext/asext.h` | `C_DLLEXPORT` declaration (internal header) |\n| 6 | `asext/include/asext_api.h` | typedef + extern + `IMPORT_ASEXT_API` + `IMPORT_ASEXT_API_DEFINE` macros |\n\nSee [asext-file-map.md](references/asext-file-map.md) for detailed file roles and layout.\n\n## Workflow\n\n### Step 1: Analyze Target Function and Create Signatures\n\nUse the [add-private-function-with-signatures](../add-private-function-with-signatures/SKILL.md) skill for the full IDA Pro workflow: decompile, extract bytes, craft signature with wildcards, and verify uniqueness.\n\n**Key observations to record** during IDA analysis:\n- **Return type** (void, int, etc.)\n- **Calling convention** (Windows: `__thiscall`/`__fastcall`/`__cdecl`; Linux: `__cdecl`)\n- **Parameter list** (types and count)\n- **Struct offsets** used inside the function (may differ between Windows and Linux)\n\n**Repeat for both platforms** (server.dll AND server.so) if both IDA databases are available.\n\n**For Linux 5.15**: Also record the C++ mangled symbol name (e.g. `_ZN16CASDocumentation19SetDefaultNamespaceEPKc`). If the binary is stripped (no symbols), only a signature is needed.\n\n### Step 2: Define Function Type in `asext/serverdef.h`\n\nAdd the typedef and extern declaration alongside existing `CASDocumentation_*` functions:\n\n```cpp\n// Comment describing the function and its Windows calling convention\ntypedef ReturnType (SC_SERVER_DECL *fnClassName_MethodName)(\n    ClassName *pthis, SC_SERVER_DUMMYARG ParamType1 param1, ParamType2 param2);\nPRIVATE_FUNCTION_EXTERN(ClassName_MethodName);\n```\n\n**Naming convention**: `fnClassName_MethodName` for the typedef, `ClassName_MethodName` for the macro name.\n\n**Calling convention selection**:\n- Class member functions (most cases): `SC_SERVER_DECL` + `SC_SERVER_DUMMYARG`\n- Static / free C functions: `SC_SERVER_CDECL` (no dummy arg)\n\n**If the function is also a hook target** (needs inline hook), add the `New*` declaration:\n```cpp\nReturnType SC_SERVER_DECL NewClassName_MethodName(\n    ClassName *pthis, SC_SERVER_DUMMYARG ParamType1 param1, ParamType2 param2);\n```\n\n### Step 3: Add Signatures in `asext/signatures.h`\n\nThe file has two sections separated by `#ifdef _WIN32` / `#else`.\n\n**Windows section** (inside `#ifdef _WIN32`):\n```cpp\n#define ClassName_MethodName_Signature \"\\x56\\x8B\\xF1\\x57...\"\n```\n\n**Linux section** (inside `#else`):\n```cpp\n#define ClassName_MethodName_Signature \"\\x56\\x53\\x83\\xEC\\x2A...\"\n#define ClassName_MethodName_Symbol \"_ZN<len>ClassName<len>MethodNameE<param_types>\"\n```\n\n**Placement**: Insert after the last function of the same class group (e.g., after `CASDocumentation_RegisterEnumValue` for CASDocumentation functions).\n\n**If signature is unknown for a platform**, use empty string `\"\"` as placeholder — the corresponding `FILL_FROM_*` call must be omitted from meta_api.cpp until the signature is provided.\n\n### Step 4: Define Function Pointer in `asext/server_hook.cpp`\n\n**4a. Add PRIVATE_FUNCTION_DEFINE** at the top of the file (with other defines):\n\n```cpp\nPRIVATE_FUNCTION_DEFINE(ClassName_MethodName);\n```\n\nThis expands to:\n```cpp\nfnClassName_MethodName g_pfn_ClassName_MethodName = NULL;\nfnClassName_MethodName g_call_original_ClassName_MethodName = NULL;\n```\n\n**4b. Add the ASEXT_* wrapper function** (the exported API that external plugins call):\n\n```cpp\nC_DLLEXPORT void ASEXT_MethodName(ClassName* pthis, ParamType1 param1)\n{\n    SC_SERVER_DUMMYVAR;\n    g_call_original_ClassName_MethodName(pthis, SC_SERVER_PASS_DUMMYARG param1);\n}\n```\n\n**Naming convention**: `ASEXT_MethodName` (drop the class name prefix, keep the method name).\n\n**Important**: The wrapper uses `g_call_original_*` (not `g_pfn_*`) to call through the original function pointer. For non-hooked functions, both point to the same address.\n\n### Step 5: Fill Function Pointer in `asext/meta_api.cpp`\n\nThere are **three code paths** in `Meta_Attach` that must be updated:\n\n**5a. Windows branch** (`#ifdef _WIN32`, ~line 162+):\n\n```cpp\nFILL_FROM_SIGNATURE(server, ClassName_MethodName);\n```\n\nOr if using a caller-based signature:\n```cpp\nFILL_FROM_SIGNATURED_CALLER_FROM_END(server, ClassName_MethodName, <offset>);\n```\n\n**5b. Linux 5.16+ branch** (`if (CreateInterface(\"SCServerDLL003\", nullptr))`, ~line 206+):\n\n```cpp\nFILL_FROM_SIGNATURE(server, ClassName_MethodName);\n```\n\nOr with caller-based:\n```cpp\nFILL_FROM_SIGNATURED_CALLER_FROM_START(server, ClassName_MethodName, <offset>);\n```\n\n**5c. Linux 5.15 branch** (`else`, ~line 262+):\n\n```cpp\nFILL_FROM_SYMBOL(server, ClassName_MethodName);\n```\n\n**5d. Add LOG_MESSAGE** (after `#endif`, ~line 300+):\n\n```cpp\nLOG_MESSAGE(PLID, \"ClassName_MethodName found at %p\", g_pfn_ClassName_MethodName);\n```\n\n**Placement in each block**: Insert after the last function of the same class group to maintain ordering.\n\nFor the full list of `FILL_FROM_*` macros and the caller-based signature approach, see [add-private-function-with-signatures](../add-private-function-with-signatures/SKILL.md) Step 5 and Step 5b.\n\n### Step 6: Add Declaration in `asext/asext.h`\n\nAdd the `C_DLLEXPORT` declaration for the wrapper function:\n\n```cpp\n/*\n    Must be called inside DocInitCallback\n*/\nC_DLLEXPORT void ASEXT_MethodName(ClassName* pthis, ParamType1 param1);\n```\n\n**Placement**: At the end of the file, or grouped with related functions.\n\n### Step 7: Add to Import API in `asext/include/asext_api.h`\n\nThis file is used by **external plugins** to dynamically import asext functions. Three locations must be updated:\n\n**7a. Add typedef + extern** (alongside existing ASEXT_* declarations):\n\n```cpp\n/*\n    Must be called inside DocInitCallback\n*/\ntypedef void(*fnASEXT_MethodName)(ClassName* pASDoc, ParamType1 param1);\n\nextern fnASEXT_MethodName ASEXT_MethodName;\n```\n\n**7b. Add to `IMPORT_ASEXT_API` macro** (the DLSYM import block):\n\n```cpp\nIMPORT_FUNCTION_DLSYM(asext, ASEXT_MethodName);\\\n```\n\n**7c. Add to `IMPORT_ASEXT_API_DEFINE` macro** (the definition block):\n\n```cpp\nIMPORT_FUNCTION_DEFINE(ASEXT_MethodName);\\\n```\n\nSee [import-macro-guide.md](references/import-macro-guide.md) for details on how these macros work.\n\n## Complete Example: `ASEXT_SetDefaultNamespace`\n\nBelow is the exact diff for adding `CASDocumentation::SetDefaultNamespace` support:\n\n### serverdef.h\n```cpp\ntypedef void (SC_SERVER_DECL* fnCASDocumentation_SetDefaultNamespace)(\n    CASDocumentation* pthis, SC_SERVER_DUMMYARG const char* ns);\nPRIVATE_FUNCTION_EXTERN(CASDocumentation_SetDefaultNamespace);\n```\n\n### signatures.h\n```cpp\n// Windows (direct function body, __thiscall)\n#define CASDocumentation_SetDefaultNamespace_Signature \\\n    \"\\x56\\x8B\\xF1\\x57\\x8B\\x7C\\x24\\x2A\\x57\\x8B\\x4E\\x24\\x8B\\x01\\xFF\\x90\\xB4\\x00\\x00\\x00\\x85\\xC0\\x78\\x03\\x89\\x7E\\x28\"\n\n// Linux (direct function body, cdecl)\n#define CASDocumentation_SetDefaultNamespace_Signature \\\n    \"\\x56\\x53\\x83\\xEC\\x2A\\x8B\\x5C\\x24\\x2A\\x8B\\x74\\x24\\x2A\\x8B\\x43\\x20\\x8B\\x10\\x89\\x74\\x24\\x2A\\x89\\x04\\x24\\xFF\\x92\\xB4\\x00\\x00\\x00\\x85\\xC0\\x78\\x03\\x89\\x73\\x24\"\n\n#define CASDocumentation_SetDefaultNamespace_Symbol \\\n    \"_ZN16CASDocumentation19SetDefaultNamespaceEPKc\"\n```\n\n### server_hook.cpp\n```cpp\nPRIVATE_FUNCTION_DEFINE(CASDocumentation_SetDefaultNamespace);\n\nC_DLLEXPORT void ASEXT_SetDefaultNamespace(CASDocumentation* pthis, const char* ns)\n{\n    SC_SERVER_DUMMYVAR;\n    g_call_original_CASDocumentation_SetDefaultNamespace(pthis, SC_SERVER_PASS_DUMMYARG ns);\n}\n```\n\n### meta_api.cpp\n```cpp\n// Windows\nFILL_FROM_SIGNATURE(server, CASDocumentation_SetDefaultNamespace);\n\n// Linux 5.16+\nFILL_FROM_SIGNATURE(server, CASDocumentation_SetDefaultNamespace);\n\n// Linux 5.15\nFILL_FROM_SYMBOL(server, CASDocumentation_SetDefaultNamespace);\n\n// Logging\nLOG_MESSAGE(PLID, \"CASDocumentation_SetDefaultNamespace found at %p\",\n    g_pfn_CASDocumentation_SetDefaultNamespace);\n```\n\n### asext.h\n```cpp\n/*\n    Must be called inside DocInitCallback\n*/\nC_DLLEXPORT void ASEXT_SetDefaultNamespace(CASDocumentation* pASDoc, const char* ns);\n```\n\n### asext_api.h\n```cpp\n// typedef + extern\ntypedef void(*fnASEXT_SetDefaultNamespace)(CASDocumentation* pASDoc, const char* ns);\nextern fnASEXT_SetDefaultNamespace ASEXT_SetDefaultNamespace;\n\n// In IMPORT_ASEXT_API macro\nIMPORT_FUNCTION_DLSYM(asext, ASEXT_SetDefaultNamespace);\\\n\n// In IMPORT_ASEXT_API_DEFINE macro\nIMPORT_FUNCTION_DEFINE(ASEXT_SetDefaultNamespace);\\\n```\n\n## Platform Differences to Watch\n\n| Aspect | Windows (server.dll) | Linux (server.so) |\n|--------|---------------------|-------------------|\n| Calling convention | `__thiscall` / `__fastcall` (ecx=this) | `cdecl` (this on stack) |\n| Struct offsets | May differ (e.g., `this+0x24`) | May differ (e.g., `this+0x20`) |\n| vtable offsets | Usually same across platforms | Usually same across platforms |\n| Signature source | IDA Pro on server.dll | IDA Pro on server.so |\n| Symbol availability | Never (use signatures only) | 5.15 has symbols; 5.16+ stripped |\n| Stack cleanup | `ret N` for thiscall | Caller cleans |\n\n## Checklist\n\n- [ ] **IDA Analysis**: Decompile target function on both Windows and Linux\n- [ ] **Signature Creation**: Create signatures from function bytes\n- [ ] **Signature Verification**: Verify uniqueness with `find_bytes` in IDA (one match only)\n- [ ] `asext/serverdef.h`: Add `typedef` + `PRIVATE_FUNCTION_EXTERN`\n- [ ] `asext/signatures.h`: Add Windows signature (line 5–45 `#ifdef _WIN32` block)\n- [ ] `asext/signatures.h`: Add Linux signature + symbol (line 46+ `#else` block)\n- [ ] `asext/server_hook.cpp`: Add `PRIVATE_FUNCTION_DEFINE`\n- [ ] `asext/server_hook.cpp`: Add `ASEXT_*` wrapper function with `C_DLLEXPORT`\n- [ ] `asext/meta_api.cpp`: Add `FILL_FROM_SIGNATURE` in Windows branch\n- [ ] `asext/meta_api.cpp`: Add `FILL_FROM_SIGNATURE` in Linux 5.16+ branch\n- [ ] `asext/meta_api.cpp`: Add `FILL_FROM_SYMBOL` in Linux 5.15 branch\n- [ ] `asext/meta_api.cpp`: Add `LOG_MESSAGE` after `#endif`\n- [ ] `asext/asext.h`: Add `C_DLLEXPORT` declaration\n- [ ] `asext/include/asext_api.h`: Add `typedef` + `extern` declaration\n- [ ] `asext/include/asext_api.h`: Add to `IMPORT_ASEXT_API` macro\n- [ ] `asext/include/asext_api.h`: Add to `IMPORT_ASEXT_API_DEFINE` macro\n- [ ] **Build**: Compile on both Windows and Linux\n- [ ] **Runtime**: Verify `LOG_MESSAGE` shows non-NULL address\n- [ ] **Integration**: Test calling `ASEXT_*` from an external plugin\n\n## References\n\n- [asext-file-map.md](references/asext-file-map.md) - Detailed file roles and insertion points\n- [import-macro-guide.md](references/import-macro-guide.md) - How the IMPORT macros work\n- [../add-private-function-with-signatures/SKILL.md](../add-private-function-with-signatures/SKILL.md) - Base skill for IDA analysis and signatures\n- [../add-private-function-with-signatures/references/signature-patterns.md](../add-private-function-with-signatures/references/signature-patterns.md) - Signature creation best practices\n- [../add-private-function-with-signatures/references/calling-conventions.md](../add-private-function-with-signatures/references/calling-conventions.md) - Calling convention reference\n"},"lastSynced":"2026-03-06T06:43:17.325Z","agentAnalysis":{"suitability":{"en":"Perfect for Game Development Agents needing to expose private game server functions to external metamod plugins like fallguys and ascurl.","zh":"非常适合需要向外部 metamod 插件（如 fallguys 和 ascurl）暴露私有游戏服务器函数的游戏开发代理","ja":"ゲーム開発エージェントが外部のmetamodプラグイン（例：fallguysとascurl）に私有のゲームサーバー関数を公開する必要がある場合に最適","ko":"외부 metamod 플러그인(예: fallguys 및 ascurl)에 개인 게임 서버 함수를 노출해야 하는 게임 개발 에이전트에 적합","es":"Perfecto para agentes de desarrollo de juegos que necesitan exponer funciones privadas del servidor de juegos a plugins externos como fallguys y ascurl.","fr":"Idéal pour les agents de développement de jeux ayant besoin d''exposer des fonctions privées du serveur de jeux à des plugins externes tels que fallguys et ascurl.","de":"Perfekt für Game-Development-Agents, die private Game-Server-Funktionen an externe Metamod-Plugins wie fallguys und ascurl exponieren müssen.","pt":"Perfeito para Agentes de Desenvolvimento de Jogos que precisam expor funções privadas do servidor de jogos para plugins de metamod externos como fallguys e ascurl.","ru":"Идеально подходит для агентов разработки игр, которым необходимо暴ить приватные функции игрового сервера для внешних плагинов метамода, таких как fallguys и ascurl.","ar":"مثالي لعمليات开发 الألعاب التي تحتاج إلى التعرض لدوال الخادم الخاصة بالألعاب إلى الإضافات الخارجية مثل fallguys و ascurl."},"recommendation":{"en":"Empowers agents to wrap private functions from server.dll or server.so and expose them through the ASEXT_* API layer, enabling seamless integration with external plugins using protocols like IDA Pro for binary analysis.","zh":"赋予代理将私有函数从server.dll或server.so包装并通过ASEXT_* API层公开，实现与外部插件（如IDA Pro用于二进制分析）无缝集成","ja":"エージェントがserver.dllまたはserver.soからのプライベート関数をラップし、ASEXT_* APIレイヤーを介して公開できるようにし、IDA Proなどの外部プラグインとのシームレスな統合を可能にします","ko":"에이전트가 server.dll 또는 server.so의 개인 함수를 래핑하여 ASEXT_* API 계층을 통해 공개할 수 있도록 하여 IDA Pro와 같은 외부 플러그인과 원활하게 통합할 수 있습니다","es":"Permite a los agentes envolver funciones privadas de server.dll o server.so y exponerlas a través de la capa de API ASEXT_*, lo que permite una integración perfecta con plugins externos que utilizan protocolos como IDA Pro para análisis de binarios.","fr":"Permet aux agents d''encapsuler des fonctions privées de server.dll ou server.so et de les exposer via la couche d''API ASEXT_*, ce qui permet une intégration transparente avec des plugins externes utilisant des protocoles tels que IDA Pro pour l''analyse de binaires.","de":"Ermächtigt Agenten, private Funktionen von server.dll oder server.so einzuhüllen und über die ASEXT_*-API-Schicht zu exponieren, sodass eine nahtlose Integration mit externen Plugins möglich ist, die Protokolle wie IDA Pro für die Binäranalyse verwenden.","pt":"Habilita os agentes a embrulhar funções privadas do server.dll ou server.so e expô-las por meio da camada de API ASEXT_*, permitindo integração perfeita com plugins externos que usam protocolos como IDA Pro para análise binária.","ru":"Наделяет агентов возможностью оборачивать приватные функции server.dll или server.so и экспонировать их через слой API ASEXT_*, обеспечивая бесшовную интеграцию с внешними плагинами, использующими протоколы, такие как IDA Pro для бинарного анализа.","ar":"يمنح الوكلاء القدرة على تغليف الدوال الخاصة من server.dll أو server.so والتعرض لها من خلال طبقة API ASEXT_*, مما يتيح التكامل السلس مع الإضافات الخارجية التي تستخدم بروتوكولات مثل IDA Pro لتحليل الثنائي."},"useCases":{"en":["Exposing private game server functions to fallguys plugin","Integrating ascurl plugin with custom ASEXT API functions","Wrapping server.dll functions for import and call at runtime"],"zh":["向fallguys插件公开私有游戏服务器函数","将ascurl插件与自定义ASEXT API函数集成","包装server.dll函数以便在运行时导入和调用"],"ja":["fallguysプラグインにプライベートゲームサーバー関数を公開する","ascurlプラグインをカスタムASEXT API関数と統合する","server.dll関数をラップしてランタイムにインポートおよび呼び出す"],"ko":["fallguys 플러그인에 개인 게임 서버 함수를 공개","ascurl 플러그인을 사용자 지정 ASEXT API 함수와 통합","server.dll 함수를 래핑하여 런타임에 가져오고 호출"],"es":["Exponer funciones privadas del servidor de juegos al plugin fallguys","Integrar el plugin ascurl con funciones personalizadas de API ASEXT","Envolver funciones de server.dll para importar y llamar en tiempo de ejecución"],"fr":["Exposer des fonctions privées du serveur de jeux au plugin fallguys","Intégrer le plugin ascurl avec des fonctions d''API ASEXT personnalisées","Encapsuler des fonctions de server.dll pour les importer et appeler à l''exécution"],"de":["Private Game-Server-Funktionen an das fallguys-Plugin exponieren","Das ascurl-Plugin mit benutzerdefinierten ASEXT-API-Funktionen integrieren","Server.dll-Funktionen einhüllen, um sie zur Laufzeit zu importieren und aufzurufen"],"pt":["Expor funções privadas do servidor de jogos para o plugin fallguys","Integrar o plugin ascurl com funções personalizadas da API ASEXT","Embrulhar funções do server.dll para importação e chamada em tempo de execução"],"ru":["Экспонировать приватные функции игрового сервера для плагина fallguys","Интегрировать плагин ascurl с пользовательскими функциями API ASEXT","Оборачивать функции server.dll для импорта и вызова во время выполнения"],"ar":["التعرض لدوال الخادم الخاصة بالألعاب إلى الإضافة fallguys","التكامل بين الإضافة ascurl والدوال المخصصة من API ASEXT","تغليف دوال server.dll للاستيراد والاستدعاء في وقت التشغيل"]},"limitations":{"en":["Requires access to game server binary","Limited to Windows and Linux platforms","Needs IDA Pro for function identification"],"zh":["需要访问游戏服务器二进制文件","仅限Windows和Linux平台","需要IDA Pro进行函数识别"],"ja":["ゲームサーバーのバイナリファイルへのアクセスが必要","WindowsおよびLinuxプラットフォームにのみ対応","関数識別のためにIDA Proが必要"],"ko":["게임 서버 바이너리 파일에 액세스해야 함","Windows 및 Linux 플랫폼만 지원","함수 식별을 위해 IDA Pro가 필요"],"es":["Requiere acceso al binario del servidor de juegos","Limitado a plataformas Windows y Linux","Necesita IDA Pro para la identificación de funciones"],"fr":["Nécessite un accès au binaire du serveur de jeux","Limité aux plates-formes Windows et Linux","Nécessite IDA Pro pour l''identification des fonctions"],"de":["Erfordert Zugriff auf die Game-Server-Binärdatei","Begrenzt auf Windows- und Linux-Plattformen","Benötigt IDA Pro für die Funktionsidentifizierung"],"pt":["Requer acesso ao binário do servidor de jogos","Limitado às plataformas Windows e Linux","Necessita do IDA Pro para identificação de funções"],"ru":["Требует доступа к бинарному файлу игрового сервера","Ограничен платформами Windows и Linux","Требует IDA Pro для идентификации функций"],"ar":["يتطلب الوصول إلى الملف الثنائي للخادم","محدود بالمنصات Windows و Linux","يحتاج إلى IDA Pro لتحديد الدوال"]},"version":4},"contentHash":"3cd40dcdbc897502e8b45ce6327d64555b3f41667e5807ad395223408ee0b585","qualityScore":33}');
