INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('hzqst/metamod-fallguys/add-new-asext-api', 'add-new-asext-api', 'hzqst', 'metamod-fallguys', 'community', 'add-new-asext-api hzqst metamod-fallguys community The add-new-asext-api skill enables developers to expose private game server functions to external metamod plugins, such as fallguys and ascurl, for enhanced functionality. 本文介绍了如何为Sven Co-op的Fall Guys地图添加新的ASEXT API函数，包括如何使用IDA Pro查找私有函数，并将其封装到asext模块中 この記事では、Sven Co-opのFall Guysマップ用に新しいASEXT API関数を追加する方法を紹介します。IDA Proを使用してプライベート関数を見つけてasextモジュールにラップする方法を学びましょう 본 문서에서는 스벤 코옵의 폴 가이즈 맵에 새로운 ASEXT API 함수를 추가하는 방법을介绍합니다. IDA Pro를 사용하여 비공개 함수를 찾고 asext 모듈에 래핑하는 방법을 알아보세요 El skill add-new-asext-api permite agregar funciones de API privadas de server.dll o server.so a la capa ASEXT para uso en plugins de Fall Guys Le skill add-new-asext-api permet d''ajouter des fonctions d''API privées de server.dll ou server.so à la couche ASEXT pour une utilisation dans les plugins Fall Guys Das Skill add-new-asext-api ermöglicht das Hinzufügen privater API-Funktionen von server.dll oder server.so zur ASEXT-Schicht für die Verwendung in Fall-Guys-Plugins O add-new-asext-api é um plugin de metamod que expõe funções privadas do servidor de jogo para plugins externos. Add-new-asext-api - это плагин metamod, который暴ляет приватные функции игрового сервера для внешних плагинов. إضافة جديدة لواجهة برمجة التطبيقات asext هي مكون إضافي لميتامود يتيح الوصول إلى وظائف خاصة بالخادم للأدوات الخارجية. how to use add-new-asext-api add-new-asext-api setup guide metamod plugin development ASEXT API documentation Fall Guys map customization Sven Co-op plugin creation add-new-asext-api alternative add-new-asext-api vs metamod plugin ASEXT API Sven Co-op Fall Guys IDA Pro 游戏服务器扩展 AI工具 metamod插件 私有函数封装 ASEXT_API层 Wraps private functions from server.dll (Windows) / server.so (Linux) for external access Exposes functions through the ASEXT_* API layer for plugin import Supports runtime calls from external plugins like fallguys and ascurl Utilizes IDA Pro for identifying private functions in game server binaries Enables creation of custom metamod plugins for Fall Guys maps add-new-asext-api is a metamod plugin skill for adding new exported API functions to the asext module in Sven Co-op');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ampcode/zvelte-check/release', 'community', 'ampcode', 'zvelte-check', 'ampcode/zvelte-check', 'release', 12, 1, 33, '2026-02-20T01:29:22Z', '2026-03-06T13:02:31.289Z', 'fd99ea0a1033d67f7332feec3b295c374970b40a6820102fcfc37a6671039abd', '{"id":"ampcode/zvelte-check/release","name":"release","description":{"en":"The release skill automates versioning for zvelte-check using git tags and zig builds, benefiting developers by simplifying the release process.","zh":"Release是指自动化版本管理和发布的过程，通过git标签和CLI命令实现","ja":"リリースは自動バージョニングとAIエージェントの公開を指します","ko":"릴리스는 자동 버전 관리 및 출시를 의미합니다","es":"Esta skill para AI Agents automatiza el proceso de lanzamiento para proyectos Zig. Gestiona versiones mediante `git describe`, actualiza `build.zig.zon` y genera notas de release de forma estructurada, optimizando el workflow de desarrollo.","fr":"Cette compétence pour outils IA automatise le processus de release des projets Zig. Elle gère les versions via `git describe`, met à jour `build.zig.zon` et génère des notes de release structurées, optimisant le flux de développement.","de":"Diese Fähigkeit für KI-Agenten automatisiert den Release-Prozess für Zig-Projekte. Sie verwaltet Versionen über `git describe`, aktualisiert `build.zig.zon` und erstellt strukturierte Release-Notes, um den Entwicklungs-Workflow zu optimieren.","pt":"O release é um processo que envolve atualizar a versão e criar notas de lançamento para o zvelte-check","ru":"Релиз - это процесс, который включает обновление версии и создание заметок о выпуске для zvelte-check","ar":"الإصدار هو عملية تتضمن تحديث الإصدار وإنشاء ملاحظات الإصدار ل zvelte-check"},"seo":{"title":{"en":"Release: Automated Versioning Setup Guide | AI Agent Skill","zh":"Release_SETUP指南：自动化版本管理和发布","ja":"リリースセットアップガイド：自動バージョニングとAIエージェントの公開","ko":"릴리스 설정 가이드: 자동 버전 관리 및 출시","es":"Guía de lanzamiento para AI Agents: Automatización de ver...","fr":"Guide de release pour outils IA : Automatisation des vers...","de":"Release-Leitfaden für KI-Agenten: Versionsautomatisierung...","pt":"Guia de Configuração de Release para Desenvolvedores","ru":"Руководство по настройке релиза для ИИ Агентов","ar":"دليل إعداد الإصدار للنمižة"},"description":{"en":"Learn how to automate versioning with the release skill, streamlining your workflow with git tags and zig builds. Get started now!","zh":"了解Release的自动化版本管理和发布流程，包括git标签和CLI命令的使用","ja":"リリースの自動バージョニングとAIエージェントの公開方法について説明します","ko":"릴리스의 자동 버전 관리 및 출시 절차를 알아보세요","es":"Automatiza el versionado y lanzamiento de proyectos Zig con git tags. Aprende a configurar `build.zig` para derivar versiones automáticamente y gestionar rel...","fr":"Automatisez le versionnage et la release de projets Zig avec des tags git. Configurez `build.zig` pour dériver les versions automatiquement et gérez les rele...","de":"Automatisieren Sie die Versionierung und das Release von Zig-Projekten mit Git-Tags. Konfigurieren Sie `build.zig` für automatische Versionierung und verwalt...","pt":"Aprenda a configurar o release com o zvelte-check, incluindo atualização de versão e criação de notas de lançamento","ru":"Узнайте, как настроить релиз с помощью zvelte-check, включая обновление версии и создание заметок о выпуске","ar":"تعلم كيفية إعداد الإصدار باستخدام zvelte-check، بما في ذلك تحديث الإصدار وإنشاء ملاحظات الإصدار"},"definition":{"en":"Release is a skill that automates versioning using git describe and zig builds, eliminating manual version updates.","zh":"Release是指软件或AI工具的版本发布和管理过程","ja":"リリースはソフトウェアまたはAIエージェントのバージョン公開と管理プロセスを指します","ko":"릴리스는 소프트웨어 또는 AI 도구의 버전 출시 및 관리 프로세스를 의미합니다","es":"Una skill de AI Agent que automatiza el proceso de lanzamiento de software para proyectos Zig. Utiliza git tags para el versionado automático, gestiona la actualización de `build.zig.zon` y la creación de documentación de releases en Markdown.","fr":"Une compétence d''outil IA qui automatise le processus de release logicielle pour les projets Zig. Elle utilise les tags git pour le versionnage automatique, gère la mise à jour de `build.zig.zon` et la création de documentation de releases en Markdown.","de":"Eine KI-Agenten-Fähigkeit, die den Software-Release-Prozess für Zig-Projekte automatisiert. Sie nutzt Git-Tags für automatische Versionierung, verwaltet die Aktualisierung von `build.zig.zon` und die Erstellung von Release-Dokumentation in Markdown.","pt":"O que é release? É o processo de preparação e distribuição de uma nova versão de software","ru":"Что такое релиз? Это процесс подготовки и распространения новой версии программного обеспечения","ar":"ما هو الإصدار؟ إنه عملية التحضير والتوزيع لإصدار جديد من البرمجيات"},"features":{"en":["Updates version in build.zig.zon","Writes release notes in docs/releases/vX.Y.Z.md","Commits changes and tags using git tag and git push","Derives version automatically from git tags at build time using git describe","Imports build_options.version in src/cli.zig"],"zh":["自动化版本管理","git标签和CLI命令的使用","版本号自动推导","build.zig和src/cli.zig的集成"],"ja":["自動バージョニング","gitタグとCLIコマンドの使用","バージョン番号の自動生成","build.zigとsrc/cli.zigの統合"],"ko":["자동 버전 관리","git 태그와 CLI 명령어의 사용","버전 번호 자동 생성","build.zig와 src/cli.zig의 통합"],"es":["Versionado automático con `git describe --match \"v*.*.*\" --tags`","Integración con `build.zig` mediante `getVersion()`","Actualización automática de versión en `build.zig.zon`","Generación de notas de release en `docs/releases/vX.Y.Z.md`","Workflow de tagging con `git tag vX.Y.Z && git push --tags`","Importación de versión mediante `build_options.version` en CLI"],"fr":["Versionnage automatique avec `git describe --match \"v*.*.*\" --tags`","Intégration avec `build.zig` via `getVersion()`","Mise à jour automatique de version dans `build.zig.zon`","Génération de notes de release dans `docs/releases/vX.Y.Z.md`","Workflow de tagging avec `git tag vX.Y.Z && git push --tags`","Importation de version via `build_options.version` en CLI"],"de":["Automatische Versionierung mit `git describe --match \"v*.*.*\" --tags`","Integration mit `build.zig` über `getVersion()`","Automatische Versionsaktualisierung in `build.zig.zon`","Generierung von Release-Notes in `docs/releases/vX.Y.Z.md`","Tagging-Workflow mit `git tag vX.Y.Z && git push --tags`","Versionsimport über `build_options.version` in der CLI"],"pt":["Atualização automática da versão com git describe","Criação de notas de lançamento em docs/releases/vX.Y.Z.md","Uso de git tag para marcação de versões","Integração com build.zig e src/cli.zig","Suporte a versões semânticas","Uso de comandos git para gerenciamento de versões"],"ru":["Автоматическое обновление версии с помощью git describe","Создание заметок о выпуске в docs/releases/vX.Y.Z.md","Использование git tag для маркировки версий","Интеграция с build.zig и src/cli.zig","Поддержка семантических версий","Использование команд git для управления версиями"],"ar":["تحديث تلقائي للإصدار مع git describe","إنشاء ملاحظات الإصدار في docs/releases/vX.Y.Z.md","استخدام git tag لتسمية الإصدارات","التكامل مع build.zig و src/cli.zig","دعم الإصدارات الدلالية","استخدام أوامر git لإدارة الإصدارات"]},"keywords":{"en":["how to use release","release setup guide","automated versioning with git","release alternative","zvelte-check release notes","git tag and push","zig build versioning"],"zh":["Release","自动化版本管理","git标签","CLI命令","AI工具","软件发布","版本管理"],"ja":["リリース","自動バージョニング","gitタグ","CLIコマンド","AIエージェント","ソフトウェア公開","バージョン管理"],"ko":["릴리스","자동 버전 관리","git 태그","CLI 명령어","AI 도구","소프트웨어 출시","버전 관리"],"es":["automatización release zig","git describe versionado","build.zig release workflow","AI Agents gestión versiones","zig versionado automático","release checklist desarrollo","git tags automatización","build.zig.zon actualización"],"fr":["automatisation release zig","git describe versionnage","build.zig workflow release","outils IA gestion versions","zig versionnage automatique","checklist release développement","tags git automatisation","build.zig.zon mise à jour"],"de":["release automatisierung zig","git describe versionierung","build.zig release workflow","KI-Agenten versionsverwaltung","zig automatische versionierung","release checkliste entwicklung","git tags automatisierung","build.zig.zon aktualisierung"],"pt":["release zvelte-check","configuração de release","atualização de versão","notas de lançamento","git describe","git tag","build.zig","src/cli.zig","versões semânticas"],"ru":["релиз zvelte-check","настройка релиза","обновление версии","заметки о выпуске","git describe","git tag","build.zig","src/cli.zig","семантические версии"],"ar":["إصدار zvelte-check","إعداد الإصدار","تحديث الإصدار","ملاحظات الإصدار","git describe","git tag","build.zig","src/cli.zig","إصدارات دلالية"]}},"owner":"ampcode","repo":"zvelte-check","repoPath":"ampcode/zvelte-check","stars":12,"forks":1,"updatedAt":"2026-02-20T01:29:22Z","topics":[],"category":"community","skillMd":{"name":"release","description":"Publishes zvelte-check releases. Use when releasing, versioning, tagging, or publishing a new version.","bodyPreview":"# Releasing zvelte-check\n\n## Quick Release Checklist\n\n1. Update version in `build.zig.zon`\n2. Write release notes in `docs/releases/vX.Y.Z.md`\n3. Commit changes\n4. Tag and push: `git tag vX.Y.Z && git push && git push --tags`\n\n## Version Handling\n\nThe version is derived automatically from git tags at build time using `git describe`. No manual version updates needed.\n\n- `build.zig` - `getVersion()` runs `git describe --match \"v*.*.*\" --tags`\n- `src/cli.zig` - imports `build_options.version` for `","body":"# Releasing zvelte-check\n\n## Quick Release Checklist\n\n1. Update version in `build.zig.zon`\n2. Write release notes in `docs/releases/vX.Y.Z.md`\n3. Commit changes\n4. Tag and push: `git tag vX.Y.Z && git push && git push --tags`\n\n## Version Handling\n\nThe version is derived automatically from git tags at build time using `git describe`. No manual version updates needed.\n\n- `build.zig` - `getVersion()` runs `git describe --match \"v*.*.*\" --tags`\n- `src/cli.zig` - imports `build_options.version` for `--version` output\n\nVersion format examples:\n- On a tag `v0.1.0` → `0.1.0`\n- 3 commits after tag → `0.1.0-3+abc123`\n- No tags → `unknown`\n\n## Release Notes\n\nCreate a markdown file at `docs/releases/vX.Y.Z.md` (must match the tag name exactly).\n\nExample for `docs/releases/v0.1.0.md`:\n\n```markdown\n## What''s New\n\n- Initial release of zvelte-check\n- Support for Svelte 5 runes and snippets\n- A11y, CSS, and TypeScript diagnostics\n\n## Breaking Changes\n\nNone (initial release)\n\n## Installation\n\n```bash\nbrew install ampcode/tap/zvelte-check\n```\n```\n\nIf no release notes file exists, the release will use \"Release vX.Y.Z\" as the body.\n\n## What Happens on Release\n\nWhen you push a tag matching `v*`:\n\n1. **Test job** - Runs `zig build` and `zig build test`\n2. **Build job** - Cross-compiles for 5 platforms:\n   - `x86_64-linux-gnu`\n   - `aarch64-linux-gnu`\n   - `x86_64-macos`\n   - `aarch64-macos`\n   - `x86_64-windows-gnu`\n3. **Release job** - Creates GitHub release with:\n   - Tarballs (`.tar.gz`) for Unix platforms\n   - Zip (`.zip`) for Windows\n   - `checksums.txt` with SHA256 hashes\n   - Release notes from `docs/releases/vX.Y.Z.md`\n4. **Homebrew update** - Pushes updated formula to `ampcode/homebrew-tap`\n\n## Prerelease Tags\n\nTags containing `-` (e.g., `v0.1.0-beta`, `v0.2.0-rc1`) are automatically marked as prereleases on GitHub.\n\n## Secrets Required\n\n- `HOMEBREW_TAP_TOKEN` - GitHub PAT with write access to `ampcode/homebrew-tap`\n\n## Aqua Registry\n\nTo make the release available via mise/aqua, submit a PR to [aquaproj/aqua-registry](https://github.com/aquaproj/aqua-registry) with the files from `.github/aqua/`.\n"},"lastSynced":"2026-03-06T13:02:31.289Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing automated versioning and release management using git tags and zig builds.","zh":"适用于需要使用git标签和zig构建进行自动化版本管理的开发代理。","ja":"gitタグとzigビルドを使用した自動バージョニングとリリース管理が必要な開発エージェントに適しています。","ko":"git 태그와 zig 빌드를 사용하여 자동 버전 관리 및 릴리스 관리가 필요한 개발 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollo que necesitan versionado y administración de lanzamientos automatizados utilizando etiquetas git y compilaciones zig.","fr":"Parfait pour les Agents de Développement ayant besoin d''une version et d''une gestion de versions automatiques utilisant des balises git et des builds zig.","de":"Perfekt für Entwicklungsmittel benötigende automatisierte Versionierung und Release-Management unter Verwendung von git-Tags und zig-Builds.","pt":"Perfeito para Agentes de Desenvolvimento que precisam de versionamento e gerenciamento de lançamento automatizados usando tags git e compilações zig.","ru":"Идеально для агентов разработки, которым необходим автоматизированный управление версиями и выпусками с использованием тегов git и сборок zig.","ar":"مثالي للوكلاء النمطية الذين يحتاجون إلى إصدار وتحديث إدارته آليًا باستخدام علامات جيت وبناء زيغ."},"recommendation":{"en":"Empowers agents to automate the release process using git describe and zig builds, simplifying version handling and providing a quick release checklist with features like automatic version derivation from git tags and release note management in markdown files.","zh":"赋予代理自动化发布过程的能力，使用git describe和zig构建，简化版本处理，并提供快速发布清单，具有从git标签自动推导版本和在markdown文件中管理发布说明等功能。","ja":"git describeとzigビルドを使用して、エージェントがリリースプロセスを自動化できるようにし、バージョンの管理を簡素化し、gitタグからの自動バージョン抽出やMarkdownファイルでのリリースノート管理などの機能で、迅速なリリースチェックリストを提供します。","ko":"에이전트가 git describe와 zig 빌드를 사용하여 릴리스 프로세스를 자동화 할 수 있도록 하며, 버전 관리를 단순화하고, git 태그에서 자동 버전 파생 및 markdown 파일에서 릴리스 노트 관리 등의 기능으로 빠른 릴리스 체크리스트를 제공합니다.","es":"Habilita a los agentes a automatizar el proceso de lanzamiento utilizando git describe y compilaciones zig, simplificando el manejo de versiones y proporcionando una lista de verificación de lanzamiento rápida con características como la derivación automática de versiones de etiquetas git y la gestión de notas de lanzamiento en archivos markdown.","fr":"Permet aux agents d''automatiser le processus de publication en utilisant git describe et des builds zig, simplifiant la gestion des versions et fournissant une liste de contrôle de publication rapide avec des fonctionnalités telles que la dérivation automatique des versions à partir de balises git et la gestion des notes de publication dans des fichiers markdown.","de":"Ermächtigt Agenten, den Release-Prozess mithilfe von git describe und zig-Builds zu automatisieren, vereinfacht die Versionsverwaltung und bietet eine schnelle Release-Checkliste mit Funktionen wie automatischer Versionsableitung aus git-Tags und Release-Notizen-Verwaltung in Markdown-Dateien.","pt":"Habilita os agentes a automatizar o processo de lançamento usando git describe e compilações zig, simplificando o tratamento de versões e fornecendo uma lista de verificação de lançamento rápida com recursos como derivação automática de versão a partir de tags git e gerenciamento de notas de lançamento em arquivos markdown.","ru":"Наделяет агентов возможностью автоматизировать процесс выпуска с использованием git describe и сборок zig, упрощая обработку версий и предоставляя быстрый чек-лист выпуска с функциями, такими как автоматическое получение версии из тегов git и управление заметками о выпуске в файлах markdown.","ar":"يمنح الوكلاء القدرة على توفير عملية الإصدار آليًا باستخدام وصف جيت وبناء زيغ، وبذلك يُبسط التعامل مع الإصدارات ويُقدم قائمة إعداد إصدار سريعة مع ميزات مثل اشتقاق الإصدار آليًا من علامات جيت وإدارة ملاحظات الإصدار في ملفات markdown."},"useCases":{"en":["Automating version updates in build.zig","Generating release notes in markdown files","Tagging and pushing releases to git repositories"],"zh":["在build.zig中自动更新版本","在markdown文件中生成发布说明","将发布标记并推送到git仓库"],"ja":["build.zigでのバージョン自動更新","Markdownファイルでのリリースノート生成","gitリポジトリへのリリースタグ付けとプッシュ"],"ko":["build.zig에서 버전 자동 更新","markdown 파일에서 릴리스 노트 생성","git 저장소에 릴리스 태그 지정 및 푸시"],"es":["Automatizar actualizaciones de versión en build.zig","Generar notas de lanzamiento en archivos markdown","Etiquetar y enviar lanzamientos a repositorios git"],"fr":["Automatiser les mises à jour de version dans build.zig","Générer des notes de publication dans des fichiers markdown","Étiqueter et envoyer des publications à des référentiels git"],"de":["Automatisieren von Versionsaktualisierungen in build.zig","Erstellen von Release-Notizen in Markdown-Dateien","Tagging und Übertragen von Releases an git-Repositorys"],"pt":["Automatizar atualizações de versão em build.zig","Gerar notas de lançamento em arquivos markdown","Marcar e enviar lançamentos para repositórios git"],"ru":["Автоматизировать обновления версий в build.zig","Генерировать заметки о выпуске в файлах markdown","Маркировать и отправлять выпуски в репозитории git"],"ar":["توفير تحديثات الإصدار في build.zig","إنشاء ملاحظات الإصدار في ملفات markdown","وضع علامات على الإصدارات وإرسالها إلى مستودعات جيت"]},"limitations":{"en":["Requires git repository access","Zig build environment needed","Manual update of version in build.zig.zon required"],"zh":["需要git仓库访问权限","需要zig构建环境","需要手动更新build.zig.zon中的版本"],"ja":["gitリポジトリへのアクセスが必要","Zigビルド環境が必要","build.zig.zonでのバージョンの手動更新が必要"],"ko":["git 저장소 액세스 권한 필요","zig 빌드 환경 필요","build.zig.zon에서 버전的手动 업데이트 필요"],"es":["Requiere acceso al repositorio git","Entorno de compilación zig necesario","Actualización manual de la versión en build.zig.zon requerida"],"fr":["Nécessite un accès au référentiel git","Environnement de build zig nécessaire","Mise à jour manuelle de la version dans build.zig.zon requise"],"de":["Benötigt Zugriff auf das git-Repository","Zig-Build-Umgebung erforderlich","Manuelle Aktualisierung der Version in build.zig.zon erforderlich"],"pt":["Requer acesso ao repositório git","Ambiente de compilação zig necessário","Atualização manual da versão em build.zig.zon requerida"],"ru":["Требуется доступ к репозиторию git","Необходимо окружение сборки zig","Требуется ручное обновление версии в build.zig.zon"],"ar":["يتطلب الوصول إلى مستودع جيت","بيئة بناء زيغ مطلوبة","يتطلب تحديث يدوي للإصدار في build.zig.zon"]},"version":4},"contentHash":"fd99ea0a1033d67f7332feec3b295c374970b40a6820102fcfc37a6671039abd","qualityScore":33}');
