INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ampcode/zvelte-check/release', 'release', 'ampcode', 'zvelte-check', 'community', 'release ampcode zvelte-check community The release skill automates versioning for zvelte-check using git tags and zig builds, benefiting developers by simplifying the release process. Release是指自动化版本管理和发布的过程，通过git标签和CLI命令实现 リリースは自動バージョニングとAIエージェントの公開を指します 릴리스는 자동 버전 관리 및 출시를 의미합니다 Esta skill para AI Agents automatiza el proceso de lanzamiento para proyectos Zig. Gestiona versiones mediante `git describe`, actualiza `build.zig.zon` y genera notas de release de forma estructurada, optimizando el workflow de desarrollo. Cette compétence pour outils IA automatise le processus de release des projets Zig. Elle gère les versions via `git describe`, met à jour `build.zig.zon` et génère des notes de release structurées, optimisant le flux de développement. Diese Fähigkeit für KI-Agenten automatisiert den Release-Prozess für Zig-Projekte. Sie verwaltet Versionen über `git describe`, aktualisiert `build.zig.zon` und erstellt strukturierte Release-Notes, um den Entwicklungs-Workflow zu optimieren. O release é um processo que envolve atualizar a versão e criar notas de lançamento para o zvelte-check Релиз - это процесс, который включает обновление версии и создание заметок о выпуске для zvelte-check الإصدار هو عملية تتضمن تحديث الإصدار وإنشاء ملاحظات الإصدار ل zvelte-check how to use release release setup guide automated versioning with git release alternative zvelte-check release notes git tag and push zig build versioning Release 自动化版本管理 git标签 CLI命令 AI工具 软件发布 版本管理 Updates version in build.zig.zon Writes release notes in docs/releases/vX.Y.Z.md Commits changes and tags using git tag and git push Derives version automatically from git tags at build time using git describe Imports build_options.version in src/cli.zig Release is a skill that automates versioning using git describe and zig builds, eliminating manual version updates.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ScavieFae/nojohns/troubleshoot', 'community', 'ScavieFae', 'nojohns', 'ScavieFae/nojohns', 'troubleshoot', 8, 0, 33, '2026-02-24T23:42:48Z', '2026-03-06T06:48:58.670Z', '92eec89571bf7a53ca1fe8a2a19214309cf79f125dff1001f650eb341e7a2412', '{"id":"ScavieFae/nojohns/troubleshoot","name":"troubleshoot","description":{"en":"The troubleshoot skill helps developers diagnose and fix common setup problems for Melee AI tournaments. It provides a step-by-step guide to resolve issues with Slippi netplay and Moltbots.","zh":"故障排除技能用于诊断和修复Moltbots Melee AI锦标赛的常见问题，确保Slippi网游的顺畅运行。它包括系统检查、Python版本检查和虚拟环境检查等步骤","ja":"トラブルシューティングスキルは、Moltbots Melee AIトーナメントの一般的な問題を診断および修復し、Slippiネットプレイのスムーズな実行を確保します。システムチェック、Pythonバージョンチェック、仮想環境チェックなどのステップを含みます","ko":"트러블슈팅 스킬은 몰트봇 Melee AI 토너먼트의 일반적인 문제를 진단 및 수정하여 Slippi 네트워크 플레이의 원활한 실행을 보장합니다. 시스템 체크, Python 버전 체크, 가상 환경 체크 등의 단계를 포함합니다","es":"El troubleshoot ayuda a diagnosticar y solucionar problemas de configuración de No Johns para desarrolladores de AI Agentes. Incluye comprobaciones de sistema y versión de Python.","fr":"Le dépannage aide à diagnostiquer et à résoudre les problèmes de configuration de No Johns pour les développeurs d''agents IA. Il comprend des vérifications de système et de version de Python.","de":"Das Troubleshoot hilft bei der Diagnose und Behebung von Konfigurationsproblemen von No Johns für KI-Agenten-Entwickler. Es umfasst System- und Python-Version-Checks.","pt":"O troubleshoot é uma ferramenta para diagnosticar e corrigir problemas de configuração do Moltbots, incluindo verificações de sistema e versão do Python.","ru":"Troubleshoot - это инструмент для диагностики и исправления проблем настройки Moltbots, включая проверки системы и версии Python.","ar":"Troubleshoot هو أداة لتشخيص ومعالجة مشاكل إعداد محاربي Moltbots، بما في ذلك فحوصات النظام وإصدار بايثون."},"seo":{"title":{"en":"Troubleshoot: Setup Guide for AI Agents | AI Agent Skill","zh":"故障排除指南：Moltbots Melee AI锦标赛排除故障","ja":"トラブルシューティングガイド：Moltbots Melee AIトーナメントのエラー解決","ko":"트러블슈팅 가이드: 몰트봇 Melee AI 토너먼트 문제 해결","es":"Guía de Configuración de Herramientas de Troubleshoot par...","fr":"Guide de Configuration de l''Outil de Dépannage pour les A...","de":"Troubleshoot-Setup-Leitfaden für KI-Agenten-Tools","pt":"Guia de Configuração do Troubleshoot para Moltbots","ru":"Настройка Troubleshoot для ИИ Агентов Moltbots","ar":"دليل إعداد Troubleshoot لمحاربي Moltbots"},"description":{"en":"Resolve common issues with Melee AI tournaments using our troubleshoot guide. Learn how to diagnose and fix problems with Slippi netplay and Moltbots.","zh":"使用故障排除技能排除Moltbots Melee AI锦标赛的常见问题，确保Slippi网游的顺畅运行","ja":"トラブルシューティングスキルを使用してMoltbots Melee AIトーナメントの一般的な問題を解決し、Slippiネットプレイのスムーズな実行を確保する","ko":"트러블슈팅 스킬을 사용하여 몰트봇 Melee AI 토너먼트의 일반적인 문제를 해결하고 Slippi 네트워크 플레이의 원활한 실행을 보장합니다","es":"Resuelva problemas comunes de configuración de No Johns con nuestra guía de troubleshoot paso a paso para desarrolladores de AI Agentes","fr":"Résolvez les problèmes courants de configuration de No Johns avec notre guide de dépannage étape par étape pour les développeurs d''agents IA","de":"Lösen Sie häufige Konfigurationsprobleme von No Johns mit unserem Schritt-für-Schritt-Troubleshoot-Leitfaden für KI-Agenten-Entwickler","pt":"Aprenda a diagnosticar e corrigir problemas comuns de configuração do Moltbots com o guia de troubleshoot","ru":"Узнайте, как диагностировать и исправлять общие проблемы настройки Moltbots с помощью руководства по устранению неполадок","ar":"تعلم كيفية تشخيص ومعالجة مشاكل الإعداد الشائعة لمحاربي Moltbots باستخدام دليل Troubleshoot"},"definition":{"en":"troubleshoot is a diagnostic tool for identifying and resolving common setup issues in Melee AI tournaments, ensuring seamless gameplay and competition.","zh":"故障排除是指使用技术手段来诊断和修复Moltbots Melee AI锦标赛的常见问题的过程","ja":"トラブルシューティングとは、Moltbots Melee AIトーナメントの一般的な問題を技術的手段を使用して診断および修復するプロセスです","ko":"트러블슈팅은 몰트봇 Melee AI 토너먼트의 일반적인 문제를 기술적인 수단을 사용하여 진단 및 수정하는 과정입니다","es":"El troubleshoot es una herramienta que ayuda a diagnosticar y solucionar problemas de configuración de AI Agentes","fr":"Le dépannage est un outil qui aide à diagnostiquer et à résoudre les problèmes de configuration des agents IA","de":"Das Troubleshoot ist ein Tool, das bei der Diagnose und Behebung von Konfigurationsproblemen von KI-Agenten hilft","pt":"O que é troubleshoot? É uma ferramenta de diagnóstico para identificar e corrigir problemas de configuração.","ru":"Что такое troubleshoot? Это инструмент диагностики для выявления и исправления проблем настройки.","ar":"ما هو Troubleshoot؟ إنه أداة تشخيص لتحديد ومعالجة مشاكل الإعداد."},"features":{"en":["Runs system checks using uname and python3.12 commands","Verifies Python version and virtual environment (venv) existence","Checks venv Python version using .venv/bin/python command","Provides step-by-step guide for diagnosing and fixing setup problems","Supports Slippi netplay and Moltbots pluggable fighters"],"zh":["系统检查：检查操作系统和架构","Python版本检查：确保Python版本为3.12.x","虚拟环境检查：检查虚拟环境的存在和Python版本","Slippi网游支持：确保Slippi网游的顺畅运行"],"ja":["システムチェック：オペレーティングシステムとアーキテクチャを確認する","Pythonバージョンチェック：Pythonバージョンが3.12.xであることを確認する","仮想環境チェック：仮想環境の存在とPythonバージョンを確認する","Slippiネットプレイサポート：Slippiネットプレイのスムーズな実行を確保する"],"ko":["시스템 체크: 운영 체제와 아키텍처를 확인합니다","Python 버전 체크: Python 버전이 3.12.x인지 확인합니다","가상 환경 체크: 가상 환경의 존재와 Python 버전을 확인합니다","Slippi 네트워크 플레이 지원: Slippi 네트워크 플레이의 원활한 실행을 보장합니다"],"es":["Comprobación del sistema operativo y arquitectura","Verificación de la versión de Python (3.12.x)","Comprobación de la existencia de un entorno virtual (venv)","Verificación de la versión de Python en el entorno virtual","Diagnóstico y solución de problemas de configuración de No Johns","Compatibilidad con Slippi netplay para torneos de Melee AI"],"fr":["Vérification du système d''exploitation et de l''architecture","Vérification de la version de Python (3.12.x)","Vérification de l''existence d''un environnement virtuel (venv)","Vérification de la version de Python dans l''environnement virtuel","Diagnostic et résolution des problèmes de configuration de No Johns","Compatibilité avec Slippi netplay pour les tournois de Melee IA"],"de":["Überprüfung des Betriebssystems und der Architektur","Überprüfung der Python-Version (3.12.x)","Überprüfung der Existenz eines virtuellen Umfelds (venv)","Überprüfung der Python-Version im virtuellen Umfeld","Diagnose und Behebung von Konfigurationsproblemen von No Johns","Kompatibilität mit Slippi netplay für Melee-KI-Turniere"],"pt":["Verificação de sistema operacional e arquitetura","Verificação da versão do Python (3.12.x)","Verificação da existência do ambiente virtual (venv)","Verificação da versão do Python no ambiente virtual","Diagnóstico de problemas de configuração do Moltbots","Correção de problemas de configuração comuns"],"ru":["Проверка операционной системы и архитектуры","Проверка версии Python (3.12.x)","Проверка наличия виртуального окружения (venv)","Проверка версии Python в виртуальном окружении","Диагностика проблем настройки Moltbots","Исправление общих проблем настройки"],"ar":["فحص نظام التشغيل والهيكل","فحص إصدار بايثون (3.12.x)","فحص وجود بيئة افتراضية (venv)","فحص إصدار بايثون في البيئة الافتراضية","تشخيص مشاكل إعداد محاربي Moltbots","معالجة مشاكل الإعداد الشائعة"]},"keywords":{"en":["how to use troubleshoot","troubleshoot setup guide","troubleshoot alternative","troubleshoot vs debug","what is troubleshoot","troubleshoot install","Melee AI tournament setup","Slippi netplay troubleshooting","Moltbots setup issues"],"zh":["故障排除","Moltbots Melee AI","Slippi网游","Python版本检查","虚拟环境检查","系统检查","AIエージェント故障排除","AI工具故障排除"],"ja":["トラブルシューティング","Moltbots Melee AI","Slippiネットプレイ","Pythonバージョンチェック","仮想環境チェック","システムチェック","AIエージェントトラブルシューティング","AIツールトラブルシューティング"],"ko":["트러블슈팅","몰트봇 Melee AI","Slippi 네트워크 플레이","Python 버전 체크","가상 환경 체크","시스템 체크","AI 에이전트 트러블슈팅","AI 툴 트러블슈팅"],"es":["troubleshoot AI Agentes","configuración de No Johns","diagnóstico de problemas de configuración","Python 3.12.x","entorno virtual venv","Slippi netplay","torneos de Melee AI","herramientas de troubleshoot para AI Agentes"],"fr":["dépannage agents IA","configuration de No Johns","diagnostic des problèmes de configuration","Python 3.12.x","environnement virtuel venv","Slippi netplay","tournois de Melee IA","outils de dépannage pour les agents IA"],"de":["Troubleshoot KI-Agenten","Konfiguration von No Johns","Diagnose von Konfigurationsproblemen","Python 3.12.x","virtuelles Umfeld venv","Slippi netplay","Melee-KI-Turniere","Troubleshoot-Tools für KI-Agenten"],"pt":["troubleshoot moltbots","configuração moltbots","problemas de configuração","diagnóstico de problemas","correção de problemas","python 3.12.x","venv","ambiente virtual"],"ru":["troubleshoot moltbots","настройка moltbots","проблемы настройки","диагностика проблем","исправление проблем","python 3.12.x","venv","виртуальное окружение"],"ar":["troubleshoot moltbots","إعداد moltbots","مشاكل الإعداد","تشخيص مشاكل","معالجة مشاكل","python 3.12.x","venv","بيئة افتراضية"]}},"owner":"ScavieFae","repo":"nojohns","repoPath":"ScavieFae/nojohns","stars":8,"forks":0,"updatedAt":"2026-02-24T23:42:48Z","topics":[],"category":"community","skillMd":{"name":"troubleshoot","description":"Diagnose No Johns setup issues. Checks Python, Dolphin, ISO, arena connectivity, and common problems.","bodyPreview":"# Setup Troubleshooter\n\nDiagnose and fix common No Johns setup problems. Run each check in order\nand report findings at the end.\n\n## Steps\n\n### 1. System Check\n\n```bash\n# OS and architecture\nuname -a\n\n# Python version (must be 3.12.x, NOT 3.13)\npython3.12 --version 2>/dev/null || python3 --version\n\n# Check if venv exists\nls -la .venv/bin/python 2>/dev/null && echo \"Venv OK\" || echo \"PROBLEM: No .venv found\"\n\n# Check venv Python version\n.venv/bin/python --version 2>/dev/null\n```\n\n**Expected:** Py","body":"# Setup Troubleshooter\n\nDiagnose and fix common No Johns setup problems. Run each check in order\nand report findings at the end.\n\n## Steps\n\n### 1. System Check\n\n```bash\n# OS and architecture\nuname -a\n\n# Python version (must be 3.12.x, NOT 3.13)\npython3.12 --version 2>/dev/null || python3 --version\n\n# Check if venv exists\nls -la .venv/bin/python 2>/dev/null && echo \"Venv OK\" || echo \"PROBLEM: No .venv found\"\n\n# Check venv Python version\n.venv/bin/python --version 2>/dev/null\n```\n\n**Expected:** Python 3.12.x. If 3.13, pyenet won''t build. If no venv, user\nneeds `python3.12 -m venv .venv`.\n\n### 2. Package Check\n\n```bash\n# libmelee (critical — the Dolphin interface)\n.venv/bin/python -c \"import melee; print(''libmelee OK'')\" 2>&1\n\n# pyenet (libmelee dependency — C extension, common build failure)\n.venv/bin/python -c \"import enet; print(''pyenet OK'')\" 2>&1\n\n# nojohns CLI\n.venv/bin/python -m nojohns.cli list-fighters 2>&1\n\n# TensorFlow (only needed for Phillip)\n.venv/bin/python -c \"import tensorflow as tf; print(f''TF {tf.__version__} OK'')\" 2>&1\n\n# slippi-ai (Phillip runtime)\n.venv/bin/python -c \"import slippi_ai; print(''slippi-ai OK'')\" 2>&1\n```\n\n**Common failures:**\n- `import enet` fails → pyenet build issue. See `docs/TROUBLESHOOTING.md` \"pyenet Build Failure\"\n  - macOS fix: `LDFLAGS=\"-L/opt/homebrew/lib -lenet\" CFLAGS=\"-I/opt/homebrew/include\" .venv/bin/pip install --no-cache-dir --no-binary :all: pyenet`\n  - Linux fix: `sudo apt install -y libenet-dev && .venv/bin/pip install --force-reinstall pyenet`\n- `import melee` fails → libmelee not installed. Run `.venv/bin/pip install -e .`\n- `import tensorflow` fails with `mutex lock` → TF 2.20 on macOS ARM. Fix: `.venv/bin/pip install \"tensorflow==2.18.1\" \"tf-keras==2.18.0\"`\n\n### 3. Config Check\n\n```bash\n# Config file exists\ncat ~/.nojohns/config.toml 2>/dev/null || echo \"PROBLEM: No config.toml — run ''nojohns setup melee''\"\n```\n\nVerify these fields in `~/.nojohns/config.toml`:\n\n- **`dolphin_path`**: Must exist and contain \"netplay\" in the path string (libmelee validates this)\n  - macOS: `~/Library/Application Support/Slippi Launcher/netplay`\n  - Linux: `~/.config/Slippi Launcher/netplay`\n- **`iso_path`**: Must exist and be >500MB (a real Melee ISO is ~1.3GB)\n- **`connect_code`**: Format `XXXX#NNN` (4 letters, hash, 1-3 digits). Avoid codes with ''9'' on macOS Sequoia.\n\n```bash\n# Verify Dolphin path exists\nDOLPHIN_PATH=$(python3 -c \"\nimport tomllib\nwith open(''$HOME/.nojohns/config.toml'', ''rb'') as f:\n    c = tomllib.load(f)\nprint(c.get(''games'', {}).get(''melee'', {}).get(''dolphin_path'', ''NOT SET''))\n\" 2>/dev/null)\necho \"Dolphin path: $DOLPHIN_PATH\"\nls \"$DOLPHIN_PATH\" 2>/dev/null && echo \"Path OK\" || echo \"PROBLEM: Path does not exist\"\n\n# Verify ISO exists and check size\nISO_PATH=$(python3 -c \"\nimport tomllib\nwith open(''$HOME/.nojohns/config.toml'', ''rb'') as f:\n    c = tomllib.load(f)\nprint(c.get(''games'', {}).get(''melee'', {}).get(''iso_path'', ''NOT SET''))\n\" 2>/dev/null)\necho \"ISO path: $ISO_PATH\"\nls -la \"$ISO_PATH\" 2>/dev/null || echo \"PROBLEM: ISO file not found\"\n```\n\n### 4. Dolphin Check\n\n```bash\n# macOS: Check Gatekeeper isn''t blocking Dolphin\n# (only relevant on macOS)\nif [[ \"$(uname)\" == \"Darwin\" ]]; then\n    DOLPHIN_APP=\"$HOME/Library/Application Support/Slippi Launcher/netplay/Slippi Dolphin.app\"\n    if [ -d \"$DOLPHIN_APP\" ]; then\n        echo \"Dolphin app found\"\n        xattr -l \"$DOLPHIN_APP\" 2>/dev/null | grep -q quarantine && \\\n            echo \"PROBLEM: Gatekeeper quarantine active. Fix: xattr -cr \\\"$DOLPHIN_APP\\\"\" || \\\n            echo \"Gatekeeper OK\"\n    else\n        echo \"PROBLEM: Dolphin.app not found at expected location\"\n        echo \"Open Slippi Launcher and let it download Dolphin\"\n    fi\nfi\n\n# Linux: Check Dolphin binary exists\nif [[ \"$(uname)\" == \"Linux\" ]]; then\n    NETPLAY_DIR=\"$HOME/.config/Slippi Launcher/netplay\"\n    if [ -d \"$NETPLAY_DIR\" ]; then\n        echo \"Slippi netplay dir found\"\n        find \"$NETPLAY_DIR\" -name \"dolphin-emu\" -o -name \"*.AppImage\" 2>/dev/null\n    else\n        echo \"PROBLEM: Slippi netplay directory not found\"\n    fi\nfi\n```\n\n### 5. Phillip Check\n\n```bash\n# Model weights exist\nMODEL=\"fighters/phillip/models/all_d21_imitation_v3.pkl\"\nif [ -f \"$MODEL\" ]; then\n    SIZE=$(wc -c < \"$MODEL\")\n    echo \"Model weights: $SIZE bytes\"\n    if [ \"$SIZE\" -lt 1000000 ]; then\n        echo \"PROBLEM: Model file too small — may be corrupted\"\n    else\n        echo \"Model OK\"\n    fi\nelse\n    echo \"PROBLEM: Model weights not found. Run: nojohns setup melee phillip\"\nfi\n\n# slippi-ai installed\nif [ -d \"fighters/phillip/slippi-ai\" ]; then\n    echo \"slippi-ai repo OK\"\nelse\n    echo \"PROBLEM: slippi-ai not cloned. Run: nojohns setup melee phillip\"\nfi\n```\n\n### 6. Network Check\n\n```bash\n# Arena reachable\nARENA_URL=$(python3 -c \"\nimport tomllib\nwith open(''$HOME/.nojohns/config.toml'', ''rb'') as f:\n    c = tomllib.load(f)\nprint(c.get(''arena'', {}).get(''url'', ''https://nojohns-arena-production.up.railway.app''))\n\" 2>/dev/null || echo \"https://nojohns-arena-production.up.railway.app\")\n\necho \"Arena URL: $ARENA_URL\"\ncurl -s --max-time 5 \"$ARENA_URL/health\" 2>/dev/null || echo \"PROBLEM: Arena unreachable\"\n```\n\n### 7. Known Issues Reference\n\nIf the checks above pass but things still don''t work, check these known issues\nin `docs/TROUBLESHOOTING.md`:\n\n| Symptom | Issue | Fix |\n|---------|-------|-----|\n| Connect codes with ''9'' fail on Sequoia | Position 3 bug | Use a code without ''9'' |\n| Netplay freezes at stock loss | Rollback desync | Set `online_delay=6` |\n| Phillip doesn''t move in netplay | Missing `on_game_start` | Update to latest code |\n| `mutex lock failed` on TF import | TF 2.20 bug on ARM | Install TF 2.18.1 |\n| `Unknown path` from libmelee | Path missing \"netplay\" | Use Slippi Launcher''s netplay dir |\n| Menu stuck on 2nd+ match | libmelee state leak | Use subprocess per match |\n| CSS stuck at character select | Intermittent | Kill and restart matchmake |\n\n### 8. Report\n\nAfter running all checks, print a summary:\n\n```\n=== No Johns Setup Diagnostic ===\nSystem:     [OS, arch, Python version]\nPackages:   [OK / PROBLEMS: list]\nConfig:     [OK / PROBLEMS: list]\nDolphin:    [OK / PROBLEMS: list]\nPhillip:    [OK / PROBLEMS: list]\nNetwork:    [OK / PROBLEMS: list]\n\n[For each PROBLEM, include the specific fix command]\n```\n\nIf everything passes: \"Setup looks good. Try `nojohns fight random do-nothing` for a smoke test.\"\n"},"lastSynced":"2026-03-06T06:48:58.670Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents like Cursor and AutoGPT needing advanced troubleshooting capabilities for Melee AI tournaments","zh":"非常适合像 Cursor 和 AutoGPT 这样的 AI Agent，它们需要为 Melee AI 赛事提供高级故障排除功能","ja":"Cursor や AutoGPT のような AI エージェントに適しており、Melee AI トーナメントのための高度なトラブルシューティング機能が必要です","ko":"Cursor 및 AutoGPT와 같은 AI 에이전트에게 적합하며, Melee AI 토너먼트를 위한 고급 문제 해결 기능이 필요합니다","es":"Ideal para Agentes de IA como Cursor y AutoGPT que necesitan capacidades avanzadas de resolución de problemas para torneos de Melee AI","fr":"Parfait pour les Agents IA comme Cursor et AutoGPT ayant besoin de capacités de dépannage avancées pour les tournois Melee AI","de":"Perfekt für KI-Agenten wie Cursor und AutoGPT, die erweiterte Fehlerbehebungsfähigkeiten für Melee AI-Turniere benötigen","pt":"Perfeito para Agentes de IA como Cursor e AutoGPT que necessitam de capacidades avançadas de solução de problemas para torneios de Melee AI","ru":"Идеально подходит для агентов ИИ, таких как Cursor и AutoGPT, требующих расширенных возможностей поиска и устранения неисправностей для турниров Melee AI","ar":"مثالي لوكلاء الذكاء الاصطناعي مثل Cursor و AutoGPT الذين يحتاجون إلى إمكانيات متقدمة لاستكشاف الأخطاء وإصلاحها من أجل بطولات Melee AI"},"recommendation":{"en":"Empowers agents to diagnose and fix common setup problems using system checks, Python version validation, and venv existence verification, all through Unix-based commands like uname and python3","zh":"赋予代理诊断和修复常见设置问题的能力，使用系统检查、Python 版本验证和 venv 存在验证等，所有这些都通过 Unix-based 命令如 uname 和 python3 实现","ja":"システムチェック、Python バージョンの検証、venv の存在の検証などを使用して、エージェントが一般的な設定問題を診断および修復する機能を提供します。すべてこれらは、Unix ベースのコマンド seperti uname および python3 を介して実行されます","ko":"시스템检查, Python 버전확인 및 venv 존재 확인 등을 통해 에이전트가 일반적인 설정 문제를 진단 및 수정 할 수 있는 기능을 제공합니다. 모두 Unix 기반 명령어 như uname 및 python3를 통해 수행됩니다","es":"Permite a los agentes diagnosticar y solucionar problemas comunes de configuración mediante comprobaciones del sistema, validación de la versión de Python y verificación de la existencia de venv, todo a través de comandos basados en Unix como uname y python3","fr":"Permet aux agents de diagnostiquer et de résoudre les problèmes courants de configuration en utilisant des vérifications système, la validation de la version de Python et la vérification de l''existence de venv, le tout via des commandes de type Unix comme uname et python3","de":"Ermöglicht Agenten, häufige Einrichtungsprobleme durch Systemprüfungen, Python-Versionsvalidierung und Überprüfung der Venv-Existenz zu diagnostizieren und zu beheben, alles über Unix-basierte Befehle wie uname und python3","pt":"Habilita os agentes a diagnosticar e corrigir problemas de configuração comuns usando verificações de sistema, validação de versão do Python e verificação de existência de venv, tudo por meio de comandos baseados em Unix, como uname e python3","ru":"Предоставляет агентам возможность диагностировать и исправлять общие проблемы настройки с помощью системных проверок, проверки версии Python и верификации существования venv, все через команды на основе Unix, такие как uname и python3","ar":"تمكّن الوكلاء من تشخيص ومعالجة مشاكل الإعداد الشائعة باستخدام فحوصات النظام وتأكيد إصدار بايثون وتحقق من وجود venv، كل ذلك من خلال أوامر مبنية على يونكس مثل uname و python3"},"useCases":{"en":["Debugging Slippi netplay issues","Resolving Moltbots setup problems","Validating Python version for compatibility"],"zh":["调试 Slippi 网络游戏问题","解决 Moltbots 设置问题","验证 Python 版本的兼容性"],"ja":["Slippi ネットプレイの問題をデバッグする","Moltbots の設定問題を解決する","Python バージョンの互換性を検証する"],"ko":["Slippi 네트워크 플레이 문제 디버깅","Moltbots 설정 문제 해결","Python 버전 호환성 확인"],"es":["Depuración de problemas de netplay de Slippi","Resolución de problemas de configuración de Moltbots","Validación de la versión de Python para compatibilidad"],"fr":["Débogage des problèmes de netplay Slippi","Résolution des problèmes de configuration Moltbots","Validation de la version de Python pour la compatibilité"],"de":["Debuggen von Slippi Netplay-Problemen","Beheben von Moltbots-Einrichtungsproblemen","Validieren der Python-Version für Kompatibilität"],"pt":["Depuração de problemas de netplay do Slippi","Resolução de problemas de configuração do Moltbots","Validação da versão do Python para compatibilidade"],"ru":["Отладка проблем сетевой игры Slippi","Решение проблем настройки Moltbots","Проверка версии Python на совместимость"],"ar":["تصحيح أخطاء مشاكل اللعب الشبكي في Slippi","حل مشاكل إعداد Moltbots","التحقق من إصدار بايثون لضمان التوافق"]},"limitations":{"en":["Requires Unix-based system for command execution","Python 3.12.x required, not compatible with Python 3.13","Venv setup necessary for proper functionality"],"zh":["需要 Unix-based 系统来执行命令","需要 Python 3.12.x，不兼容 Python 3.13","需要 venv 设置以实现正确的功能"],"ja":["コマンドの実行には Unix ベースのシステムが必要","Python 3.12.x が必要で、Python 3.13 と互換性がない","正しい機能を実現するには venv の設定が必要"],"ko":["명령어 실행을 위해 Unix 기반 시스템이 필요합니다","Python 3.12.x가 필요하며 Python 3.13과 호환되지 않습니다","정확한 기능을 구현하기 위해 venv 설정이 필요합니다"],"es":["Requiere un sistema basado en Unix para la ejecución de comandos","Python 3.12.x requerido, no compatible con Python 3.13","Configuración de Venv necesaria para un funcionamiento adecuado"],"fr":["Nécessite un système de type Unix pour l''exécution des commandes","Python 3.12.x requis, non compatible avec Python 3.13","Configuration Venv nécessaire pour un fonctionnement correct"],"de":["Erfordert ein Unix-basiertes System für die Befehlsausführung","Python 3.12.x erforderlich, nicht kompatibel mit Python 3.13","Venv-Einrichtung für eine ordnungsgemäße Funktionalität notwendig"],"pt":["Requer um sistema baseado em Unix para execução de comandos","Python 3.12.x necessário, não compatível com Python 3.13","Configuração de venv necessária para funcionalidade adequada"],"ru":["Требуется система на основе Unix для выполнения команд","Python 3.12.x необходим, не совместим с Python 3.13","Настройка venv необходима для правильной функциональности"],"ar":["يتطلب نظامًا مبنيًا على يونكس لتنفيذ الأوامر","يُحتاج إلى بايثون 3.12.x، غير متوافق مع بايثون 3.13","يُحتاج إلى إعداد venv لضمان الوظائف المناسبة"]},"version":4},"contentHash":"92eec89571bf7a53ca1fe8a2a19214309cf79f125dff1001f650eb341e7a2412","qualityScore":33}');
