INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ScavieFae/nojohns/troubleshoot', 'troubleshoot', 'ScavieFae', 'nojohns', 'community', 'troubleshoot ScavieFae nojohns community The troubleshoot skill helps developers diagnose and fix common setup problems for Melee AI tournaments. It provides a step-by-step guide to resolve issues with Slippi netplay and Moltbots. 故障排除技能用于诊断和修复Moltbots Melee AI锦标赛的常见问题，确保Slippi网游的顺畅运行。它包括系统检查、Python版本检查和虚拟环境检查等步骤 トラブルシューティングスキルは、Moltbots Melee AIトーナメントの一般的な問題を診断および修復し、Slippiネットプレイのスムーズな実行を確保します。システムチェック、Pythonバージョンチェック、仮想環境チェックなどのステップを含みます 트러블슈팅 스킬은 몰트봇 Melee AI 토너먼트의 일반적인 문제를 진단 및 수정하여 Slippi 네트워크 플레이의 원활한 실행을 보장합니다. 시스템 체크, Python 버전 체크, 가상 환경 체크 등의 단계를 포함합니다 El troubleshoot ayuda a diagnosticar y solucionar problemas de configuración de No Johns para desarrolladores de AI Agentes. Incluye comprobaciones de sistema y versión de Python. Le dépannage aide à diagnostiquer et à résoudre les problèmes de configuration de No Johns pour les développeurs d''agents IA. Il comprend des vérifications de système et de version de Python. Das Troubleshoot hilft bei der Diagnose und Behebung von Konfigurationsproblemen von No Johns für KI-Agenten-Entwickler. Es umfasst System- und Python-Version-Checks. O troubleshoot é uma ferramenta para diagnosticar e corrigir problemas de configuração do Moltbots, incluindo verificações de sistema e versão do Python. Troubleshoot - это инструмент для диагностики и исправления проблем настройки Moltbots, включая проверки системы и версии Python. Troubleshoot هو أداة لتشخيص ومعالجة مشاكل إعداد محاربي Moltbots، بما في ذلك فحوصات النظام وإصدار بايثون. how to use troubleshoot troubleshoot setup guide troubleshoot alternative troubleshoot vs debug what is troubleshoot troubleshoot install Melee AI tournament setup Slippi netplay troubleshooting Moltbots setup issues 故障排除 Moltbots Melee AI Slippi网游 Python版本检查 虚拟环境检查 系统检查 AIエージェント故障排除 AI工具故障排除 Runs system checks using uname and python3.12 commands Verifies Python version and virtual environment (venv) existence Checks venv Python version using .venv/bin/python command Provides step-by-step guide for diagnosing and fixing setup problems Supports Slippi netplay and Moltbots pluggable fighters troubleshoot is a diagnostic tool for identifying and resolving common setup issues in Melee AI tournaments, ensuring seamless gameplay and competition.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('indiesoftby/defold-poki-auds/defold-build', 'community', 'indiesoftby', 'defold-poki-auds', 'indiesoftby/defold-poki-auds', 'defold-build', 4, 0, 33, '2026-02-03T20:16:07Z', '2026-03-06T06:59:22.974Z', '44ba7253222dd88b05284f9001883ddc93463980a7dd1e4b43fb0cfc6c87dd5b', '{"id":"indiesoftby/defold-poki-auds/defold-build","name":"defold-build","description":{"en":"The defold-build skill is a Lua module for automating Defold builds and smoke tests using Poki AUDS. It benefits Defold developers by simplifying the build process.","zh":"Defold Build Skill 是一个 Lua 模块，使用 Defold 的 http.request 实现 Poki AUDS。它提供了下载最新的 Defold bob.jar 和运行烟雾测试构建的功能","ja":"Defold Build Skill は、Defold の http.request を使用して Poki AUDS を実現する Lua モジュールです。最新の Defold bob.jar をダウンロードし、煙霧テストビルドを実行する機能を提供します","ko":"Defold Build Skill은 Defold의 http.request를 사용하여 Poki AUDS를 구현하는 Lua 모듈입니다. 최신의 Defold bob.jar를 다운로드하고 스모크 테스트 빌드를 실행하는 기능을 제공합니다","es":"Defold-build es un módulo Lua que utiliza Defold''s http.request para Poki AUDS, compatible con Java 25+.","fr":"Defold-build est un module Lua qui utilise Defold''s http.request pour Poki AUDS, compatible avec Java 25+.","de":"Defold-build ist ein Lua-Modul, das Defold''s http.request für Poki AUDS verwendet, kompatibel mit Java 25+.","pt":"O Defold Build é um módulo Lua para o Poki AUDS, que utiliza o http.request do Defold. Ele baixa a versão estável mais recente do Defold bob.jar e executa testes de fumça","ru":"Defold Build - это модуль Lua для Poki AUDS, использующий http.request Defold. Он загружает последнюю стабильную версию Defold bob.jar и запускает тесты","ar":"أداة Defold Build هي وحدة لوح لغة Lua لخزن البيانات المستخدمة من Poki، وتستخدم طلب HTTP من Defold. وهي تتنزيل أحدث إصدار مستقر من Defold bob.jar وتنفذ اختبارات الدخان"},"seo":{"title":{"en":"defold-build: Automated Build Setup Guide | AI Agent Skill","zh":"Defold Build Setup Guide - Lua 模块和 Poki AUDS","ja":"Defold Build セットアップガイド - Lua モジュールと AIエージェント Poki AUDS","ko":"Defold Build 설정 가이드 - Lua 모듈과 AI 도구 Poki AUDS","es":"Guía de configuración de defold-build para desarrolladores","fr":"Guide de configuration de defold-build pour les développeurs","de":"Einrichtungsleitfaden für defold-build-Entwickler","pt":"Guia de Configuração do Defold Build","ru":"Настройка Defold Build: Руководство","ar":"إعداد أداة Defold Build: دليل المستخدم"},"description":{"en":"Discover how to streamline your Defold development with defold-build. Learn to automate builds and smoke tests with this Lua module for Poki AUDS.","zh":"使用 Defold 的 http.request 实现 Lua 模块和 Poki AUDS，了解 Defold Build Skill 的技术细节","ja":"Defold の http.request を使用して Lua モジュールと AIエージェント Poki AUDS を実現する - Defold Build Skill の技術的な詳細","ko":"Defold의 http.request를 사용하여 Lua 모듈과 AI 도구 Poki AUDS를 구현하는 방법 - Defold Build Skill의 기술적 세부 사항","es":"Aprende a configurar defold-build con Java 25+ y ejecutar pruebas de humo con bob.jar","fr":"Découvrez comment configurer defold-build avec Java 25+ et exécuter des tests de fumée avec bob.jar","de":"Erfahren Sie, wie Sie defold-build mit Java 25+ konfigurieren und Rauchtests mit bob.jar ausführen","pt":"Aprenda a configurar o Defold Build com o nosso guia passo a passo, incluindo a verificação da versão do Java e a execução de testes de fumça","ru":"Узнайте, как настроить Defold Build с помощью нашего пошагового руководства, включая проверку версии Java и запуск тестов","ar":"تعلم كيفية إعداد أداة Defold Build باستخدام دليلنا الخطوة بخطوة، بما في ذلك التحقق من إصدار Java وتنفيذ اختبارات الدخان"},"definition":{"en":"defold-build is a Lua module that automates Defold builds and smoke tests using Poki AUDS and Defold''s http.request.","zh":"Defold Build Skill 是一个使用 Defold 的 http.request 实现 Poki AUDS 的 Lua 模块","ja":"Defold Build Skill は、Defold の http.request を使用して Poki AUDS を実現する Lua モジュールです","ko":"Defold Build Skill은 Defold의 http.request를 사용하여 Poki AUDS를 구현하는 Lua 모듈입니다","es":"Defold-build es un módulo Lua que facilita la configuración y pruebas de Defold con Java","fr":"Defold-build est un module Lua qui facilite la configuration et les tests de Defold avec Java","de":"Defold-build ist ein Lua-Modul, das die Konfiguration und Tests von Defold mit Java erleichtert","pt":"O que é Defold Build? É um módulo Lua que utiliza o http.request do Defold para baixar e testar o Defold bob.jar","ru":"Что такое Defold Build? Это модуль Lua, использующий http.request Defold для загрузки и тестирования Defold bob.jar","ar":"ما هي أداة Defold Build؟ وهي وحدة لوح لغة Lua تستخدم طلب HTTP من Defold لتنزيل واختبار Defold bob.jar"},"features":{"en":["Downloads the latest stable Defold bob.jar","Runs smoke test builds using Java 25+","Supports platform-specific scripts for Windows and Linux/macOS","Verifies Java version using `java -version` command","Executes scripts using PowerShell or Bash"],"zh":["使用 Defold 的 http.request 实现 Poki AUDS","下载最新的 Defold bob.jar","运行烟雾测试构建","支持 Java 25+","提供 Windows 和 Linux/macOS 脚本","支持 Lua 模块"],"ja":["Defold の http.request を使用して Poki AUDS を実現","最新の Defold bob.jar をダウンロード","煙霧テストビルドを実行","Java 25+ をサポート","Windows と Linux/macOS 用のスクリプトを提供","Lua モジュールをサポート"],"ko":["Defold의 http.request를 사용하여 Poki AUDS를 구현","최신의 Defold bob.jar를 다운로드","스모크 테스트 빌드를 실행","Java 25+를 지원","Windows와 Linux/macOS용 스크립트를 제공","Lua 모듈을 지원"],"es":["Compatibilidad con Java 25+","Descarga de bob.jar para pruebas de humo","Ejecución de pruebas de humo con bob.jar","Uso de Defold''s http.request para Poki AUDS","Soporte para plataformas Windows, Linux y macOS"],"fr":["Compatibilité avec Java 25+","Téléchargement de bob.jar pour les tests de fumée","Exécution des tests de fumée avec bob.jar","Utilisation de Defold''s http.request pour Poki AUDS","Prise en charge des plates-formes Windows, Linux et macOS"],"de":["Kompatibilität mit Java 25+","Download von bob.jar für Rauchtests","Ausführung von Rauchtests mit bob.ja