INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('spideystreet/nephila/new-dagster-asset', 'new-dagster-asset', 'spideystreet', 'nephila', 'community', 'new-dagster-asset spideystreet nephila community The new-dagster-asset skill helps pharmacists navigate drug shortages by adding a new Dagster asset, utilizing Python and PipelineSettings. This skill benefits pharmacists and developers working with Dagster. 新Dagster资产设置指南，使用Python创建新资产，包括选择层文件、声明资产和文件命名 新しいDagsterアセットのセットアップガイド。Pythonを使用して新しいアセットを作成します 새 Dagster 자산 설정 가이드. Python을 사용하여 새로운 자산을 생성합니다 new-dagster-asset es una habilidad que permite a los desarrolladores agregar nuevos activos Dagster de manera eficiente new-dagster-asset est une compétence qui permet aux développeurs d''ajouter de nouveaux actifs Dagster de manière efficace new-dagster-asset ist eine Fähigkeit, die es Entwicklern ermöglicht, neue Dagster-Assets effizient hinzuzufügen O novo ativo Dagster é uma ferramenta para ajudar a gerenciar ativos com Python, permitindo uma navegação fácil pelas camadas de ativos Новый актив Dagster - это инструмент для управления активами с помощью Python, позволяющий легко ориентироваться в слоях активов المورد الجديد في Dagster هو أداة لمساعدة إدارة الموارد باستخدام Python، مما يسمح بالتنقل بسهولة عبر طبقات الموارد how to use new-dagster-asset new-dagster-asset setup guide what is new-dagster-asset new-dagster-asset alternative new-dagster-asset vs dagster new-dagster-asset install dagster asset management python dagster integration nephila ai agent Dagster Python 新Dagster资产 资产设置 数据管理 PipelineSettings AI工具 资产管理 Declares assets using Python decorators with @asset Utilizes PipelineSettings for customized workflow management Follows a specific file naming convention, <type>_<function>.py Supports dependency declaration with deps=["<upstream_asset>"] Adds output metadata with context.add_output_metadata Chooses layer files from asset_bronze.py, asset_silver.py, or asset_gold.py new-dagster-asset is a skill that enables the addition of new Dagster assets, leveraging Python decorators and PipelineSettings for efficient workflow management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ryanmat/mcp-server-logicmonitor/lm-portal', 'community', 'ryanmat', 'mcp-server-logicmonitor', 'ryanmat/mcp-server-logicmonitor', 'lm-portal', 3, 0, 33, '2026-02-27T15:08:24Z', '2026-03-06T07:02:16.743Z', '35c784679387c24d846e4087a55d0134a63a883ed13ccab05c7cbbcd24949ab4', '{"id":"ryanmat/mcp-server-logicmonitor/lm-portal","name":"lm-portal","description":{"en":"lm-portal enables AI assistants to interact with LogicMonitor monitoring data through structured tools, ideal for portal health analysts. It integrates with LogicMonitor REST API v3 for comprehensive health snapshots","zh":"lm-portal是LogicMonitor REST API v3的MCP服务器，实现AI助手与监控数据的交互","ja":"lm-portalはLogicMonitor REST API v3のMCPサーバーで、AIエージェントが監視データとやり取りすることを可能にします","ko":"lm-portal은 LogicMonitor REST API v3의 MCP 서버로 AI 도구가 모니터링 데이터와 상호작용할 수 있습니다","es":"lm-portal es un servidor MCP para la integración de la API de LogicMonitor v3, que permite a los asistentes de IA interactuar con datos de monitoreo estructurados","fr":"lm-portal est un serveur MCP pour l''intégration de l''API LogicMonitor v3, qui permet aux assistants de l''IA d''interagir avec des données de surveillance structurées","de":"lm-portal ist ein MCP-Server für die Integration der LogicMonitor-API v3, der es AI-Assistenten ermöglicht, mit strukturierten Überwachungsdaten zu interagieren","pt":"O lm-portal é um servidor MCP para integração com a API do LogicMonitor v3, permitindo que assistentes de IA interajam com dados de monitoramento","ru":"lm-portal — это сервер MCP для интеграции с API LogicMonitor v3, позволяющий ИИ-ассистентам взаимодействовать с данными мониторинга","ar":"lm-portal هو خادم MCP لإدماج LogicMonitor API v3، مما يسمح للأدوات الذكاء الاصطناعي بالتفاعل مع بيانات المراقبة"},"seo":{"title":{"en":"lm-portal: LogicMonitor REST API v3 Integration Setup Gui...","zh":"lm-portal集成指南：LogicMonitor REST API v3 Setup Guide","ja":"lm-portalの設定方法：LogicMonitor REST API v3ベストプラクティス","ko":"lm-portal 설정 가이드: LogicMonitor REST API v3 통합 방법","es":"Guía de configuración de lm-portal para API de LogicMonitor","fr":"Guide d''intégration de lm-portal pour l''API LogicMonitor","de":"Einrichtungsleitfaden für lm-portal mit LogicMonitor-API","pt":"lm-portal: Guia de Configuração para Integração com Logic...","ru":"lm-portal: Руководство по настройке для интеграции с Logi...","ar":"lm-portal: دليل الإعداد لإدماج LogicMonitor مع أدوات الذك..."},"description":{"en":"Discover how to leverage lm-portal for seamless LogicMonitor monitoring data interaction. Get started with our expert guide and unlock efficient shift handof...","zh":"了解lm-portal的功能和特点，实现LogicMonitor监控数据的AI分析","ja":"lm-portalを使用してLogicMonitorの監視データをAIエージェントで分析する方法","ko":"lm-portal을 사용하여 LogicMonitor 모니터링 데이터를 AI 도구로 분석하는 방법","es":"Descubre cómo integrar lm-portal con la API de LogicMonitor v3 para análisis de datos de monitoreo","fr":"Découvrez comment intégrer lm-portal avec l''API LogicMonitor v3 pour l''analyse des données de surveillance","de":"Erfahren Sie, wie Sie lm-portal mit der LogicMonitor-API v3 für die Analyse von Überwachungsdaten integrieren","pt":"Aprenda a configurar o lm-portal para integrar com a API do LogicMonitor e melhorar a análise de dados de monitoramento","ru":"Узнайте, как настроить lm-portal для интеграции с API LogicMonitor и улучшить анализ данных мониторинга с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد lm-portal لإدماج LogicMonitor وتحسين تحليل بيانات المراقبة مع أدوات الذكاء الاصطناعي"},"definition":{"en":"lm-portal is a MCP server for LogicMonitor REST API v3 integration, designed to facilitate AI assistant interaction with monitoring data","zh":"lm-portal是一种实现LogicMonitor监控数据AI分析的MCP服务器","ja":"lm-portalはLogicMonitorの監視データをAIエージェントで分析するためのMCPサーバーです","ko":"lm-portal은 LogicMonitor 모니터링 데이터를 AI 도구로 분석하는 MCP 서버입니다","es":"lm-portal es un servidor de integración para la API de LogicMonitor que permite el análisis de datos de monitoreo","fr":"lm-portal est un serveur d''intégration pour l''API LogicMonitor qui permet l''analyse des données de surveillance","de":"lm-portal ist ein Integrations-Server für die LogicMonitor-API, der die Analyse von Überwachungsdaten ermöglicht","pt":"O lm-portal é um servidor que permite a integração com a API do LogicMonitor para análise de dados de monitoramento","ru":"lm-portal — это сервер, позволяющий интегрироваться с API LogicMonitor для анализа данных мониторинга","ar":"lm-portal هو خادم يسمح بإدماج LogicMonitor API للتحليل البيانات المراقبة"},"features":{"en":["Executes argument parsing for lookback windows via hours_back parameter","Provides alert landscape overview through get_a command","Supports incremental findings presentation for shift handoffs and morning standups","Enables on-call situation reports with structured tools","Integrates with LogicMonitor REST API v3 for comprehensive monitoring data access"],"zh":["支持LogicMonitor REST API v3","实现AI助手与监控数据的交互","提供结构化的监控数据分析工具","支持自定义的lookback窗口","集成了 Argument Parsing 功能"],"ja":["LogicMonitor REST API v3をサポート","AIエージェントが監視データとやり取りすることを可能に","構造化された監視データ分析ツールを提供","カスタマイズ可能なlookbackウィンドウをサポート","Argument Parsing機能を統合"],"ko":["LogicMonitor REST API v3 지원","AI 도구가 모니터링 데이터와 상호작용할 수 있도록 함","구조화된 모니터링 데이터 분석 도구 제공","사용자 정의 lookback 창 지원","Argument Parsing 기능 통합"],"es":["Integración con la API de LogicMonitor v3","Análisis de datos de monitoreo estructurados","Compatibilidad con herramientas de análisis de datos","Soporte para la generación de informes de salud del portal","Argumentos de análisis personalizables (hours_back)","Ejecución de flujos de trabajo para la generación de informes"],"fr":["Intégration avec l''API LogicMonitor v3","Analyse de données de surveillance structurées","Compatibilité avec les outils d''analyse de données","Prise en charge de la génération de rapports de santé du portail","Arguments d''analyse personnalisables (hours_back)","Exécution de flux de travail pour la génération de rapports"],"de":["Integration mit der LogicMonitor-API v3","Analyse von strukturierten Überwachungsdaten","Kompatibilität mit Datenanalyse-Tools","Unterstützung für die Generierung von Portal-Gesundheitsberichten","Anpassbare Analyseargumente (hours_back)","Ausführung von Workflows für die Berichtsgenerierung"],"pt":["Integração com API do LogicMonitor v3","Análise de dados de monitoramento em tempo real","Suporte a argumentos de linha de comando, como hours_back","Execução de fluxos de trabalho personalizados","Suporte a relatórios de saúde do portal"],"ru":["Интеграция с API LogicMonitor v3","Анализ данных мониторинга в режиме реального времени","Поддержка командной строки, таких как hours_back","Выполнение пользовательских рабочих процессов","Поддержка отчетов о здоровье портала"],"ar":["إدماج LogicMonitor API v3","تحليل البيانات المراقبة في الوقت الفعلي","دعم سطر الأوامر، مثل hours_back","تنفيذ تدفقات العمل المخصصة","دعم تقارير صحة البوابة"]},"keywords":{"en":["how to use lm-portal","lm-portal alternative","lm-portal setup guide","what is lm-portal","lm-portal vs logicmonitor","lm-portal install","logicmonitor rest api v3 integration","lm-portal for ai agents","lm-portal for portal health analysis"],"zh":["lm-portal","LogicMonitor REST API v3","AI分析","MCP服务器","监控数据","结构化分析","lookback窗口","Argument Parsing"],"ja":["lm-portal","LogicMonitor REST API v3","AIエージェント","MCPサーバー","監視データ","構造化分析","lookbackウィンドウ","Argument Parsing"],"ko":["lm-portal","LogicMonitor REST API v3","AI 도구","MCP 서버","모니터링 데이터","구조화된 분석","lookback 창","Argument Parsing"],"es":["lm-portal","API de LogicMonitor","análisis de datos de monitoreo","integración de datos","herramientas de análisis de datos","informes de salud del portal","argumentos de análisis personalizables","Herramientas de IA para monitoreo"],"fr":["lm-portal","API LogicMonitor","analyse de données de surveillance","intégration de données","outils d''analyse de données","rapports de santé du portail","arguments d''analyse personnalisables","Outils d''IA pour la surveillance"],"de":["lm-portal","LogicMonitor-API","Analyse von Überwachungsdaten","Datenintegration","Datenanalyse-Tools","Portal-Gesundheitsberichte","anpassbare Analyseargumente","AI-Tools für Überwachung"],"pt":["lm-portal","integração LogicMonitor","API v3","análise de dados de monitoramento","assistente de IA","servidor MCP","configuração lm-portal","guia de instalação lm-portal"],"ru":["lm-portal","ИИ Агенты","интеграция LogicMonitor","API v3","анализ данных мониторинга","настройка lm-portal","руководство по установке lm-portal","ИИ инструменты"],"ar":["lm-portal","أدوات الذكاء الاصطناعي","إدماج LogicMonitor","API v3","تحليل البيانات المراقبة","إعداد lm-portal","دليل التثبيت lm-portal","أدوات الذكاء الاصطناعي للتحليل"]}},"owner":"ryanmat","repo":"mcp-server-logicmonitor","repoPath":"ryanmat/mcp-server-logicmonitor","stars":3,"forks":0,"updatedAt":"2026-02-27T15:08:24Z","topics":[],"category":"community","skillMd":{"name":"lm-portal","description":"Portal-wide health overview -- alert breakdown, collector status, active SDTs, alert clusters, noise scoring, and down devices.","bodyPreview":"# LogicMonitor Portal Health Overview\n\nYou are a portal health analyst for LogicMonitor. Your job is to produce a\nportal-wide health snapshot suitable for shift handoffs, morning standups, or\non-call situation reports.\n\n## Argument Parsing\n\n- **hours_back** — Lookback window in hours (default: 4)\n\nIf no argument is provided, use a 4-hour window.\n\n## Workflow\n\nExecute these steps in order. Present findings incrementally.\n\n### Step 1: Alert Landscape\n\nGet the overall alert picture.\n\n1. Call `get_a","body":"# LogicMonitor Portal Health Overview\n\nYou are a portal health analyst for LogicMonitor. Your job is to produce a\nportal-wide health snapshot suitable for shift handoffs, morning standups, or\non-call situation reports.\n\n## Argument Parsing\n\n- **hours_back** — Lookback window in hours (default: 4)\n\nIf no argument is provided, use a 4-hour window.\n\n## Workflow\n\nExecute these steps in order. Present findings incrementally.\n\n### Step 1: Alert Landscape\n\nGet the overall alert picture.\n\n1. Call `get_alert_statistics` for the lookback window to get time-bucketed trends.\n2. Call `get_alerts` with `cleared=false` and `severity>=3` (critical) to get the\n   critical alert list.\n\nPresent a severity breakdown:\n\n```\n| Severity | Active | Trend ({hours_back}h) |\n|----------|--------|-----------------------|\n| Critical |   N    | rising/stable/falling |\n| Error    |   N    | rising/stable/falling |\n| Warning  |   N    | rising/stable/falling |\n| Total    |   N    |                       |\n```\n\nFlag if critical count is rising or above a notable threshold.\n\n### Step 2: Collector Status\n\nCall `get_collectors` to get all collector statuses.\n\nCategorize collectors:\n\n```\n| Status   | Count | Collectors          |\n|----------|-------|---------------------|\n| Up       |   N   |                     |\n| Down     |   N   | [list if any]       |\n| Degraded |   N   | [list if any]       |\n```\n\nIf any collectors are down, this is a high-priority finding. Down collectors\nmean monitored devices behind them are blind.\n\n### Step 3: Maintenance Windows\n\nCall `get_active_sdts` to get currently active scheduled downtime windows.\n\nPresent active SDTs:\n\n```\n| Type    | Target          | Started    | Ends       | Comment    |\n|---------|-----------------|------------|------------|------------|\n| Device  | [name]          | [time]     | [time]     | [comment]  |\n| Group   | [name]          | [time]     | [time]     | [comment]  |\n```\n\nNote: Alerts from SDT-covered resources are suppressed. If many critical alerts\ncoincide with SDT expirations, flag potential alert storms on SDT end.\n\n### Step 4: Alert Clustering\n\nCall `correlate_alerts` scoped to critical alerts from the lookback window.\n\nPresent the top 5 clusters:\n\n```\n## Top Alert Clusters\n\n1. **[common factor]** — N alerts\n   - [resource]: [alert summary]\n   - [resource]: [alert summary]\n   - Hypothesis: [likely root cause]\n\n2. ...\n```\n\nIdentify common factors: shared device group, shared datasource, shared collector,\ntemporal burst.\n\nIf no clusters are found, note that critical alerts appear independent.\n\n### Step 5: Noise Assessment\n\nCall `score_alert_noise` for the portal-wide alert set.\n\nReport:\n- Overall noise score (0-100)\n- Noise level: High (>70) / Moderate (40-70) / Low (<40)\n- Top noise offenders (alert rules, datasources, or device groups generating\n  the most noise)\n\nIf noise is high, recommend specific tuning actions.\n\n### Step 6: Down Devices\n\nCall `get_devices` filtered to `status=dead` (down/dead devices).\n\nPresent down devices:\n\n```\n| Device          | Groups            | Collector | Down Since |\n|-----------------|-------------------|-----------|------------|\n| [name]          | [group path]      | [id]      | [time]     |\n```\n\nApply heuristic: if >20 devices are down AND they share a collector, flag this\nas a likely collector issue rather than individual device failures.\n\nIf no devices are down, report that.\n\n### Step 7: Portal Summary\n\nCompile a shift-handoff-ready summary:\n\n```\n## Portal Health Snapshot — [timestamp]\n\n### Status: [GREEN / YELLOW / RED]\n\nCriteria:\n- GREEN: No critical alerts rising, all collectors up, noise < 40\n- YELLOW: Some critical alerts, or moderate noise, or degraded collectors\n- RED: Critical alerts rising, or collectors down, or noise > 70\n\n### Key Numbers\n- Active alerts: N (C critical, E error, W warning)\n- Collectors: N up, N down, N degraded\n- Active SDTs: N\n- Down devices: N\n- Noise score: NN/100\n\n### Key Concerns\n1. [Most important finding requiring action]\n2. [Second most important finding]\n3. [Third most important finding]\n\n### Recommended Actions\n1. [Highest priority action]\n2. [Second priority action]\n3. [Third priority action]\n```\n"},"lastSynced":"2026-03-06T07:02:16.743Z","agentAnalysis":{"suitability":{"en":"Perfect for Monitoring Agents needing advanced LogicMonitor data analysis and visualization capabilities.","zh":"非常适合需要高级 LogicMonitor 数据分析和可视化功能的监控 Agent。","ja":"高度な LogicMonitor データ分析および可視化機能を必要とする監視 Agent に最適です。","ko":"고급 LogicMonitor 데이터 분석 및 시각화 기능이 필요한 모니터링 Agent에 완벽합니다.","es":"Perfecto para agentes de monitoreo que necesitan capacidades avanzadas de análisis y visualización de datos de LogicMonitor.","fr":"Parfait pour les agents de surveillance nécessitant des capacités avancées d''analyse et de visualisation de données LogicMonitor.","de":"Perfekt für Überwachungsagenten, die erweiterte LogicMonitor-Datenanalyse- und Visualisierungsfunktionen benötigen.","pt":"Perfeito para Agentes de Monitoramento que necessitam de capacidades avançadas de análise e visualização de dados do LogicMonitor.","ru":"Идеально подходит для агентов мониторинга, которым требуются расширенные возможности анализа и визуализации данных LogicMonitor.","ar":"مثالي لعمليات وكيل المراقبة التي تحتاج إلى قدرات متقدمة لتحليل وتصور بيانات LogicMonitor."},"recommendation":{"en":"Empowers agents to interact with LogicMonitor monitoring data through structured tools, utilizing the LogicMonitor REST API v3 for comprehensive health snapshots, and providing capabilities like argument parsing for customizable lookback windows.","zh":"使 Agent 能够通过结构化工具与 LogicMonitor 监控数据进行交互，利用 LogicMonitor REST API v3 获取全面的运行状况快照，并提供参数解析等功能以实现可自定义的回看窗口。","ja":"構造化されたツールを通じて LogicMonitor 監視データと対話することを Agent に可能にし、LogicMonitor REST API v3 を利用して包括的なヘルススナップショットを取得し、カスタマイズ可能なルックバックウィンドウのための引数解析などの機能を提供します。","ko":"Agent가 구조화된 도구를 통해 LogicMonitor 모니터링 데이터와 상호 작용할 수 있도록 하여, LogicMonitor REST API v3를 활용하여 포괄적인 상태 스냅샷을 얻고, 사용자 정의 가능한 lookback window를 위한 인수 구문 분석과 같은 기능을 제공합니다.","es":"Habilita a los agentes a interactuar con los datos de monitoreo de LogicMonitor a través de herramientas estructuradas, utilizando la API REST de LogicMonitor v3 para obtener instantáneas de estado integral y proporcionando capacidades como el análisis de argumentos para ventanas de retroceso personalizables.","fr":"Permet aux agents d''interagir avec les données de surveillance LogicMonitor via des outils structurés, en utilisant l''API REST LogicMonitor v3 pour des instantanés d''état complet et en fournissant des capacités telles que l''analyse d''arguments pour des fenêtres de retour arrière personnalisables.","de":"Ermächtigt Agenten, mit LogicMonitor-Überwachungsdaten über strukturierte Tools zu interagieren, wobei die LogicMonitor-REST-API v3 für umfassende Gesundheitsschnappschüsse verwendet wird und Funktionen wie Argumentparsing für anpassbare Rückblickfenster bereitstellt.","pt":"Habilita os agentes a interagir com os dados de monitoramento do LogicMonitor por meio de ferramentas estruturadas, utilizando a API REST do LogicMonitor v3 para instantâneos de saúde abrangentes e fornecendo capacidades como análise de argumentos para janelas de lookback personalizáveis.","ru":"Наделяет агентов возможностью взаимодействовать с данными мониторинга LogicMonitor с помощью структурированных инструментов, используя API REST LogicMonitor v3 для комплексных снимков здоровья и предоставляя возможности, такие как парсинг аргументов для настраиваемых окон просмотра.","ar":"تمكّن الوكيل من التفاعل مع بيانات مراقبة LogicMonitor من خلال أدوات منظمة، باستخدام واجهة برمجة تطبيقات LogicMonitor REST v3 للحصول على لقطات شاملة لصحة النظام، وتوفير قدرات مثل تحليل الحجج للنوافذ الخلفية القابلة للتعديل."},"useCases":{"en":["Automating portal-wide health snapshots for shift handoffs and morning standups","Generating on-call situation reports with detailed alert landscapes","Debugging portal health issues using customizable lookback windows"],"zh":["为轮班交接和晨会自动化生成整个门户的运行状况快照","生成包含详细警报态势的 on-call 事件报告","使用可自定义的回看窗口调试门户运行状况问题"],"ja":["シフト引継ぎと朝のスタンドアップミーティングのためのポータル全体のヘルススナップショットの自動化","詳細なアラート状況を記載したオンコール状況報告書の生成","カスタマイズ可能なルックバックウィンドウを使用したポータルヘルス問題のデバッグ"],"ko":["교대 근무 인수인과 모닝 스탠드업을 위한 포털 전체 상태 스냅샷 자동화","세부적인 알람 현황을 포함한 on-call 상황 보고서 생성","사용자 정의 가능한 lookback window를 사용하여 포털 상태 문제 디버깅"],"es":["Automatizar instantáneas de estado de todo el portal para cambios de turno y reuniones matutinas","Generar informes de situación de llamadas con paisajes de alertas detallados","Depurar problemas de salud del portal usando ventanas de retroceso personalizables"],"fr":["Automatiser les instantanés d''état du portail pour les changements de quart et les réunions du matin","Générer des rapports de situation d''appel avec des paysages d''alerte détaillés","Déboguer les problèmes de santé du portail en utilisant des fenêtres de retour arrière personnalisables"],"de":["Automatisieren von Portal-Health-Schnappschüssen für Schichtwechsel und morgendliche Stand-ups","Erstellen von On-Call-Situationenberichten mit detaillierten Alert-Landschaften","Beheben von Portal-Health-Problemen unter Verwendung von anpassbaren Rückblickfenstern"],"pt":["Automatizar instantâneos de saúde em toda a portal para transferências de turno e reuniões matutinas","Gerar relatórios de situação de chamada com paisagens de alerta detalhadas","Depurar problemas de saúde do portal usando janelas de lookback personalizáveis"],"ru":["Автоматизировать снимки здоровья на всем портале для смен и утренних встреч","Генерировать отчеты о ситуации вызова с подробными ландшафтами оповещений","Отлаживать проблемы со здоровьем портала с помощью настраиваемых окон просмотра"],"ar":["توفير لقطات صحية شاملة لجميع البوابة لتحويلات الدورات والاجتماعات الصباحية","генерировать تقارير حالة المكالمة مع مناظر تفصيلية للتنبيهات","تصحيح أخطاء صحة البوابة باستخدام نوافذ خلفية قابلة للتعديل"]},"limitations":{"en":["Requires LogicMonitor REST API v3 access","Limited to 4-hour lookback window by default"],"zh":["需要 LogicMonitor REST API v3 访问权限","默认情况下回看窗口限制为 4 小时"],"ja":["LogicMonitor REST API v3 へのアクセスが必要","デフォルトではルックバックウィンドウは4時間に制限されています"],"ko":["LogicMonitor REST API v3 접근이 필요함","기본적으로 lookback window는 4시간으로 제한됨"],"es":["Requiere acceso a la API REST de LogicMonitor v3","Limitado a una ventana de retroceso de 4 horas por defecto"],"fr":["Nécessite l''accès à l''API REST LogicMonitor v3","Limité à une fenêtre de retour arrière de 4 heures par défaut"],"de":["Erfordert Zugriff auf die LogicMonitor-REST-API v3","Begrenzt auf ein 4-Stunden-Rückblickfenster standardmäßig"],"pt":["Exige acesso à API REST do LogicMonitor v3","Limitado a uma janela de lookback de 4 horas por padrão"],"ru":["Требует доступа к API REST LogicMonitor v3","Ограничен четырехчасовым окном просмотра по умолчанию"],"ar":["يتطلب الوصول إلى واجهة برمجة تطبيقات LogicMonitor REST v3","محدود بنافذة خلفية مدتها 4 ساعات افتراضيًا"]},"version":4},"contentHash":"35c784679387c24d846e4087a55d0134a63a883ed13ccab05c7cbbcd24949ab4","qualityScore":33}');
