INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ryanmat/mcp-server-logicmonitor/lm-portal', 'lm-portal', 'ryanmat', 'mcp-server-logicmonitor', 'community', 'lm-portal ryanmat mcp-server-logicmonitor community lm-portal enables AI assistants to interact with LogicMonitor monitoring data through structured tools, ideal for portal health analysts. It integrates with LogicMonitor REST API v3 for comprehensive health snapshots lm-portal是LogicMonitor REST API v3的MCP服务器，实现AI助手与监控数据的交互 lm-portalはLogicMonitor REST API v3のMCPサーバーで、AIエージェントが監視データとやり取りすることを可能にします lm-portal은 LogicMonitor REST API v3의 MCP 서버로 AI 도구가 모니터링 데이터와 상호작용할 수 있습니다 lm-portal es un servidor MCP para la integración de la API de LogicMonitor v3, que permite a los asistentes de IA interactuar con datos de monitoreo estructurados lm-portal est un serveur MCP pour l''intégration de l''API LogicMonitor v3, qui permet aux assistants de l''IA d''interagir avec des données de surveillance structurées lm-portal ist ein MCP-Server für die Integration der LogicMonitor-API v3, der es AI-Assistenten ermöglicht, mit strukturierten Überwachungsdaten zu interagieren O lm-portal é um servidor MCP para integração com a API do LogicMonitor v3, permitindo que assistentes de IA interajam com dados de monitoramento lm-portal — это сервер MCP для интеграции с API LogicMonitor v3, позволяющий ИИ-ассистентам взаимодействовать с данными мониторинга lm-portal هو خادم MCP لإدماج LogicMonitor API v3، مما يسمح للأدوات الذكاء الاصطناعي بالتفاعل مع بيانات المراقبة how to use lm-portal lm-portal alternative lm-portal setup guide what is lm-portal lm-portal vs logicmonitor lm-portal install logicmonitor rest api v3 integration lm-portal for ai agents lm-portal for portal health analysis lm-portal LogicMonitor REST API v3 AI分析 MCP服务器 监控数据 结构化分析 lookback窗口 Argument Parsing Executes argument parsing for lookback windows via hours_back parameter Provides alert landscape overview through get_a command Supports incremental findings presentation for shift handoffs and morning standups Enables on-call situation reports with structured tools Integrates with LogicMonitor REST API v3 for comprehensive monitoring data access lm-portal is a MCP server for LogicMonitor REST API v3 integration, designed to facilitate AI assistant interaction with monitoring data');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('extropolis/claudia/list-tasks', 'community', 'extropolis', 'claudia', 'extropolis/claudia', 'list-tasks', 3, 1, 33, '2026-03-01T18:01:43Z', '2026-03-06T13:06:44.640Z', '9ce620ac749c113663e0169d681782901fa238ee622b746f2163b4cfa9c71bd5', '{"id":"extropolis/claudia/list-tasks","name":"list-tasks","description":{"en":"The list-tasks skill allows developers to list all tasks in the orchestrator and format the output to show task ID, name, status, and workspace. It benefits developers working with task management systems.","zh":"列表任务功能允许您使用CLI和tsx来列出和管理任务，包括任务ID、名称、状态和工作空间","ja":"タスク一覧機能を使用して、CLIとtsxでタスクを管理できます。タスクID、名称、状態、ワークスペースなど","ko":"작업 목록 기능을 사용하여 CLI와 tsx로 작업을 관리할 수 있습니다. 작업 ID, 이름, 상태, 작업 공간 등","es":"Listar tareas de AI Agent con CLI es una función que permite a los desarrolladores ver todas las tareas en el orquestador","fr":"Lister les tâches d''Agent IA avec la ligne de commande est une fonction qui permet aux développeurs de voir toutes les tâches dans l''orchestrateur","de":"Die Auflistung von AI-Agent-Aufgaben mit CLI ist eine Funktion, die es Entwicklern ermöglicht, alle Aufgaben im Orchestrierer anzuzeigen","pt":"O list-tasks é uma ferramenta que executa tarefas utilizando o CLI, fornecendo detalhes de tarefas específicas e saída formatada.","ru":"List-tasks - это инструмент, который запускает задачи с помощью CLI, предоставляя подробную информацию о конкретных задачах и форматированный вывод.","ar":"أداة list-tasks هي أداة تشغيل المهام باستخدام واجهة سطر الأوامر، توفر معلومات مفصلة حول المهام المحددة وخرج معالج بشكل جيد."},"seo":{"title":{"en":"list-tasks: Task Management Setup Guide | AI Agent Skill","zh":"列表任务setup指南 - 使用CLI和tsx","ja":"タスク一覧のベストプラクティス - CLIとtsxを使用","ko":"작업 목록 가이드 - CLI와 tsx로 작업 관리","es":"Guía para listar tareas de AI Agent con CLI","fr":"Lister les tâches d''Agent IA avec la ligne de commande","de":"Leitfaden für die Auflistung von AI-Agent-Aufgaben mit CLI","pt":"Guia de Configuração do list-tasks: Executando Tarefas co...","ru":"ИИ Агенты: Руководство по настройке list-tasks для запуск...","ar":"إعداد أداة list-tasks: دليل تشغيل المهام باستخدام واجهة س..."},"description":{"en":"Discover how to list and manage tasks with the list-tasks AI agent skill. Learn to run test CLI and format output for efficient task monitoring. Get started ...","zh":"了解如何使用CLI和tsx来列出和管理任务，包括任务ID、名称、状态和工作空间","ja":"CLIとtsxを使用してタスクを一覧表示し、管理方法を学習します。タスクID、名称、状態、ワークスペースなど","ko":"CLI와 tsx를 사용하여 작업을 목록으로 표시하고 관리하는 방법을 알아보세요. 작업 ID, 이름, 상태, 작업 공간 등","es":"Aprende a utilizar el comando CLI para listar tareas en el orquestador y obtener información detallada sobre cada tarea","fr":"Découvrez comment utiliser la ligne de commande pour lister les tâches dans l''orchestrateur et obtenir des informations détaillées sur chaque tâche","de":"Erfahren Sie, wie Sie den CLI-Befehl verwenden, um Aufgaben im Orchestrierer aufzulisten und detaillierte Informationen über jede Aufgabe zu erhalten","pt":"Aprenda a executar e gerenciar tarefas com o list-tasks, incluindo detalhes de tarefas específicas e saída formatada","ru":"Узнайте, как запускать и управлять задачами с помощью list-tasks, включая подробную информацию о конкретных задачах и форматированный вывод","ar":"تعرف على كيفية تشغيل وإدارة المهام باستخدام أداة list-tasks، بما في ذلك تفاصيل المهام المحددة وخرج معالج بشكل جيد"},"definition":{"en":"list-tasks is a skill that enables listing and managing tasks in an orchestrator, providing detailed information on task status and workspace","zh":"列表任务是AIエージェント中的一个功能，用于列出和管理任务","ja":"タスク一覧は、AIエージェントの機能の1つで、タスクを一覧表示し、管理するために使用されます","ko":"작업 목록은 AI 도구의 기능 중 하나로 작업을 목록으로 표시하고 관리하는 데 사용됩니다","es":"Listar tareas es una función que muestra información sobre las tareas en ejecución, completadas o con error en el orquestador","fr":"Lister les tâches est une fonction qui affiche des informations sur les tâches en cours, terminées ou en erreur dans l''orchestrateur","de":"Die Auflistung von Aufgaben ist eine Funktion, die Informationen über die Aufgaben im Orchestrierer anzeigt, die ausgeführt, abgeschlossen oder fehlerhaft sind","pt":"O list-tasks é uma ferramenta de linha de comando que lista e gerencia tarefas","ru":"List-tasks - это команда CLI, которая перечисляет и управляет задачами","ar":"أداة list-tasks هي أداة سطر أوامر تقوم بتحديث و إدارة المهام"},"features":{"en":["Runs test CLI using tsx and test-cli.ts","Lists all tasks in the orchestrator with task ID, name, and status","Formats output to show task details, including workspace","Supports filtering by task ID for detailed information","Utilizes npx for package execution and bash for scripting"],"zh":["使用CLI和tsx来列出任务","显示任务ID、名称、状态和工作空间","支持任务ID参数来显示详细信息","格式化输出以显示任务信息","使用npx tsx test-cli.ts来运行测试CLI"],"ja":["CLIとtsxを使用してタスクを一覧表示","タスクID、名称、状態、ワークスペースを表示","タスクIDパラメータを使用して詳細情報を表示","出力フォーマットを使用してタスク情報を表示","npx tsx test-cli.tsを使用してテストCLIを実行"],"ko":["CLI와 tsx를 사용하여 작업을 목록으로 표시","작업 ID, 이름, 상태, 작업 공간을 표시","작업 ID 매개 변수를 사용하여 상세 정보를 표시","출력 형식을 사용하여 작업 정보를 표시","npx tsx test-cli.ts를 사용하여 테스트 CLI를 실행"],"es":["Utiliza el comando CLI para listar tareas","Muestra información detallada sobre cada tarea, incluyendo ID, nombre y estado","Permite filtrar tareas por ID de tarea","Utiliza TypeScript y la línea de comando para ejecutar el comando de prueba","Utiliza la herramienta de línea de comando tsx para ejecutar el comando de prueba"],"fr":["Utilisez la ligne de commande pour lister les tâches","Affiche des informations détaillées sur chaque tâche, y compris l''ID, le nom et l''état","Permet de filtrer les tâches par ID de tâche","Utilise TypeScript et la ligne de commande pour exécuter la commande de test","Utilise l''outil de ligne de commande tsx pour exécuter la commande de test"],"de":["Verwenden Sie den CLI-Befehl, um Aufgaben aufzulisten","Zeigt detaillierte Informationen über jede Aufgabe an, einschließlich ID, Name und Status","Ermöglicht das Filtern von Aufgaben nach Aufgaben-ID","Verwendet TypeScript und die Kommandozeile, um den Testbefehl auszuführen","Verwendet das Kommandozeilen-Tool tsx, um den Testbefehl auszuführen"],"pt":["Executa tarefas utilizando o CLI","Fornece detalhes de tarefas específicas","Saída formatada com informações de tarefa","Suporta argumentos para tarefas específicas","Integração com o tsx test-cli.ts"],"ru":["Запускает задачи с помощью CLI","Предоставляет подробную информацию о конкретных задачах","Форматированный вывод с информацией о задаче","Поддерживает аргументы для конкретных задач","Интеграция с tsx test-cli.ts"],"ar":["تشغيل المهام باستخدام واجهة سطر الأوامر","توفر معلومات مفصلة حول المهام المحددة","خرج معالج بشكل جيد مع معلومات المهمة","دعم الحجج للمهام المحددة","التكامل مع tsx test-cli.ts"]},"keywords":{"en":["how to use list-tasks","list-tasks setup guide","task management with list-tasks","list-tasks alternative","list-tasks vs taskmaster","install list-tasks","list-tasks tutorial","what is list-tasks","list-tasks documentation"],"zh":["列表任务","CLI","tsx","AIエージェント","任务管理","工作空间","npx tsx test-cli.ts","任务ID","名称","状态"],"ja":["タスク一覧","CLI","tsx","AIエージェント","タスク管理","ワークスペース","npx tsx test-cli.ts","タスクID","名称","状態"],"ko":["작업 목록","CLI","tsx","AI 도구","작업 관리","작업 공간","npx tsx test-cli.ts","작업 ID","이름","상태"],"es":["listar tareas AI Agent","CLI para listar tareas","orquestador de tareas","TypeScript para AI Agent","tsx para AI Agent","comando de prueba para AI Agent","filtrar tareas por ID","información detallada sobre tareas"],"fr":["lister les tâches d''Agent IA","ligne de commande pour lister les tâches","orchestrateur de tâches","TypeScript pour Agent IA","tsx pour Agent IA","commande de test pour Agent IA","filtrer les tâches par ID","informations détaillées sur les tâches"],"de":["Auflisten von AI-Agent-Aufgaben","CLI-Befehl für die Auflistung von Aufgaben","Orchestrierer von Aufgaben","TypeScript für AI-Agent","tsx für AI-Agent","Testbefehl für AI-Agent","Filtern von Aufgaben nach ID","detaillierte Informationen über Aufgaben"],"pt":["list-tasks","CLI","tsx","test-cli.ts","gerenciamento de tarefas","execução de tarefas","ferramentas de desenvolvimento"],"ru":["list-tasks","CLI","tsx","test-cli.ts","управление задачами","запуск задач","инструменты разработки","ИИ Агенты"],"ar":["list-tasks","CLI","tsx","test-cli.ts","إدارة المهام","تشغيل المهام","أدوات التطوير","أدوات الذكاء الاصطناعي"]}},"owner":"extropolis","repo":"claudia","repoPath":"extropolis/claudia","stars":3,"forks":1,"updatedAt":"2026-03-01T18:01:43Z","topics":[],"category":"community","skillMd":{"name":"list-tasks","description":"List all tasks in the Claudia orchestrator using the test CLI. Use when you need to see running or completed tasks.","bodyPreview":"# List Claudia Tasks\n\nRun the test CLI to list all tasks in the orchestrator:\n\n```bash\ncd /Users/I850333/projects/experiments/claudia/backend && npx tsx test-cli.ts --list-tasks\n```\n\nFormat the output nicely showing:\n- Task ID\n- Task name\n- Status (running/completed/error)\n- Workspace\n\nIf $ARGUMENTS contains a task ID, also show detailed info for that specific task.","body":"# List Claudia Tasks\n\nRun the test CLI to list all tasks in the orchestrator:\n\n```bash\ncd /Users/I850333/projects/experiments/claudia/backend && npx tsx test-cli.ts --list-tasks\n```\n\nFormat the output nicely showing:\n- Task ID\n- Task name\n- Status (running/completed/error)\n- Workspace\n\nIf $ARGUMENTS contains a task ID, also show detailed info for that specific task.\n"},"lastSynced":"2026-03-06T13:06:44.640Z","agentAnalysis":{"suitability":{"en":"Ideal for Task Management Agents requiring comprehensive task listing and status tracking capabilities.","zh":"适用于需要全面任务列表和状态跟踪功能的任务管理代理。","ja":"タスク管理エージェントが包括的なタスクリストとステータストラッキング機能を必要とする場合に適しています。","ko":"포괄적인 작업 목록 및 상태 추적 기능이 필요한 작업 관리 에이전트에 적합합니다.","es":"Ideal para Agentes de Gestión de Tareas que requieren una lista de tareas y capacidades de seguimiento de estado comprehensivas.","fr":"Idéal pour les agents de gestion de tâches nécessitant une liste de tâches et des capacités de suivi d''état complètes.","de":"Ideal für Task-Management-Agents, die eine umfassende Aufgabenliste und Statusverfolgungsfunktionen erfordern.","pt":"Ideal para Agentes de Gerenciamento de Tarefas que requerem listagem de tarefas abrangente e capacidades de rastreamento de status.","ru":"Идеально для агентов по управлению задачами, требующих всестороннего перечня задач и возможностей отслеживания статуса.","ar":"مثالية للوكلاء إدارة المهام التي تتطلب قائمة شاملة للمهام وقدرات تتبع الحالة."},"recommendation":{"en":"Empowers agents to efficiently list and manage tasks using CLI commands, providing detailed task information including task ID, name, status, and workspace, and supporting task-specific queries via $ARGUMENTS.","zh":"赋予代理使用CLI命令高效地列出和管理任务的能力，提供包括任务ID、名称、状态和工作空间在内的详细任务信息，并支持通过$ARGUMENTS进行任务特定查询。","ja":"CLIコマンドを使用してタスクを効率的にリストし、管理するエージェントの機能を強化し、タスクID、名前、ステータス、ワークスペースを含む詳細なタスク情報を提供し、$ARGUMENTSを介してタスク特定のクエリをサポートします。","ko":"CLI 명령을 사용하여 에이전트가 작업을 효율적으로 목록화하고 관리할 수 있는 능력을 부여하며, 작업 ID, 이름, 상태 및 작업 공간을 포함한 자세한 작업 정보를 제공하고, $ARGUMENTS를 통해 작업 특정 쿼리를 지원합니다.","es":"Habilita a los agentes a listar y gestionar tareas de manera eficiente utilizando comandos CLI, proporcionando información detallada sobre las tareas, incluyendo ID de tarea, nombre, estado y espacio de trabajo, y admitiendo consultas específicas de tareas a través de $ARGUMENTS.","fr":"Permet aux agents de lister et de gérer des tâches de manière efficace en utilisant des commandes CLI, en fournissant des informations détaillées sur les tâches, y compris l''ID de tâche, le nom, l''état et l''espace de travail, et en prenant en charge les requêtes spécifiques à la tâche via $ARGUMENTS.","de":"Ermöglicht es Agenten, Aufgaben effizient mithilfe von CLI-Befehlen zu listen und zu verwalten, indem detaillierte Aufgabeninformationen bereitgestellt werden, einschließlich Aufgaben-ID, Name, Status und Arbeitsbereich, und unterstützt aufgabenbezogene Abfragen über $ARGUMENTS.","pt":"Habilita agentes a listarem e gerenciarem tarefas de forma eficiente usando comandos CLI, fornecendo informações detalhadas sobre as tarefas, incluindo ID da tarefa, nome, status e espaço de trabalho, e suportando consultas específicas de tarefas via $ARGUMENTS.","ru":"Наделяет агентов возможностью эффективно перечислять и управлять задачами с помощью команд CLI, предоставляя подробную информацию о задачах, включая идентификатор задачи, имя, статус и рабочее пространство, и поддерживая запросы, специфичные для задач, через $ARGUMENTS.","ar":"تمكين الوكلاء من قائمة المهام وإدارتها بفعالية باستخدام أوامر CLI، وتقديم معلومات مفصلة حول المهام، بما في ذلك معرف المهام،اسم،حالة،ومساحة العمل، ودعم استفسارات محددة للمهام عبر $ARGUMENTS."},"useCases":{"en":["Listing all tasks in the orchestrator for status tracking","Retrieving detailed information for a specific task by ID","Formatting task output for improved readability and analysis"],"zh":["在编排器中列出所有任务以进行状态跟踪","通过ID检索特定任务的详细信息","格式化任务输出以提高可读性和分析性"],"ja":["オーケストレーター内のすべてのタスクをステータストラッキングのためにリストする","IDによって特定のタスクの詳細情報を取得する","タスク出力をフォーマットして可読性と分析性を向上させる"],"ko":["오케스트레이터에서 모든 작업을 상태 추적을 위해 목록화하는 것","ID로 특정 작업의 자세한 정보를 검색하는 것","작업 출력을 형식화하여 가독성과 분석성을 향상시키는 것"],"es":["Listar todas las tareas en el orchestrator para realizar un seguimiento de estado","Recuperar información detallada para una tarea específica por ID","Formato de salida de tareas para mejorar la legibilidad y el análisis"],"fr":["Lister toutes les tâches dans l''orchestrator pour effectuer un suivi d''état","Récupérer des informations détaillées pour une tâche spécifique par ID","Mise en forme de la sortie des tâches pour améliorer la lisibilité et l''analyse"],"de":["Auflisten aller Aufgaben im Orchestrator zur Statusverfolgung","Abrufen detaillierter Informationen für eine bestimmte Aufgabe per ID","Formatierung der Aufgaben Ausgabe zur Verbesserung der Lesbarkeit und Analyse"],"pt":["Listar todas as tarefas no orchestrator para rastreamento de status","Recuperar informações detalhadas para uma tarefa específica por ID","Formatar a saída de tarefas para melhor legibilidade e análise"],"ru":["Перечисление всех задач в orchestrator для отслеживания статуса","Получение подробной информации для конкретной задачи по идентификатору","Форматирование вывода задач для улучшения читаемости и анализа"],"ar":["قائمة جميع المهام في الاوركسترا للتعقب الحالة","استرجاع معلومات مفصلة لمهمة محددة بواسطة المعرف","تنسيق مخرجات المهام لتحسين القراءة والتحليل"]},"limitations":{"en":["Requires access to the orchestrator and task management system","Dependent on CLI commands and $ARGUMENTS for task-specific queries"],"zh":["需要访问编排器和任务管理系统","依赖于CLI命令和$ARGUMENTS进行任务特定查询"],"ja":["オーケストレーターとタスク管理システムへのアクセスが必要","CLIコマンドと$ARGUMENTSに依存してタスク特定のクエリを実行する"],"ko":["오케스트레이터 및 작업 관리 시스템에 대한 액세스가 필요함","CLI 명령 및 $ARGUMENTS에 의존하여 작업 특정 쿼리를 수행함"],"es":["Requiere acceso al orchestrator y al sistema de gestión de tareas","Dependiente de comandos CLI y $ARGUMENTS para consultas específicas de tareas"],"fr":["Nécessite un accès à l''orchestrator et au système de gestion de tâches","Dépend des commandes CLI et de $ARGUMENTS pour les requêtes spécifiques à la tâche"],"de":["Benötigt Zugriff auf den Orchestrator und das Task-Management-System","Abhängig von CLI-Befehlen und $ARGUMENTS für aufgabenbezogene Abfragen"],"pt":["Requer acesso ao orchestrator e sistema de gerenciamento de tarefas","Dependente de comandos CLI e $ARGUMENTS para consultas específicas de tarefas"],"ru":["Требует доступа к orchestrator и системе управления задачами","Зависит от команд CLI и $ARGUMENTS для запросов, специфичных для задач"],"ar":["يتطلب الوصول إلى الاوركسترا ونظام إدارة المهام","يعتمد على أوامر CLI و $ARGUMENTS للاستفسارات المحددة للمهام"]},"version":4},"contentHash":"9ce620ac749c113663e0169d681782901fa238ee622b746f2163b4cfa9c71bd5","qualityScore":33}');
