INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('extropolis/claudia/list-tasks', 'list-tasks', 'extropolis', 'claudia', 'community', 'list-tasks extropolis claudia community The list-tasks skill allows developers to list all tasks in the orchestrator and format the output to show task ID, name, status, and workspace. It benefits developers working with task management systems. 列表任务功能允许您使用CLI和tsx来列出和管理任务，包括任务ID、名称、状态和工作空间 タスク一覧機能を使用して、CLIとtsxでタスクを管理できます。タスクID、名称、状態、ワークスペースなど 작업 목록 기능을 사용하여 CLI와 tsx로 작업을 관리할 수 있습니다. 작업 ID, 이름, 상태, 작업 공간 등 Listar tareas de AI Agent con CLI es una función que permite a los desarrolladores ver todas las tareas en el orquestador Lister les tâches d''Agent IA avec la ligne de commande est une fonction qui permet aux développeurs de voir toutes les tâches dans l''orchestrateur Die Auflistung von AI-Agent-Aufgaben mit CLI ist eine Funktion, die es Entwicklern ermöglicht, alle Aufgaben im Orchestrierer anzuzeigen O list-tasks é uma ferramenta que executa tarefas utilizando o CLI, fornecendo detalhes de tarefas específicas e saída formatada. List-tasks - это инструмент, который запускает задачи с помощью CLI, предоставляя подробную информацию о конкретных задачах и форматированный вывод. أداة list-tasks هي أداة تشغيل المهام باستخدام واجهة سطر الأوامر، توفر معلومات مفصلة حول المهام المحددة وخرج معالج بشكل جيد. how to use list-tasks list-tasks setup guide task management with list-tasks list-tasks alternative list-tasks vs taskmaster install list-tasks list-tasks tutorial what is list-tasks list-tasks documentation 列表任务 CLI tsx AIエージェント 任务管理 工作空间 npx tsx test-cli.ts 任务ID 名称 状态 Runs test CLI using tsx and test-cli.ts Lists all tasks in the orchestrator with task ID, name, and status Formats output to show task details, including workspace Supports filtering by task ID for detailed information Utilizes npx for package execution and bash for scripting list-tasks is a skill that enables listing and managing tasks in an orchestrator, providing detailed information on task status and workspace');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('marchatton/agent-skills/ask-questions-if-underspecified', 'community', 'marchatton', 'agent-skills', 'marchatton/agent-skills', 'ask-questions-if-underspecified', 3, 0, 33, '2026-03-03T18:15:28Z', '2026-03-06T07:04:12.962Z', 'b9b1c99c8df6297ee0df8017d4a2c2f31cc00152311787fef8ddbf742966ae0d', '{"id":"marchatton/agent-skills/ask-questions-if-underspecified","name":"ask-questions-if-underspecified","description":{"en":"The ask-questions-if-underspecified skill helps developers avoid implementing incorrect solutions by asking clarifying questions to ensure objectives are clear. It benefits agentic software development teams.","zh":"『ask-questions-if-underspecified』技能帮助开发者避免不必要的工作，通过提出最少的澄清问题来确保正确的实现","ja":"『ask-questions-if-underspecified』スキルは、開発者が必要最小限の質問を通じて正しい実装を確保するのに役立ちます","ko":"『ask-questions-if-underspecified』 기능은 개발자가 최소한의 질문을 통해 올바른 구현을 보장하는 데 도움이 됩니다","es":"Ask-questions-if-underspecified es una habilidad para Agentes de IA que ayuda a evitar trabajo incorrecto haciendo preguntas clarificadoras antes de implementar","fr":"Ask-questions-if-underspecified est une compétence pour les Outils d''IA qui aide à éviter les erreurs en posant des questions de clarification avant la mise en œuvre","de":"Ask-questions-if-underspecified ist eine Fähigkeit für KI-Agenten, die dabei hilft, Fehlarbeit zu vermeiden, indem sie klärende Fragen stellt, bevor sie implementiert","pt":"O ''ask-questions-if-underspecified'' é uma habilidade que ajuda a evitar trabalho errado em desenvolvimento de software, fazendo perguntas clarificadoras antes de iniciar a implementação","ru":"ИИ Агент ''ask-questions-if-underspecified'' помогает избежать неправильной работы при разработке программного обеспечения, задавая уточняющие вопросы перед началом реализации","ar":"يعمل ''ask-questions-if-underspecified'' على مساعدة تجنب العمل الخاطئ في تطوير البرمجيات، من خلال طرح أسئلة توضيحية قبل البدء في التنفيذ"},"seo":{"title":{"en":"ask-questions-if-underspecified: Clarifying Questions Set...","zh":"AI工具 - 如何设置『ask-questions-if-underspecified』技能","ja":"AIエージェントの『ask-questions-if-underspecified』設定ガイド","ko":"AI 에이전트 - 『ask-questions-if-underspecified』 기능 설정 방법","es":"Guía de configuración para ask-questions-if-underspecifie...","fr":"Meilleures pratiques pour ask-questions-if-underspecified...","de":"Einrichtungsleitfaden für ask-questions-if-underspecified...","pt":"Guia de Configuração para ''ask-questions-if-underspecifie...","ru":"Настройка ИИ Агентов: ''ask-questions-if-underspecified'' д...","ar":"دليل الإعداد ل ''ask-questions-if-underspecified'' في تطوير..."},"description":{"en":"Discover how ask-questions-if-underspecified helps you avoid wrong work by asking the right questions - explore the workflow and get started today!","zh":"了解『ask-questions-if-underspecified』技能的技术细节，避免不必要的工作，提高开发效率","ja":"『ask-questions-if-underspecified』スキルを使用して、開発効率を向上させる方法を学ぶ","ko":"『ask-questions-if-underspecified』 기능을 사용하여 개발 효율을 높이는 방법을 알아보세요","es":"Aprende a implementar ask-questions-if-underspecified en tus proyectos de Agentes de IA para evitar trabajo incorrecto y mejorar la eficiencia","fr":"Découvrez comment utiliser ask-questions-if-underspecified avec les Outils d''IA pour améliorer la qualité de vos développements","de":"Erfahren Sie, wie Sie ask-questions-if-underspecified in KI-Agenten einsetzen, um Fehlarbeit zu vermeiden und die Effizienz zu steigern","pt":"Aprenda a implementar ''ask-questions-if-underspecified'' para evitar trabalho errado em desenvolvimento de software, com dicas e práticas recomendadas","ru":"Изучите, как настроить ''ask-questions-if-underspecified'' для избежания неправильной работы при разработке программного обеспечения, с помощью советов и реком...","ar":"تعلم كيفية تنفيذ ''ask-questions-if-underspecified'' لتجنب العمل الخاطئ في تطوير البرمجيات، مع نصائح وأفضل الممارسات"},"definition":{"en":"ask-questions-if-underspecified is a curated skill for agentic software development that ensures clear objectives and requirements before implementation begins.","zh":"『ask-questions-if-underspecified』是AI工具的一种技能，用于提出最少的澄清问题以避免错误的工作","ja":"『ask-questions-if-underspecified』は、AIエージェントのスキルの一種で、必要最小限の質問を通じて誤った作業を避けるために使用されます","ko":"『ask-questions-if-underspecified』는 AI 에이전트의 기능 중 하나로, 최소한의 질문을 통해 잘못된 작업을 피하는 데 사용됩니다","es":"Ask-questions-if-underspecified es una habilidad que permite a los Agentes de IA hacer preguntas para aclarar objetivos y requisitos antes de implementar","fr":"Ask-questions-if-underspecified est une compétence qui permet aux Outils d''IA de poser des questions pour clarifier les objectifs et les exigences avant la mise en œuvre","de":"Ask-questions-if-underspecified ist eine Fähigkeit, die es KI-Agenten ermöglicht, Fragen zu stellen, um Ziele und Anforderungen vor der Implementierung zu klären","pt":"O ''ask-questions-if-underspecified'' é uma habilidade de software que faz perguntas clarificadoras para evitar trabalho errado","ru":"ИИ Агент ''ask-questions-if-underspecified'' - это способность программного обеспечения, которая задает уточняющие вопросы для избежания неправильной работы","ar":"هو ''ask-questions-if-underspecified'' سمة برنامج تعمل على طرح أسئلة توضيحية لتجنب العمل الخاطئ"},"features":{"en":["Decides whether a request is underspecified based on clear objectives and requirements","Asks the minimum set of clarifying questions needed to avoid wrong work","Treats requests as underspecified if objectives, definitions, or other key factors are unclear","Delays implementation until must-have questions are answered or assumptions are approved","Ensures users explicitly approve proceeding with stated assumptions when necessary","Follows a defined workflow to ensure efficient and accurate question-asking"],"zh":["决定请求是否不明确","提出最少的澄清问题","避免不必要的工作","提高开发效率","确保正确的实现"],"ja":["リクエストが不明確かどうかを判断する","必要最小限の質問を出す","不必要な作業を避ける","開発効率を向上させる","正しい実装を確保する"],"ko":["요청이 불명확한지 결정","최소한의 질문을 하기","불필요한 작업을 피하기","개발 효율을 높이기","올바른 구현을 보장"],"es":["Decide si una solicitud está subespecificada","Hace preguntas clarificadoras para evitar trabajo incorrecto","Define el objetivo y los requisitos antes de implementar","Permite a los usuarios aprobar explícitamente las suposiciones","Mejora la eficiencia y reduce errores"],"fr":["Détermine si une demande est sous-spécifiée","Pose des questions de clarification pour éviter les erreurs","Définit l''objectif et les exigences avant la mise en œuvre","Permet aux utilisateurs d''approuver explicitement les hypothèses","Améliore l''efficacité et réduit les erreurs"],"de":["Entscheidet, ob eine Anfrage unvollständig spezifiziert ist","Stellt klärende Fragen, um Fehlarbeit zu vermeiden","Definiert das Ziel und die Anforderungen vor der Implementierung","Ermöglicht es Benutzern, Annahmen explizit zu genehmigen","Verbessert die Effizienz und reduziert Fehler"],"pt":["Decisão sobre se o pedido é subespecificado","Definição do objetivo e identificação do que deve mudar","Formulação de perguntas clarificadoras para evitar trabalho errado","Implementação condicional com base em respostas ou aprovação explícita do usuário","Integração com fluxos de trabalho de desenvolvimento de software"],"ru":["Определение, является ли запрос неоднозначным","Определение цели и определение того, что должно измениться","Формулирование уточняющих вопросов для избежания неправильной работы","Условная реализация на основе ответов или явного одобрения пользователя","Интеграция с рабочими процессами разработки программного обеспечения"],"ar":["تحديد ما إذا كان الطلب غير محدد","تحديد الهدف وتحديد ما يجب تغييره","صياغة أسئلة توضيحية لتجنب العمل الخاطئ","التنفيذ الشرطي بناءً على الإجابات أو الموافقة الصريحة للمستخدم","التكامل مع سير عمل تطوير البرمجيات"]},"keywords":{"en":["how to use ask-questions-if-underspecified","what is ask-questions-if-underspecified","ask-questions-if-underspecified alternative","ask-questions-if-underspecified vs other AI skills","ask-questions-if-underspecified install guide","ask-questions-if-underspecified setup tutorial","agentic software development best practices","avoiding wrong work in software development","clarifying questions in software development"],"zh":["AI工具","ask-questions-if-underspecified","开发效率","避免不必要的工作","正确的实现","AI开发","软件开发","开发技巧"],"ja":["AIエージェント","ask-questions-if-underspecified","開発効率","不必要な作業を避ける","正しい実装","AI開発","ソフトウェア開発","開発テクニック"],"ko":["AI 에이전트","ask-questions-if-underspecified","개발 효율","불필요한 작업을 피하기","올바른 구현","AI 개발","소프트웨어 개발","개발 기술"],"es":["Agentes de IA","ask-questions-if-underspecified","desarrollo de software","eficiencia en el desarrollo","evitar trabajo incorrecto","preguntas clarificadoras","objetivos y requisitos"],"fr":["Outils d''IA","ask-questions-if-underspecified","développement de logiciels","efficacité dans le développement","éviter les erreurs","questions de clarification","objectifs et exigences"],"de":["KI-Agenten","ask-questions-if-underspecified","Software-Entwicklung","Effizienz im Entwicklungsprozess","Fehlarbeit vermeiden","klärende Fragen","Ziele und Anforderungen"],"pt":["desenvolvimento de software","ask-questions-if-underspecified","IIs Agents","programação","desenvolvimento ágil","gestão de projetos","qualidade de software","testes de software","depuração de software"],"ru":["разработка программного обеспечения","ИИ Агенты","ask-questions-if-underspecified","программирование","гибкая разработка","управление проектами","качество программного обеспечения","тестирование программного обеспечения","отладка программного обеспечения"],"ar":["تطوير البرمجيات","وكلاء الذكاء الاصطناعي","ask-questions-if-underspecified","البرمجة","التطوير المحدد","إدارة المشاريع","جودة البرمجيات","اختبار البرمجيات","تصحيح البرمجيات"]}},"owner":"marchatton","repo":"agent-skills","repoPath":"marchatton/agent-skills","stars":3,"forks":0,"updatedAt":"2026-03-03T18:15:28Z","topics":[],"category":"community","skillMd":{"name":"ask-questions-if-underspecified","description":"Clarify requirements before implementing. Do not use automatically, only when invoked explicitly.","bodyPreview":"# Ask Questions If Underspecified\n\n## Goal\n\nAsk the minimum set of clarifying questions needed to avoid wrong work; do not start implementing until the must-have questions are answered (or the user explicitly approves proceeding with stated assumptions).\n\n## Workflow\n\n### 1) Decide whether the request is underspecified\n\nTreat a request as underspecified if after exploring how to perform the work, some or all of the following are not clear:\n- Define the objective (what should change vs stay the s","body":"# Ask Questions If Underspecified\n\n## Goal\n\nAsk the minimum set of clarifying questions needed to avoid wrong work; do not start implementing until the must-have questions are answered (or the user explicitly approves proceeding with stated assumptions).\n\n## Workflow\n\n### 1) Decide whether the request is underspecified\n\nTreat a request as underspecified if after exploring how to perform the work, some or all of the following are not clear:\n- Define the objective (what should change vs stay the same)\n- Define \"done\" (acceptance criteria, examples, edge cases)\n- Define scope (which files/components/users are in/out)\n- Define constraints (compatibility, performance, style, deps, time)\n- Identify environment (language/runtime versions, OS, build/test runner)\n- Clarify safety/reversibility (data migration, rollout/rollback, risk)\n\nIf multiple plausible interpretations exist, assume it is underspecified.\n\n### 2) Ask must-have questions first (keep it small)\n\nAsk 1-5 questions in the first pass. Prefer questions that eliminate whole branches of work.\n\nMake questions easy to answer:\n- Optimize for scannability (short, numbered questions; avoid paragraphs)\n- Offer multiple-choice options when possible\n- Suggest reasonable defaults when appropriate (mark them clearly as the default/recommended choice; bold the recommended choice in the list, or if you present options in a code block, put a bold \"Recommended\" line immediately above the block and also tag defaults inside the block)\n- Include a fast-path response (e.g., reply `defaults` to accept all recommended/default choices)\n- Include a low-friction \"not sure\" option when helpful (e.g., \"Not sure - use default\")\n- Separate \"Need to know\" from \"Nice to know\" if that reduces friction\n- Justify your choices (e.g., explain why a particular option is recommended in plain English)\n- Structure options so the user can respond with compact decisions (e.g., `1b 2a 3c`); restate the chosen options in plain language to confirm\n\n### 3) Pause before acting\n\nUntil must-have answers arrive:\n- Do not run commands, edit files, or produce a detailed plan that depends on unknowns\n- Do perform a clearly labeled, low-risk discovery step only if it does not commit you to a direction (e.g., inspect repo structure, read relevant config files)\n\nIf the user explicitly asks you to proceed without answers:\n- State your assumptions as a short numbered list\n- Ask for confirmation; proceed only after they confirm or correct them\n\n### 4) Confirm interpretation, then proceed\n\nOnce you have answers, restate the requirements in 1-3 sentences (including key constraints and what success looks like), then start work.\n\n## Question templates\n\n- \"Before I start, I need: (1) ..., (2) ..., (3) .... If you don''t care about (2), I will assume ....\"\n- \"Which of these should it be? A) ... B) ... C) ... (pick one)\"\n- \"What would you consider ''done''? For example: ...\"\n- \"Any constraints I must follow (versions, performance, style, deps)? If none, I will target the existing project defaults.\"\n- Use numbered questions with lettered options and a clear reply format\n\n```text\n1) Scope?\na) Minimal change (default)\nb) Refactor while touching the area\nc) Not sure - use default\n2) Compatibility target?\na) Current project defaults (default)\nb) Also support older versions: <specify>\nc) Not sure - use default\n\nReply with: defaults (or 1a 2a)\n```\n\n## Anti-patterns\n\n- Don''t ask questions you can answer with a quick, low-risk discovery read (e.g., configs, existing patterns, docs).\n- Don''t ask open-ended questions if a tight multiple-choice or yes/no would eliminate ambiguity faster.\n"},"lastSynced":"2026-03-06T07:04:12.962Z","agentAnalysis":{"suitability":{"en":"Perfect for Agentic Software Development Agents needing clear objective definitions and requirement clarifications.","zh":"非常适合需要明确目标定义和需求澄清的Agentic Software Development Agents。","ja":"Agentic Software Development Agentsが明確な目的の定義と要件の明確化を必要とする場合に最適です。","ko":"명확한 목표 정의 및 요구 사항 명확화가 필요한 Agentic Software Development 에이전트에 적합합니다.","es":"Perfecto para Agentes de Desarrollo de Software Agentic que necesitan definiciones de objetivos claras y aclaraciones de requisitos.","fr":"Parfait pour les Agents de Développement de Logiciels Agentic ayant besoin de définitions d''objectifs claires et de clarifications de exigences.","de":"Perfekt für Agentic Software-Entwicklungsagenten, die klare Zieldefinitionen und Anforderungsklärungen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento de Software Agêntico que necessitam de definições de objetivos claras e esclarecimentos de requisitos.","ru":"Идеально подходит для агентских программных агентов, требующих четких определений целей и разъяснений требований.","ar":"مثالي لعمليات تطوير البرمجيات الوكيل التي تحتاج إلى تعريفات واضحة للأهداف وتوضيحات للمتطلبات."},"recommendation":{"en":"Empowers agents to ask targeted clarifying questions, ensuring objectives are well-defined and avoiding incorrect implementations by utilizing protocols like decision-making workflows and assumption validation.","zh":"赋予代理人提出有针对性的澄清问题的能力，确保目标明确定义，并通过使用决策工作流和假设验证等协议避免不正确的实现。","ja":"エージェントにターゲットを絞ったクエリを提出する能力を付与し、目標が明確に定義され、デシジョンワークフローや仮定の検証などのプロトコルを利用して不正確な実装を回避します。","ko":"에이전트가 목표가 잘 정의되어 있는지 확인하고, 의사 결정 워크플ロー 및 가설 검증 등 프로토콜을 사용하여 잘못된 구현을 피함으로써 목적에 맞게 질문을 할 수 있도록 합니다.","es":"Habilita a los agentes a hacer preguntas clarificadoras dirigidas, asegurando que los objetivos estén bien definidos y evitando implementaciones incorrectas mediante protocolos como flujos de trabajo de toma de decisiones y validación de suposiciones.","fr":"Permet aux agents de poser des questions clarificatrices ciblées, garantissant que les objectifs soient bien définis et évitant les mises en œuvre incorrectes en utilisant des protocoles tels que des flux de travail de prise de décision et de validation des hypothèses.","de":"Ermächtigt die Agenten, gezielte Klärungsfragen zu stellen, um sicherzustellen, dass die Ziele gut definiert sind und falsche Implementierungen durch Protokolle wie Entscheidungsfluss-Workflows und Annahmevalidierung vermieden werden.","pt":"Habilita os agentes a fazer perguntas esclarecedoras direcionadas, garantindo que os objetivos estejam bem definidos e evitando implementações incorretas por meio de protocolos como fluxos de trabalho de tomada de decisões e validação de suposições.","ru":"Наделяет агентов возможностью задавать целевые уточняющие вопросы, гарантируя, что цели хорошо определены и избегая неправильных реализаций путем использования протоколов типа рабочих процессов принятия решений и проверки предположений.","ar":"تمكّن الوكيل من طرح أسئلة توضيحية موجهة، مما يضمن تحديد الأهداف بدقة وتجنب التنفيذ الخاطئ من خلال بروتوكولات مثل سير عمل اتخاذ القرارات وتصديق الفرضيات."},"useCases":{"en":["Clarifying underspecified project objectives","Validating assumptions before implementation","Determining must-have questions for clear requirement definitions"],"zh":["澄清不明确的项目目标","在实施之前验证假设","为明确的要求定义确定必须的问题"],"ja":["不明確なプロジェクト目的の明確化","実装前の仮定の検証","明確な要件定義のための必須質問の決定"],"ko":["불명확한 프로젝트 목표의 澄清","구현 전 가설의 검증","명확한 요구 사항 정의를 위한 필수 질문의 결정"],"es":["Clarificar los objetivos del proyecto poco especificados","Validar suposiciones antes de la implementación","Determinar las preguntas imprescindibles para definiciones de requisitos claras"],"fr":["Clarifier les objectifs de projet mal spécifiés","Valider les hypothèses avant la mise en œuvre","Déterminer les questions essentielles pour des définitions de exigences claires"],"de":["Klärung ungenauer Projektziele","Validierung von Annahmen vor der Implementierung","Bestimmung der unverzichtbaren Fragen für klare Anforderungsdefinitionen"],"pt":["Esclarecer objetivos de projeto pouco especificados","Validar suposições antes da implementação","Determinar perguntas essenciais para definições de requisitos claras"],"ru":["Уточнение нечетко определенных целей проекта","Проверка предположений перед реализацией","Определение обязательных вопросов для четких определений требований"],"ar":["توضيح أهداف المشروع غير المحددة بوضوح","تصديق الفرضيات قبل التنفيذ","تحديد الأسئلة الضرورية لتعريفات متطلبات واضحة"]},"limitations":{"en":["Requires explicit user approval for proceeding with stated assumptions","Dependent on developer''s ability to identify underspecified requests"],"zh":["需要用户明确批准才能继续使用声明的假设","依赖于开发人员识别不明确请求的能力"],"ja":["記述された仮定を続行するために明示的なユーザー承認が必要","不明確なリクエストを識別する開発者の能力に依存"],"ko":["선언된 가설을 계속하려면 명시적인 사용자 승인이 필요","개발자가 불분명한 요청을 식별하는 능력에 의존"],"es":["Requiere una aprobación explícita del usuario para proceder con suposiciones declaradas","Depende de la capacidad del desarrollador para identificar solicitudes poco especificadas"],"fr":["Nécessite une approbation explicite de l''utilisateur pour poursuivre avec des hypothèses déclarées","Dépend de la capacité du développeur à identifier des demandes mal spécifiées"],"de":["Erfordert eine explizite Benutzerzustimmung für die Fortsetzung mit angegebenen Annahmen","Hängt von der Fähigkeit des Entwicklers ab, ungenaue Anforderungen zu identifizieren"],"pt":["Exige aprovação explícita do usuário para prosseguir com suposições declaradas","Depende da capacidade do desenvolvedor de identificar solicitações pouco especificadas"],"ru":["Требует явного одобрения пользователя для продолжения работы с заявленными предположениями","Зависит от способности разработчика определять нечетко определенные запросы"],"ar":["يتطلب موافقة مستخدم صريحة للمتابعة مع افتراضات محددة","يعتمد على قدرة المطور على تحديد الطلبات غير المحددة بوضوح"]},"version":4},"contentHash":"b9b1c99c8df6297ee0df8017d4a2c2f31cc00152311787fef8ddbf742966ae0d","qualityScore":33}');
