INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('marchatton/agent-skills/ask-questions-if-underspecified', 'ask-questions-if-underspecified', 'marchatton', 'agent-skills', 'community', 'ask-questions-if-underspecified marchatton agent-skills community The ask-questions-if-underspecified skill helps developers avoid implementing incorrect solutions by asking clarifying questions to ensure objectives are clear. It benefits agentic software development teams. 『ask-questions-if-underspecified』技能帮助开发者避免不必要的工作，通过提出最少的澄清问题来确保正确的实现 『ask-questions-if-underspecified』スキルは、開発者が必要最小限の質問を通じて正しい実装を確保するのに役立ちます 『ask-questions-if-underspecified』 기능은 개발자가 최소한의 질문을 통해 올바른 구현을 보장하는 데 도움이 됩니다 Ask-questions-if-underspecified es una habilidad para Agentes de IA que ayuda a evitar trabajo incorrecto haciendo preguntas clarificadoras antes de implementar Ask-questions-if-underspecified est une compétence pour les Outils d''IA qui aide à éviter les erreurs en posant des questions de clarification avant la mise en œuvre Ask-questions-if-underspecified ist eine Fähigkeit für KI-Agenten, die dabei hilft, Fehlarbeit zu vermeiden, indem sie klärende Fragen stellt, bevor sie implementiert O ''ask-questions-if-underspecified'' é uma habilidade que ajuda a evitar trabalho errado em desenvolvimento de software, fazendo perguntas clarificadoras antes de iniciar a implementação ИИ Агент ''ask-questions-if-underspecified'' помогает избежать неправильной работы при разработке программного обеспечения, задавая уточняющие вопросы перед началом реализации يعمل ''ask-questions-if-underspecified'' على مساعدة تجنب العمل الخاطئ في تطوير البرمجيات، من خلال طرح أسئلة توضيحية قبل البدء في التنفيذ how to use ask-questions-if-underspecified what is ask-questions-if-underspecified ask-questions-if-underspecified alternative ask-questions-if-underspecified vs other AI skills ask-questions-if-underspecified install guide ask-questions-if-underspecified setup tutorial agentic software development best practices avoiding wrong work in software development clarifying questions in software development AI工具 ask-questions-if-underspecified 开发效率 避免不必要的工作 正确的实现 AI开发 软件开发 开发技巧 Decides whether a request is underspecified based on clear objectives and requirements Asks the minimum set of clarifying questions needed to avoid wrong work Treats requests as underspecified if objectives, definitions, or other key factors are unclear Delays implementation until must-have questions are answered or assumptions are approved Ensures users explicitly approve proceeding with stated assumptions when necessary Follows a defined workflow to ensure efficient and accurate question-asking ask-questions-if-underspecified is a curated skill for agentic software development that ensures clear objectives and requirements before implementation begins.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('zsutxz/ClaudeLearning/github-ai-projects', 'community', 'zsutxz', 'ClaudeLearning', 'zsutxz/ClaudeLearning', 'github-ai-projects', 0, 0, 33, '2026-03-07T01:49:01.449Z', '2026-03-07T01:54:50.857Z', '6ca42f663e2bbd6515cd0bb4f33a196e1ba8af4b9c3aa5aad6786d3dd965b030', '{"id":"zsutxz/ClaudeLearning/github-ai-projects","name":"github-ai-projects","description":{"en":"The github-ai-projects skill helps developers find and analyze top AI projects on GitHub, utilizing GitHub API and search functionality with keywords like artificial intelligence and machine learning.","zh":"GitHub AI 项目搜索和分析技能，帮助开发者快速找到热门 AI 项目和分析项目活跃度","ja":"GitHub AI プロジェクト検索と分析スキルは、開発者が人気の AI プロジェクトを見つけてプロジェクトの活性度を分析するのに役立ちます","ko":"GitHub AI 프로젝트 검색 및 분석 스킬은 개발자가 인기 있는 AI 프로젝트를 찾고 프로젝트 활동을 분석하는 데 도움이 됩니다","es":"Aprende a utilizar la API de GitHub para buscar proyectos de inteligencia artificial y analizar su popularidad","fr":"Apprenez à utiliser l''API GitHub pour rechercher des projets d''intelligence artificielle et analyser leur popularité","de":"Lernen Sie, die GitHub-API zu nutzen, um KI-Projekte zu suchen und ihre Popularität zu analysieren","pt":"O GitHub-ai-projects é uma habilidade que ajuda a encontrar projetos AI de ponta no GitHub, incluindo PyTorch, TensorFlow e Hugging Face.","ru":"ИИ Агенты GitHub-ai-projects - это навык, который помогает найти передовые проекты ИИ на GitHub, включая PyTorch, TensorFlow и Hugging Face.","ar":"GitHub-ai-projects هو مهارة تساعد في العثور على مشاريع الذكاء الاصطناعي الرائدة على GitHub، بما في ذلك PyTorch و TensorFlow و Hugging Face."},"seo":{"title":{"en":"github-ai-projects: GitHub AI Project Search Setup Guide ...","zh":"GitHub AI 项目搜索和分析 Setup Guide","ja":"GitHub AI プロジェクト検索と分析ベストプラクティス","ko":"GitHub AI 프로젝트 검색 및 분석 가이드","es":"Guía de configuración de proyectos de inteligencia artifi...","fr":"Guide de mise en place des projets d''intelligence artific...","de":"Einrichtungsanleitung für KI-Projekte auf GitHub","pt":"Guia de Configuração do GitHub-ai-projects: Projetos AI e...","ru":"Настройка ИИ Агентов: GitHub-ai-projects для разработчиков","ar":"دليل إعداد GitHub-ai-projects: مشاريع الذكاء الاصطناعي ال..."},"description":{"en":"Discover top AI projects on GitHub with github-ai-projects. Learn how to search and analyze AI project updates, and get started with our setup guide today!","zh":"使用 GitHub API 和搜索功能，获取热门 AI 项目、分析项目活跃度和查看更新状态","ja":"GitHub API と検索機能を使用して、人気の AI プロジェクトを取得し、プロジェクトの活性度を分析し、更新状況を確認する","ko":"GitHub API와 검색 기능을 사용하여 인기 있는 AI 프로젝트를 가져오고 프로젝트 활동을 분석하며 업데이트 상태를 확인합니다","es":"Descubre los proyectos de inteligencia artificial más populares en GitHub y aprende a utilizar la API de GitHub para buscar y analizar proyectos de AI","fr":"Découvrez les projets d''intelligence artificielle les plus populaires sur GitHub et apprenez à utiliser l''API GitHub pour rechercher et analyser les projets ...","de":"Entdecken Sie die beliebtesten KI-Projekte auf GitHub und lernen Sie, die GitHub-API zu nutzen, um Projekte zu suchen und zu analysieren","pt":"Aprenda a utilizar o GitHub-ai-projects para encontrar projetos AI de ponta, incluindo PyTorch, TensorFlow e Hugging Face","ru":"Узнайте, как использовать ИИ Агенты GitHub-ai-projects для поиска передовых проектов ИИ, включая PyTorch, TensorFlow и Hugging Face","ar":"تعلم كيفية استخدام GitHub-ai-projects للعثور على مشاريع الذكاء الاصطناعي الرائدة، بما في ذلك PyTorch و TensorFlow و Hugging Face"},"definition":{"en":"github-ai-projects is a skill that enables AI agents to search and retrieve information on popular AI projects hosted on GitHub, focusing on machine learning and deep learning frameworks.","zh":"GitHub AI 项目搜索和分析是一种使用 GitHub API 和搜索功能的技能，用于获取热门 AI 项目和分析项目活跃度","ja":"GitHub AI プロジェクト検索と分析は、GitHub API と検索機能を使用して人気の AI プロジェクトを取得し、プロジェクトの活性度を分析するスキルです","ko":"GitHub AI 프로젝트 검색 및 분석은 GitHub API와 검색 기능을 사용하여 인기 있는 AI 프로젝트를 가져오고 프로젝트 활동을 분석하는 스킬입니다","es":"Un proyecto de inteligencia artificial en GitHub es un conjunto de código y recursos que utilizan técnicas de aprendizaje automático y procesamiento de lenguaje natural","fr":"Un projet d''intelligence artificielle sur GitHub est un ensemble de code et de ressources qui utilisent des techniques d''apprentissage automatique et de traitement du langage naturel","de":"Ein KI-Projekt auf GitHub ist eine Sammlung von Code und Ressourcen, die Techniken des maschinellen Lernens und der Verarbeitung von natürlicher Sprache verwenden","pt":"O que é GitHub-ai-projects? É uma habilidade que utiliza a API do GitHub para encontrar projetos AI de ponta.","ru":"Что такое ИИ Агенты GitHub-ai-projects? Это навык, который использует API GitHub для поиска передовых проектов ИИ.","ar":"ما هو GitHub-ai-projects؟ هو مهارة تستخدم واجهة برمجة التطبيقات GitHub للعثور على مشاريع الذكاء الاصطناعي الرائعة."},"features":{"en":["Searches GitHub projects using AI/ML keywords like artificial intelligence and machine learning","Utilizes GitHub API to retrieve project information and updates","Analyzes project activity and popularity based on star count and recent updates","Supports filtering by popular frameworks like PyTorch and TensorFlow","Provides information on emerging technologies like LLM and transformer models"],"zh":["使用 GitHub API 获取热门 AI 项目","分析项目活跃度和更新状态","支持多种 AI 框架，包括 PyTorch、TensorFlow 和 Scikit-learn","支持多种 AI 应用领域，包括计算机视觉、NLP 和强化学习","按星标数量排序，快速找到最热门的 AI 项目"],"ja":["GitHub API を使用して人気の AI プロジェクトを取得する","プロジェクトの活性度と更新状況を分析する","多種の AI フレームワーク、包括 PyTorch、TensorFlow、Scikit-learn をサポート","多種の AI アプリケーション分野、包括コンピュータビジョン、NLP、強化学習をサポート","スター数でソートして、最も人気のある AI プロジェクトを見つける"],"ko":["GitHub API를 사용하여 인기 있는 AI 프로젝트를 가져옵니다","프로젝트 활동과 업데이트 상태를 분석합니다","다양한 AI 프레임워크를 지원합니다. PyTorch, TensorFlow, Scikit-learn 등","다양한 AI 애플리케이션 분야를 지원합니다. 컴퓨터 비전, NLP, 강화 학습 등","スター 수로 정렬하여 가장 인기 있는 AI 프로젝트를 찾습니다"],"es":["Búsqueda de proyectos de inteligencia artificial utilizando la API de GitHub","Análisis de la popularidad de los proyectos de AI mediante la cantidad de estrellas","Filtrado de proyectos por tecnologías como PyTorch, TensorFlow y Scikit-learn","Búsqueda de proyectos por aplicaciones como visión por computadora, NLP y aprendizaje reforzado","Análisis de la actividad de los proyectos de AI en los últimos días, semanas o meses"],"fr":["Recherche de projets d''intelligence artificielle à l''aide de l''API GitHub","Analyse de la popularité des projets d''IA en fonction du nombre d''étoiles","Filtrage des projets par technologies comme PyTorch, TensorFlow et Scikit-learn","Recherche de projets par applications comme la vision par ordinateur, le NLP et l''apprentissage par renforcement","Analyse de l''activité des projets d''IA au cours des derniers jours, semaines ou mois"],"de":["Suche nach KI-Projekten mit der GitHub-API","Analyse der Popularität von KI-Projekten anhand der Anzahl der Sterne","Filterung von Projekten nach Technologien wie PyTorch, TensorFlow und Scikit-learn","Suche nach Projekten nach Anwendungen wie Computer-Vision, NLP und maschinellem Lernen","Analyse der Aktivität von KI-Projekten in den letzten Tagen, Wochen oder Monaten"],"pt":["Utiliza a API do GitHub para buscar projetos AI","Suporte a PyTorch, TensorFlow e Hugging Face","Análise de projetos com mais de 10 estrelas","Filtragem por data de atualização","Suporte a busca por palavras-chave como ''artificial intelligence'' e ''machine learning''"],"ru":["Использует API GitHub для поиска проектов ИИ","Поддержка PyTorch, TensorFlow и Hugging Face","Анализ проектов с более 10 звездами","Фильтрация по дате обновления","Поддержка поиска по ключевым словам как ''искусственный интеллект'' и ''machine learning''"],"ar":["استخدام واجهة برمجة التطبيقات GitHub للبحث عن مشاريع الذكاء الاصطناعي","دعم PyTorch و TensorFlow و Hugging Face","تحليل المشاريع التي لديها أكثر من 10 نجوم","الترشيح حسب تاريخ التحديث","دعم البحث بالكلمات المفتاحية مثل ''الذكاء الاصطناعي'' و ''machine learning''"]},"keywords":{"en":["github-ai-projects setup guide","how to use github-ai-projects","github-ai-projects vs github trending","github-ai-projects alternative","github ai project search","machine learning project ideas on github","install github-ai-projects","github-ai-projects documentation"],"zh":["GitHub AI 项目","AI 项目搜索","AI 项目分析","GitHub API","PyTorch","TensorFlow","Scikit-learn","计算机视觉","NLP","强化学习"],"ja":["GitHub AI プロジェクト","AI プロジェクト検索","AI プロジェクト分析","GitHub API","PyTorch","TensorFlow","Scikit-learn","コンピュータビジョン","NLP","強化学習"],"ko":["GitHub AI 프로젝트","AI 프로젝트 검색","AI 프로젝트 분석","GitHub API","PyTorch","TensorFlow","Scikit-learn","컴퓨터 비전","NLP","강화 학습"],"es":["proyectos de inteligencia artificial en GitHub","API de GitHub para inteligencia artificial","búsqueda de proyectos de AI","análisis de popularidad de proyectos de AI","PyTorch","TensorFlow","Scikit-learn","visión por computadora","NLP","aprendizaje reforzado"],"fr":["projets d''intelligence artificielle sur GitHub","API GitHub pour l''intelligence artificielle","recherche de projets d''IA","analyse de popularité des projets d''IA","PyTorch","TensorFlow","Scikit-learn","vision par ordinateur","NLP","apprentissage par renforcement"],"de":["KI-Projekte auf GitHub","GitHub-API für KI","Suche nach KI-Projekten","Analyse der Popularität von KI-Projekten","PyTorch","TensorFlow","Scikit-learn","Computer-Vision","NLP","maschinelles Lernen"],"pt":["github-ai-projects","projetos ai github","pytorch","tensorflow","hugging face","api github","busca projetos ai","análise de projetos ai"],"ru":["github-ai-projects","проекты ИИ на github","pytorch","tensorflow","hugging face","api github","поиск проектов ИИ","анализ проектов ИИ"],"ar":["github-ai-projects","مشاريع الذكاء الاصطناعي على github","pytorch","tensorflow","hugging face","واجهة برمجة التطبيقات github","بحث مشاريع الذكاء الاصطناعي","تحليل مشاريع الذكاء الاصطناعي"]}},"owner":"zsutxz","repo":"ClaudeLearning","repoPath":"zsutxz/ClaudeLearning","stars":0,"forks":0,"updatedAt":"2026-03-07T01:49:01.449Z","topics":[],"category":"community","skillMd":{"name":"github-ai-projects","description":"这个skill专门用于监控GitHub上的热门AI项目，获取项目的简述信息和不同时间范围的更新状态。当用户需要了解GitHub AI项目动态时使用此skill。通过智能分析项目的活跃度、星标增长、提交频率等指标，为用户提供AI领域最具潜力和活跃度的开源项目洞察。","bodyPreview":"## 使用时机\n当用户提出以下需求时，使用此skill：\n- \"获取GitHub热门AI项目\"\n- \"最近AI领域有什么值得关注的开源项目\"\n- \"查看AI项目更新状态\"\n- \"GitHub上AI项目活跃度分析\"\n- \"最近一天/本周/最近一个月的AI项目动态\"\n\n## 执行流程\n\n### 1. 项目搜索策略\n使用GitHub API和搜索功能，重点关注：\n- **AI/ML关键词**：artificial intelligence, machine learning, deep learning, neural network\n- **热门框架**：pytorch, tensorflow, scikit-learn, huggingface, langchain\n- **新兴技术**：llm, transformer, diffusion, stable diffusion, chatgpt\n- **应用领域**：computer vision, nlp, reinforcement learning, generative ai\n\n搜索参数：\n- 按星标数量排序（stars:>10","body":"## 使用时机\n当用户提出以下需求时，使用此skill：\n- \"获取GitHub热门AI项目\"\n- \"最近AI领域有什么值得关注的开源项目\"\n- \"查看AI项目更新状态\"\n- \"GitHub上AI项目活跃度分析\"\n- \"最近一天/本周/最近一个月的AI项目动态\"\n\n## 执行流程\n\n### 1. 项目搜索策略\n使用GitHub API和搜索功能，重点关注：\n- **AI/ML关键词**：artificial intelligence, machine learning, deep learning, neural network\n- **热门框架**：pytorch, tensorflow, scikit-learn, huggingface, langchain\n- **新兴技术**：llm, transformer, diffusion, stable diffusion, chatgpt\n- **应用领域**：computer vision, nlp, reinforcement learning, generative ai\n\n搜索参数：\n- 按星标数量排序（stars:>100）\n- 按最近更新时间排序\n- 过滤低质量项目（要求有README、有代码提交）\n- 限制编程语言（Python, JavaScript, C++, Rust等）\n\n### 2. 时间范围分析\n针对不同时间范围分析项目活跃度：\n\n#### 最近1天（24小时）\n- **活跃指标**：新的代码提交、issue讨论、PR合并\n- **热度指标**：星标增长、fork增长\n- **关注重点**：紧急bug修复、新功能发布、社区讨论热点\n\n#### 本周（7天）\n- **活跃指标**：提交频率、版本发布、重要合并\n- **热度指标**：周星标增长率、社区参与度\n- **关注重点**：功能迭代、技术债务清理、社区建设\n\n#### 最近一个月（30天）\n- **活跃指标**：版本发布周期、重要功能更新\n- **热度指标**：月度增长趋势、长期活跃度\n- **关注重点**：重大更新、架构改进、生态建设\n\n### 3. 项目评估维度\n\n#### 技术指标\n- **代码质量**：提交频率、代码审查、测试覆盖率\n- **文档完整性**：README质量、API文档、示例代码\n- **依赖管理**：依赖更新频率、安全漏洞修复\n\n#### 社区指标\n- **活跃度**：issues讨论、PR参与、社区响应\n- **增长性**：星标增长、fork数量、贡献者增加\n- **多样性**：贡献者地理分布、使用场景多样性\n\n#### 创新指标\n- **技术新颖性**：是否采用前沿技术或方法\n- **应用价值**：解决实际问题的能力\n- **生态影响**：对相关项目或社区的影响\n\n### 4. 项目简述生成\n为每个项目生成简明扼要的简述：\n\n#### 简述结构\n```\n📦 [项目名称]\n⭐ [星标数] | 🍴 [Fork数] | 📅 [最后更新]\n🏷️ [主要标签] [编程语言]\n📝 [项目简介 - 50字以内]\n🔥 [热度分析：为什么值得关注]\n📊 [活跃度评分：1-10分]\n🔗 [项目链接]\n```\n\n#### 热度分析要点\n- **技术创新性**：是否采用了新的技术或方法\n- **实用价值**：解决了什么实际问题\n- **社区活跃度**：开发者参与程度\n- **成长潜力**：未来发展趋势\n- **学习价值**：对AI学习者的参考价值\n\n### 5. 输出格式设计\n\n#### 整体报告格式\n```\n🚀 GitHub AI热门项目监控报告\n📅 更新时间：{当前日期时间}\n🔍 监控范围：{搜索条件}\n\n## 📈 热度排行榜（Top 10）\n\n### 🥇 第1名：[项目名称]\n⭐ [星标数] | 🍴 [Fork数] | 📅 [最后更新]\n🏷️ [主要标签] [编程语言]\n📝 [项目简介 - 50字以内]\n🔥 [热度分析：为什么值得关注]\n📊 [活跃度评分：1-10分]\n🔗 [项目链接]\n\n### 🥈 第2名：[项目名称]\n⭐ [星标数] | 🍴 [Fork数] | 📅 [最后更新]\n🏷️ [主要标签] [编程语言]\n📝 [项目简介 - 50字以内]\n🔥 [热度分析：为什么值得关注]\n📊 [活跃度评分：1-10分]\n🔗 [项目链接]\n\n## ⏰ 时间维度分析\n\n### 🔥 最近1天活跃项目\n- [项目列表和简要分析]\n\n### 📅 本周热门项目\n- [项目列表和简要分析]\n\n### 📊 最近一个月趋势\n- [项目列表和简要分析]\n\n## 🎯 重点推荐\n[基于多个维度综合评估的重点推荐项目]\n\n## 📋 数据洞察\n[整体趋势分析和发现]\n```\n\n## 技术实现方案\n\n### 1. GitHub API集成\n- **搜索API**：使用GitHub搜索API查找相关项目\n- **仓库API**：获取项目详细信息、统计数据\n- **提交API**：分析提交历史和活跃度\n- **Issue API**：监控社区讨论和问题反馈\n\n### 2. 数据处理流程\n```python\n# 伪代码示例\ndef fetch_github_ai_projects():\n    # 搜索AI相关项目\n    projects = search_github_repos(\n        query=\"artificial intelligence machine learning\",\n        sort=\"stars\",\n        order=\"desc\"\n    )\n    \n    # 获取项目详细信息\n    detailed_projects = []\n    for project in projects:\n        details = get_repo_details(project[''id''])\n        metrics = calculate_activity_metrics(details)\n        detailed_projects.append({\n            ''basic_info'': project,\n            ''details'': details,\n            ''metrics'': metrics,\n            ''summary'': generate_summary(project, details, metrics)\n        })\n    \n    return rank_projects(detailed_projects)\n```\n\n### 3. 活跃度计算算法\n```python\ndef calculate_activity_score(repo_details, timeframe):\n    weights = {\n        ''commits'': 0.4,\n        ''issues'': 0.2,\n        ''pull_requests'': 0.2,\n        ''stars_growth'': 0.1,\n        ''forks_growth'': 0.1\n    }\n    \n    # 根据时间范围计算各项指标\n    commits_score = normalize_commits(repo_details[''commits''], timeframe)\n    issues_score = normalize_issues(repo_details[''issues''], timeframe)\n    pr_score = normalize_prs(repo_details[''pull_requests''], timeframe)\n    stars_score = normalize_stars_growth(repo_details[''stars''], timeframe)\n    forks_score = normalize_forks_growth(repo_details[''forks''], timeframe)\n    \n    # 加权计算总活跃度评分\n    total_score = (\n        commits_score * weights[''commits''] +\n        issues_score * weights[''issues''] +\n        pr_score * weights[''pull_requests''] +\n        stars_score * weights[''stars_growth''] +\n        forks_score * weights[''forks_growth'']\n    )\n    \n    return min(10, max(1, total_score))\n```\n\n## 质量控制标准\n\n### 项目筛选标准\n- **最低要求**：至少100个星标，有README文档\n- **活跃度要求**：最近一个月内有代码提交\n- **质量标准**：有清晰的文档和许可证\n- **相关性**：确实属于AI/ML领域\n\n### 数据准确性\n- **实时更新**：确保获取最新数据\n- **多源验证**：交叉验证不同数据源\n- **异常检测**：识别和处理异常数据\n- **定期校准**：定期调整评估算法\n\n## 使用示例\n\n### 基本用法\n```\n用户：\"获取GitHub上最近的热门AI项目\"\nAI执行：\n1. 搜索AI相关项目\n2. 分析最近一周活跃度\n3. 生成项目排行榜\n4. 输出详细报告\n```\n\n### 高级用法\n```\n用户：\"重点关注计算机视觉领域的项目，最近一个月的更新\"\nAI执行：\n1. 搜索computer vision相关项目\n2. 过滤最近一个月有更新的项目\n3. 分析CV领域的具体技术栈\n4. 生成专业化的分析报告\n```\n\n## 扩展功能\n\n### 1. 个性化推荐\n- 基于用户兴趣标签推荐项目\n- 学习路径建议\n- 技术栈匹配分析\n\n### 2. 趋势分析\n- 长期趋势图表\n- 技术热点变化\n- 社区发展预测\n\n### 3. 竞品分析\n- 同类项目对比\n- 技术方案比较\n- 社区生态分析\n\n\n\n  \n## 注意事项\n1. **API限制**：注意GitHub API的调用限制\n2. **数据延迟**：GitHub数据可能有延迟，需要考虑时效性\n3. **语言处理**：项目描述可能包含多语言，需要适当处理\n4. **质量判断**：避免基于单一指标判断项目质量\n5. **隐私保护**：不获取或分析用户私有仓库信息\n6. **保存**：把内容以日期为分界,保存在根目录下的GitHubHot.md。\n\n现在你可以开始为用户提供GitHub AI热门项目的监控和分析服务了！"},"lastSynced":"2026-03-07T01:54:50.857Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agent Ecosystems needing to discover and analyze top AI projects on GitHub, utilizing GitHub API and search functionality with keywords like artificial intelligence and machine learning.","zh":"适用于需要发现和分析 GitHub 上顶级 AI 项目的 AI Agent 生态系统，利用 GitHub API 和搜索功能，使用人工智能和机器学习等关键词。","ja":"GitHub 上のトップ AI プロジェクトを発見して分析する必要がある AI Agent エコシステムに適しています。GitHub API と検索機能を使用し、人工知能や機械学習などのキーワードを使用します。","ko":"GitHub에서 상위 AI 프로젝트를 발견하고 분석해야 하는 AI 에이전트 생태계에 적합합니다. GitHub API 및 검색 기능을 사용하여 인공 지능 및 기계 학습과 같은 키워드를 사용합니다.","es":"Perfecto para ecosistemas de agentes de inteligencia artificial que necesitan descubrir y analizar los mejores proyectos de inteligencia artificial en GitHub, utilizando la API de GitHub y la funcionalidad de búsqueda con palabras clave como inteligencia artificial y aprendizaje automático.","fr":"Parfait pour les écosystèmes d''agents d''intelligence artificielle ayant besoin de découvrir et d''analyser les meilleurs projets d''intelligence artificielle sur GitHub, en utilisant l''API GitHub et la fonctionnalité de recherche avec des mots clés comme l''intelligence artificielle et l''apprentissage automatique.","de":"Perfekt für KI-Agenten-Ökosysteme, die die besten KI-Projekte auf GitHub entdecken und analysieren müssen, indem sie die GitHub-API und die Suchfunktion mit Schlüsselwörtern wie künstlicher Intelligenz und maschinellem Lernen nutzen.","pt":"Perfeito para Ecossistemas de Agentes de IA que precisam descobrir e analisar os principais projetos de IA no GitHub, utilizando a API do GitHub e a funcionalidade de pesquisa com palavras-chave como inteligência artificial e aprendizado de máquina.","ru":"Идеально подходит для Экосистем Агентов ИИ, которым необходимо обнаруживать и анализировать лучшие проекты ИИ на GitHub, используя GitHub API и функциональность поиска с ключевыми словами, такими как искусственный интеллект и машинное обучение.","ar":"مثالي لنظم وكلاء الذكاء الاصطناعي التي تحتاج إلى اكتشاف وتحليل أفضل مشاريع الذكاء الاصطناعي على GitHub، باستخدام واجهة برمجة تطبيقات GitHub ووظيفة البحث بالكلمات المفتاحية مثل الذكاء الاصطناعي والتعلم الآلي."},"recommendation":{"en":"Empowers agents to find and analyze GitHub projects using AI/ML keywords like pytorch, tensorflow, and scikit-learn, as well as new technologies such as llm, transformer, and stable diffusion, providing insights into project updates, popularity, and trends.","zh":"赋予代理找到和分析使用 AI/ML 关键词（如 pytorch、tensorflow 和 scikit-learn）的 GitHub 项目的能力，以及新技术如 llm、transformer 和 stable diffusion，提供对项目更新、受欢迎程度和趋势的洞察。","ja":"エージェントが AI/ML キーワード（pytorch、tensorflow、scikit-learn など）や新しいテクノロジー（llm、transformer、stable diffusion など）を使用して GitHub プロジェクトを検索して分析する能力を提供し、プロジェクトの更新、人気、トレンドに関する洞察を提供します。","ko":"에이전트가 AI/ML 키워드(pytorch, tensorflow, scikit-learn 등) 및 새로운 기술(llm, transformer, stable diffusion 등)을 사용하여 GitHub 프로젝트를 검색하고 분석할 수 있는 능력을 제공하며, 프로젝트 업데이트에 대한洞察, 인기, 트렌드에 대한洞察을 제공합니다.","es":"Habilita a los agentes a encontrar y analizar proyectos de GitHub utilizando palabras clave de IA/ML como pytorch, tensorflow y scikit-learn, así como nuevas tecnologías como llm, transformer y stable diffusion, proporcionando información sobre actualizaciones de proyectos, popularidad y tendencias.","fr":"Permet aux agents de trouver et d''analyser les projets GitHub en utilisant des mots clés IA/ML comme pytorch, tensorflow et scikit-learn, ainsi que de nouvelles technologies comme llm, transformer et stable diffusion, fournissant des informations sur les mises à jour de projets, la popularité et les tendances.","de":"Ermächtigt Agenten, GitHub-Projekte mithilfe von IA/ML-Schlüsselwörtern wie pytorch, tensorflow und scikit-learn sowie neuen Technologien wie llm, transformer und stable diffusion zu finden und zu analysieren, und gibt Einblicke in Projektaktualisierungen, Popularität und Trends.","pt":"Habilita os agentes a encontrar e analisar projetos do GitHub usando palavras-chave de IA/ML como pytorch, tensorflow e scikit-learn, bem como novas tecnologias como llm, transformer e stable diffusion, fornecendo insights sobre atualizações de projeto, popularidade e tendências.","ru":"Наделяет агентов возможностью находить и анализировать проекты GitHub с использованием ключевых слов ИИ/МО, таких как pytorch, tensorflow и scikit-learn, а также новых технологий, таких как llm, transformer и stable diffusion, обеспечивая информацию об обновлениях проекта, популярности и тенденциях.","ar":"يمنح الوكلاء القدرة على العثور على مشاريع GitHub وتحليلها باستخدام كلمات مفتاحية من الذكاء الاصطناعي والتعلم الآلي مثل pytorch وtensorflow وscikit-learn، وكذلك التكنولوجيا الجديدة مثل llm وtransformer وstable diffusion، مما يوفر رؤى حول تحديثات المشروع والشعبية والتوجهات."},"useCases":{"en":["Searching for popular AI projects with specific keywords like computer vision, nlp, or reinforcement learning","Analyzing the update status of AI projects on GitHub","Discovering recently trending AI projects using GitHub''s star and fork metrics","Identifying active AI projects with high community engagement"],"zh":["使用特定关键词（如计算机视觉、NLP 或强化学习）搜索流行的 AI 项目","分析 GitHub 上的 AI 项目的更新状态","使用 GitHub 的星和 fork 指标发现最近流行的 AI 项目","识别具有高社区参与度的活跃 AI 项目"],"ja":["特定キーワード（コンピュータビジョン、NLP、強化学習など）を使用して人気のある AI プロジェクトを検索する","GitHub 上の AI プロジェクトの更新状況を分析する","GitHub のスターとフォークの指標を使用して最近のトレンドの AI プロジェクトを発見する","高いコミュニティの関与度を持つ活発な AI プロジェクトを特定する"],"ko":["특정 키워드(컴퓨터 비전, NLP 또는 강화 학습 등)를 사용하여 인기 있는 AI 프로젝트를 검색합니다","GitHub上的 AI 프로젝트의 更新 상태를 분석합니다","GitHub의 별과 포크 지표를 사용하여 최근 트렌드의 AI 프로젝트를 발견합니다","높은 커뮤니티 참여도를 가진 활발한 AI 프로젝트를 식별합니다"],"es":["Buscar proyectos de IA populares con palabras clave específicas como visión por computadora, nlp o aprendizaje por refuerzo","Analizar el estado de actualización de los proyectos de IA en GitHub","Descubrir proyectos de IA que están siendo tendencia recientemente utilizando las métricas de estrellas y bifurcaciones de GitHub","Identificar proyectos de IA activos con una alta participación de la comunidad"],"fr":["Rechercher des projets d''IA populaires avec des mots clés spécifiques comme la vision par ordinateur, le nlp ou l''apprentissage par renforcement","Analyser l''état de mise à jour des projets d''IA sur GitHub","Découvrir les projets d''IA qui sont tendance récemment en utilisant les métriques d''étoiles et de fork de GitHub","Identifier les projets d''IA actifs avec une forte participation de la communauté"],"de":["Nach beliebten KI-Projekten mit spezifischen Schlüsselwörtern wie Computer-Vision, nlp oder Verstärkungslernen suchen","Den Aktualisierungsstatus von KI-Projekten auf GitHub analysieren","Aktuell trendy KI-Projekte mithilfe der Stern- und Fork-Metriken von GitHub entdecken","Aktive KI-Projekte mit hoher Community-Beteiligung identifizieren"],"pt":["Pesquisar projetos de IA populares com palavras-chave específicas como visão computacional, nlp ou aprendizado por reforço","Analizar o status de atualização de projetos de IA no GitHub","Descobrir projetos de IA recentemente em alta usando as métricas de estrelas e bifurcações do GitHub","Identificar projetos de IA ativos com alta participação da comunidade"],"ru":["Поиск популярных проектов ИИ с конкретными ключевыми словами, такими как компьютерное зрение, nlp или обучение с подкреплением","Анализ статуса обновления проектов ИИ на GitHub","Обнаружение недавно популярных проектов ИИ с использованием метрик звезд и вилок GitHub","Определение активных проектов ИИ с высокой вовлеченностью сообщества"],"ar":["البحث عن مشاريع الذكاء الاصطناعي الشهيرة باستخدام كلمات مفتاحية محددة مثل الرؤية الحاسوبية أو nlp أو التعلم بالتقوية","تحليل حالة تحديث مشاريع الذكاء الاصطناعي على GitHub","اكتشاف مشاريع الذكاء الاصطناعي التي تحظى باهتمام最近 باستخدام مقاييس النجوم والتشعب على GitHub","تحديد مشاريع الذكاء الاصطناعي النشطة التي تتمتع بمشاركة مجتمعية عالية"]},"limitations":{"en":["Requires GitHub API access","Limited to public GitHub repositories","Search results are filtered by stars (>10) and may not include lesser-known projects"],"zh":["需要 GitHub API 访问","仅限于公共 GitHub 仓库","搜索结果按星数（>10）过滤，可能不包括较不知名的项目"],"ja":["GitHub API アクセスが必要","パブリック GitHub リポジトリのみに限定","スター数（>10）でフィルタリングされた検索結果であるため、知名度の低いプロジェクトは含まれない場合がある"],"ko":["GitHub API 액세스가 필요합니다","공개 GitHub 리포지토리만 해당됩니다","スター 수(>10)로 필터링된 검색 결과이므로 상대적으로不知名한 프로젝트는 포함되지 않을 수 있습니다"],"es":["Requiere acceso a la API de GitHub","Limitado a los repositorios públicos de GitHub","Los resultados de la búsqueda se filtran por estrellas (>10) y pueden no incluir proyectos menos conocidos"],"fr":["Nécessite un accès à l''API GitHub","Limité aux dépôts publics GitHub","Les résultats de recherche sont filtrés par étoiles (>10) et peuvent ne pas inclure des projets moins connus"],"de":["Benötigt Zugriff auf die GitHub-API","Begrenzt auf öffentliche GitHub-Repositorys","Suchergebnisse werden durch Sterne (>10) gefiltert und können weniger bekannte Projekte nicht enthalten"],"pt":["Requer acesso à API do GitHub","Limitado a repositórios públicos do GitHub","Os resultados da pesquisa são filtrados por estrelas (>10) e podem não incluir projetos menos conhecidos"],"ru":["Требуется доступ к GitHub API","Ограничен публичными репозиториями GitHub","Результаты поиска фильтруются по звездам (>10) и могут не включать менее известные проекты"],"ar":["يتطلب الوصول إلى واجهة برمجة تطبيقات GitHub","محدود بمخازن GitHub العامة","تُفلتر نتائج البحث حسب النجوم (>10) وอาจ لا تشمل مشاريع أقل شهرة"]},"version":4},"contentHash":"6ca42f663e2bbd6515cd0bb4f33a196e1ba8af4b9c3aa5aad6786d3dd965b030","qualityScore":33}');
