INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('zsutxz/ClaudeLearning/github-ai-projects', 'github-ai-projects', 'zsutxz', 'ClaudeLearning', 'community', 'github-ai-projects zsutxz ClaudeLearning community The github-ai-projects skill helps developers find and analyze top AI projects on GitHub, utilizing GitHub API and search functionality with keywords like artificial intelligence and machine learning. GitHub AI 项目搜索和分析技能，帮助开发者快速找到热门 AI 项目和分析项目活跃度 GitHub AI プロジェクト検索と分析スキルは、開発者が人気の AI プロジェクトを見つけてプロジェクトの活性度を分析するのに役立ちます GitHub AI 프로젝트 검색 및 분석 스킬은 개발자가 인기 있는 AI 프로젝트를 찾고 프로젝트 활동을 분석하는 데 도움이 됩니다 Aprende a utilizar la API de GitHub para buscar proyectos de inteligencia artificial y analizar su popularidad Apprenez à utiliser l''API GitHub pour rechercher des projets d''intelligence artificielle et analyser leur popularité Lernen Sie, die GitHub-API zu nutzen, um KI-Projekte zu suchen und ihre Popularität zu analysieren O GitHub-ai-projects é uma habilidade que ajuda a encontrar projetos AI de ponta no GitHub, incluindo PyTorch, TensorFlow e Hugging Face. ИИ Агенты GitHub-ai-projects - это навык, который помогает найти передовые проекты ИИ на GitHub, включая PyTorch, TensorFlow и Hugging Face. GitHub-ai-projects هو مهارة تساعد في العثور على مشاريع الذكاء الاصطناعي الرائدة على GitHub، بما في ذلك PyTorch و TensorFlow و Hugging Face. github-ai-projects setup guide how to use github-ai-projects github-ai-projects vs github trending github-ai-projects alternative github ai project search machine learning project ideas on github install github-ai-projects github-ai-projects documentation GitHub AI 项目 AI 项目搜索 AI 项目分析 GitHub API PyTorch TensorFlow Scikit-learn 计算机视觉 NLP 强化学习 Searches GitHub projects using AI/ML keywords like artificial intelligence and machine learning Utilizes GitHub API to retrieve project information and updates Analyzes project activity and popularity based on star count and recent updates Supports filtering by popular frameworks like PyTorch and TensorFlow Provides information on emerging technologies like LLM and transformer models github-ai-projects is a skill that enables AI agents to search and retrieve information on popular AI projects hosted on GitHub, focusing on machine learning and deep learning frameworks.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('wfukatsu/architecture-redesign-agent/create-domain-story', 'community', 'wfukatsu', 'architecture-redesign-agent', 'wfukatsu/architecture-redesign-agent', 'create-domain-story', 2, 0, 33, '2026-02-21T08:07:43Z', '2026-03-06T07:06:24.459Z', 'adbfbfb00e43b426cf9eb3fef8f51d36803d6c105a075280ad65415cf44ae739', '{"id":"wfukatsu/architecture-redesign-agent/create-domain-story","name":"create-domain-story","description":{"en":"The create-domain-story skill analyzes legacy systems and refactors microservices for Claude Code, benefiting developers and system architects. It utilizes domain storytelling to visualize business processes.","zh":"create-domain-story AI 代理是基于 Claude Code 的微服务重构和领域驱动设计工具，用于分析和重构遗留系统","ja":"create-domain-story AI エージェントは、Claude Code を用いたマイクロサービスリファクタリングとドメイン駆動設計ツールであり、レガシーシステムの分析とリファクタリングを行う","ko":"create-domain-story AI 에이전트는 Claude Code 기반의 마이크로 서비스 리팩토링 및 도메인 주도 설계 도구로, 레거시 시스템의 분석 및 리팩토링을 수행합니다","es":"create-domain-story es un agente de análisis de sistemas legados y refactoring de microservicios que utiliza la técnica de Domain Storytelling para visualizar procesos de negocio","fr":"create-domain-story est un agent d''analyse de systèmes hérités et de refactoring de microservices qui utilise la technique de Domain Storytelling pour visualiser les processus métier","de":"create-domain-story ist ein Agent für die Analyse von Legacy-Systemen und das Refactoring von Microservices, der die Domain-Storytelling-Technik verwendet, um Geschäftsprozesse zu visualisieren","pt":"O agente de criação de histórias de domínio é uma ferramenta para análise de sistemas legados e refatoração de microsserviços com Claude Code, utilizando a técnica de domínio storyteller","ru":"ИИ Агент для создания истории домена - это инструмент для анализа устаревших систем и рефакторинга микросервисов с Claude Code, использующий технику домén storyteller","ar":"وكيل إنشاء قصة المجال هو أداة لتحليل الأنظمة القديمة وإعادة هيكلة الميكروسيرفس مع Claude Code، باستخدام تقنية روائي المجال"},"seo":{"title":{"en":"create-domain-story: Microservices Refactoring Setup Guid...","zh":"Create-Domain-Story Setup Guide: 基于 Claude Code 的微服务重构","ja":"create-domain-story セットアップガイド: Claude Code を用いたマイクロサービスリフ...","ko":"create-domain-story 설정 가이드: Claude Code 기반의 마이크로 서비스 리팩토링","es":"Guía de configuración de create-domain-story: Análisis de...","fr":"Guide de configuration de create-domain-story : Analyse d...","de":"Einrichtungsleitfaden für create-domain-story: Analyse vo...","pt":"Guia de Configuração do Agente de Criação de Histórias de...","ru":"ИИ Агент: Создание истории домена - Руководство по настройке","ar":"دليل إعداد وكيل إنشاء قصة المجال"},"description":{"en":"Discover how to refactor legacy systems with create-domain-story. Learn to analyze business processes and generate domain stories with this AI agent skill.","zh":"使用 create-domain-story AI 代理实现领域驱动设计和微服务重构，提高系统可维护性和可扩展性","ja":"create-domain-story AI エージェントを使用してドメイン駆動設計とマイクロサービスリファクタリングを行い、システムの保守性と拡張性を向上させる","ko":"create-domain-story AI 에이전트를 사용하여 도메인 주도 설계 및 마이크로 서비스 리팩토링을 구현하여 시스템의 유지 보수성과 확장성을 향상시킵니다","es":"Descubre cómo create-domain-story utiliza la técnica de Domain Storytelling para analizar sistemas legados y refactorizar microservicios de manera eficiente","fr":"Découvrez comment create-domain-story utilise la technique de Domain Storytelling pour analyser les systèmes hérités et refactoriser les microservices de man...","de":"Erfahren Sie, wie create-domain-story die Domain-Storytelling-Technik verwendet, um Legacy-Systeme zu analysieren und Microservices effizient zu refactorieren","pt":"Aprenda a configurar o agente de criação de histórias de domínio para análise de sistemas legados e refatoração de microsserviços com Claude Code","ru":"Изучите, как настроить ИИ Агент для создания истории домена, анализа устаревших систем и рефакторинга микросервисов с Claude Code","ar":"تعرف على كيفية إعداد وكيل إنشاء قصة المجال لتحليل الأنظمة القديمة وإعادة هيكلة الميكروسيرفس مع Claude Code"},"definition":{"en":"create-domain-story is a legacy system analysis and microservices refactoring agent system that uses domain storytelling to organize business processes into narrative formats.","zh":"create-domain-story 是一种基于领域驱动设计的 AI 代理，用于分析和重构遗留系统","ja":"create-domain-story は、ドメイン駆動設計に基づく AI エージェントであり、レガシーシステムの分析とリファクタリングを行う","ko":"create-domain-story는 도메인 주도 설계에 기반한 AI 에이전트로, 레거시 시스템의 분석 및 리팩토링을 수행합니다","es":"create-domain-story es una herramienta de análisis de sistemas legados y refactoring de microservicios que utiliza la técnica de Domain Storytelling","fr":"create-domain-story est un outil d''analyse de systèmes hérités et de refactoring de microservices qui utilise la technique de Domain Storytelling","de":"create-domain-story ist ein Tool für die Analyse von Legacy-Systemen und das Refactoring von Microservices, das die Domain-Storytelling-Technik verwendet","pt":"O que é um agente de criação de histórias de domínio? É uma ferramenta que utiliza a técnica de domínio storyteller para analisar sistemas legados","ru":"Что такое ИИ Агент для создания истории домена? Это инструмент, использующий технику домén storyteller для анализа устаревших систем","ar":"ما هو وكيل إنشاء قصة المجال؟ هو أداة تستخدم تقنية روائي المجال لتحليل الأنظمة القديمة"},"features":{"en":["Utilizes domain storytelling to visualize business processes","Identifies actors, work items, and activities in business processes","Generates reports in Markdown format, including bounded-contexts-redesign.md and ubiquitous-language.md","Integrates with /ddd-redesign and /analyze-system outputs","Organizes domain knowledge into narrative structures using tables and icons"],"zh":["支持领域驱动设计","基于 Claude Code 的微服务重构","分析和重构遗留系统","使用领域故事讲述法来可视化业务流程","输出 bounded-contexts-redesign 和 ubiquitous-language 报告"],"ja":["ドメイン駆動設計をサポート","Claude Code を用いたマイクロサービスリファクタリング","レガシーシステムの分析とリファクタリング","ドメインストーリーテリング手法を使用してビジネスプロセスを可視化","bounded-contexts-redesign と ubiquitous-language レポートを出力"],"ko":["도메인 주도 설계를 지원","Claude Code 기반의 마이크로 서비스 리팩토링","레거시 시스템의 분석 및 리팩토링","도메인 스토리 텔링 방법을 사용하여 비즈니스 프로세스를 시각화","bounded-contexts-redesign 및 ubiquitous-language 보고서 출력"],"es":["Análisis de sistemas legados utilizando la técnica de Domain Storytelling","Refactoring de microservicios para mejorar la eficiencia","Visualización de procesos de negocio mediante la identificación de actores, work items y actividades","Generación de informes de diseño y análisis de sistemas","Integración con herramientas de análisis de sistemas y refactoring de microservicios"],"fr":["Analyse de systèmes hérités à l''aide de la technique de Domain Storytelling","Refactoring de microservices pour améliorer l''efficacité","Visualisation des processus métier grâce à l''identification d''acteurs, d''éléments de travail et d''activités","Génération de rapports de conception et d''analyse de systèmes","Intégration avec des outils d''analyse de systèmes et de refactoring de microservices"],"de":["Analyse von Legacy-Systemen mithilfe der Domain-Storytelling-Technik","Refactoring von Microservices zur Effizienzsteigerung","Visualisierung von Geschäftsprozessen durch die Identifizierung von Akteuren, Arbeitsobjekten und Aktivitäten","Erstellung von Design- und Analyseberichten für Systeme","Integration mit Tools für die Analyse von Systemen und das Refactoring von Microservices"],"pt":["Análise de sistemas legados com técnica de domínio storyteller","Refatoração de microsserviços com Claude Code","Utilização de elementos como Ator, Work Item e Atividade","Geração de relatórios de redesign de contextos limitados","Integração com outputs de análise de sistema"],"ru":["Анализ устаревших систем с помощью техники домén storyteller","Рефакторинг микросервисов с Claude Code","Использование элементов, таких как Актор, Work Item и Активность","Генерация отчётов по переработке ограниченных контекстов","Интеграция с результатами анализа системы"],"ar":["تحليل الأنظمة القديمة باستخدام تقنية روائي المجال","إعادة هيكلة الميكروسيرفس مع Claude Code","استخدام عناصر مثل الممثل والعنصر العمل والنشاط","توليد تقارير إعادة تصميم السياقات المحدودة","التكامل مع مخرجات تحليل النظام"]},"keywords":{"en":["how to use create-domain-story","create-domain-story setup guide","domain storytelling techniques","microservices refactoring tools","legacy system analysis methods","create-domain-story vs ddd-redesign","install create-domain-story","create-domain-story alternative"],"zh":["create-domain-story","AI 代理","领域驱动设计","微服务重构","遗留系统分析","Claude Code","领域故事讲述法"],"ja":["create-domain-story","AI エージェント","ドメイン駆動設計","マイクロサービスリファクタリング","レガシーシステム分析","Claude Code","ドメインストーリーテリング"],"ko":["create-domain-story","AI 에이전트","도메인 주도 설계","마이크로 서비스 리팩토링","레거시 시스템 분석","Claude Code","도메인 스토리 텔링"],"es":["create-domain-story","análisis de sistemas legados","refactoring de microservicios","Domain Storytelling","visualización de procesos de negocio","herramientas de análisis de sistemas","refactoring de microservicios","diseño de sistemas","informes de análisis de sistemas"],"fr":["create-domain-story","analyse de systèmes hérités","refactoring de microservices","Domain Storytelling","visualisation des processus métier","outils d''analyse de systèmes","refactoring de microservices","conception de systèmes","rapports d''analyse de systèmes"],"de":["create-domain-story","Analyse von Legacy-Systemen","Refactoring von Microservices","Domain-Storytelling","Visualisierung von Geschäftsprozessen","Tools für die Analyse von Systemen","Refactoring von Microservices","Systemdesign","Analyseberichte für Systeme"],"pt":["agente de criação de histórias de domínio","análise de sistemas legados","refatoração de microsserviços","Claude Code","domínio storyteller","técnica de domínio storyteller","análise de sistema","refatoração de código"],"ru":["ИИ Агент для создания истории домена","анализ устаревших систем","рефакторинг микросервисов","Claude Code","домén storyteller","техника домén storyteller","анализ системы","рефакторинг кода"],"ar":["وكيل إنشاء قصة المجال","تحليل الأنظمة القديمة","إعادة هيكلة الميكروسيرفس","Claude Code","روائي المجال","تقنية روائي المجال","تحليل النظام","إعادة هيكلة الكود"]}},"owner":"wfukatsu","repo":"architecture-redesign-agent","repoPath":"wfukatsu/architecture-redesign-agent","stars":2,"forks":0,"updatedAt":"2026-02-21T08:07:43Z","topics":[],"category":"community","skillMd":{"name":"create-domain-story","description":"ドメインストーリーテリングエージェント - ドメインストーリーの作成、ビジネスプロセスの可視化。/create-domain-story --domain=[ドメイン名] で呼び出し。","bodyPreview":"# Domain Storyteller Agent\n\nドメインストーリーテリング手法を用いて、各ドメインのビジネスプロセスを物語形式で整理するエージェントです。\n\n## 概要\n\nドメインストーリーテリングは、ビジネスプロセスの暗黙知を引き出し、可視化する手法です。以下の3つの要素で物語を構成します：\n\n| 要素 | 説明 | 表記 |\n|-----|------|-----|\n| **アクター** | 登場人物（人、役割、システム） | 人型アイコン |\n| **ワークアイテム** | 扱うモノや情報 | 長方形 |\n| **アクティビティ** | 実行する行動 | 矢印とラベル |\n\n## 前提条件\n\n**推奨（/ddd-redesign の出力）:**\n- `reports/03_design/bounded-contexts-redesign.md` - 境界コンテキスト再設計\n\n**推奨（/analyze-system の出力）:**\n- `reports/01_analysis/ubiquitous-language.md` - ユビキタス言語集\n- `reports/01","body":"# Domain Storyteller Agent\n\nドメインストーリーテリング手法を用いて、各ドメインのビジネスプロセスを物語形式で整理するエージェントです。\n\n## 概要\n\nドメインストーリーテリングは、ビジネスプロセスの暗黙知を引き出し、可視化する手法です。以下の3つの要素で物語を構成します：\n\n| 要素 | 説明 | 表記 |\n|-----|------|-----|\n| **アクター** | 登場人物（人、役割、システム） | 人型アイコン |\n| **ワークアイテム** | 扱うモノや情報 | 長方形 |\n| **アクティビティ** | 実行する行動 | 矢印とラベル |\n\n## 前提条件\n\n**推奨（/ddd-redesign の出力）:**\n- `reports/03_design/bounded-contexts-redesign.md` - 境界コンテキスト再設計\n\n**推奨（/analyze-system の出力）:**\n- `reports/01_analysis/ubiquitous-language.md` - ユビキタス言語集\n- `reports/01_analysis/actors-roles-permissions.md` - アクター・ロール・権限\n\n## 出力先\n\n結果は `reports/04_stories/` に出力します。\n**重要**: 各ステップ完了時に即座にファイルを出力してください。\n\n## 実行モード\n\n### インタラクティブモード（推奨）\n\nユーザーとの対話を通じてストーリーを引き出します。AskUserQuestionツールを活用して、以下の7段階のプロセスで進行します。\n\n### 自動生成モード\n\n既存の分析結果からストーリーを自動生成します。精度は低下しますが、大量のドメインを効率的に処理できます。\n\n## 7段階のファシリテーションプロセス\n\n### Stage 1: 舞台設定（Context Setting）\n\n**目的**: ストーリーのスコープを決定する\n\n**質問例**:\n- 「どのビジネスプロセスについて話しましょうか？」\n- 「このプロセスはどこから始まり、どこで終わりますか？」\n- 「主な目的は何ですか？」\n\n```\nAskUserQuestion を使用して以下を確認：\n- 対象プロセス名\n- 開始点と終了点\n- 主要な目的\n```\n\n### Stage 2: 物語開始（Story Opening）\n\n**目的**: 最初のアクターと行動を特定する\n\n**質問例**:\n- 「このプロセスを始めるのは誰ですか？」\n- 「最初に何をしますか？」\n- 「何を使って/何に対して行いますか？」\n\n```markdown\n## 最初のシーン\n\n**アクター**: [誰が]\n**アクティビティ**: [何をする]\n**ワークアイテム**: [何を/何に対して]\n```\n\n### Stage 3: 展開（Story Development）\n\n**目的**: 時系列でアクティビティの連鎖を追跡する\n\n**質問例**:\n- 「次に何が起こりますか？」\n- 「それを受けて誰が動きますか？」\n- 「どんな情報が渡されますか？」\n\n```markdown\n## シーン [N]\n\n**前提**: [前のシーンからの引き継ぎ]\n**アクター**: [誰が]\n**アクティビティ**: [何をする]\n**ワークアイテム**: [何を/何に対して]\n**結果**: [次のシーンへの引き継ぎ]\n```\n\n### Stage 4: 確認（Confirmation）\n\n**目的**: 整理した内容をレビューする\n\n**確認事項**:\n- 抜け漏れがないか\n- 順序は正しいか\n- 用語は適切か\n\n### Stage 5: 例外検討（Exception Handling）\n\n**目的**: うまくいかないパターンを確認する\n\n**質問例**:\n- 「このステップが失敗したらどうなりますか？」\n- 「データが不正だった場合は？」\n- 「システムが応答しない場合は？」\n\n```markdown\n## 例外シナリオ\n\n### [例外名1]\n**トリガー**: [何が起こると]\n**対応**: [どう対処する]\n**復帰**: [どう正常フローに戻る]\n\n### [例外名2]\n...\n```\n\n### Stage 6: 可視化（Visualization）\n\n**目的**: Mermaidコードでプロセス図を生成する\n\n```mermaid\nsequenceDiagram\n    actor Actor1 as [アクター1]\n    actor Actor2 as [アクター2]\n    participant System as [システム]\n\n    Actor1->>System: [アクティビティ1]\n    System-->>Actor2: [アクティビティ2]\n    Note over System: [補足説明]\n```\n\n### Stage 7: クロージング（Closing）\n\n**目的**: 調整確認と終了判断\n\n**確認事項**:\n- 追加したいシナリオはあるか\n- 用語の定義は明確か\n- 次に掘り下げるべきプロセスはあるか\n\n### Stage 8: Mermaid図の検証\n\n出力したファイルのMermaid図を検証し、エラーがあれば修正：\n\n```bash\n/fix-mermaid ./reports/04_stories\n```\n\n## 出力フォーマット\n\n### [domain]_story.md\n\nドメインストーリー（概要、登場人物、ワークアイテム、メインストーリー、ストーリーフロー図、例外シナリオ、業務ルール一覧、ドメインイベント、用語集、関連ストーリー、改善提案、メタデータ）\n\n## インタラクティブモードの実装\n\n```javascript\n// ファシリテーションの疑似コード\nasync function facilitateDomainStory(domainName) {\n    // Stage 1: 舞台設定\n    const context = await askUser({\n        questions: [\n            {\n                question: \"どのビジネスプロセスについて話しますか？\",\n                header: \"プロセス\",\n                options: [\n                    { label: \"注文処理\", description: \"顧客からの注文を処理するプロセス\" },\n                    { label: \"在庫管理\", description: \"商品在庫を管理するプロセス\" },\n                    { label: \"顧客対応\", description: \"顧客からの問い合わせ対応\" }\n                ]\n            }\n        ]\n    });\n\n    // Stage 2-6: ストーリー構築\n    const story = await buildStory(context);\n\n    // Stage 7: クロージング\n    const confirmation = await confirmStory(story);\n\n    // 出力\n    await writeStoryFile(domainName, story);\n}\n```\n\n## 自動生成モードの実装\n\n既存の分析結果から推論：\n\n1. **アクター抽出**\n   - `actors-roles-permissions.md` から人間アクター\n   - `system-overview.md` からシステムアクター\n\n2. **ワークアイテム抽出**\n   - `ubiquitous-language.md` からエンティティ\n   - `domain-code-mapping.md` からデータオブジェクト\n\n3. **アクティビティ推論**\n   - API定義からCRUD操作を特定\n   - イベント定義からビジネスアクションを特定\n\n4. **ストーリー構築**\n   - ユースケースの順序を推論\n   - 依存関係からフローを構築\n\n## ツール活用\n\n### 対話的な情報収集\n\n```\nAskUserQuestion でユーザーから情報を収集\n```\n\n### 既存情報の読み取り\n\n```\nRead で中間ファイルを読み込み\nmcp__serena__find_symbol でコードからメソッドを特定\n```\n\n### 図の生成\n\n- Mermaid sequence diagram を使用\n- 複雑な場合は複数の図に分割\n\n## ベストプラクティス\n\n### Do''s\n- ビジネス用語を使用（技術用語を避ける）\n- 具体的なシナリオで説明\n- 例外ケースも必ず確認\n- 図と文章の両方で表現\n\n### Don''ts\n- 実装詳細に踏み込まない\n- 仮定で進めない（必ず確認）\n- 複雑すぎる図を作らない\n- 専門用語を説明なしで使わない\n\n## エラーハンドリング\n\n- ドメインエキスパートが不在 → 既存ドキュメント・コードから推測（精度低下を警告）\n- ストーリーが複雑すぎる場合 → サブプロセスに分割を提案\n- ユビキタス言語が未定義 → `/analyze-system` の先行実行を案内\n- Mermaid図の構文エラー → `/fix-mermaid` で修正\n\n## 関連スキル\n\n| スキル | 用途 |\n|-------|-----|\n| `/analyze-system` | ユビキタス言語・アクター抽出（入力） |\n| `/ddd-redesign` | DDD再設計（次ステップ） |\n| `/map-domains` | ドメインマッピング（補完） |\n| `/build-graph` | ナレッジグラフ構築（出力活用） |\n"},"lastSynced":"2026-03-06T07:06:24.459Z","agentAnalysis":{"suitability":{"en":"Perfect for System Architecture Agents needing advanced domain storytelling and microservice refactoring capabilities.","zh":"非常适合需要高级领域故事讲述和微服务重构能力的系统架构代理。","ja":"システムアーキテクチャエージェントが高度なドメインストーリーテリングとマイクロサービス再構成機能を必要とする場合に最適です。","ko":"시스템 아키텍처 에이전트가 고급 도메인 스토리 텔링과 마이크로 서비스 리팩토링 기능을 필요로 할 때 완벽합니다.","es":"Perfecto para agentes de Arquitectura de Sistemas que necesitan capacidades de narración de dominio avanzadas y refactorización de microservicios.","fr":"Parfait pour les agents d''Architecture de Systèmes ayant besoin de capacités de narration de domaine avancées et de refactorisation de microservices.","de":"Perfekt für Systemarchitektur-Agents, die erweiterte Domänen-Geschichtenerzählung und Microservice-Refactoring-Fähigkeiten benötigen.","pt":"Perfeito para Agentes de Arquitetura de Sistema que necessitam de capacidades avançadas de narração de domínio e refatoração de microsserviços.","ru":"Идеально подходит для агентов системной архитектуры, которым необходимы продвинутые возможности повествования в области и рефакторинга микросервисов.","ar":"مثالي لعمليات وكلاء الهيكل النظامي الذين يحتاجون إلى قدرات متقدمة في رواية القصص في المجال وإعادة هيكلة الخدمات الدقيقة."},"recommendation":{"en":"Empowers agents to visualize business processes using domain storytelling, refactoring microservices for Claude Code, and leveraging ubiquitous language to create bounded context redesigns in Markdown format.","zh":"赋予代理以领域故事讲述可视化业务流程、为 Claude Code 重构微服务以及利用无处不在的语言以 Markdown 格式创建有界上下文重新设计的能力。","ja":"エージェントにビジネスプロセスをドメインストーリーテリングで可視化し、Claude Code のマイクロサービスをリファクタリングし、Markdown 形式で境界付きコンテキストの再設計を作成するために、汎用的な言語を利用する機能を提供します。","ko":"에이전트가 도메인 스토리 텔링으로 비즈니스 프로세스를 시각화하고, Claude Code를 위한 마이크로 서비스를 리팩토링하고, Markdown 형식으로 경계 있는 컨텍스트 재설계를 생성하기 위해 유비쿼터스 언어를 활용하는 기능을 제공합니다.","es":"Habilita a los agentes a visualizar procesos comerciales mediante la narración de dominio, la refactorización de microservicios para Claude Code y la utilización de lenguaje ubicuo para crear rediseños de contexto limitado en formato Markdown.","fr":"Permet aux agents de visualiser les processus métier à l''aide de la narration de domaine, de la refactorisation de microservices pour Claude Code et de l''utilisation de langage ubiquitaire pour créer des révisions de contexte limité au format Markdown.","de":"Ermächtigt Agenten, Geschäftsprozesse mithilfe von Domänen-Geschichtenerzählung zu visualisieren, Microservices für Claude Code zu refaktorisieren und ubiquitäres Sprachverständnis zu nutzen, um begrenzte Kontext-Neugestaltungen im Markdown-Format zu erstellen.","pt":"Habilita os agentes a visualizar processos de negócios usando narração de domínio, refatoração de microsserviços para Claude Code e aproveitando a linguagem onipresente para criar redesenho de contextos limitados no formato Markdown.","ru":"Наделяет агентов возможностью визуализировать бизнес-процессы с помощью повествования в области, рефакторинга микросервисов для Claude Code и использования повсеместного языка для создания редизайна ограниченных контекстов в формате Markdown.","ar":"تمكّن الوكلاء من تصور العمليات التجارية باستخدام رواية القصص في المجال، وإعادة هيكلة الخدمات الدقيقة لصالح Claude Code، وتفعيل اللغة الشاملة لإنشاء تصميمات إعادة الصياغة للمواضيع المحددة بالتنسيق Markdown."},"useCases":{"en":["Refactoring legacy systems into modular microservices for Claude Code","Generating domain stories to visualize complex business processes","Creating bounded context redesigns using ubiquitous language and Markdown reports"],"zh":["将遗留系统重构为 Claude Code 的模块化微服务","生成领域故事以可视化复杂的业务流程","使用无处不在的语言和 Markdown 报表创建有界上下文重新设计"],"ja":["レガシーシステムを Claude Code のモジュラーマイクロサービスにリファクタリングする","複雑なビジネスプロセスを可視化するためのドメインストーリーを生成する","汎用的な言語と Markdown レポートを使用して境界付きコンテキストの再設計を作成する"],"ko":["레거시 시스템을 Claude Code의 모듈화된 마이크로 서비스로 리팩토링하는 것","복잡한 비즈니스 프로세스를 시각화하기 위한 도메인 스토리를 생성하는 것","유비쿼터스 언어와 Markdown 보고서를 사용하여 경계 있는 컨텍스트 재설계를 생성하는 것"],"es":["Refactorización de sistemas heredados en microservicios modulares para Claude Code","Generación de historias de dominio para visualizar procesos comerciales complejos","Creación de rediseños de contexto limitado utilizando lenguaje ubicuo e informes en formato Markdown"],"fr":["Refactorisation de systèmes hérités en microservices modulaires pour Claude Code","Génération d''histoires de domaine pour visualiser les processus métier complexes","Création de révisions de contexte limité en utilisant le langage ubiquitaire et les rapports au format Markdown"],"de":["Refaktorisierung von Legacy-Systemen in modulare Microservices für Claude Code","Erzeugung von Domänen-Geschichten zur Visualisierung komplexer Geschäftsprozesse","Erstellung von begrenzten Kontext-Neugestaltungen unter Verwendung von ubiquitärem Sprachverständnis und Markdown-Berichten"],"pt":["Refatoração de sistemas legados em microsserviços modulares para Claude Code","Geração de histórias de domínio para visualizar processos de negócios complexos","Criação de redesenho de contextos limitados usando linguagem onipresente e relatórios no formato Markdown"],"ru":["Рефакторинг устаревших систем в модульные микросервисы для Claude Code","Генерация историй области для визуализации сложных бизнес-процессов","Создание редизайна ограниченных контекстов с помощью повсеместного языка и отчетов в формате Markdown"],"ar":["إعادة هيكلة الأنظمة القديمة إلى خدمات دقيقة متعددة لصالح Claude Code","توليد قصص المجال لتصور العمليات التجارية المعقدة","إنشاء تصميمات إعادة الصياغة للمواضيع المحددة باستخدام اللغة الشاملة وتقارير بالتنسيق Markdown"]},"limitations":{"en":["Requires output from /ddd-redesign and /analyze-system","Specifically designed for Claude Code and domain storytelling methodology"],"zh":["需要 /ddd-redesign 和 /analyze-system 的输出","专门为 Claude Code 和领域故事讲述方法论设计"],"ja":["/ddd-redesign と /analyze-system の出力を必要とする","Claude Code とドメインストーリーテリングの方法論のために特別に設計されている"],"ko":["/ddd-redesign 및 /analyze-system의 출력이 필요함","Claude Code 및 도메인 스토리 텔링 방법론을 위한 특별한 설계"],"es":["Requiere la salida de /ddd-redesign y /analyze-system","Diseñado específicamente para Claude Code y la metodología de narración de dominio"],"fr":["Nécessite la sortie de /ddd-redesign et /analyze-system","Conçu spécifiquement pour Claude Code et la méthodologie de narration de domaine"],"de":["Benötigt die Ausgabe von /ddd-redesign und /analyze-system","Speziell für Claude Code und die Domänen-Geschichtenerzählungsmethode entwickelt"],"pt":["Exige saída de /ddd-redesign e /analyze-system","Projetado especificamente para Claude Code e metodologia de narração de domínio"],"ru":["Требует вывода из /ddd-redesign и /analyze-system","Спецально разработан для Claude Code и методологии повествования в области"],"ar":["يتطلب إخراج من /ddd-redesign و /analyze-system","صمم خصيصًا لصالح Claude Code ومنهجية رواية القصص في المجال"]},"version":4},"contentHash":"adbfbfb00e43b426cf9eb3fef8f51d36803d6c105a075280ad65415cf44ae739","qualityScore":33}');
