INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('wfukatsu/architecture-redesign-agent/create-domain-story', 'create-domain-story', 'wfukatsu', 'architecture-redesign-agent', 'community', 'create-domain-story wfukatsu architecture-redesign-agent community The create-domain-story skill analyzes legacy systems and refactors microservices for Claude Code, benefiting developers and system architects. It utilizes domain storytelling to visualize business processes. create-domain-story AI 代理是基于 Claude Code 的微服务重构和领域驱动设计工具，用于分析和重构遗留系统 create-domain-story AI エージェントは、Claude Code を用いたマイクロサービスリファクタリングとドメイン駆動設計ツールであり、レガシーシステムの分析とリファクタリングを行う create-domain-story AI 에이전트는 Claude Code 기반의 마이크로 서비스 리팩토링 및 도메인 주도 설계 도구로, 레거시 시스템의 분석 및 리팩토링을 수행합니다 create-domain-story es un agente de análisis de sistemas legados y refactoring de microservicios que utiliza la técnica de Domain Storytelling para visualizar procesos de negocio create-domain-story est un agent d''analyse de systèmes hérités et de refactoring de microservices qui utilise la technique de Domain Storytelling pour visualiser les processus métier create-domain-story ist ein Agent für die Analyse von Legacy-Systemen und das Refactoring von Microservices, der die Domain-Storytelling-Technik verwendet, um Geschäftsprozesse zu visualisieren O agente de criação de histórias de domínio é uma ferramenta para análise de sistemas legados e refatoração de microsserviços com Claude Code, utilizando a técnica de domínio storyteller ИИ Агент для создания истории домена - это инструмент для анализа устаревших систем и рефакторинга микросервисов с Claude Code, использующий технику домén storyteller وكيل إنشاء قصة المجال هو أداة لتحليل الأنظمة القديمة وإعادة هيكلة الميكروسيرفس مع Claude Code، باستخدام تقنية روائي المجال how to use create-domain-story create-domain-story setup guide domain storytelling techniques microservices refactoring tools legacy system analysis methods create-domain-story vs ddd-redesign install create-domain-story create-domain-story alternative create-domain-story AI 代理 领域驱动设计 微服务重构 遗留系统分析 Claude Code 领域故事讲述法 Utilizes domain storytelling to visualize business processes Identifies actors, work items, and activities in business processes Generates reports in Markdown format, including bounded-contexts-redesign.md and ubiquitous-language.md Integrates with /ddd-redesign and /analyze-system outputs Organizes domain knowledge into narrative structures using tables and icons create-domain-story is a legacy system analysis and microservices refactoring agent system that uses domain storytelling to organize business processes into narrative formats.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('zorgentech/archon/create-adr', 'community', 'zorgentech', 'archon', 'zorgentech/archon', 'create-adr', 1, 0, 33, '2026-02-23T01:21:59Z', '2026-03-06T07:11:17.715Z', 'e8c275ce41665941fe3627a605b041ce664f1d6e4ab01fa0c39c37602eeb7686', '{"id":"zorgentech/archon/create-adr","name":"create-adr","description":{"en":"The create-adr skill generates Architecture Decision Records (ADRs) for projects, accepting PR numbers, textual descriptions, or interactive mode. It saves ADRs in docs/adr/potential-adr/ for review.","zh":"create-adr 是一个自动创建架构决策记录的 AIエージェント，支持 PR 号、文本描述和交互模式","ja":"create-adr は、アーキテクチャ決定レコードを自動作成する AIエージェントで、PR 番号、テキスト描述、インタラクティブモードをサポートします","ko":"create-adr는 아키텍처 결정 기록을 자동 생성하는 AI 에이전트로, PR 번호, 텍스트 설명, 상호작용 모드를 지원합니다","es":"Create-adr es una herramienta que permite a los desarrolladores crear registros de decisión de arquitectura de manera eficiente. Se integra con PR y análisis de texto","fr":"Create-adr est un outil qui permet aux développeurs de créer des enregistrements de décision d''architecture de manière efficace. Il s''intègre avec PR et l''analyse de texte","de":"Create-adr ist ein Tool, das es Entwicklern ermöglicht, Architektur-Entscheidungsregister effizient zu erstellen. Es integriert sich mit PR und Textanalyse","pt":"O create-adr é uma ferramenta que ajuda a criar registros de decisões de arquitetura, aceitando números de PR, descrições textuais ou modo interativo.","ru":"create-adr - это инструмент, который помогает создавать записи об архитектурных решениях, принимая номера PR, текстовые описания или интерактивный режим.","ar":"create-adr هو أداة تساعد في إنشاء سجلات قرارات الهندسة المعمارية، وقبول أرقام الطلبات، وصفات نصية أو وضع التفاعل."},"seo":{"title":{"en":"create-adr: Architecture Decision Record Setup Guide | AI...","zh":"create-adr Setup Guide: 自动创建架构决策记录","ja":"create-adr セットアップガイド: アーキテクチャ決定レコードの自動作成","ko":"create-adr 설정 가이드: 아키텍처 결정 기록 자동 생성","es":"Guía de configuración de create-adr para registros de dec...","fr":"Configurer create-adr pour les enregistrements de décisio...","de":"Einrichtungsleitfaden für create-adr zur Erstellung von A...","pt":"Guia de Configuração do create-adr: Crie Registros de Dec...","ru":"Настройка create-adr: Руководство по созданию записей об ...","ar":"دليل إعداد create-adr: إنشاء سجلات قرارات الهندسة المعمار..."},"description":{"en":"Streamline your project''s architecture decisions with create-adr. Learn how to automate ADR documentation and review processes. Get started now!","zh":"使用 create-adr AIエージェント自动创建架构决策记录，提高项目开发效率","ja":"create-adr AIエージェントを使用してアーキテクチャ決定レコードを自動作成し、プロジェクト開発の効率を向上させる","ko":"create-adr AI 에이전트를 사용하여 아키텍처 결정 기록을 자동 생성하고 프로젝트 개발 효율을 높여보세요","es":"Aprende a crear registros de decisión de arquitectura con create-adr, una herramienta de agente de inteligencia artificial para desarrolladores","fr":"Découvrez comment créer des enregistrements de décision d''architecture avec create-adr, un outil d''agent d''intelligence artificielle pour les développeurs","de":"Erfahren Sie, wie Sie Architektur-Entscheidungsregister mit create-adr erstellen, einem Tool für intelligente Agenten für Entwickler","pt":"Aprenda a criar registros de decisões de arquitetura com o create-adr. Descubra como automatizar a análise de mudanças e revisar propostas de arquitetura.","ru":"Узнайте, как создать записи об архитектурных решениях с помощью create-adr. Откройте для себя, как автоматизировать анализ изменений и проверять предложения ...","ar":"تعرف على كيفية إنشاء سجلات قرارات الهندسة المعمارية باستخدام create-adr. اكتشف كيفية توفير وقتك في تحليل التغييرات ومراجعة المقترحات المعمارية باستخدام أدوات..."},"definition":{"en":"create-adr is an AI agent skill that automates the creation of Architecture Decision Records (ADRs) for project documentation and review","zh":"create-adr 是一种自动创建架构决策记录的工具，用于记录项目开发中的架构决策","ja":"create-adr は、アーキテクチャ決定レコードを自動作成するツールで、プロジェクト開発中のアーキテクチャ決定を記録するために使用されます","ko":"create-adr는 아키텍처 결정 기록을 자동 생성하는 도구로, 프로젝트 개발 중 아키텍처 결정 사항을 기록하는데 사용됩니다","es":"Create-adr es una herramienta de agente de inteligencia artificial que crea registros de decisión de arquitectura","fr":"Create-adr est un outil d''agent d''intelligence artificielle qui crée des enregistrements de décision d''architecture","de":"Create-adr ist ein Tool für intelligente Agenten, das Architektur-Entscheidungsregister erstellt","pt":"O create-adr é uma ferramenta de criação de registros de decisões de arquitetura que documenta decisões arquiteturais do projeto.","ru":"create-adr - это инструмент создания записей об архитектурных решениях, который документирует архитектурные решения проекта.","ar":"create-adr هو أداة لإنشاء سجلات قرارات الهندسة المعمارية التي توثق قرارات الهندسة المعمارية للمشروع."},"features":{"en":["Generates ADR documents based on PR numbers or textual descriptions","Supports interactive mode for custom ADR creation","Saves ADRs in docs/adr/potential-adr/ with ''proposto'' status for review","Automates workflow based on $ARGUMENTS type (PR number or text)","Integrates with project documentation for seamless ADR management"],"zh":["支持 PR 号自动分析","支持文本描述和交互模式","自动创建架构决策记录","保存记录到 docs/adr/potential-adr/ 目录","记录状态为 \"提案\" 以待审批"],"ja":["PR 番号の自動分析をサポート","テキスト描述とインタラクティブモードをサポート","アーキテクチャ決定レコードを自動作成","レコードを docs/adr/potential-adr/ ディレクトリに保存","レコード状態を \"提案\" に設定して審批待ち"],"ko":["PR 번호 자동 분석 지원","텍스트 설명과 상호작용 모드 지원","아키텍처 결정 기록 자동 생성","기록을 docs/adr/potential-adr/ 디렉토리에 저장","기록 상태를 \"제안\"으로 설정하여 승인 대기"],"es":["Crea registros de decisión de arquitectura de manera automática","Integración con PR para análisis de cambios","Análisis de texto para descripciones de decisión","Registro de decisión con status ''proposto'' para revisión","Almacenamiento en docs/adr/potential-adr/"],"fr":["Crée des enregistrements de décision d''architecture de manière automatique","Intégration avec PR pour analyse de changements","Analyse de texte pour descriptions de décision","Enregistrement de décision avec status ''proposto'' pour révision","Stockage dans docs/adr/potential-adr/"],"de":["Erstellt Architektur-Entscheidungsregister automatisch","Integration mit PR für Änderungsanalyse","Textanalyse für Entscheidungsbeschreibungen","Entscheidungsregister mit Status ''proposto'' für Überprüfung","Speicherung in docs/adr/potential-adr/"],"pt":["Criação de registros de decisões de arquitetura","Análise automática de mudanças com base em números de PR","Modo interativo para revisar propostas de arquitetura","Suporte a descrições textuais para registros de decisões","Salva registros em `docs/adr/potential-adr/` com status ''proposto''"],"ru":["Создание записей об архитектурных решениях","Автоматический анализ изменений на основе номеров PR","Интерактивный режим для проверки предложений по архитектуре","Поддержка текстовых описаний для записей об архитектурных решениях","Сохранение записей в `docs/adr/potential-adr/` со статусом ''предложено''"],"ar":["إنشاء سجلات قرارات الهندسة المعمارية","تحليل تلقائي للتغييرات على أساس أرقام الطلبات","وضع التفاعل لمراجعة المقترحات المعمارية","دعم الوصف النصي لسجلات قرارات الهندسة المعمارية","حفظ السجلات في `docs/adr/potential-adr/` بالحالة ''مقترح''"]},"keywords":{"en":["create-adr setup guide","what is create-adr","how to use create-adr","create-adr alternative","create-adr vs architecture decision record tools","install create-adr","create-adr documentation","adr automation","architecture decision record best practices"],"zh":["create-adr","AIエージェント","架构决策记录","自动创建","PR 号分析","文本描述","交互模式","docs/adr/potential-adr/"],"ja":["create-adr","AIエージェント","アーキテクチャ決定レコード","自動作成","PR 番号分析","テキスト描述","インタラクティブモード","docs/adr/potential-adr/"],"ko":["create-adr","AI 에이전트","아키텍처 결정 기록","자동 생성","PR 번호 분석","텍스트 설명","상호작용 모드","docs/adr/potential-adr/"],"es":["create-adr","registros de decisión de arquitectura","herramientas de agente de inteligencia artificial","desarrollo de software","análisis de texto","integración con PR","automatización de registros"],"fr":["create-adr","enregistrements de décision d''architecture","outils d''agent d''intelligence artificielle","développement de logiciels","analyse de texte","intégration avec PR","automatisation d''enregistrements"],"de":["create-adr","Architektur-Entscheidungsregister","Tools für intelligente Agenten","Softwareentwicklung","Textanalyse","Integration mit PR","Automatisierung von Registern"],"pt":["create-adr","registros de decisões de arquitetura","análise de mudanças","revisão de propostas de arquitetura","desenvolvimento de software","ferramentas de desenvolvimento","criação de registros de decisões"],"ru":["create-adr","записи об архитектурных решениях","анализ изменений","проверка предложений по архитектуре","разработка программного обеспечения","инструменты разработки","создание записей об архитектурных решениях","ИИ Агенты"],"ar":["create-adr","سجلات قرارات الهندسة المعمارية","تحليل التغييرات","مراجعة المقترحات المعمارية","تطوير البرمجيات","أدوات التطوير","إنشاء سجلات قرارات الهندسة المعمارية","أدوات الذكاء الاصطناعي"]}},"owner":"zorgentech","repo":"archon","repoPath":"zorgentech/archon","stars":1,"forks":0,"updatedAt":"2026-02-23T01:21:59Z","topics":[],"category":"community","skillMd":{"name":"create-adr","description":"Creates an Architecture Decision Record (ADR) from PR changes or a manually described architectural decision. Use when a PR introduces a significant architectural choice that requires documentation, or when a standalone decision needs to be captured.","bodyPreview":"<objective>\nCria um Architecture Decision Record (ADR) documentando decisoes arquiteturais do projeto. Aceita um numero de PR para analise automatica das mudancas, uma descricao textual, ou modo interativo. O ADR e salvo em `docs/adr/potential-adr/` com status \"proposto\" para revisao antes de aprovacao.\n</objective>\n\n<quick_start>\nDispatch com base no tipo de `$ARGUMENTS`:\n- Se `$ARGUMENTS` for um numero, trate como PR e siga o workflow a partir do Step 2 (branch PR).\n- Se `$ARGUMENTS` for texto","body":"<objective>\nCria um Architecture Decision Record (ADR) documentando decisoes arquiteturais do projeto. Aceita um numero de PR para analise automatica das mudancas, uma descricao textual, ou modo interativo. O ADR e salvo em `docs/adr/potential-adr/` com status \"proposto\" para revisao antes de aprovacao.\n</objective>\n\n<quick_start>\nDispatch com base no tipo de `$ARGUMENTS`:\n- Se `$ARGUMENTS` for um numero, trate como PR e siga o workflow a partir do Step 2 (branch PR).\n- Se `$ARGUMENTS` for texto, trate como descricao e siga o workflow a partir do Step 2 (branch descricao).\n- Se `$ARGUMENTS` estiver vazio, pergunte ao usuario via AskUserQuestion.\n\nEm seguida, siga o `<workflow>` passo a passo.\n</quick_start>\n\n<arguments>\n`$ARGUMENTS` - Numero do PR (ex: 256) OU descricao da decisao arquitetural. Se vazio, pergunta interativamente.\n</arguments>\n\n<pre_conditions>\n- Diretorio `docs/adr/potential-adr/` deve existir (criar com `mkdir -p` se ausente)\n- Template disponivel em `docs/adr/0000-adr-template.md` (usar estrutura MADR padrao se ausente)\n</pre_conditions>\n\n<workflow>\n\n<step_1 name=\"Determinar Proximo Numero\">\nEscanear tanto `docs/adr/` quanto `docs/adr/potential-adr/` para evitar numeros duplicados:\n\n```bash\n{ ls docs/adr/*.md 2>/dev/null; ls docs/adr/potential-adr/*.md 2>/dev/null; } | grep -oE ''[0-9]{4}'' | sort -n | tail -1\n```\n\nIncrementar em 1 (ex: 0012 -> 0013). Formatar com 4 digitos.\n</step_1>\n\n<step_2 name=\"Identificar Contexto\">\nSe `$ARGUMENTS` for numero de PR:\n\n```bash\ngh pr view $ARGUMENTS --json title,body\ngh pr diff $ARGUMENTS --name-only\n```\n\nAnalisar mudancas para identificar: decisao tomada, alternativas consideradas, justificativa.\n\nSe `$ARGUMENTS` for descricao textual: usar como base para a secao \"Contexto e Problema\". Inferir alternativas provaveis a partir do dominio e marcar `decisores: []` como pendente de preenchimento pelo usuario antes da aprovacao.\n\nSe `$ARGUMENTS` estiver vazio: perguntar ao usuario se quer fornecer numero de PR ou descrever manualmente.\n</step_2>\n\n<step_3 name=\"Gerar Titulo\">\nFormato: `XXXX-titulo-em-kebab-case.md`\n\nExemplos:\n- `0013-integracao-oauth-google-drive.md`\n- `0014-arquitetura-sistema-notificacoes.md`\n</step_3>\n\n<step_4 name=\"Criar Conteudo\">\nUsar o template em `docs/adr/0000-adr-template.md` como base:\n\n<adr_template>\n```markdown\n---\nstatus: proposto\ndata: YYYY-MM-DD\ndecisores: []\n---\n\n# XXXX-Titulo Descritivo\n\n## Contexto e Problema\n[2-3 frases descrevendo o contexto]\n\n## Fatores de Decisao\n* [Extraidos dos requisitos/discussoes]\n\n## Opcoes Consideradas\n* [Opcao implementada]\n* [Alternativa 1]\n* [Alternativa 2]\n\n## Resultado da Decisao\n**Opcao escolhida:** \"[Opcao X]\", porque [justificativa].\n\n### Consequencias\n**Positivas:**\n* [Beneficios]\n\n**Negativas:**\n* [Tradeoffs]\n\n## Confirmacao\n[Como validar a implementacao]\n\n## Mais Informacoes\n- PR: #$ARGUMENTS (se aplicavel)\n```\n</adr_template>\n</step_4>\n\n<step_5 name=\"Salvar ADR\">\nCriar o arquivo em `docs/adr/potential-adr/XXXX-titulo-kebab-case.md`.\n</step_5>\n\n<step_6 name=\"Atualizar README\">\nAdicionar entrada na secao \"ADRs Pendentes\" de `docs/adr/README.md`:\n\n```markdown\n| ADR-$ADR_NUM | [$ADR_TITLE](./potential-adr/$ADR_FILENAME) | $(date +%Y-%m-%d) | Proposto |\n```\n</step_6>\n\n<step_7 name=\"Reportar ao Usuario\">\nInformar: arquivo criado, numero do ADR, resumo do conteudo. Sugerir revisao e aprovacao com `/adr-approve XXXX`.\n</step_7>\n\n</workflow>\n\n<constraints>\n- SEMPRE use o template oficial de `docs/adr/0000-adr-template.md`\n- SEMPRE salve em `potential-adr/` com status \"proposto\" (NUNCA diretamente em `docs/adr/`)\n- SEMPRE atualize o README.md com a nova entrada\n- SEMPRE gere ADRs com: contexto claro (2-3 frases), alternativas reais (minimo 2), justificativa concreta, e consequencias honestas com tradeoffs\n</constraints>\n\n<error_handling>\n- Se `docs/adr/potential-adr/` nao existe: criar com `mkdir -p docs/adr/potential-adr/`\n- Se PR nao encontrado: informar numero invalido e pedir novo input\n- Se template nao existe: criar ADR com estrutura padrao MADR\n- Se README.md nao tem secao de pendentes: criar a secao\n</error_handling>\n\n<success_criteria>\n- Numero do ADR determinado corretamente (proximo sequencial, sem conflito com potential-adr/)\n- Contexto extraido do PR ou descricao\n- ADR criado em `docs/adr/potential-adr/` com status \"proposto\"\n- README.md atualizado com entrada pendente\n- Usuario informado com proximos passos (`/adr-approve`)\n</success_criteria>\n"},"lastSynced":"2026-03-06T07:11:17.715Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring automated Architecture Decision Record generation and project documentation management.","zh":"适用于需要自动化架构决策记录生成和项目文档管理的开发代理。","ja":"開発エージェントが自動化されたアーキテクチャ決定レコードの生成とプロジェクト文書管理を必要とする場合に適しています。","ko":"자동화된 아키텍처 결정 레코드 생성 및 프로젝트 문서 관리가 필요한 개발 에이전트에 적합합니다.","es":"Ideal para Agentes de Desarrollo que requieren generación automática de registros de decisión de arquitectura y gestión de documentación de proyectos.","fr":"Idéal pour les agents de développement nécessitant une génération automatisée d''enregistrements de décision d''architecture et une gestion de documentation de projet.","de":"Ideal für Entwicklungsmittel, die eine automatisierte Generierung von Architektur-Entscheidungsaufzeichnungen und eine Projekt-Dokumentenverwaltung erfordern.","pt":"Ideal para Agentes de Desenvolvimento que exigem geração automática de Registros de Decisão de Arquitetura e gerenciamento de documentação de projeto.","ru":"Идеально для агентов разработки, требующих автоматизированного создания записей об архитектурных решениях и управления документацией проекта.","ar":"مثالي لعميل التطوير الذين يتطلبون إنتاج سجل quyếtارات الهندسية أتوماتيكيا و إدارة توثيق المشروع."},"recommendation":{"en":"Empowers agents to create and manage Architecture Decision Records (ADRs) using PR numbers, textual descriptions, or interactive modes, leveraging documentation in Markdown format and storing them in a designated directory for review and approval, utilizing protocols such as Git for version control.","zh":"赋予代理创建和管理架构决策记录（ADRs），使用PR编号、文本描述或交互模式，利用Markdown格式的文档，并将其存储在指定目录中进行审查和批准，利用Git等协议进行版本控制。","ja":"エージェントがアーキテクチャ決定レコード（ADRs）を作成および管理できるようにし、PR番号、テキストの説明、またはインタラクティブモードを使用し、Markdown形式のドキュメントを活用し、指定されたディレクトリに保存してレビューおよび承認を行い、Gitなどのプロトコルを使用してバージョン管理を行う。","ko":"에이전트가 아키텍처 결정 레코드(ADRs)를 생성 및 관리할 수 있도록 하여 PR 번호, 텍스트 설명 또는 상호 작용 모드를 사용하고 Markdown 형식의 문서를 활용하며 지정된 디렉토리에 저장하여 검토 및 승인을 진행하며 Git 등의 프로토콜을 사용하여 버전 관리를 수행한다.","es":"Habilita a los agentes a crear y gestionar registros de decisión de arquitectura (ADRs) utilizando números de PR, descripciones textuales o modos interactivos, aprovechando la documentación en formato Markdown y almacenándolos en un directorio designado para su revisión y aprobación, utilizando protocolos como Git para el control de versiones.","fr":"Permet aux agents de créer et de gérer des enregistrements de décision d''architecture (ADRs) à l''aide de numéros de PR, de descriptions textuelles ou de modes interactifs, en exploitant la documentation au format Markdown et en les stockant dans un répertoire désigné pour examen et approbation, en utilisant des protocoles tels que Git pour la gestion de version.","de":"Ermöglicht es den Agenten, Architektur-Entscheidungsaufzeichnungen (ADRs) zu erstellen und zu verwalten, indem sie PR-Nummern, textuelle Beschreibungen oder interaktive Modi verwenden, die Dokumentation im Markdown-Format nutzt und sie in einem bestimmten Verzeichnis für Überprüfung und Genehmigung speichert, wobei Protokolle wie Git für die Versionsverwaltung verwendet werden.","pt":"Permite que os agentes criem e gerenciem Registros de Decisão de Arquitetura (ADRs) usando números de PR, descrições textuais ou modos interativos, aproveitando a documentação no formato Markdown e armazenando-as em um diretório designado para revisão e aprovação, utilizando protocolos como Git para controle de versão.","ru":"Наделяет агентов возможностью создавать и управлять записями об архитектурных решениях (ADRs) с использованием номеров PR, текстовых описаний или интерактивных режимов, используя документацию в формате Markdown и храня их в назначенном каталоге для рассмотрения и утверждения, используя протоколы, такие как Git, для управления версиями.","ar":"يمكن للعميل إنشاء و إدارة سجلات قرارات الهندسية (ADRs) باستخدام أرقام PR و وصف نصي أو وضع تفاعلي ، واستغلال الوثائق بالتنسيق Markdown و تخزينها في دليل معين للاستعراض و الموافقة ، باستخدام بروتوكولات مثل Git لإدارة الإصدارات."},"useCases":{"en":["Automating ADR generation for project changes","Documenting architectural decisions with PR analysis","Streamlining project documentation with interactive ADR creation"],"zh":["自动化项目更改的ADR生成","使用PR分析记录架构决策","通过交互式ADR创建简化项目文档"],"ja":["プロジェクトの変更のADR生成の自動化","PR分析を使用したアーキテクチャ決定のドキュメント化","インタラクティブなADR作成によるプロジェクトドキュメントの簡素化"],"ko":["프로젝트 변경의 ADR 생성 자동화","PR 분석을 사용한 아키텍처 결정 문서화","상호 작용형 ADR 생성을 통한 프로젝트 문서의 간소화"],"es":["Automatizar la generación de ADR para cambios de proyecto","Documentar decisiones arquitectónicas con análisis de PR","Optimizar la documentación del proyecto con la creación interactiva de ADR"],"fr":["Automatiser la génération d''ADR pour les modifications de projet","Documenter les décisions d''architecture avec l''analyse de PR","Optimiser la documentation du projet avec la création interactive d''ADR"],"de":["Automatisierung der ADR-Generierung für Projekänderungen","Dokumentation von Architektur-Entscheidungen mit PR-Analyse","Optimierung der Projekt-Dokumentation mit interaktiver ADR-Erstellung"],"pt":["Automatizar a geração de ADRs para alterações de projeto","Documentar decisões arquiteturais com análise de PR","Otimizar a documentação de projeto com criação interativa de ADRs"],"ru":["Автоматизировать создание записей об архитектурных решениях для изменений проекта","Документировать архитектурные решения с помощью анализа PR","Оптимизировать документацию проекта с помощью интерактивного создания записей об архитектурных решениях"],"ar":["أتمتة إنشاء سجلات قرارات الهندسية لتغييرات المشروع","توثيق قرارات الهندسية مع تحليل PR","تحسين توثيق المشروع مع إنشاء قرارات الهندسية التفاعلي"]},"limitations":{"en":["Requires access to project repository for PR analysis","Limited to generating ADRs in Markdown format","Dependent on Git version control system for workflow management"],"zh":["需要访问项目仓库以进行PR分析","仅限于生成Markdown格式的ADR","依赖于Git版本控制系统进行工作流管理"],"ja":["PR分析のためにプロジェクトリポジトリへのアクセスが必要","ADRはMarkdown形式でのみ生成可能","ワークフローの管理にはGitバージョン管理システムに依存"],"ko":["PR 분석을 위해 프로젝트 저장소에 접근할 수 있어야 함","ADR는 Markdown 형식으로만 생성 가능","워크플로우 관리에는 Git 버전 관리 시스템에 의존"],"es":["Requiere acceso al repositorio del proyecto para el análisis de PR","Limitado a generar ADR en formato Markdown","Dependiente del sistema de control de versiones Git para la gestión del flujo de trabajo"],"fr":["Nécessite un accès au référentiel de projet pour l''analyse de PR","Limité à la génération d''ADR au format Markdown","Dépendant du système de contrôle de version Git pour la gestion du flux de travail"],"de":["Erfordert Zugriff auf das Projekt-Repository für die PR-Analyse","Begrenzt auf die Generierung von ADR im Markdown-Format","Abhängig vom Git-Versionsverwaltungssystem für die Workflow-Verwaltung"],"pt":["Exige acesso ao repositório do projeto para análise de PR","Limitado a gerar ADRs no formato Markdown","Dependente do sistema de controle de versão Git para gerenciamento de fluxo de trabalho"],"ru":["Требует доступа к репозиторию проекта для анализа PR","Ограничен генерацией записей об архитектурных решениях в формате Markdown","Зависит от системы управления версиями Git для управления рабочим процессом"],"ar":["يتطلب الوصول إلى مستودع المشروع لتحليل PR","محدود بإنتاج سجلات قرارات الهندسية بتنسيق Markdown","يعتمد على نظام إدارة الإصدارات Git لإدارة تدفق العمل"]},"version":4},"contentHash":"e8c275ce41665941fe3627a605b041ce664f1d6e4ab01fa0c39c37602eeb7686","qualityScore":33}');
