INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('zorgentech/archon/create-adr', 'create-adr', 'zorgentech', 'archon', 'community', 'create-adr zorgentech archon community The create-adr skill generates Architecture Decision Records (ADRs) for projects, accepting PR numbers, textual descriptions, or interactive mode. It saves ADRs in docs/adr/potential-adr/ for review. create-adr 是一个自动创建架构决策记录的 AIエージェント，支持 PR 号、文本描述和交互模式 create-adr は、アーキテクチャ決定レコードを自動作成する AIエージェントで、PR 番号、テキスト描述、インタラクティブモードをサポートします create-adr는 아키텍처 결정 기록을 자동 생성하는 AI 에이전트로, PR 번호, 텍스트 설명, 상호작용 모드를 지원합니다 Create-adr es una herramienta que permite a los desarrolladores crear registros de decisión de arquitectura de manera eficiente. Se integra con PR y análisis de texto Create-adr est un outil qui permet aux développeurs de créer des enregistrements de décision d''architecture de manière efficace. Il s''intègre avec PR et l''analyse de texte Create-adr ist ein Tool, das es Entwicklern ermöglicht, Architektur-Entscheidungsregister effizient zu erstellen. Es integriert sich mit PR und Textanalyse O create-adr é uma ferramenta que ajuda a criar registros de decisões de arquitetura, aceitando números de PR, descrições textuais ou modo interativo. create-adr - это инструмент, который помогает создавать записи об архитектурных решениях, принимая номера PR, текстовые описания или интерактивный режим. create-adr هو أداة تساعد في إنشاء سجلات قرارات الهندسة المعمارية، وقبول أرقام الطلبات، وصفات نصية أو وضع التفاعل. create-adr setup guide what is create-adr how to use create-adr create-adr alternative create-adr vs architecture decision record tools install create-adr create-adr documentation adr automation architecture decision record best practices create-adr AIエージェント 架构决策记录 自动创建 PR 号分析 文本描述 交互模式 docs/adr/potential-adr/ Generates ADR documents based on PR numbers or textual descriptions Supports interactive mode for custom ADR creation Saves ADRs in docs/adr/potential-adr/ with ''proposto'' status for review Automates workflow based on $ARGUMENTS type (PR number or text) Integrates with project documentation for seamless ADR management create-adr is an AI agent skill that automates the creation of Architecture Decision Records (ADRs) for project documentation and review');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('BluMintInc/eslint-custom-rules/system-documentation', 'community', 'BluMintInc', 'eslint-custom-rules', 'BluMintInc/eslint-custom-rules', 'system-documentation', 1, 1, 33, '2026-02-23T15:04:44Z', '2026-03-06T07:11:15.761Z', 'c6fc4377eb97362bfb37e0caad07d7b4d33de7340b76728f029e0384aa2d2c0e', '{"id":"BluMintInc/eslint-custom-rules/system-documentation","name":"system-documentation","description":{"en":"The system-documentation skill ensures comprehensive documentation for major code systems in BluMint repositories, reflecting their current state and design philosophy. It benefits developers maintaining large codebases.","zh":"系统文档设置指南，帮助您为 BluMint 仓库创建和维护全面文档，包括 Claude Code Skills 和自定义规则","ja":"BluMint リポジトリのシステムドキュメント設定ガイド - Claude Code Skills とカスタムルールを使用した包括的なドキュメントの作成と維持","ko":"시스템 문서 설정 가이드 - BluMint 저장소에 대한 포괄적인 문서를 생성하고 유지하기 위한 Claude Code Skills 및 사용자 정의 규칙","es":"La documentación de sistemas es crucial para el mantenimiento de código. Aprende a crear y mantener documentación con AI Agent.","fr":"La documentation système est essentielle pour la maintenance du code. Découvrez comment créer et maintenir la documentation avec Outil IA.","de":"Die Systemdokumentation ist entscheidend für die Wartung von Code. Erfahren Sie, wie Sie Dokumentationen mit KI-Tool erstellen und pflegen.","pt":"O sistema de documentação permite criar e manter documentação abrangente para sistemas de código maiores em repositórios BluMint.","ru":"Система документации позволяет создавать и поддерживать полную документацию для крупных кодовых систем в репозиториях BluMint.","ar":"نظام التوثيق يسمح بإنشاء وتحديث توثيق شامل لنظم الكود الكبيرة في مخازن BluMint."},"seo":{"title":{"en":"system-documentation: Setup Guide for AI Agents | AI Agen...","zh":"系统文档设置指南 - BluMint 仓库自定义规则","ja":"システムドキュメント設定ガイド - BluMint リポジトリのカスタムルール","ko":"시스템 문서 설정 가이드 - BluMint 저장소 사용자 정의 규칙","es":"Guía de configuración para documentación de sistemas con ...","fr":"Guide de mise en place de la documentation système avec O...","de":"Einrichtungsleitfaden für Systemdokumentation mit KI-Tool","pt":"Guia de Configuração de Documentação de Sistemas para Rep...","ru":"Настройка документации системы для репозиториев BluMint с...","ar":"دليل إعداد توثيق النظام لمخازن BluMint باستخدام أدوات الذ..."},"description":{"en":"Discover how to implement custom rules in BluMint repositories with system-documentation. Learn more and get started today!","zh":"了解如何为 BluMint 仓库创建和维护系统文档，包括 Claude Code Skills 和自定义规则","ja":"BluMint リポジトリのシステムドキュメントを作成して維持する方法を学びましょう - Claude Code Skills とカスタムルールを含む","ko":"BluMint 저장소의 시스템 문서를 생성하고 유지하는 방법을 알아보세요 - Claude Code Skills 및 사용자 정의 규칙 포함","es":"Aprende a crear y mantener documentación para sistemas de código con AI Agent y Claude Code Skills","fr":"Découvrez comment créer et maintenir la documentation pour les systèmes de code avec Outil IA et Claude Code Skills","de":"Erfahren Sie, wie Sie Dokumentationen für Code-Systeme mit KI-Tool und Claude Code Skills erstellen und pflegen","pt":"Aprenda a criar e manter documentação abrangente para sistemas de código maiores em repositórios BluMint com regras personalizadas","ru":"Узнайте, как создавать и поддерживать полную документацию для крупных кодовых систем в репозиториях BluMint с помощью индивидуальных правил и ИИ Агентов","ar":"تعلم كيفية إنشاء وتحديث توثيق شامل لنظم الكود الكبيرة في مخازن BluMint باستخدام قواعد مخصصة وأدوات الذكاء الاصطناعي"},"definition":{"en":"system-documentation is a set of custom rules for maintaining comprehensive documentation of major code systems in BluMint repositories.","zh":"系统文档是指 BluMint 仓库中使用的 Claude Code Skills 和自定义规则，用于创建和维护代码系统的文档","ja":"システムドキュメントは、BluMint リポジトリで使用される Claude Code Skills とカスタムルールで、コードシステムのドキュメントを作成して維持するために使用される","ko":"시스템 문서는 BluMint 저장소에서 사용되는 Claude Code Skills 및 사용자 정의 규칙으로, 코드 시스템의 문서를 생성하고 유지하는 데 사용됩니다","es":"La documentación de sistemas es un conjunto de reglas para crear y mantener documentación para sistemas de código","fr":"La documentation système est un ensemble de règles pour créer et maintenir la documentation pour les systèmes de code","de":"Die Systemdokumentation ist ein Satz von Regeln zur Erstellung und Pflege von Dokumentationen für Code-Systeme","pt":"O sistema de documentação é um conjunto de regras personalizadas para criar e manter documentação de sistemas de código","ru":"Система документации - это набор индивидуальных правил для создания и поддержки документации кодовых систем","ar":"نظام التوثيق هو مجموعة من القواعد المخصصة لإنشاء وتحديث توثيق أنظمة الكود"},"features":{"en":["Generates documentation for major code systems stored in .claude/skills/","Maintains documentation for existing systems, reflecting their current state","Supports design philosophy documentation for cohesive code purposes","Applies to collections of components, hooks, contexts, and utilities","Ensures reusable functionality documentation for other parts of the codebase","Works with Claude Code Skills for streamlined documentation"],"zh":["支持 Claude Code Skills","自定义规则用于 BluMint 仓库","全面文档创建和维护","代码系统文档生成","BluMint 仓库集成"],"ja":["Claude Code Skills をサポート","BluMint リポジトリ用のカスタムルール","包括的なドキュメントの作成と維持","コードシステムのドキュメント生成","BluMint リポジトリとの統合"],"ko":["Claude Code Skills 지원","BluMint 저장소용 사용자 정의 규칙","포괄적인 문서 생성 및 유지","코드 시스템 문서 생성","BluMint 저장소 통합"],"es":["Creación de documentación para sistemas de código con Claude Code Skills","Mantenimiento de documentación para sistemas existentes","Uso de componentes, hooks, contexts y utilities para proporcionar funcionalidad reutilizable","Soporte para múltiples archivos y directorios","Integración con BluMint repositories"],"fr":["Création de documentation pour les systèmes de code avec Claude Code Skills","Maintenance de la documentation pour les systèmes existants","Utilisation de composants, hooks, contexts et utilities pour fournir une fonctionnalité réutilisable","Prise en charge de plusieurs fichiers et répertoires","Intégration avec les référentiels BluMint"],"de":["Erstellung von Dokumentationen für Code-Systeme mit Claude Code Skills","Pflege von Dokumentationen für bestehende Systeme","Verwendung von Komponenten, Hooks, Contexts und Utilities zur Bereitstellung von wiederverwendbarer Funktionalität","Unterstützung für mehrere Dateien und Verzeichnisse","Integration mit BluMint-Repositorys"],"pt":["Criação de documentação abrangente para sistemas de código maiores","Manutenção de documentação atualizada para sistemas existentes","Suporte a repositórios BluMint","Regras personalizadas para documentação de sistemas","Integração com Claude Code Skills","Suporte a múltiplos arquivos e diretórios"],"ru":["Создание полной документации для крупных кодовых систем","Поддержка актуальной документации для существующих систем","Поддержка репозиториев BluMint","Индивидуальные правила для документации систем","Интеграция с Claude Code Skills","Поддержка нескольких файлов и директорий"],"ar":["إنشاء توثيق شامل لنظم الكود الكبيرة","تحديث توثيق محدث لنظم موجودة","دعم مخازن BluMint","قواعد مخصصة لتوثيق الأنظمة","التكامل مع Claude Code Skills","دعم عدة ملفات ومجلات"]},"keywords":{"en":["how to use system-documentation","what is system-documentation","system-documentation alternative","system-documentation vs BluMint","system-documentation install","system-documentation setup guide","BluMint repository documentation","Claude Code Skills documentation","major code system documentation"],"zh":["系统文档","BluMint 仓库","Claude Code Skills","自定义规则","代码系统文档","文档生成","BluMint 集成","AIエージェント","代码管理"],"ja":["システムドキュメント","BluMint リポジトリ","Claude Code Skills","カスタムルール","コードシステムのドキュメント","ドキュメント生成","BluMint 統合","AIエージェント","コード管理"],"ko":["시스템 문서","BluMint 저장소","Claude Code Skills","사용자 정의 규칙","코드 시스템 문서","문서 생성","BluMint 통합","AI 에이전트","코드 관리"],"es":["documentación de sistemas","AI Agent","Claude Code Skills","BluMint repositories","desarrollo de software","mantenimiento de código","creación de documentación","integración con herramientas de desarrollo"],"fr":["documentation système","Outil IA","Claude Code Skills","référentiels BluMint","développement de logiciels","maintenance de code","création de documentation","intégration avec les outils de développement"],"de":["Systemdokumentation","KI-Tool","Claude Code Skills","BluMint-Repositorys","Software-Entwicklung","Code-Wartung","Dokumentationserstellung","Integration mit Entwicklungstools"],"pt":["documentação de sistemas","repositórios BluMint","regras personalizadas","Claude Code Skills","sistemas de código maiores","manutenção de documentação","criação de documentação","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["документация системы","репозитории BluMint","индивидуальные правила","Claude Code Skills","крупные кодовые системы","поддержка документации","создание документации","разработка программного обеспечения","инструменты разработки","ИИ Агенты"],"ar":["توثيق الأنظمة","مخازن BluMint","قواعد مخصصة","Claude Code Skills","نظم الكود الكبيرة","تحديث التوثيق","إنشاء توثيق","تطوير البرمجيات","أدوات التطوير","أدوات الذكاء الاصطناعي"]}},"owner":"BluMintInc","repo":"eslint-custom-rules","repoPath":"BluMintInc/eslint-custom-rules","stars":1,"forks":1,"updatedAt":"2026-02-23T15:04:44Z","topics":[],"category":"community","skillMd":{"name":"system-documentation","description":"Use when creating or updating SKILL.md documentation for major code systems.","bodyPreview":"## Purpose\n\nTo ensure that comprehensive documentation for major code systems (in the form of Claude Code Skills stored in `.claude/skills/`) is both created for new systems and diligently maintained for existing ones, reflecting their current state and design philosophy.\n\nA \"major code system\" is a collection of components, hooks, contexts, and utilities that serve a cohesive purpose and often span multiple files and directories, providing reusable functionality for other parts of the codebase.","body":"## Purpose\n\nTo ensure that comprehensive documentation for major code systems (in the form of Claude Code Skills stored in `.claude/skills/`) is both created for new systems and diligently maintained for existing ones, reflecting their current state and design philosophy.\n\nA \"major code system\" is a collection of components, hooks, contexts, and utilities that serve a cohesive purpose and often span multiple files and directories, providing reusable functionality for other parts of the codebase.\n\n## Part 1: Creating New Documentation Guides\n\nWhen you implement a new major code system that does not yet have a corresponding `.claude/skills/*/SKILL.md` documentation file, you should draft a new one.\n\n### Creation Steps\n1.  **Identify the Need**: Recognize that a new, cohesive system has been built (e.g., a new data handling paradigm, a complex UI widget family).\n2.  **Draft the Skill**: Create a new `SKILL.md` file in `.claude/skills/<skill-name>/`.\n3.  **Structure the Guide**: Follow the template below to structure the content.\n\n### Documentation Template\n```markdown\n---\nname: <skill-name>\ndescription: \"Use when...\"\nuser-invocable: false\n---\n\n# Introduction\n\n## Purpose\n[Hook the user on how this system can make their lives easier. Explain the **core insights** or paradigms that drive its design. Keep it concise but meaningful.]\n\n## Definitions\n\n*Reserve this section for vocabulary and conceptual terminology. Describe ideas, patterns, and domain-specific language that developers must understand. Do not list file names, concrete classes, or modules here—capture those in the optional **Core Components** section instead.*\n\n*   **[Key Term 1]**: [Clear, concise definition explaining what this concept means within the context of the system. Include any important relationships to other concepts. Focus on what developers need to understand to work with the system effectively.]\n\n*   **[Key Term 2]**: [Continue adding definitions for the core concepts, patterns, or architectural ideas that are central to understanding and using the system.]\n\n*   **[Additional Terms]**: [Add as many definitions as needed to cover the essential vocabulary of the system. These should be the terms that appear frequently in the codebase or are critical to understanding the system''s design.]\n\n## Core Components (Optional)\n[If the system exposes notable classes, modules, or files, document them here instead of the Definitions section. Provide brief descriptions that explain each component''s responsibility and how developers should interact with it.]\n\n## Why did we build [System Name]?\n[Discuss the key pain points or motivations that led to creating this system. What gap does it fill? How does it improve or simplify an existing process?]\n\n## How does this system make developers'' lives easier?\n[Explain the most common use cases and **practical benefits**. Focus on how to solve real-world problems with the system.]\n\n## Directory Structure\n\n```\npath/to/\n├── functions/**/*              # [Description of what''s in this directory]\n├── components/**/*             # [Description of what''s in this directory]\n└── ...\n```\n\n[Briefly describe **why** these directories exist or how they are logically organized.]\n\n## How to Use [System Name]\n[Provide several subsections on how to use the system, each complete with examples. Focus on **how to use the system, not on implementation details**. Start simple and progressively get more complex, introducing new concepts by their purpose.]\n\n## Critical Insights for Maintainers\n[Capture non-obvious lessons and rationale to guide future maintainers. Focus on pitfalls to avoid and why specific design choices were made.]\n\n### Major deviations from the initial plan\n[- List the most important changes from the original design and why they were made.]\n\n### Critical insights discovered\n[- Summarize the key insights that shaped the final design and usage patterns.]\n\n### Notable assumptions that proved inaccurate\n[- Call out initial assumptions that were revised and what replaced them.]\n\n### Important lessons or improvements\n[- Provide actionable advice for future changes and improvements while preserving system integrity.]\n```\n\n## Part 2: Updating Existing Documentation Guides\n\nWhen you significantly refactor or extend an existing code system that already has a `.claude/skills/*/SKILL.md` file, you must update the corresponding documentation.\n\n### Update Steps\n1.  **Identify Changes**: After modifying the code, review the changes.\n2.  **Update Documentation**: Edit the corresponding `SKILL.md` file to:\n    - Reflect new system behaviors and functionality.\n    - Incorporate any new paradigms, core ideas, or design philosophies introduced by the changes.\n    - Update code examples to be accurate and relevant.\n    - Adjust the purpose/motivation statements if the system''s role has evolved.\n\n## When This Rule Should Be Followed\n\n- **Creating**: Apply this rule **when a new major code system is implemented** and lacks documentation.\n- **Updating**: Apply this rule **after a code system with existing documentation has been significantly refactored or extended**. This is a mandatory step before considering the task complete, as outlined in the \"Agent Task Completion Standards\".\n\n### Common Pitfalls\n- **Use A-temporal phrasing**: Avoid time-coupled language (for example: \"now\", \"currently\", \"recently\", \"new\", \"old\", \"temporary\"); when editing documentation, do not refer to past states (e.g., avoid \"Refactored from v2 to v3\").\n"},"lastSynced":"2026-03-06T07:11:15.761Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Maintenance Agents requiring thorough documentation of major code systems in BluMint repositories.","zh":"适用于需要对 BluMint 仓库中的主要代码系统进行彻底文档记录的代码维护代理。","ja":"BluMint リポジトリ内の主なコード システムの包括的なドキュメント作成を必要とするコード メンテナンス エージェントに最適です。","ko":"BluMint 리포지토리의 주요 코드 시스템에 대한 철저한 문서화가 필요한 코드 유지 보수 에이전트에 적합합니다.","es":"Ideal para Agentes de Mantenimiento de Código que requieren una documentación exhaustiva de los principales sistemas de código en los repositorios de BluMint.","fr":"Idéal pour les Agents de Maintenance de Code nécessitant une documentation complète des principaux systèmes de code dans les référentiels BluMint.","de":"Ideal für Code-Wartungsagenten, die eine gründliche Dokumentation der wichtigsten Codesysteme in den BluMint-Repositorys benötigen.","pt":"Ideal para Agentes de Manutenção de Código que exigem documentação completa de principais sistemas de código nos repositórios BluMint.","ru":"Идеально подходит для агентов по техническому обслуживанию кода, требующих тщательной документации основных систем кода в репозиториях BluMint.","ar":"مثالي للوكلاء الذين يحتاجون إلى توثيق شامل لأنظمة التعليمات الرئيسية في مستودعات BluMint."},"recommendation":{"en":"Empowers agents to maintain comprehensive documentation for major code systems using Claude Code Skills stored in `.claude/skills/`, ensuring accuracy and consistency across large codebases, and supporting design philosophy and current system states through diligent updates.","zh":"赋予代理维护使用存储在 `.claude/skills/` 的 Claude Code Skills 的主要代码系统的全面文档的能力，确保大型代码库中的准确性和一致性，并通过勤勉的更新支持设计哲学和当前系统状态。","ja":"`.claude/skills/` に保存されている Claude Code Skills を使用して主要なコード システムの包括的なドキュメントをメンテナンスするエージェントの能力を提供し、大規模なコード ベース全体の正確性と一貫性を確保し、デザイン哲学と現在のシステム状態を徹底した更新を通じてサポートします。","ko":"`.claude/skills/`에 저장된 Claude Code Skills를 사용하여 주요 코드 시스템의 종합 문서를 유지 보수하는 에이전트의 능력을 제공하여 대규모 코드베이스 전반의 정확성과 일관성을 보장하며, 디자인 철학과 현재 시스템 상태를勤勉한 업데이트를 통해 지원합니다.","es":"Habilita a los agentes a mantener una documentación completa para los principales sistemas de código utilizando habilidades de código Claude almacenadas en `.claude/skills/`, garantizando la precisión y la coherencia en grandes bases de código, y apoyando la filosofía del diseño y los estados actuales del sistema a través de actualizaciones diligentes.","fr":"Permet aux agents de maintenir une documentation complète pour les principaux systèmes de code en utilisant les compétences de code Claude stockées dans `.claude/skills/`, garantissant l''exactitude et la cohérence sur de grandes bases de code, et soutenant la philosophie de conception et les états actuels du système grâce à des mises à jour diligentes.","de":"Ermächtigt die Agenten, eine umfassende Dokumentation für die wichtigsten Codesysteme mithilfe von Claude Code Skills zu erstellen, die in `.claude/skills/` gespeichert sind, und gewährleistet so Genauigkeit und Konsistenz in großen Codebasen, und unterstützt die Designphilosophie und den aktuellen Systemzustand durch sorgfältige Updates.","pt":"Habilita os agentes a manter documentação abrangente para principais sistemas de código usando Habilidades de Código Claude armazenadas em `.claude/skills/`, garantindo precisão e consistência em grandes bases de código, e apoiando a filosofia de design e os estados atuais do sistema por meio de atualizações diligentes.","ru":"Наделяет агентов возможностью поддерживать всестороннюю документацию для основных систем кода с помощью навыков кода Claude, хранящихся в `.claude/skills/`, обеспечивая точность и согласованность на больших кодовых базах, и поддерживая философию дизайна и текущие состояния системы за счет тщательных обновлений.","ar":"تمكّن الوكلاء من الحفاظ على توثيق شامِل لأنظمة التعليمات الرئيسية باستخدام مهارات Claude Code المخزنة في `.claude/skills/`، مما يضمن الدقة والاتساق عبر قواعد التعليمات البرمجية الكبيرة، ودعم فلسفة التصميم والحالات الحالية للنظام من خلال تحديثات مدروسة."},"useCases":{"en":["Generating documentation for new code systems","Updating existing documentation to reflect design philosophy changes","Maintaining consistency across multiple files and directories"],"zh":["为新代码系统生成文档","更新现有文档以反映设计哲学的变化","在多个文件和目录中保持一致性"],"ja":["新しいコード システムのドキュメントを生成する","設計哲学の変更を反映するために既存のドキュメントを更新する","複数のファイルとディレクトリ間で一貫性を維持する"],"ko":["새 코드 시스템에 대한 문서 생성","디자인 철학의 변경을 반영하기 위해 기존 문서를 업데이트","여러 파일 및 디렉토리에서 일관성을 유지"],"es":["Generar documentación para nuevos sistemas de código","Actualizar la documentación existente para reflejar los cambios en la filosofía del diseño","Mantener la coherencia en varios archivos y directorios"],"fr":["Générer la documentation pour les nouveaux systèmes de code","Mettre à jour la documentation existante pour refléter les changements de philosophie de conception","Maintenir la cohérence dans plusieurs fichiers et répertoires"],"de":["Dokumentation für neue Codesysteme generieren","Vorhandene Dokumentation aktualisieren, um Änderungen an der Designphilosophie widerzuspiegeln","Konsistenz in mehreren Dateien und Verzeichnissen aufrechterhalten"],"pt":["Geração de documentação para novos sistemas de código","Atualização da documentação existente para refletir alterações na filosofia de design","Manutenção da consistência em vários arquivos e diretórios"],"ru":["Генерация документации для новых систем кода","Обновление существующей документации для отражения изменений в философии дизайна","Поддержание согласованности в нескольких файлах и директориях"],"ar":["إنتاج توثيق لأنظمة التعليمات الجديدة","تحديث التوثيق الحالي ليعكس التغييرات في فلسفة التصميم","الحفاظ على الاتساق عبر الملفات والمجلدات المتعددة"]},"limitations":{"en":["Requires access to BluMint repositories","Limited to Claude Code Skills format"],"zh":["需要访问 BluMint 仓库","仅限 Claude Code Skills 格式"],"ja":["BluMint リポジトリへのアクセスが必要","Claude Code Skills フォーマットに限定される"],"ko":["BluMint 리포지토리에 대한 액세스가 필요","Claude Code Skills 형식으로 제한"],"es":["Requiere acceso a los repositorios de BluMint","Limitado al formato de habilidades de código Claude"],"fr":["Requiert un accès aux référentiels BluMint","Limité au format de compétences de code Claude"],"de":["Erfordert Zugriff auf die BluMint-Repositorys","Begrenzt auf das Format der Claude Code Skills"],"pt":["Exige acesso aos repositórios BluMint","Limitado ao formato de Habilidades de Código Claude"],"ru":["Требует доступа к репозиториям BluMint","Ограничен форматом навыков кода Claude"],"ar":["يتطلب الوصول إلى مستودعات BluMint","محدود بالتنسيق مهارات Claude Code"]},"version":4},"contentHash":"c6fc4377eb97362bfb37e0caad07d7b4d33de7340b76728f029e0384aa2d2c0e","qualityScore":33}');
