INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('BluMintInc/eslint-custom-rules/system-documentation', 'system-documentation', 'BluMintInc', 'eslint-custom-rules', 'community', 'system-documentation BluMintInc eslint-custom-rules community The system-documentation skill ensures comprehensive documentation for major code systems in BluMint repositories, reflecting their current state and design philosophy. It benefits developers maintaining large codebases. 系统文档设置指南，帮助您为 BluMint 仓库创建和维护全面文档，包括 Claude Code Skills 和自定义规则 BluMint リポジトリのシステムドキュメント設定ガイド - Claude Code Skills とカスタムルールを使用した包括的なドキュメントの作成と維持 시스템 문서 설정 가이드 - BluMint 저장소에 대한 포괄적인 문서를 생성하고 유지하기 위한 Claude Code Skills 및 사용자 정의 규칙 La documentación de sistemas es crucial para el mantenimiento de código. Aprende a crear y mantener documentación con AI Agent. La documentation système est essentielle pour la maintenance du code. Découvrez comment créer et maintenir la documentation avec Outil IA. Die Systemdokumentation ist entscheidend für die Wartung von Code. Erfahren Sie, wie Sie Dokumentationen mit KI-Tool erstellen und pflegen. O sistema de documentação permite criar e manter documentação abrangente para sistemas de código maiores em repositórios BluMint. Система документации позволяет создавать и поддерживать полную документацию для крупных кодовых систем в репозиториях BluMint. نظام التوثيق يسمح بإنشاء وتحديث توثيق شامل لنظم الكود الكبيرة في مخازن BluMint. how to use system-documentation what is system-documentation system-documentation alternative system-documentation vs BluMint system-documentation install system-documentation setup guide BluMint repository documentation Claude Code Skills documentation major code system documentation 系统文档 BluMint 仓库 Claude Code Skills 自定义规则 代码系统文档 文档生成 BluMint 集成 AIエージェント 代码管理 Generates documentation for major code systems stored in .claude/skills/ Maintains documentation for existing systems, reflecting their current state Supports design philosophy documentation for cohesive code purposes Applies to collections of components, hooks, contexts, and utilities Ensures reusable functionality documentation for other parts of the codebase Works with Claude Code Skills for streamlined documentation system-documentation is a set of custom rules for maintaining comprehensive documentation of major code systems in BluMint repositories.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('6/turbocop/triage', 'community', '6', 'turbocop', '6/turbocop', 'triage', 1, 0, 33, '2026-02-25T05:33:45Z', '2026-03-06T13:08:30.135Z', 'b5b9f4ed4b95d0fbc22b000ad3ecf628efb253345d9ac98202faf929e3048671', '{"id":"6/turbocop/triage","name":"triage","description":{"en":"Triage is an experimental RuboCop rewrite in Rust that helps developers identify and fix top cops by divergence in their Ruby code. It benefits developers working with Ruby and Rust.","zh":"Triage 是一个实验性的 RuboCop 重写版本，使用 Rust 编写。它可以帮助您找到需要修复的顶级 cops","ja":"Triage は、Rust で書かれた実験的な RuboCop の再実装です。修正する必要があるトップレベルの cops を見つけるのに役立ちます","ko":"Triage는 러스트로 작성된 실험적인 루비コ프 재구현입니다. 수정해야 하는 상위 cops를 찾는 데 도움이 됩니다","es":"Triage es una herramienta experimental para identificar y solucionar problemas con RuboCop en Rust, utilizando un script Python para analizar resultados","fr":"Triage est un outil expérimental pour identifier et résoudre les problèmes avec RuboCop en Rust, en utilisant un script Python pour analyser les résultats","de":"Triage ist ein experimentelles Tool, um Probleme mit RuboCop in Rust zu identifizieren und zu lösen, indem es ein Python-Skript verwendet, um Ergebnisse zu analysieren","pt":"O Triage é uma ferramenta experimental que reescreve o RuboCop em Rust para melhorar o desempenho. Execute o script de triage para encontrar os principais cops a serem corrigidos.","ru":"Triage - это экспериментальный инструмент, переписывающий RuboCop на Rust для улучшения производительности. Запустите скрипт triage, чтобы найти лучших cops для исправления.","ar":"التriage هو أداة تجريبية لتعزيز أداء RuboCop باستخدام Rust. تشغيل سكريبت التriage لتحديد القوات الرئيسية التي يجب تصحيحها."},"seo":{"title":{"en":"Triage: Experimental RuboCop Rewrite Setup Guide | AI Age...","zh":"Triage 技术指南：使用 Rust 重写 RuboCop","ja":"Triage セットアップガイド：Rust で RuboCop を再実装","ko":"Triage 설정 가이드: Rust로 RuboCop 다시 작성","es":"Guía de Configuración de Triage para RuboCop en Rust","fr":"Guide de Configuration de Triage pour RuboCop en Rust","de":"Einrichtungsleitfaden für Triage mit RuboCop in Rust","pt":"Guia de Configuração do Triage: Otimização de RuboCop com...","ru":"ИИ Агент Triage: Руководство по Настройке для Оптимизации...","ar":"دليل إعداد التriage: تحسين أداء RuboCop باستخدام Rust"},"description":{"en":"Discover how to use triage to optimize your Ruby code with a Rust-powered RuboCop rewrite. Learn how to run the triage script and fix top cops by divergence.","zh":"使用 Triage 技术自动下载最新的 corpus-results.json，并找到需要修复的顶级 cops","ja":"Triage を使用して最新の corpus-results.json を自動ダウンロードし、修正する必要があるトップレベルの cops を見つける","ko":"Triage를 사용하여 최신 corpus-results.json를 자동으로 다운로드하고 수정해야 하는 상위 cops를 찾습니다","es":"Aprende a utilizar Triage para identificar y solucionar problemas con RuboCop en Rust de manera eficiente","fr":"Découvrez comment utiliser Triage pour identifier et résoudre les problèmes avec RuboCop en Rust de manière efficace","de":"Erfahren Sie, wie Sie Triage verwenden, um Probleme mit RuboCop in Rust effizient zu identifizieren und zu lösen","pt":"Aprenda a usar o Triage para otimizar o desempenho do RuboCop com Rust e melhore a eficiência do seu código","ru":"Узнайте, как использовать ИИ Агент Triage для оптимизации RuboCop с помощью Rust и улучшения производительности кода","ar":"تعرف على كيفية استخدام التriage لتحسين أداء RuboCop باستخدام Rust وزيادة كفاءة кодك"},"definition":{"en":"Triage is an experimental RuboCop rewrite in Rust that runs a script to find and fix top cops by divergence in Ruby code.","zh":"Triage 是一个 AI エージェント，使用 Rust 重写 RuboCop，自动下载最新的 corpus-results.json","ja":"Triage は、AI エージェントの一種で、Rust で RuboCop を再実装し、最新の corpus-results.json を自動ダウンロードする","ko":"Triage는 AI 에이전트의 일종으로 Rust로 RuboCop를 다시 작성하고 최신 corpus-results.json를 자동으로 다운로드합니다","es":"Triage es una herramienta de análisis para RuboCop en Rust que utiliza un script Python para identificar problemas","fr":"Triage est un outil d''analyse pour RuboCop en Rust qui utilise un script Python pour identifier les problèmes","de":"Triage ist ein Analyse-Tool für RuboCop in Rust, das ein Python-Skript verwendet, um Probleme zu identifizieren","pt":"O Triage é uma ferramenta de otimização que reescreve o RuboCop em Rust","ru":"Triage - это инструмент оптимизации, переписывающий RuboCop на Rust","ar":"التriage هو أداة تحسين تعزز أداء RuboCop باستخدام Rust"},"features":{"en":["Runs the triage script using `python3 .claude/skills/triage/scripts/triage.py` to find top cops by divergence","Auto-downloads the latest `corpus-results.json` from CI via `gh run download` if no input is provided","Supports filtering by department using `--department` flag, e.g. `/triage --department RSpec`","Allows excluding departments using `--exclude-department` flag, e.g. `/triage --exclude-department Layout`","Provides option to show only cops with false positives using `--fp-only` flag"],"zh":["自动下载最新的 corpus-results.json","找到需要修复的顶级 cops","支持多种命令行参数，例如 --limit、--department、--exclude-department","可以过滤和排除特定的 cops","支持 false positive 仅显示"],"ja":["最新の corpus-results.json を自動ダウンロード","修正する必要があるトップレベルの cops を見つける","様々なコマンドラインパラメータをサポート（--limit、--department、--exclude-department など）","特定の cops をフィルタリングおよび除外","false positive のみを表示"],"ko":["최신 corpus-results.json를 자동으로 다운로드","수정해야 하는 상위 cops를 찾습니다","다양한 명령줄 매개변수를 지원합니다(--limit, --department, --exclude-department 등)","특정 cops를 필터링 및 제외","false positive만 표시"],"es":["Análisis de resultados de RuboCop en Rust utilizando un script Python","Identificación de los principales problemas de copias","Filtrado de departamentos y exclusión de copias complejas","Opción para mostrar solo copias con falsos positivos","Integración con GitHub Actions para descargar resultados de CI"],"fr":["Analyse des résultats de RuboCop en Rust à l''aide d''un script Python","Identification des principaux problèmes de copie","Filtrage des départements et exclusion des copies complexes","Option pour afficher uniquement les copies avec de faux positifs","Intégration avec GitHub Actions pour télécharger les résultats de CI"],"de":["Analyse von RuboCop-Ergebnissen in Rust mithilfe eines Python-Skripts","Identifizierung der wichtigsten Probleme mit Kopien","Filtern von Abteilungen und Ausschluss komplexer Kopien","Option, nur Kopien mit Falschpositiven anzuzeigen","Integration mit GitHub Actions zum Herunterladen von CI-Ergebnissen"],"pt":["Otimização do desempenho do RuboCop com Rust","Execução do script de triage para encontrar os principais cops a serem corrigidos","Filtragem por departamentos","Exclusão de departamentos complexos","Opção para exibir apenas cops com falsos positivos"],"ru":["Оптимизация производительности RuboCop с помощью Rust","Запуск скрипта triage для поиска лучших cops для исправления","Фильтрация по отделам","Исключение сложных отделов","Вариант отображения только cops с ложными срабатываниями"],"ar":["تحسين أداء RuboCop باستخدام Rust","تشغيل سكريبت التriage لتحديد القوات الرئيسية التي يجب تصحيحها","التصفية حسب الإدارات","استبعاد الإدارات المعقدة","خيار عرض القوات فقط مع الإيجابيات الكاذبة"]},"keywords":{"en":["how to use triage","what is triage","triage alternative","triage vs rubocop","triage install","triage setup guide","ruby code optimization","rust powered rubocop"],"zh":["Triage 技术","RuboCop 重写","Rust 编写","AI エージェント","自动下载 corpus-results.json","修复顶级 cops","命令行参数","false positive 仅显示"],"ja":["Triage 技術","RuboCop 再実装","Rust で書かれた","AI エージェント","corpus-results.json の自動ダウンロード","トップレベルの cops の修正","コマンドラインパラメータ","false positive のみ表示"],"ko":["Triage 기술","루비コ프 재구현","러스트로 작성된","AI 에이전트","corpus-results.json 자동 다운로드","상위 cops 수정","명령줄 매개변수","false positive만 표시"],"es":["Triage para RuboCop","Herramientas de análisis de Rust","Script de Python para RuboCop","Identificación de problemas en RuboCop","Filtrado de departamentos en RuboCop","Exclusión de copias complejas en RuboCop","Integración con GitHub Actions"],"fr":["Triage pour RuboCop","Outils d''analyse de Rust","Script Python pour RuboCop","Identification de problèmes dans RuboCop","Filtrage de départements dans RuboCop","Exclusion de copies complexes dans RuboCop","Intégration avec GitHub Actions"],"de":["Triage für RuboCop","Analyse-Tools für Rust","Python-Skript für RuboCop","Identifizierung von Problemen in RuboCop","Filtern von Abteilungen in RuboCop","Ausschluss komplexer Kopien in RuboCop","Integration mit GitHub Actions"],"pt":["Triage","RuboCop","Rust","Otimização de desempenho","Ferramentas de desenvolvimento","Código eficiente","Desenvolvimento de software","Programação em Rust","Ferramentas de análise de código"],"ru":["Triage","RuboCop","Rust","Оптимизация производительности","Инструменты разработки","Эффективный код","Разработка программного обеспечения","Программирование на Rust","Инструменты анализа кода"],"ar":["التriage","RuboCop","Rust","تحسين الأداء","أدوات التطوير","كود فعال","تطوير البرمجيات","برمجة بلغة Rust","أدوات تحليل الكود"]}},"owner":"6","repo":"turbocop","repoPath":"6/turbocop","stars":1,"forks":0,"updatedAt":"2026-02-25T05:33:45Z","topics":["rubocop","ruby","rust"],"category":"community","skillMd":{"name":"triage","description":"Rank cops by FP+FN from the corpus oracle to find the next batch to fix","bodyPreview":"Run the triage script to find the top cops to fix:\n\n```bash\npython3 .claude/skills/triage/scripts/triage.py $ARGUMENTS\n```\n\nIf no `--input` is provided, it auto-downloads the latest `corpus-results.json` from CI via `gh run download`.\n\nCommon invocations:\n- `/triage` — top 30 cops by divergence\n- `/triage --limit 50` — show more\n- `/triage --department RSpec` — filter to one department\n- `/triage --exclude-department Layout` — skip complex layout cops\n- `/triage --fp-only` — only cops with false","body":"Run the triage script to find the top cops to fix:\n\n```bash\npython3 .claude/skills/triage/scripts/triage.py $ARGUMENTS\n```\n\nIf no `--input` is provided, it auto-downloads the latest `corpus-results.json` from CI via `gh run download`.\n\nCommon invocations:\n- `/triage` — top 30 cops by divergence\n- `/triage --limit 50` — show more\n- `/triage --department RSpec` — filter to one department\n- `/triage --exclude-department Layout` — skip complex layout cops\n- `/triage --fp-only` — only cops with false positives\n- `/triage --input /tmp/corpus-report/corpus-results.json` — use local file\n\nAfter identifying targets, use `investigate-cop.py` to see all FP/FN locations with source context:\n\n```bash\npython3 scripts/investigate-cop.py Department/CopName --context --fp-only\n```\n\nThen read the cop source in `src/cop/<dept>/<cop>.rs` and the vendor spec at `vendor/rubocop*/spec/` to understand the root cause before fixing.\n\nThis skill is read-only. Parallel-agent activity may leave unrelated local modifications in the working tree; do not edit or revert them while triaging.\nIf triage transitions into code edits, switch to a dedicated git worktree before making changes, then use a fix skill workflow that integrates retained progress back into `main` before ending the run.\n"},"lastSynced":"2026-03-06T13:08:30.135Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Analysis Agents needing advanced Ruby code inspection and correction capabilities using Rust and RuboCop","zh":"适合需要高级Ruby代码检查和纠正能力的代码分析代理，使用Rust和RuboCop","ja":"Rubyコードの高度な分析と修正機能を必要とするコード分析エージェントに適しています。RustとRuboCopを使用","ko":"고급 Ruby 코드 검사 및 수정 기능을 필요로 하는 코드 분석 에이전트에 적합합니다. Rust 및 RuboCop를 사용합니다.","es":"Perfecto para agentes de análisis de código que necesitan capacidades avanzadas de inspección y corrección de código Ruby utilizando Rust y RuboCop","fr":"Parfait pour les agents d''analyse de code nécessitant des capacités avancées d''inspection et de correction de code Ruby utilisant Rust et RuboCop","de":"Perfekt für Code-Analyse-Agents, die erweiterte Ruby-Code-Inspektion und -Korrekturmöglichkeiten mit Rust und RuboCop benötigen","pt":"Perfeito para Agentes de Análise de Código que necessitam de capacidades avançadas de inspeção e correção de código Ruby usando Rust e RuboCop","ru":"Идеально для Агентов анализа кода, которым необходимы продвинутые возможности инспекции и исправления кода Ruby с помощью Rust и RuboCop","ar":"مثالي لعميل تحليل الشفرة الذي يحتاج إلى قدرات متقدمة لتفحص وتحسين الشفرة Ruby باستخدام Rust و RuboCop"},"recommendation":{"en":"Empowers agents to identify and fix top cops by divergence in Ruby code using Python scripts and gh run download for corpus-results.json, providing advanced code quality control and auto-fixing with options like --limit, --department, and --exclude-department","zh":"赋予代理识别和修复Ruby代码中的顶级问题，使用Python脚本和gh run下载corpus-results.json，提供高级代码质量控制和自动修复功能，包括--limit、--department和--exclude-department等选项","ja":"エージェントがRubyコードのトップレベルの問題を特定して修正できるようにし、Pythonスクリプトとgh runによるcorpus-results.jsonのダウンロードを使用して、高度なコード品質管理と自動修正を提供します。--limit、--department、--exclude-departmentなどのオプションを提供します","ko":"에이전트가 Ruby 코드의 상위 문제를 식별하고 수정할 수 있도록 해줍니다. Python 스크립트와 gh run을 통해 corpus-results.json을 다운로드하여 고급 코드 품질 제어 및 자동 수정 기능을 제공하며 --limit, --department, --exclude-department 등의 옵션을 제공합니다.","es":"Habilita a los agentes a identificar y corregir los principales problemas mediante la divergencia en el código Ruby utilizando scripts de Python y gh run download para corpus-results.json, proporcionando un control avanzado de la calidad del código y auto-corrección con opciones como --limit, --department y --exclude-department","fr":"Permet aux agents d''identifier et de corriger les principaux problèmes par divergence dans le code Ruby en utilisant des scripts Python et gh run download pour corpus-results.json, fournissant un contrôle avancé de la qualité du code et une auto-correction avec des options comme --limit, --department et --exclude-department","de":"Ermöglicht es Agenten, die wichtigsten Probleme durch Abweichung im Ruby-Code zu identifizieren und zu korrigieren, indem sie Python-Skripte und gh run download für corpus-results.json verwenden, und bietet so eine erweiterte Code-Qualitätskontrolle und Auto-Korrektur mit Optionen wie --limit, --department und --exclude-department","pt":"Habilita os agentes a identificar e corrigir os principais problemas por divergência no código Ruby usando scripts Python e gh run download para corpus-results.json, fornecendo controle de qualidade de código avançado e auto-correção com opções como --limit, --department e --exclude-department","ru":"Наделяет агентов возможностью выявлять и исправлять основные проблемы, возникающие из-за расхождений в коде Ruby, используя скрипты Python и gh run download для corpus-results.json, обеспечивая продвинутый контроль качества кода и автоисправление с опциями, такими как --limit, --department и --exclude-department","ar":"يمكن للعميل تحديد وتصحيح مشاكل رئيسية ناتجة عن انحراف في الشفرة Ruby باستخدام سكريبتات Python و gh run download لملف corpus-results.json، وتوفير تحكم متقدم في جودة الشفرة وتصحيح تلقائي مع خيارات مثل --limit، --department و --exclude-department"},"useCases":{"en":["Identifying top cops by divergence for code quality improvement","Automating Ruby code corrections using triage.py script","Filtering and excluding specific departments for focused code analysis"],"zh":["识别代码质量改进的顶级问题","使用triage.py脚本自动纠正Ruby代码","过滤和排除特定部门以进行重点代码分析"],"ja":["コード品質の向上のためのトップレベルの問題を特定する","triage.pyスクリプトを使用してRubyコードを自動的に修正する","特定の部門をフィルタリングして除外して、焦点を当てたコード分析を実行する"],"ko":["코드 품질 향상을 위한 상위 문제를 식별하는 것","triage.py 스크립트를 사용하여 Ruby 코드를 자동으로 수정하는 것","특정 부서를 필터링하고 제외하여 집중적인 코드 분석을 수행하는 것"],"es":["Identificar los principales problemas por divergencia para la mejora de la calidad del código","Automatizar las correcciones de código Ruby utilizando el script triage.py","Filtrar y excluir departamentos específicos para un análisis de código enfocado"],"fr":["Identifier les principaux problèmes par divergence pour l''amélioration de la qualité du code","Automatiser les corrections de code Ruby en utilisant le script triage.py","Filtrer et exclure des départements spécifiques pour une analyse de code ciblée"],"de":["Die wichtigsten Probleme durch Abweichung für die Verbesserung der Code-Qualität identifizieren","Ruby-Code-Korrekturen mithilfe des Skripts triage.py automatisieren","Spezifische Abteilungen filtern und ausschließen, um eine fokussierte Code-Analyse durchzuführen"],"pt":["Identificar os principais problemas por divergência para melhoria da qualidade do código","Automatizar correções de código Ruby usando o script triage.py","Filtrar e excluir departamentos específicos para análise de código focada"],"ru":["Выявление основных проблем, возникающих из-за расхождений для улучшения качества кода","Автоматизация исправления кода Ruby с помощью скрипта triage.py","Фильтрация и исключение конкретных отделов для сосредоточенного анализа кода"],"ar":["تحديد المشاكل الرئيسية الناجمة عن الانحراف لتحسين جودة الشفرة","تأتمة تصحيح الشفرة Ruby باستخدام سكريبت triage.py","ترشيح واستبعاد أقسام معينة لتحليل الشفرة المُركز"]},"limitations":{"en":["Requires Python 3 to run triage.py script","Limited to Ruby and Rust code analysis","Dependent on gh run download for latest corpus-results.json"],"zh":["需要Python 3来运行triage.py脚本","仅限Ruby和Rust代码分析","依赖于gh run下载的最新corpus-results.json"],"ja":["triage.pyスクリプトを実行するにはPython 3が必要","RubyとRustのコード分析のみ","最新のcorpus-results.jsonをgh runでダウンロードすることに依存"],"ko":["triage.py 스크립트를 실행하려면 Python 3가 필요합니다.","Ruby 및 Rust 코드 분석만 해당합니다.","최신 corpus-results.json을 gh run으로 다운로드 하는 것에 의존합니다."],"es":["Requiere Python 3 para ejecutar el script triage.py","Limitado al análisis de código Ruby y Rust","Dependiente de gh run download para el último corpus-results.json"],"fr":["Nécessite Python 3 pour exécuter le script triage.py","Limité à l''analyse de code Ruby et Rust","Dépendant de gh run download pour le dernier corpus-results.json"],"de":["Benötigt Python 3, um das Skript triage.py auszuführen","Begrenzt auf Ruby- und Rust-Code-Analyse","Abhängig von gh run download für die neueste corpus-results.json"],"pt":["Requer Python 3 para executar o script triage.py","Limitado à análise de código Ruby e Rust","Dependente de gh run download para o arquivo corpus-results.json mais recente"],"ru":["Требуется Python 3 для запуска скрипта triage.py","Ограничен анализом кода Ruby и Rust","Зависит от gh run download для последнего файла corpus-results.json"],"ar":["يتطلب Python 3 لتشغيل سكريبت triage.py","محدود بتحليل الشفرة Ruby و Rust","يعتمد على غه رن داون لملف كوربوس-ريزالتس.جسون الأكثر حداثة"]},"version":4},"contentHash":"b5b9f4ed4b95d0fbc22b000ad3ecf628efb253345d9ac98202faf929e3048671","qualityScore":33}');
