INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('6/turbocop/triage', 'triage', '6', 'turbocop', 'community', 'triage 6 turbocop community rubocop ruby rust Triage is an experimental RuboCop rewrite in Rust that helps developers identify and fix top cops by divergence in their Ruby code. It benefits developers working with Ruby and Rust. Triage 是一个实验性的 RuboCop 重写版本，使用 Rust 编写。它可以帮助您找到需要修复的顶级 cops Triage は、Rust で書かれた実験的な RuboCop の再実装です。修正する必要があるトップレベルの cops を見つけるのに役立ちます Triage는 러스트로 작성된 실험적인 루비コ프 재구현입니다. 수정해야 하는 상위 cops를 찾는 데 도움이 됩니다 Triage es una herramienta experimental para identificar y solucionar problemas con RuboCop en Rust, utilizando un script Python para analizar resultados Triage est un outil expérimental pour identifier et résoudre les problèmes avec RuboCop en Rust, en utilisant un script Python pour analyser les résultats Triage ist ein experimentelles Tool, um Probleme mit RuboCop in Rust zu identifizieren und zu lösen, indem es ein Python-Skript verwendet, um Ergebnisse zu analysieren O Triage é uma ferramenta experimental que reescreve o RuboCop em Rust para melhorar o desempenho. Execute o script de triage para encontrar os principais cops a serem corrigidos. Triage - это экспериментальный инструмент, переписывающий RuboCop на Rust для улучшения производительности. Запустите скрипт triage, чтобы найти лучших cops для исправления. التriage هو أداة تجريبية لتعزيز أداء RuboCop باستخدام Rust. تشغيل سكريبت التriage لتحديد القوات الرئيسية التي يجب تصحيحها. how to use triage what is triage triage alternative triage vs rubocop triage install triage setup guide ruby code optimization rust powered rubocop Triage 技术 RuboCop 重写 Rust 编写 AI エージェント 自动下载 corpus-results.json 修复顶级 cops 命令行参数 false positive 仅显示 Runs the triage script using `python3 .claude/skills/triage/scripts/triage.py` to find top cops by divergence Auto-downloads the latest `corpus-results.json` from CI via `gh run download` if no input is provided Supports filtering by department using `--department` flag, e.g. `/triage --department RSpec` Allows excluding departments using `--exclude-department` flag, e.g. `/triage --exclude-department Layout` Provides option to show only cops with false positives using `--fp-only` flag Triage is an experimental RuboCop rewrite in Rust that runs a script to find and fix top cops by divergence in Ruby code.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('p-iknow/fullstack-forge/frontend-style-layout', 'community', 'p-iknow', 'fullstack-forge', 'p-iknow/fullstack-forge', 'frontend-style-layout', 1, 0, 33, '2026-02-25T14:46:47Z', '2026-03-06T07:12:01.431Z', '53d8cab0a1ffb030d12bbd61ffa6d11e4370fb34fbf68985bac76b03b14f8ade', '{"id":"p-iknow/fullstack-forge/frontend-style-layout","name":"frontend-style-layout","description":{"en":"The frontend-style-layout skill provides a hands-on fullstack monorepo for building a quick-commerce app with TypeSpec API contracts and Kubernetes deployment. It benefits developers looking to implement Tailwind CSS styling patterns.","zh":"本项目提供了使用 Tailwind v4 实现前端样式布局的实践指南，涵盖页面结构、间距、响应式图像和 v3 到 v4 迁移","ja":"このプロジェクトでは、Tailwind v4 を使用したフロントエンドスタイルレイアウトの実装方法を提供します。ページ構造、スペーシング、レスポンシブ画像、v3 から v4 への移行など","ko":"이 프로젝트는 Tailwind v4를 사용하여 프론트엔드 스타일 레이아웃을 구현하는 방법을 제공합니다. 페이지 구조, 간격, 반응형 이미지, v3에서 v4로의 마이그레이션 등","es":"El frontend-style-layout utiliza Tailwind v4 para crear patrones de diseño y layout de pagina. Incluye estructura de pagina, espaciado y migración de v3 a v4.","fr":"Le frontend-style-layout utilise Tailwind v4 pour créer des modèles de conception et de disposition de page. Il comprend la structure de page, l''espacement et la migration de v3 à v4.","de":"Das frontend-style-layout verwendet Tailwind v4, um Design- und Layout-Muster für Seiten zu erstellen. Es umfasst Seitenstruktur, Abstände und Migration von v3 auf v4.","pt":"O frontend-style-layout é um padrão de layout de página que utiliza Tailwind v4 e semantic HTML para criar layouts responsivos e espaçamento.","ru":"Frontend-style-layout — это шаблон макета страницы, который использует Tailwind v4 и семантический HTML для создания адаптивных макетов и пространства.","ar":"frontend-style-layout هو نمط تخطيط صفحة يستخدم Tailwind v4 و HTML семантиكي لإنشاء تخطيطات صفحة مس