INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('p-iknow/fullstack-forge/frontend-style-layout', 'frontend-style-layout', 'p-iknow', 'fullstack-forge', 'community', 'frontend-style-layout p-iknow fullstack-forge community The frontend-style-layout skill provides a hands-on fullstack monorepo for building a quick-commerce app with TypeSpec API contracts and Kubernetes deployment. It benefits developers looking to implement Tailwind CSS styling patterns. 本项目提供了使用 Tailwind v4 实现前端样式布局的实践指南，涵盖页面结构、间距、响应式图像和 v3 到 v4 迁移 このプロジェクトでは、Tailwind v4 を使用したフロントエンドスタイルレイアウトの実装方法を提供します。ページ構造、スペーシング、レスポンシブ画像、v3 から v4 への移行など 이 프로젝트는 Tailwind v4를 사용하여 프론트엔드 스타일 레이아웃을 구현하는 방법을 제공합니다. 페이지 구조, 간격, 반응형 이미지, v3에서 v4로의 마이그레이션 등 El frontend-style-layout utiliza Tailwind v4 para crear patrones de diseño y layout de pagina. Incluye estructura de pagina, espaciado y migración de v3 a v4. Le frontend-style-layout utilise Tailwind v4 pour créer des modèles de conception et de disposition de page. Il comprend la structure de page, l''espacement et la migration de v3 à v4. Das frontend-style-layout verwendet Tailwind v4, um Design- und Layout-Muster für Seiten zu erstellen. Es umfasst Seitenstruktur, Abstände und Migration von v3 auf v4. O frontend-style-layout é um padrão de layout de página que utiliza Tailwind v4 e semantic HTML para criar layouts responsivos e espaçamento. Frontend-style-layout — это шаблон макета страницы, который использует Tailwind v4 и семантический HTML для создания адаптивных макетов и пространства. frontend-style-layout هو نمط تخطيط صفحة يستخدم Tailwind v4 و HTML семантиكي لإنشاء تخطيطات صفحة مستجيب ومسافات how to use frontend-style-layout Tailwind CSS styling patterns frontend-style-layout setup guide quick-commerce app development semantic HTML best practices frontend-style-layout vs Bootstrap install frontend-style-layout frontend-style-layout alternative responsive design with Tailwind v4 前端样式布局 Tailwind v4 页面结构 间距 响应式图像 v3 到 v4 迁移 semantic HTML Kubernetes 部署 AIエージェント Implements Section Compound Pattern for explicit page layout structure Utilizes Tailwind v4 styling patterns for responsive design Supports v3→v4 migration for seamless upgrades Employs semantic HTML for accessible and maintainable code Enables flexible spacing and responsive image handling frontend-style-layout is a set of Tailwind CSS styling patterns for building quick-commerce apps with semantic HTML and explicit page structure.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pjcau/esp32-emu-turbo/pcb-review', 'community', 'pjcau', 'esp32-emu-turbo', 'pjcau/esp32-emu-turbo', 'pcb-review', 1, 0, 33, '2026-03-01T21:46:46Z', '2026-03-06T13:09:34.939Z', 'e41fc2ee30110be6e1e9c754a739e01982d545b8923e9fa8a7bbc573a006a08e', '{"id":"pjcau/esp32-emu-turbo/pcb-review","name":"pcb-review","description":{"en":"The pcb-review skill provides a comprehensive design review of PCB layouts, analyzing 6 key domains and producing a scored report with suggestions. It benefits developers working with ESP32-S3 for NES and SNES emulation.","zh":"PCB Review是一种手持式复古游戏机控制台设计审查工具，基于ESP32-S3进行NES和SNES模拟","ja":"PCB Reviewは、ESP32-S3を使用したNESとSNESエミュレーションを実現する携帯型レトロゲーム機の設計審查ツールです","ko":"PCB Review는 ESP32-S3를 기반으로 하는 NES 및 SNES 에뮬레이션을 위한携帯용 레트로 게임 콘솔 설계審查 도구입니다","es":"pcb-review es una herramienta de revisión de diseño de PCB para consolas de juegos retro como NES y SNES, basada en ESP32-S3","fr":"pcb-review est un outil de révision de conception de PCB pour les consoles de jeux rétro comme NES et SNES, basé sur ESP32-S3","de":"pcb-review ist ein Werkzeug zur Überprüfung des PCB-Designs für Retro-Spielkonsolen wie NES und SNES, basierend auf ESP32-S3","pt":"O pcb-review é uma ferramenta de análise de PCB para emulação de NES e SNES baseada em ESP32-S3. Fornece um relatório detalhado com sugestões de melhoria.","ru":"ИИ Агент pcb-review - это инструмент комплексного обзора проектирования платы для эмуляции NES и SNES на основе ESP32-S3. Выдаёт подробный отчёт с предложениями по улучшению.","ar":"pcb-review هو أداة لمراجعة تصميم لوحة الدوائر المطبوعة لتعزيز NES و SNES dựa على ESP32-S3. يقدم تقريرًا مفصلاً مع اقتراحات تحسين"},"seo":{"title":{"en":"pcb-review: Comprehensive PCB Design Review for AI Agents","zh":"PCB Review_setup_guide_ESP32-S3","ja":"PCB Reviewベストプラクティス_AIエージェント","ko":"PCB Review설치 가이드_ESP32-S3","es":"Guía de configuración de pcb-review para consolas de jueg...","fr":"Guide de configuration de pcb-review pour les consoles de...","de":"Einrichtungsleitfaden für pcb-review für Retro-Spielkonsolen","pt":"Guia de Configuração do pcb-review: Análise de PCB para E...","ru":"Настройка ИИ Агента pcb-review: Комплексный обзор проекти...","ar":"دليل إعداد pcb-review: مراجعة تصميم لوحة الدوائر المطبوعة..."},"description":{"en":"Discover how to optimize your PCB layout with pcb-review. Run automated reviews and get actionable improvement suggestions. Learn more and get started today!","zh":"使用PCB Review工具对ESP32-S3进行全面设计审查，获得有价值的改进建议","ja":"PCB Reviewを使用してESP32-S3の設計を徹底的に分析し、改善提案を取得します","ko":"PCB Review 도구를 사용하여 ESP32-S3의 설계를 완전하게审查하고 개선 제안을 얻으세요","es":"Mejora tus habilidades en diseño de PCB con pcb-review, una herramienta de revisión de diseño de circuitos impresos para consolas de juegos retro como NES y ...","fr":"Améliorez vos compétences en conception de PCB avec pcb-review, un outil de révision de conception de circuit imprimé pour les consoles de jeux rétro comme N...","de":"Verbessern Sie Ihre Fähigkeiten im PCB-Design mit pcb-review, einem Werkzeug zur Überprüfung des Schaltplattendesigns für Retro-Spielkonsolen wie NES und SNES","pt":"Aprenda a configurar o pcb-review para análise de PCB e melhore a emulação de NES e SNES com nosso guia passo a passo","ru":"Узнайте, как настроить ИИ Агент pcb-review для комплексного обзора проектирования платы и улучшения эмуляции NES и SNES","ar":"تعرف على كيفية إعداد pcb-review لمراجعة تصميم لوحة الدوائر المطبوعة وتحسين تعزيز NES و SNES مع دليلنا خطوة بخطوة"},"definition":{"en":"pcb-review is a skill that performs a thorough analysis of PCB designs, checking domains like Power Integrity and Decoupling cap, to provide a scored report and improvement suggestions.","zh":"PCB Review是一种设计审查工具，用于分析ESP32-S3的PCB布局","ja":"PCB Reviewは、ESP32-S3のPCBレイアウトを分析する設計審查ツールです","ko":"PCB Review는 ESP32-S3의 PCB 레이아웃을 분석하는 설계審查 도구입니다","es":"pcb-review es una herramienta de revisión de diseño de circuitos impresos que analiza 6 dominios clave","fr":"pcb-review est un outil de révision de conception de circuit imprimé qui analyse 6 domaines clés","de":"pcb-review ist ein Werkzeug zur Überprüfung des Schaltplattendesigns, das 6 Schlüsselbereiche analysiert","pt":"O pcb-review é uma ferramenta de análise de PCB que avalia 6 domínios-chave para melhorar a emulação de NES e SNES","ru":"ИИ Агент pcb-review - это инструмент комплексного обзора проектирования платы, который оценивает 6 ключевых областей для улучшения эмуляции NES и SNES","ar":"pcb-review هو أداة لمراجعة تصميم لوحة الدوائر المطبوعة التي تقيم 6 مجالات رئيسية لتحسين تعزيز NES و SNES"},"features":{"en":["Analyzes 6 key domains, including Power Integrity and Decoupling cap","Runs automated reviews using the pcb_review.py script","Produces a scored report with actionable improvement suggestions","Supports ESP32-S3 for NES and SNES emulation","Utilizes Python 3 for script execution","Reviews findings based on a scored system (1-10) for each domain"],"zh":["自动化设计审查","6个关键域分析（得分1-10）","产生有价值的改进建议报告","支持ESP32-S3的NES和SNES模拟","使用Python脚本进行设计审查","支持Power Integrity和Decoupling Cap分析"],"ja":["自動設計審查","6つの重要なドメイン分析（スコア1-10）","有益な改善提案レポートを生成","ESP32-S3のNESとSNESエミュレーションをサポート","Pythonスクリプトを使用した設計審查","Power IntegrityとDecoupling Capの分析をサポート"],"ko":["자동 설계審查","6개의 중요한 도메인 분석（점수 1-10）","유용한 개선 제안 보고서 생성","ESP32-S3의 NES 및 SNES 에뮬레이션 지원","Python 스크립트를 사용한 설계審查","Power Integrity 및 Decoupling Cap 분석 지원"],"es":["Análisis de integridad de potencia","Revisión de la configuración de decoupling cap","Compatibilidad con ESP32-S3","Emulación de NES y SNES","Informe de revisión con puntuación y sugerencias de mejora","Ejecución automática con script de Python"],"fr":["Analyse de l''intégrité de puissance","Révision de la configuration de decoupling cap","Compatibilité avec ESP32-S3","Émulation de NES et SNES","Rapport de révision avec notation et suggestions d''amélioration","Exécution automatique avec script Python"],"de":["Analyse der Leistungsintegrität","Überprüfung der Decoupling-Cap-Konfiguration","Kompatibilität mit ESP32-S3","Emulation von NES und SNES","Überprüfungsbericht mit Punktzahl und Verbesserungsvorschlägen","Automatisierte Ausführung mit Python-Skript"],"pt":["Análise de integridade de energia","Verificação de capacitor de desacoplamento","Avaliação de 6 domínios-chave","Relatório detalhado com sugestões de melhoria","Compatibilidade com ESP32-S3","Emulação de NES e SNES"],"ru":["Анализ целостности питания","Проверка конденсатора развязки","Оценка 6 ключевых областей","Подробный отчёт с предложениями по улучшению","Совместимость с ESP32-S3","Эмуляция NES и SNES"],"ar":["تحليل سلامة الطاقة","فحص مكثف الفصل","تقييم 6 مجالات رئيسية","تقرير مفصل مع اقتراحات تحسين","التوافق مع ESP32-S3","تعزيز NES و SNES"]},"keywords":{"en":["how to use pcb-review","pcb-review setup guide","pcb-review alternative","pcb-review vs other design review tools","pcb-review install","what is pcb-review","pcb-review for ESP32-S3","pcb-review for NES and SNES emulation","pcb-review automated review","pcb-review design optimization"],"zh":["PCB设计审查","ESP32-S3","NES模拟","SNES模拟","Python脚本","Power Integrity","Decoupling Cap","设计审查工具","携帯式レトロゲーム机"],"ja":["PCB設計審查","ESP32-S3","NESエミュレーション","SNESエミュレーション","Pythonスクリプト","Power Integrity","Decoupling Cap","設計審查ツール","携帯型レトロゲーム機","AIエージェント"],"ko":["PCB 설계審查","ESP32-S3","NES 에뮬레이션","SNES 에뮬레이션","Python 스크립트","Power Integrity","Decoupling Cap","설계審查 도구","携帯용 레트로 게임 콘솔","AI 에이전트"],"es":["pcb-review","diseño de PCB","consolas de juegos retro","NES","SNES","ESP32-S3","emulación","revisión de diseño","herramientas de diseño de PCB"],"fr":["pcb-review","conception de PCB","consoles de jeux rétro","NES","SNES","ESP32-S3","émulation","révision de conception","outils de conception de PCB"],"de":["pcb-review","PCB-Design","Retro-Spielkonsolen","NES","SNES","ESP32-S3","Emulation","Überprüfung des Designs","Werkzeuge für PCB-Design"],"pt":["pcb-review","análise de PCB","emulação de NES","emulação de SNES","ESP32-S3","desenvolvimento de jogos","ferramentas de desenvolvimento","análise de integridade de energia","verificação de capacitor de desacoplamento"],"ru":["pcb-review","комплексный обзор проектирования платы","эмуляция NES","эмуляция SNES","ESP32-S3","разработка игр","инструменты разработки","анализ целостности питания","проверка конденсатора развязки"],"ar":["pcb-review","مراجعة تصميم لوحة الدوائر المطبوعة","تعزيز NES","تعزيز SNES","ESP32-S3","تطوير الألعاب","أدوات التطوير","تحليل سلامة الطاقة","فحص مكثف الفصل"]}},"owner":"pjcau","repo":"esp32-emu-turbo","repoPath":"pjcau/esp32-emu-turbo","stars":1,"forks":0,"updatedAt":"2026-03-01T21:46:46Z","topics":[],"category":"community","skillMd":{"name":"pcb-review","description":"Comprehensive PCB design review — power, signal, thermal, EMI, manufacturability, mechanical","bodyPreview":"# PCB Design Review\n\nComprehensive design review of the PCB layout, analyzing 6 key domains like a senior PCB engineer would. Produces a scored report with actionable improvement suggestions.\n\n## Steps\n\n### 1. Run the automated review\n\n```bash\ncd /Users/pierrejonnycau/Documents/WORKS/esp32-emu-turbo\npython3 scripts/pcb_review.py\n```\n\n### 2. Review findings\n\nThe script analyzes 6 domains (scored 1-10 each):\n\n| Domain | What it checks |\n|--------|---------------|\n| Power Integrity | Decoupling cap","body":"# PCB Design Review\n\nComprehensive design review of the PCB layout, analyzing 6 key domains like a senior PCB engineer would. Produces a scored report with actionable improvement suggestions.\n\n## Steps\n\n### 1. Run the automated review\n\n```bash\ncd /Users/pierrejonnycau/Documents/WORKS/esp32-emu-turbo\npython3 scripts/pcb_review.py\n```\n\n### 2. Review findings\n\nThe script analyzes 6 domains (scored 1-10 each):\n\n| Domain | What it checks |\n|--------|---------------|\n| Power Integrity | Decoupling caps near ICs, power trace widths, GND plane coverage |\n| Signal Integrity | Bus trace length matching, parallel trace crosstalk, high-speed routing |\n| Thermal | Power IC thermal relief, via count, copper area for heat spreading |\n| Manufacturability | JLCPCB min trace/space, drill sizes, annular rings |\n| EMI/EMC | Ground plane continuity, signal return paths, decoupling strategy |\n| Mechanical | Mounting hole symmetry, connector accessibility, FPC strain relief |\n\n### 3. Address priority items\n\nFocus on the Top 5 improvements suggested by the review.\n\n### 4. Re-run to verify\n\nAfter making changes, regenerate and re-run:\n```bash\npython3 -m scripts.generate_pcb hardware/kicad\npython3 scripts/pcb_review.py\n```\n\n## Summary Report Format\n\n| Domain | Score | Key Finding |\n|--------|-------|-------------|\n| Power Integrity | ?/10 | ... |\n| Signal Integrity | ?/10 | ... |\n| Thermal | ?/10 | ... |\n| Manufacturability | ?/10 | ... |\n| EMI/EMC | ?/10 | ... |\n| Mechanical | ?/10 | ... |\n| **OVERALL** | **?/60** | ... |\n\n## Key Files\n\n- `scripts/pcb_review.py` — Automated review script\n- `.claude/skills/pcb-review/review-checklist.md` — Detailed scoring criteria\n- `scripts/drc_check.py` — Reuses parse_pcb() for PCB parsing\n- `scripts/generate_pcb/board.py` — Component positions\n- `scripts/generate_pcb/routing.py` — Trace routing constants\n"},"lastSynced":"2026-03-06T13:09:34.939Z","agentAnalysis":{"suitability":{"en":"Perfect for Embedded System Agents needing comprehensive PCB design review and analysis capabilities for ESP32-S3 based projects.","zh":"非常适合需要为基于ESP32-S3的项目提供全面PCB设计审查和分析能力的嵌入式系统Agent。","ja":"ESP32-S3ベースのプロジェクトのために包括的なPCB設計レビューと分析機能を必要とする組み込みシステムエージェントに最適です。","ko":"ESP32-S3 기반 프로젝트를 위한 포괄적인 PCB 설계 검토 및 분석 기능이 필요한 임베디드 시스템 에이전트에 완벽합니다.","es":"Ideal para agentes de sistemas embebidos que necesitan capacidades completas de revisión y análisis de diseño de PCB para proyectos basados en ESP32-S3.","fr":"Parfait pour les agents de systèmes embarqués nécessitant des capacités complètes de révision et d''analyse de conception de PCB pour les projets basés sur ESP32-S3.","de":"Perfekt für Embedded System Agents, die umfassende Fähigkeiten zur Überprüfung und Analyse von PCB-Designs für ESP32-S3-basierte Projekte benötigen.","pt":"Perfeito para Agentes de Sistemas Incorporados que necessitam de capacidades de revisão e análise de design de PCB abrangentes para projetos baseados em ESP32-S3.","ru":"Идеально подходит для агентов встроенных систем, которым необходимы всесторонние возможности проверки и анализа конструкции ПЛИС для проектов на основе ESP32-S3.","ar":"مثالي لعميل نظام متضمّن يحتاج إلى قدرات شاملة لمراجعة و تحليل تصميم لوحة الدوائر المطبوعة لمشاريع تستند إلى ESP32-S3."},"recommendation":{"en":"Empowers agents to analyze PCB layouts across 6 key domains, including Power Integrity and Decoupling Cap, generating scored reports with actionable improvement suggestions using Python scripts like pcb_review.py.","zh":"使Agent能够跨6个关键领域（包括电源完整性和去耦电容）分析PCB布局，使用诸如pcb_review.py之类的Python脚本生成带有可操作改进建议的评分报告。","ja":"Power IntegrityやDecoupling Capを含む6つの主要ドメインにわたってPCBレイアウトを分析し、pcb_review.pyのようなPythonスクリプトを使用して、実行可能な改善提案を含むスコア付きレポートを生成することをエージェントに可能にします。","ko":"Power Integrity 및 Decoupling Cap을 포함한 6가지 주요 영역에 걸쳐 PCB 레이아웃을 분석하고, pcb_review.py와 같은 Python 스크립트를 사용하여 실행 가능한 개선 제안이 포함된 점수화된 보고서를 생성하도록 에이전트를 지원합니다.","es":"Permite a los agentes analizar diseños de PCB en 6 dominios clave, incluidos Power Integrity y Decoupling Cap, generando informajes puntuados con sugerencias de mejora accionables utilizando scripts de Python como pcb_review.py.","fr":"Permet aux agents d''analyser les conceptions de PCB dans 6 domaines clés, y compris Power Integrity et Decoupling Cap, en générant des rapports notés avec des suggestions d''amélioration actionnables à l''aide de scripts Python comme pcb_review.py.","de":"Ermöglicht Agents, PCB-Layouts in 6 Schlüsselbereichen zu analysieren, einschließlich Power Integrity und Decoupling Cap, und erstellt bewertete Berichte mit umsetzbaren Verbesserungsvorschlägen unter Verwendung von Python-Skripten wie pcb_review.py.","pt":"Habilita os agentes a analisar layouts de PCB em 6 domínios principais, incluindo Integridade de Energia e Capacitor de Desacoplamento, gerando relatórios avaliados com sugestões de melhoria executáveis usando scripts Python como pcb_review.py.","ru":"Позволяет агентам анализировать компоновку ПЛИС в 6 ключевых областях, включая целостность питания и конденсатор развязки, генерируя оценочные отчеты с действенными предложениями по улучшению с использованием скриптов Python, таких как pcb_review.py.","ar":"تمكّن العملاء من تحليل تصميم لوحة الدوائر المطبوعة عبر 6 مجالات رئيسية، بما في ذلك سلامة الطاقة و مكثف الفصل، مع توليد تقارير مقيّسة مع اقتراحات تحسين قابلة للتنفيذ باستخدام نصوص برمجة بايثون مثل pcb_review.py."},"useCases":{"en":["Automating PCB design reviews for NES and SNES emulation projects","Generating detailed reports for PCB layout optimization","Debugging Power Integrity issues in ESP32-S3 designs"],"zh":["为NES和SNES仿真项目自动化PCB设计审查","为PCB布局优化生成详细报告","调试ESP32-S3设计中的电源完整性问题"],"ja":["NESおよびSNESエミュレーションプロジェクトのためのPCB設計レビューの自動化","PCBレイアウト最適化のための詳細なレポートの生成","ESP32-S3設計におけるPower Integrity問題のデバッグ"],"ko":["NES 및 SNES 에뮬레이션 프로젝트를 위한 PCB 설계 검토 자동화","PCB 레이아웃 최적화를 위한 상세 보고서 생성","ESP32-S3 설계에서 Power Integrity 문제 디버깅"],"es":["Automatización de revisiones de diseño de PCB para proyectos de emulación de NES y SNES","Generación de informes detallados para la optimización del diseño de PCB","Depuración de problemas de Power Integrity en diseños con ESP32-S3"],"fr":["Automatisation des revues de conception de PCB pour les projets d''émulation NES et SNES","Génération de rapports détaillés pour l''optimisation de la conception de PCB","Débogage des problèmes d''intégrité de l''alimentation (Power Integrity) dans les conceptions ESP32-S3"],"de":["Automatisierung von PCB-Design-Reviews für NES- und SNES-Emulationsprojekte","Erstellung detaillierter Berichte zur Optimierung von PCB-Layouts","Debugging von Power Integrity-Problemen in ESP32-S3-Designs"],"pt":["Automatizar revisões de design de PCB para projetos de emulação de NES e SNES","Gerar relatórios detalhados para otimização de layout de PCB","Depurar problemas de Integridade de Energia em designs de ESP32-S3"],"ru":["Автоматизировать проверку конструкции ПЛИС для проектов эмуляции NES и SNES","Генерировать подробные отчеты для оптимизации компоновки ПЛИС","Отладить проблемы целостности питания в конструкциях ESP32-S3"],"ar":["أتمتة مراجعة تصميم لوحة الدوائر المطبوعة لمشاريع محاكاة NES و SNES","توليد تقارير مفصّلة لتحسين تصميم لوحة الدوائر المطبوعة","تصحيح أخطاء في سلامة الطاقة في تصاميم ESP32-S3"]},"limitations":{"en":["Requires Python 3.x","Limited to ESP32-S3 based projects","Needs access to PCB layout files and design specifications"],"zh":["需要Python 3.x","仅限于基于ESP32-S3的项目","需要访问PCB布局文件和设计规范"],"ja":["Python 3.xが必要","ESP32-S3ベースのプロジェクトに限定される","PCBレイアウトファイルと設計仕様書へのアクセスが必要"],"ko":["Python 3.x 필요","ESP32-S3 기반 프로젝트로 제한됨","PCB 레이아웃 파일 및 설계 사양에 대한 액세스 필요"],"es":["Requiere Python 3.x","Limitado a proyectos basados en ESP32-S3","Necesita acceso a archivos de diseño de PCB y especificaciones"],"fr":["Nécessite Python 3.x","Limité aux projets basés sur ESP32-S3","Nécessite un accès aux fichiers de conception de PCB et aux spécifications"],"de":["Erfordert Python 3.x","Beschränkt auf ESP32-S3-basierte Projekte","Benötigt Zugriff auf PCB-Layout-Dateien und Designspezifikationen"],"pt":["Exige Python 3.x","Limitado a projetos baseados em ESP32-S3","Necessita acesso a arquivos de layout de PCB e especificações de design"],"ru":["Требует Python 3.x","Ограничен проектами на основе ESP32-S3","Требует доступа к файлам компоновки ПЛИС и спецификациям конструкции"],"ar":["يتطلّب بايثون 3.x","محدود بمشاريع تستند إلى ESP32-S3","يحتاج إلى الوصول إلى ملفات تصميم لوحة الدوائر المطبوعة والمواصفات التصميمية"]},"version":4},"contentHash":"e41fc2ee30110be6e1e9c754a739e01982d545b8923e9fa8a7bbc573a00